def get_role_name(role_key):
    if not role_key:
        return '未分配'
    key = str(role_key).strip().lower()
    for k, v in _ROLE_CN.items():
        if k == key or k in key:
            return v
    # 首字母大写友好显示
    s = str(role_key).strip().replace('_', ' ')
    return s[:1].upper() + s[1:]


