@app.route('/api/user/request_education_upgrade', methods=['POST'])
@system_container('user_request_education_upgrade', require_auth='login')
def api_user_request_education_upgrade():
    """登录后在「个人设置→身份认证」提交组别申请（审批流入口）。"""
    u = _safe_user_ctx(_current_user())
    if not u:
        return jsonify({'success': False, 'message': '未登录'}), 401
    data = request.get_json(silent=True) or {}
    apply_type = _safe_str(data.get('apply_education_type'), max_len=32).strip().lower()
    if not apply_type:
        return jsonify({'success': False, 'message': '请选择要申请的教育组别'}), 400
    age = 0
    try:
        age = int(u.get('age') or 0)
    except (TypeError, ValueError):
        age = 0
    # 如果请求体有 age 则按实际年龄判断（用户可能后来补填）
    try:
        if data.get('age'):
            age = int(data.get('age'))
    except (TypeError, ValueError):
        pass
    allowed, valid = _validate_education_apply_by_age(age, apply_type)
    if not valid:
        return jsonify({
            'success': False,
            'message': f'您的年龄不允许申请【{_EDUCATION_TYPE_CN.get(apply_type, apply_type)}】。允许申请：{"、".join(sorted(allowed))}。',
            'allowed': sorted(allowed),
        }), 400
    now_iso = datetime.now().isoformat()
    import json as _rj
    apply_json = _rj.dumps({
        'requested': apply_type,
        'age': age,
        'requested_at': now_iso,
        'status': 'pending',
        'reason': _safe_str(data.get('reason') or data.get('justification'), max_len=500),
        'reviewed_by': None,
        'reviewed_at': None,
        'review_comment': None,
    }, ensure_ascii=False)
    written = False
    write_db = None
    try:
        for dbp in (_bizdb_path(), APP_DB, AUTH_DB):
            try:
                with _get_conn(dbp) as conn:
                    # 确保列存在
                    for col, decl in [('pending_education_apply', 'TEXT'),
                                      ('education_apply_status', "TEXT DEFAULT 'none'"),
                                      ('education_apply_approved_at', 'TEXT')]:
                        try: conn.execute(f"ALTER TABLE users ADD COLUMN {col} {decl}")
                        except sqlite3.Error: pass
                    cur = conn.execute(
                        "UPDATE users SET pending_education_apply=?, education_apply_status='pending', "
                        "updated_at=? WHERE id=? AND username=?",
                        (apply_json, now_iso, int(u.get('id') or 0), str(u.get('username') or ''))
                    )
                    conn.commit()
                    if cur.rowcount and cur.rowcount > 0:
                        written = True; write_db = dbp; break
            except sqlite3.Error:
                continue
    except Exception:
        pass
    ip = request.remote_addr or 'unknown_ip'
    ua = request.headers.get('User-Agent', '')[:200]
    try:
        _ef_process_report_anomaly(
            'education_upgrade_requested', 'api_user_request_education_upgrade', 'MEDIUM',
            {'user_id': u.get('id'), 'username': u.get('username'),
             'apply': apply_type, 'age': age, 'db': os.path.basename(write_db) if write_db else None,
             'written': written,
             'reason': _safe_str(data.get('reason') or '', max_len=200)},
            notify_ai_employees=True, auto_apply_fix=False,
            operator_user=u.get('username') or 'anonymous', client_ip=ip, client_ua=ua
        )
    except Exception:
        pass
    if not written:
        return jsonify({'success': False,
                        'message': '申请写入失败：用户数据库暂不可用，请稍后重试。'}), 500
    return jsonify({
        'success': True,
        'message': (f'✅ 已提交【{_EDUCATION_TYPE_CN.get(apply_type, apply_type)}】组别申请。'
                    f'管理员审批通过后将自动解锁对应功能；审批前仍为【普通组别】。\n'
                    f'（提交时间：{now_iso}）'),
        'apply_education_type': apply_type,
        'education_apply_status': 'pending',
        'requested_at': now_iso,
    })


@app.route('/api/user/cancel_education_apply', methods=['POST'])
@system_container('cancel_education_apply', require_auth='login')
def api_user_cancel_education_apply():
    """撤销待审批的组别申请"""
    u = _safe_user_ctx(_current_user())
    if not u:
        return jsonify({'success': False, 'message': '未登录'}), 401
    uid = int(u.get('id') or 0)
    username = str(u.get('username') or '')
    now_iso = datetime.now().isoformat()

    try:
        with _get_conn(AUTH_DB) as conn:
            pending_row = conn.execute(
                "SELECT pending_education_apply FROM users WHERE id=? AND username=? LIMIT 1",
                (uid, username)
            ).fetchone()
            if not pending_row or not pending_row['pending_education_apply']:
                return jsonify({'success': False, 'message': '没有待审批的申请'})

            conn.execute(
                "UPDATE users SET pending_education_apply=NULL, education_apply_status='cancelled', "
                "updated_at=? WHERE id=? AND username=?",
                (now_iso, uid, username)
            )
            conn.commit()
        return jsonify({'success': True, 'message': '已撤销申请'})
    except Exception as e:
        return jsonify({'success': False, 'message': f'撤销失败: {str(e)}'}), 500


@app.route('/api/user/education_apply_status', methods=['GET'])
@system_container('education_apply_status', require_auth='login')
def api_user_education_apply_status():
    """查询当前用户的组别申请状态"""
    u = _safe_user_ctx(_current_user())
    if not u:
        return jsonify({'success': False, 'message': '未登录'}), 401
    uid = int(u.get('id') or 0)
    username = str(u.get('username') or '')

    try:
        with _get_conn(AUTH_DB) as conn:
            row = conn.execute(
                "SELECT education_type, pending_education_apply, education_apply_status, education_apply_approved_at "
                "FROM users WHERE id=? AND username=? LIMIT 1",
                (uid, username)
            ).fetchone()
        if not row:
            return jsonify({'success': False, 'message': '用户不存在'})

        current_type = row['education_type'] or '普通'
        pending_json = row['pending_education_apply']
        apply_status = row['education_apply_status'] or 'none'

        import json as _rj
        pending_data = None
        is_pending = False
        if pending_json:
            try:
                pending_data = _rj.loads(pending_json)
                if pending_data.get('status') == 'pending':
                    is_pending = True
            except (TypeError, ValueError):
                pass

        data = {
            'current_education_type': current_type,
            'pending': is_pending,
            'apply_status': apply_status,
        }
        if pending_data and is_pending:
            data['pending_type'] = pending_data.get('requested', '')
            data['pending_cn'] = _EDUCATION_TYPE_CN.get(pending_data.get('requested', ''), '')
            data['submitted_at'] = pending_data.get('requested_at', '')
        elif apply_status == 'approved' and row['education_apply_approved_at']:
            data['approved_at'] = row['education_apply_approved_at']

        return jsonify({'success': True, 'data': data})
    except Exception as e:
        return jsonify({'success': False, 'message': f'查询失败: {str(e)}'}), 500


# ============ Remember-Me 自动登录恢复中间件（session过期但cookie有效时自动恢复）============
@app.before_request
def _mt_remember_me_auto_login():
    # 跳过：静态资源、API登录/登出页面、已登录session
    if session.get('logged_in'):
        return
    p = request.path or ''
    # 不处理登录/登出
    if p in ('/auth/login', '/auth/logout', '/auth/forgot_password', '/auth/register'):
        return
    if p.startswith('/static/') or p.startswith('/assets/') or p.startswith('/favicon'):
        return
    # 仅 GET/HEAD 触发（POST 等带 body 请求先过正常 session 校验）
    if request.method not in ('GET', 'HEAD'):
        return
    cookie = request.cookies.get(_MT_REMEMBER_COOKIE)
    if not cookie:
        return
    ip = request.remote_addr or 'unknown_ip'
    ua = request.headers.get('User-Agent', '')[:200]
    uid, uname, new_cookie = _remember_me_consume(cookie, ip=ip, ua=ua)
    if not uid or not uname:
        # token 无效：清除 cookie（_remember_me_consume 已做内部告警和撤销）
        return
    # 恢复会话
    try:
        # 查用户跨库信息（补全角色等）
        row_dict, _ = _find_user_across_dbs(uname)
        role = 'user'
        db_sa_ok = False
        if row_dict:
            role = str(row_dict.get('role') or 'user').lower() or 'user'
            db_sa_ok = bool(row_dict.get('super_admin_approved'))
        # SA 白名单（最高优先级）
        if str(uname or '').lower() == 'wuchenghao15':
            role = 'super_admin'
        elif role == 'super_admin':
            role = 'admin'
        session['user_id'] = uid
        session['username'] = uname
        session['role'] = role
        session['logged_in'] = True
        session['csrf_token'] = hashlib.sha256(f'mtscos-csrf-sess-{time.time()}-{os.urandom(16)}'.encode()).hexdigest()
        session.permanent = True
        if db_sa_ok:
            session['super_admin_approved'] = True
        try:
            session['_remember_token_id'] = (new_cookie or '').split('.', 1)[0][:64]
        except Exception:
            pass
        # 触发 EF + AI员工5人磋商
        try:
            _ef_process_report_anomaly(
                'remember_auto_login_ok', 'remember_me_auto_login', 'LOW',
                {'username': uname, 'uid': uid, 'role': role, 'note': 'remember-me cookie自动恢复登录成功'},
                notify_ai_employees=False, auto_apply_fix=False,
                operator_user=uname or 'anonymous', client_ip=ip, client_ua=ua
            )
        except Exception:
            pass
    except Exception as e:
        try:
            _ef_process_report_anomaly(
                'remember_auto_login_fail', 'remember_me_auto_login', 'MEDIUM',
                {'error': str(e)[:200], 'note': '自动恢复失败，已跳过remember-me'},
                notify_ai_employees=True, auto_apply_fix=True,
                client_ip=ip, client_ua=ua
            )
        except Exception:
            pass
        return
    # 轮换 cookie：写入新 cookie
    if new_cookie:
        from flask import g as _g
        try:
            _g._remember_new_cookie = new_cookie
        except Exception:
            pass
        # 此处不能直接 set_cookie（before_request），挂 after_request 写


@app.before_request
def _mt_security_shield_before_request():
    """4合1安全盾牌中间件：防黑客/防暴力破解/防撞库/反编译水印校验"""
    try:
        p = (request.path or '').lower()
        if p.startswith('/static/') or p.startswith('/assets/') or p.startswith('/favicon'):
            return
        checks = [
            _security_check_hacking,
            _security_check_bruteforce,
            _security_check_credential_stuffing,
            _security_check_decompile_watermark,
            _security_check_ssl_binding,  # 【STEP_7 SSL绑定】第5项检查
        ]
        for fn in checks:
            try:
                r = fn()
                if isinstance(r, dict) and r.get('blocked'):
                    try:
                        _security_report_anomaly('security_shield_block', {'check': fn.__name__, 'path': p})
                    except Exception:
                        pass
                    return jsonify({'success': False, 'message': 'Forbidden', '_eigenflux': {'blocked': True}}), 403
            except Exception:
                pass
    except Exception:
        pass


def _security_check_hacking():
    """防黑客：检查UA恶意特征、路径注入、异常header — 真正落库sec_hacking_events"""
    try:
        ua = (request.headers.get('User-Agent', '') or '')
        path = request.path or ''
        ip = request.remote_addr or 'unknown'
        attack_type = None
        payload = None
        evil_uas = [('sqlmap', 'sqlmap_scan'), ('nmap', 'nmap_scan'), ('havij', 'havij_scan'),
                    ('acunetix', 'acunetix_scan'), ('nessus', 'nessus_scan'), ('nikto', 'nikto_scan'),
                    ('burp', 'burp_scan'), ('masscan', 'masscan_scan')]
        for eu, at in evil_uas:
            if eu in ua.lower():
                attack_type = at
                payload = ua[:200]
                break
        if attack_type is None:
            evil_paths = [('../', 'path_traversal'), ('./etc/passwd', 'path_traversal'),
                          ('{{7*7}}', 'ssti_injection'), ('<script', 'xss_injection'),
                          ('union select', 'sqli_injection'), (' or 1=1', 'sqli_injection')]
            for ep, at in evil_paths:
                if ep.lower() in path.lower():
                    attack_type = at
                    payload = path[:300]
                    break
        if attack_type is None:
            xff = request.headers.get('X-Forwarded-For', '')
            if xff and xff.count(',') > 3:
                attack_type = 'xff_forgery'
                payload = xff[:200]
        if attack_type is not None:
            # 真正落库（之前缺失的INSERT）
            try:
                with _get_conn(APP_DB) as c:
                    _ensure_security_schema(c)
                    c.execute(
                        "INSERT INTO sec_hacking_events (ip_addr,user_agent,path,attack_type,payload_excerpt,blocked,eigenflux_verdict) VALUES (?,?,?,?,?,1,'AUTO_BLOCKED')",
                        (ip, ua[:300], path[:300], attack_type, (payload or '')[:500])
                    )
                    c.commit()
            except Exception:
                pass
            try:
                _security_audit_log('hacking', 'HIGH', f'黑客攻击 detected: attack_type={attack_type} payload={(payload or "")[:80]}', path=path, eigenflux_flag=1)
            except Exception:
                pass
            try:
                _security_report_anomaly('hack_' + attack_type, {'ip': ip, 'path': path, 'ua': ua[:100], 'payload': (payload or '')[:200]})
            except Exception:
                pass
            return {'blocked': True, 'reason': attack_type}
    except Exception:
        pass
    return {'blocked': False}


def _security_check_bruteforce():
    """防暴力破解：【先查已存在锁】再统计login_attempts阈值，IP+username双维度锁定"""
    try:
        if not (request.path or '').lower().endswith('/login'):
            return {'blocked': False}
        if request.method != 'POST':
            return {'blocked': False}
        ip = request.remote_addr or 'unknown'
        data = request.get_json(force=True, silent=True) or {}
        form = request.form or {}
        uname = (data.get('username') or form.get('username') or '').strip()
        now_ts = datetime.now()
        now_str = now_ts.strftime('%Y-%m-%d %H:%M:%S')
        try:
            with _get_conn(APP_DB) as c:
                _ensure_security_schema(c)
                # --- 第一步：先查sec_bruteforce_locks里有没有未过期锁（落地关键）---
                for col, val in [('ip_addr', ip), ('username', uname)]:
                    if not val:
                        continue
                    ex = c.execute(
                        f"SELECT lock_id,locked_until,reason FROM sec_bruteforce_locks WHERE {col}=? AND locked_until>? ORDER BY lock_id DESC LIMIT 1",
                        (val, now_str)
                    ).fetchone()
                    if ex:
                        try:
                            _security_audit_log('bruteforce', 'MEDIUM', f'已有{col}锁命中 lock_id={ex[0]} 到期={ex[1]} reason={ex[2]}', eigenflux_flag=1)
                        except Exception:
                            pass
                        return {'blocked': True, 'reason': f'already_locked_{col}'}
                # --- 第二步：统计login_attempts阈值，超阈值就INSERT锁 ---
                # 注意：login_attempts.timestamp 用 datetime.now().isoformat() 写入（ISO格式带'T'），
                # 而 strftime('%Y-%m-%d %H:%M:%S') 生成的是空格分隔格式。
                # 字符串比较时 'T'(0x54) > ' '(0x20)，导致所有 ISO 时间戳都被误判为"最近1分钟内"，
                # 引发 caopw 等正常用户登录被误判为暴力破解而返回 Forbidden。
                # 修复：用 SQLite datetime() 函数进行真正的时间比较，兼容 ISO 和空格两种格式。
                for col, val in [('ip_address', ip), ('username', uname)]:
                    if not val:
                        continue
                    one_min = c.execute(
                        f"SELECT COUNT(*) FROM login_attempts WHERE {col}=? AND success=0 AND datetime(timestamp)>=datetime(?)",
                        (val, (now_ts - timedelta(minutes=1)).strftime('%Y-%m-%d %H:%M:%S'))
                    ).fetchone()
                    one_hr = c.execute(
                        f"SELECT COUNT(*) FROM login_attempts WHERE {col}=? AND success=0 AND datetime(timestamp)>=datetime(?)",
                        (val, (now_ts - timedelta(hours=1)).strftime('%Y-%m-%d %H:%M:%S'))
                    ).fetchone()
                    one_day = c.execute(
                        f"SELECT COUNT(*) FROM login_attempts WHERE {col}=? AND success=0 AND datetime(timestamp)>=datetime(?)",
                        (val, (now_ts - timedelta(hours=24)).strftime('%Y-%m-%d %H:%M:%S'))
                    ).fetchone()
                    cnt_1m = one_min[0] if one_min else 0
                    cnt_1h = one_hr[0] if one_hr else 0
                    cnt_24h = one_day[0] if one_day else 0
                    # 5级阈值完整匹配：LEVEL1 1m>5 / LEVEL2 1h>20 / LEVEL3 24h>50 / LEVEL4 24h>80 / LEVEL5 24h>=100
                    if cnt_1m > 5 or cnt_1h > 20 or cnt_24h >= 50:
                        if cnt_24h >= 100:
                            level = 5
                        elif cnt_24h >= 80:
                            level = 4
                        elif cnt_24h >= 50:
                            level = 3
                        elif cnt_1h > 20:
                            level = 2
                        else:
                            level = 1
                        lock_until = now_ts + timedelta(minutes=_security_lockout_time(level))
                        try:
                            c.execute(
                                "INSERT OR IGNORE INTO sec_bruteforce_locks (ip_addr,username,locked_until,reason,unlock_code,eigenflux_flag) VALUES (?,?,?,?,?,1)",
                                (ip if col == 'ip_address' else None,
                                 uname if col == 'username' else None,
                                 lock_until.strftime('%Y-%m-%d %H:%M:%S'),
                                 f'LEVEL{level}_bruteforce_{col}_1m{cnt_1m}_1h{cnt_1h}_24h{cnt_24h}',
                                 hashlib.md5(os.urandom(16)).hexdigest()[:16])
                            )
                            c.commit()
                        except Exception:
                            pass
                        try:
                            _security_audit_log('bruteforce', 'HIGH' if level>=3 else 'MEDIUM', f'防爆破LEVEL{level}锁 {col}={val} 1m={cnt_1m}/1h={cnt_1h}/24h={cnt_24h}', eigenflux_flag=1)
                        except Exception:
                            pass
                        try:
                            _security_report_anomaly(f'brute_level{level}_lock', {'col': col, 'val': val, 'level': level, 'cnt_1m': cnt_1m, 'cnt_1h': cnt_1h, 'cnt_24h': cnt_24h})
                        except Exception:
                            pass
                        return {'blocked': True, 'reason': f'bruteforce_lock_LEVEL{level}_{col}'}
        except Exception:
            pass
    except Exception:
        pass
    return {'blocked': False}


def _security_check_credential_stuffing():
    """防撞库：多账号同IP连续登录、密码长度固定+弱密码库top100匹配 — 所有命中都落库"""
    try:
        if not (request.path or '').lower().endswith('/login') or request.method != 'POST':
            return {'blocked': False}
        ip = request.remote_addr or 'unknown'
        data = request.get_json(force=True, silent=True) or {}
        form = request.form or {}
        uname = (data.get('username') or form.get('username') or '').strip()
        pwd = (data.get('password') or form.get('password') or '')
        now_ts = datetime.now()
        now_str = now_ts.strftime('%Y-%m-%d %H:%M:%S')
        # --- 弱密码命中：真落库（之前只audit_log没写表）---
        # ⚠️ 超级管理员例外：已改为 VIKEY + SZU100 双硬件认证，不再走密码通道，故无需弱密码检测
        if uname.lower() in _SA_HIDDEN_NAMES_LOWER:
            pass  # 超级管理员通过双硬件登录，无密码字段，不走弱密码检测
        elif _security_is_weak_password(pwd):
            try:
                with _get_conn(APP_DB) as c:
                    _ensure_security_schema(c)
                    c.execute(
                        "INSERT INTO sec_credential_stuffing_logs (ip_addr,batch_count,unique_accounts_attempted,detected_at,blocked,eigenflux_severity) VALUES (?,?,?,?,?,?)",
                        (ip, 0, 1, now_str, 1, 'WEAK_PASSWORD')
                    )
                    c.commit()
            except Exception:
                pass
            try:
                _security_audit_log('credential_stuffing', 'HIGH', f'撞库弱密码匹配 IP={ip} user={uname}', eigenflux_flag=1)
            except Exception:
                pass
            try:
                _security_report_anomaly('stuffing_weak_password', {'ip': ip, 'username': uname})
            except Exception:
                pass
            return {'blocked': True, 'reason': 'weak_password_stuffing'}
        # --- 多账号同IP批量尝试：真落库（原本已写，这里保留并增强）---
        # 修复：用 datetime() 函数比较时间，避免 ISO 格式 timestamp 与空格分隔比较值字符串比较的 BUG
        # （同 _security_check_bruteforce 修复，详见上方注释）
        try:
            with _get_conn(APP_DB) as c:
                _ensure_security_schema(c)
                r = c.execute(
                    "SELECT COUNT(DISTINCT username) FROM login_attempts WHERE ip_address=? AND success=0 AND datetime(timestamp)>=datetime(?)",
                    (ip, (now_ts - timedelta(minutes=10)).strftime('%Y-%m-%d %H:%M:%S'))
                ).fetchone()
                distinct_users = r[0] if r else 0
                if distinct_users >= 5:
                    try:
                        c.execute(
                            "INSERT INTO sec_credential_stuffing_logs (ip_addr,batch_count,unique_accounts_attempted,detected_at,blocked,eigenflux_severity) VALUES (?,?,?,?,?,?)",
                            (ip, distinct_users, distinct_users, now_str, 1, 'HIGH')
                        )
                        c.commit()
                    except Exception:
                        pass
                    try:
                        _security_audit_log('credential_stuffing', 'CRITICAL', f'撞库特征 IP={ip} 10分钟内{distinct_users}个账号尝试', eigenflux_flag=1)
                    except Exception:
                        pass
                    try:
                        _security_report_anomaly('stuffing_batch_attack', {'ip': ip, 'distinct_users': distinct_users})
                    except Exception:
                        pass
                    return {'blocked': True, 'reason': 'credential_stuffing_pattern'}
        except Exception:
            pass
    except Exception:
        pass
    return {'blocked': False}


def _security_check_decompile_watermark():
    """反编译水印校验：POST含_debug_token但不等于SECURITY_WATERMARK → 404 + INSERT tamper_logs"""
    try:
        if request.method == 'POST':
            debug_token = None
            try:
                data = request.get_json(force=True, silent=True) or {}
                debug_token = data.get('_debug_token')
            except Exception:
                pass
            if debug_token is None:
                debug_token = request.form.get('_debug_token') if request.form else None
            if debug_token is not None:
                expected = app.config.get('SECURITY_WATERMARK', 'MTSCOS_SEC_DEFAULT_WM_2026')
                if str(debug_token) != str(expected):
                    ip = request.remote_addr or 'unknown'
                    ua = request.headers.get('User-Agent', '')[:300]
                    path = request.path or ''
                    # 真正写入篡改日志表（之前只UPDATE计数没写日志）
                    try:
                        with _get_conn(APP_DB) as c:
                            _ensure_security_schema(c)
                            c.execute(
                                "INSERT INTO sec_decompile_tamper_logs (ip_addr,user_agent,path,tamper_type,tamper_detail,eigenflux_flag) VALUES (?,?,?,?,?,1)",
                                (ip, ua, path, 'watermark_mismatch', f'token={str(debug_token)[:200]}')
                            )
                            c.execute(
                                "UPDATE sec_decompile_watermarks SET tamper_detected_count=tamper_detected_count+1 WHERE watermark_token=?",
                                (str(expected),)
                            )
                            c.commit()
                    except Exception:
                        pass
                    # 额外：UA含反编译工具关键字 → 单独再记一笔工具探测
                    tool_hit = None
                    for tool in ['pycdc', 'uncompyle', 'uncompyle6', 'decompyle', 'devtools', 'inspect', 'pyinstxtractor']:
                        if tool in (ua or '').lower():
                            tool_hit = tool
                            break
                    if tool_hit:
                        try:
                            with _get_conn(APP_DB) as c:
                                _ensure_security_schema(c)
                                c.execute(
                                    "INSERT INTO sec_decompile_tamper_logs (ip_addr,user_agent,path,tamper_type,tamper_detail,eigenflux_flag) VALUES (?,?,?,?,?,1)",
                                    (ip, ua, path, 'reverse_tool_detected', f'UA工具={tool_hit}')
                                )
                                c.commit()
                        except Exception:
                            pass
                    try:
                        _security_audit_log('decompile', 'CRITICAL', f'反编译调试探测 IP={ip} token={str(debug_token)[:50]} tool={tool_hit or "N/A"}', eigenflux_flag=1)
                    except Exception:
                        pass
                    try:
                        _security_report_anomaly('decompile_probe', {'ip': ip, 'tool': tool_hit, 'token': str(debug_token)[:100], 'ua': ua[:100]})
                    except Exception:
                        pass
                    return {'blocked': True, 'reason': 'decompile_probe_404'}
    except Exception:
        pass
    return {'blocked': False}


