def _h(s):
    """最小 HTML escape，独立路由内使用以避免依赖 Jinja2 过滤器"""
    return (str(s) if s is not None else '').replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;').replace("'", '&#39;')


