@app.route('/auth/forgot_password', methods=['GET', 'POST'])
@system_container('auth_forgot_password', require_auth='guest')
def forgot_password():
    v, info, _ = get_version_info()
    client_ip = request.remote_addr or 'unknown_ip'
    if request.method == 'POST':
        data = request.get_json(silent=True) or {}
        identifier = (
            data.get('username')
            or data.get('email')
            or data.get('identifier')
            or request.form.get('identifier')
            or ''
        ).strip()
        success_msg = None
        error_msg = None
        # ---------- 空标识 ----------
        if not identifier:
            if request.is_json or (data and (data.get('username') or data.get('email'))):
                ef = _ef_process_report_anomaly(
                    'invalid_request', 'auth_forgot_POST', 'LOW',
                    {'missing': 'identifier'}, client_ip=client_ip, client_ua=_ua())
                return jsonify({'success': False, 'message': '请输入用户名或邮箱',
                                '_eigenflux': _ef_strip(ef)}), 400
            error_msg = '请输入用户名或邮箱'
        # ---------- SA保护 ----------
        if identifier and str(identifier).lower() in _SA_HIDDEN_NAMES_LOWER:
            ef = _ef_process_report_anomaly(
                'sa_reset_blocked', 'auth_forgot_POST', 'HIGH',
                {'target_identifier': identifier,
                 'note': '超级管理员账号不可通过公开忘记密码页重置，请使用Vikey或联系管理员'},
                operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
            msg = '该账号为超级管理员/保留账号，不可通过公开忘记密码页重置。请使用 Vikey 硬件授权或联系管理员。'
            if request.is_json:
                return jsonify({'success': False, 'message': msg, '_eigenflux': _ef_strip(ef)}), 403
            error_msg = msg
        # ---------- 双维度速率限制 ----------
        if identifier and not error_msg:
            now = time.time()
            # 1) IP维度
            if client_ip not in _MT_FORGOT_LIMIT_IP:
                _MT_FORGOT_LIMIT_IP[client_ip] = []
            _MT_FORGOT_LIMIT_IP[client_ip] = [t for t in _MT_FORGOT_LIMIT_IP[client_ip] if now - t < _MT_FORGOT_WINDOW]
            ip_hit = len(_MT_FORGOT_LIMIT_IP[client_ip]) >= _MT_FORGOT_MAX_PER_IP
            # 2) 用户维度
            ident_key = str(identifier).lower().strip()
            if ident_key and ident_key not in _MT_FORGOT_LIMIT_USER:
                _MT_FORGOT_LIMIT_USER[ident_key] = []
            _MT_FORGOT_LIMIT_USER[ident_key] = [t for t in _MT_FORGOT_LIMIT_USER.get(ident_key, []) if now - t < _MT_FORGOT_WINDOW]
            user_hit = len(_MT_FORGOT_LIMIT_USER.get(ident_key, [])) >= _MT_FORGOT_MAX_PER_USER
            if ip_hit or user_hit:
                ef = _ef_process_report_anomaly(
                    'abuse_rate_limit', 'auth_forgot_POST', 'HIGH',
                    {'target': identifier, 'ip': client_ip,
                     'ip_count': len(_MT_FORGOT_LIMIT_IP.get(client_ip, [])),
                     'user_count': len(_MT_FORGOT_LIMIT_USER.get(ident_key, [])),
                     'ip_limit': _MT_FORGOT_MAX_PER_IP, 'user_limit': _MT_FORGOT_MAX_PER_USER,
                     'window_sec': _MT_FORGOT_WINDOW,
                     'which_limit': 'IP' if ip_hit else 'USER'},
                    operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
                msg = '重置请求过于频繁，请1小时后再试'
                if request.is_json:
                    return jsonify({'success': False, 'message': msg, '_eigenflux': _ef_strip(ef)}), 429
                error_msg = msg
            # 通过了：加计数
            if not error_msg:
                _MT_FORGOT_LIMIT_IP.setdefault(client_ip, []).append(now)
                if ident_key:
                    _MT_FORGOT_LIMIT_USER.setdefault(ident_key, []).append(now)
        # ---------- 主逻辑：跨库查 → 强随机重置 → read-back验证哈希 ----------
        if identifier and not error_msg:
            target_user_db = None
            target_row = None
            try:
                # 关键修复：用 _find_user_across_dbs 跨所有库查（不局限AUTH_DB）
                # _find_user_across_dbs 返回 (row_dict, db_path)
                target_row_dict, target_user_db = _find_user_across_dbs(identifier)
                # 兼容：如果返回dict但缺少email等，再按真实用户表取完整row
                if target_row_dict and target_user_db:
                    try:
                        with _get_conn(target_user_db) as conn:
                            conn.row_factory = sqlite3.Row
                            uid_ = target_row_dict.get('id')
                            uname_ = target_row_dict.get('username') or ''
                            r = None
                            if uid_:
                                r = conn.execute(
                                    "SELECT id, username, email, is_active, password, role, super_admin_approved "
                                    "FROM users WHERE id = ? LIMIT 1", (uid_,)).fetchone()
                            if not r and uname_:
                                r = conn.execute(
                                    "SELECT id, username, email, is_active, password, role, super_admin_approved "
                                    "FROM users WHERE lower(username)=? OR lower(email)=? LIMIT 1",
                                    (uname_.lower(), uname_.lower())).fetchone()
                            if r:
                                target_row = dict(r)
                    except Exception:
                        target_row = target_row_dict if isinstance(target_row_dict, dict) else None
                elif target_row_dict:
                    target_row = target_row_dict if isinstance(target_row_dict, dict) else None

                if not target_row:
                    ef = _ef_process_report_anomaly(
                        'user_not_found', 'auth_forgot_POST', 'MEDIUM',
                        {'target': identifier,
                         'note': '跨库搜索未找到对应用户名/邮箱（新注册用户可能在APP_DB而不是AUTH_DB）'},
                        operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
                    if request.is_json:
                        return jsonify({'success': False, 'message': '未找到该用户',
                                        '_eigenflux': _ef_strip(ef)}), 404
                    error_msg = '未找到该用户'
                else:
                    row_ = target_row
                    is_active = row_.get('is_active')
                    if is_active in (0, False, '0'):
                        ef = _ef_process_report_anomaly(
                            'user_disabled', 'auth_forgot_POST', 'HIGH',
                            {'target': identifier, 'uid': row_.get('id'),
                             'db': os.path.basename(target_user_db) if target_user_db else None},
                            operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
                        if request.is_json:
                            return jsonify({'success': False, 'message': '账户已被禁用',
                                            '_eigenflux': _ef_strip(ef)}), 403
                        error_msg = '账户已被禁用'
                    else:
                        if not target_user_db:
                            # 没拿到db路径——不可能写回
                            ef = _ef_process_report_anomaly(
                                'db_write_error', 'auth_forgot_POST', 'CRITICAL',
                                {'target': identifier, 'uid': row_.get('id'),
                                 'reason': '_find_user_across_dbs未返回user_db路径，无法写回'},
                                operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
                            if request.is_json:
                                return jsonify({'success': False, 'message': '内部错误：无法定位用户数据库',
                                                '_eigenflux': _ef_strip(ef)}), 500
                            error_msg = '内部错误：无法定位用户数据库'
                        else:
                            # 生成强随机重置密码 + 写回
                            new_pw = _generate_strong_reset_pw(14)
                            new_hash = _hash_password(new_pw)
                            uid = row_.get('id')
                            verify_hash_ok = False
                            verify_hash_issues = []
                            try:
                                with _get_conn(target_user_db) as conn:
                                    conn.execute(
                                        "UPDATE users SET password = ?, updated_at = ?, failed_login_count = 0, locked_until = NULL "
                                        "WHERE id = ?",
                                        (new_hash, datetime.now().isoformat(), uid)
                                    )
                                    conn.commit()
                                    # read-back 验证哈希
                                    try:
                                        conn.row_factory = sqlite3.Row
                                        rb = conn.execute(
                                            "SELECT password FROM users WHERE id = ? LIMIT 1", (uid,)
                                        ).fetchone()
                                        if rb and rb['password']:
                                            if _verify_password(new_pw, rb['password']):
                                                verify_hash_ok = True
                                            else:
                                                verify_hash_issues.append('read_back_hash_not_match_new_pw')
                                        else:
                                            verify_hash_issues.append('read_back_password_column_empty')
                                    except Exception as ve:
                                        verify_hash_issues.append('read_back_exception:' + str(ve)[:80])
                            except sqlite3.Error as dbe:
                                ef = _ef_process_report_anomaly(
                                    'db_write_error', 'auth_forgot_POST', 'HIGH',
                                    {'target': identifier, 'uid': uid,
                                     'db': os.path.basename(target_user_db),
                                     'error': str(dbe)},
                                    operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
                                if request.is_json:
                                    return jsonify({'success': False, 'message': f'重置失败：{dbe}',
                                                    '_eigenflux': _ef_strip(ef)}), 500
                                error_msg = f'重置失败：{dbe}'
                                continue_flag = False
                            else:
                                continue_flag = True
                            if not continue_flag:
                                pass
                            elif not verify_hash_ok:
                                # 写成功但哈希验证失败：EF告警+返回（但密码已改，避免误导）
                                ef = _ef_process_report_anomaly(
                                    'hash_mismatch', 'auth_forgot_POST', 'CRITICAL',
                                    {'target': identifier, 'uid': uid,
                                     'db': os.path.basename(target_user_db),
                                     'verify_issues': verify_hash_issues,
                                     'note': 'UPDATE返回成功但read-back哈希验证失败（列名/回滚/数据库损坏？）'},
                                    operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
                                msg = (f'密码已重置为：{new_pw}（请登录后立即修改）'
                                       f'\n⚠️ 系统内部自检：写回后哈希验证失败——已记录AI员工审计。')
                                if request.is_json:
                                    ef_out = _ef_strip(ef)
                                    ef_out['warn'] = True
                                    ef_out['verify_issues'] = verify_hash_issues
                                    return jsonify({
                                        'success': True,
                                        'message': msg,
                                        'redirect': '/',
                                        '_eigenflux': ef_out,
                                    })
                                success_msg = msg
                            else:
                                # 全部成功
                                ef = _ef_process_report_anomaly(
                                    'password_reset_success', 'auth_forgot_POST', 'LOW',
                                    {'target': identifier, 'uid': uid,
                                     'db': os.path.basename(target_user_db),
                                     'pw_len': len(new_pw)},
                                    notify_ai_employees=False,
                                    operator_user=identifier or 'anonymous',
                                    client_ip=client_ip, client_ua=_ua())
                                msg = f'密码已重置为：{new_pw}（请登录后立即修改）'
                                if request.is_json:
                                    return jsonify({
                                        'success': True, 'message': msg, 'redirect': '/',
                                        '_eigenflux': _ef_strip(ef)
                                    })
                                success_msg = msg
            except Exception as e:
                ef = _ef_process_report_anomaly(
                    'forgot_internal_error', 'auth_forgot_POST', 'HIGH',
                    {'target': identifier, 'error': str(e),
                     'traceback': (str(getattr(e, '__traceback__', ''))[:200] if False else '')},
                    operator_user=identifier or 'anonymous', client_ip=client_ip, client_ua=_ua())
                if request.is_json:
                    return jsonify({'success': False, 'message': f'重置失败：{e}',
                                    '_eigenflux': _ef_strip(ef)}), 500
                error_msg = f'重置失败：{e}'
        # ---------- form POST 渲染模板 ----------
        if request.method == 'POST' and not request.is_json:
            return render_template(
                'forgot_password.html',
                success=success_msg,
                error=error_msg,
                version=v,
                version_info=info,
            )
    return render_template('forgot_password.html', version=v, version_info=info)


@app.route('/settings')
@system_container('settings', require_auth='login')
def settings_page():
    """设置页：所有登录角色统一渲染；SA/admin 不再跳 dashboard（避免丢失 username/version 参数校验）
    信息绑数据库：所有字段从 DB 读取真实值，并同步 session，确保前后端一致。
    """
    if not session.get('username'):
        return redirect('/')
    role = (session.get('role') or 'user').lower()
    username = (session.get('username') or '').lower()
    # SA / admin 不再重定向，直接渲染 settings.html
    v, info, _ = get_version_info()
    uid = session.get('user_id')
    user_dict = {
        'id': uid,
        'username': session.get('username'),
        'email': session.get('email') or '',
        'phone': session.get('phone') or '',
        'grade': session.get('grade') or '',
        'education_type': session.get('education_type') or 'K12',
        'education_stage': session.get('education_stage') or '',
        'signature': session.get('signature') or '',
        'score': session.get('score') or 0,
        'role': session.get('role') or 'user',
        'real_name': session.get('real_name') or '',
        'age': session.get('age') or 0,
        'ssl_binding_status': 'unbound',
        'ssl_binding_count': 0,
        'ssl_grace_period_until': '',
        'fingerprint_enabled': False,
    }
    try:
        if os.path.exists(AUTH_DB) and uid:
            with _get_conn(AUTH_DB) as conn:
                # EigenFlux：确保列存在（兼容旧库）
                for col, decl in [('grade', 'TEXT'), ('education_type', 'TEXT'),
                                  ('education_stage', 'TEXT'), ('signature', 'TEXT'),
                                  ('score', 'INTEGER DEFAULT 0'), ('age', 'INTEGER DEFAULT 0'),
                                  ('real_name', 'TEXT'), ('phone', 'TEXT'),
                                  ('ssl_binding_status', "TEXT DEFAULT 'unbound'"),
                                  ('ssl_binding_count', 'INTEGER DEFAULT 0'),
                                  ('ssl_grace_period_until', 'TEXT'),
                                  ('fingerprint_enabled', 'INTEGER DEFAULT 0')]:
                    try:
                        conn.execute(f"ALTER TABLE users ADD COLUMN {col} {decl}")
                    except Exception:
                        pass
                # EigenFlux 修复：跨 db 的 id 不一致（auth.db id=4 是 caopw，app.db id=5 是 caopw；
                # 若 session.uid 来自 app.db(=5) 直接按 id 查 auth.db 会拿到 test_parent(家长) 的数据）
                # 改为 username 优先 + id fallback：username 是跨 db 一致的语义主键
                sess_username = (session.get('username') or '').strip()
                if sess_username:
                    row = conn.execute(
                        "SELECT email, phone, grade, education_type, education_stage, signature, score, role, super_admin_approved, age, real_name, ssl_binding_status, ssl_binding_count, ssl_grace_period_until, fingerprint_enabled FROM users WHERE username = ? COLLATE NOCASE LIMIT 1",
                        (sess_username,)
                    ).fetchone()
                else:
                    row = None
                if row is None and uid:
                    # 仅当 username 查不到时才用 uid 兜底（避免历史 session 无 username 的情况）
                    row = conn.execute(
                        "SELECT email, phone, grade, education_type, education_stage, signature, score, role, super_admin_approved, age, real_name, ssl_binding_status, ssl_binding_count, ssl_grace_period_until, fingerprint_enabled FROM users WHERE id = ? LIMIT 1",
                        (uid,)
                    ).fetchone()
                if row:
                    user_dict['email'] = row['email'] or ''
                    user_dict['phone'] = row['phone'] or ''
                    user_dict['grade'] = row['grade'] or ''
                    user_dict['education_type'] = row['education_type'] or 'K12'
                    user_dict['education_stage'] = row['education_stage'] or ''
                    user_dict['signature'] = row['signature'] or ''
                    user_dict['score'] = row['score'] or 0
                    user_dict['role'] = row['role'] or user_dict['role']
                    user_dict['age'] = row['age'] or 0
                    user_dict['real_name'] = row['real_name'] or ''
                    user_dict['fingerprint_enabled'] = bool(row['fingerprint_enabled'])
                    # 信息绑数据库：同步 session，确保后续页面读取一致
                    session['email'] = user_dict['email']
                    session['phone'] = user_dict['phone']
                    session['grade'] = user_dict['grade']
                    session['education_type'] = user_dict['education_type']
                    session['education_stage'] = user_dict['education_stage']
                    session['signature'] = user_dict['signature']
                    session['score'] = user_dict['score']
                    session['age'] = user_dict['age']
                    session['real_name'] = user_dict['real_name']
        # SSL 绑定状态从 APP_DB 读取（SSL 绑定逻辑存储在 app.db）
        try:
            if os.path.exists(APP_DB) and uid:
                with _get_conn(APP_DB) as conn:
                    # 确保 SSL 字段存在
                    for col, decl in [('ssl_binding_status', "TEXT DEFAULT 'unbound'"),
                                      ('ssl_binding_count', 'INTEGER DEFAULT 0'),
                                      ('ssl_grace_period_until', 'TEXT')]:
                        try:
                            conn.execute(f"ALTER TABLE users ADD COLUMN {col} {decl}")
                        except Exception:
                            pass
                    sess_username = (session.get('username') or '').strip()
                    ssl_row = None
                    if sess_username:
                        ssl_row = conn.execute(
                            "SELECT ssl_binding_status, ssl_binding_count, ssl_grace_period_until FROM users WHERE username = ? COLLATE NOCASE LIMIT 1",
                            (sess_username,)
                        ).fetchone()
                    if ssl_row is None and uid:
                        ssl_row = conn.execute(
                            "SELECT ssl_binding_status, ssl_binding_count, ssl_grace_period_until FROM users WHERE id = ? LIMIT 1",
                            (uid,)
                        ).fetchone()
                    if ssl_row:
                        user_dict['ssl_binding_status'] = ssl_row['ssl_binding_status'] or 'unbound'
                        user_dict['ssl_binding_count'] = ssl_row['ssl_binding_count'] or 0
                        user_dict['ssl_grace_period_until'] = ssl_row['ssl_grace_period_until'] or ''
        except Exception:
            pass
    except Exception:
        pass
    if role == 'teacher':
        template_name = 'teacher_settings.html'
    elif role in ('student', 'student_vip', '成人学生'):
        template_name = 'student_settings.html'
    elif role in ('parent', '家长'):
        template_name = 'parent_settings.html'
    else:
        template_name = 'settings.html'
    return render_template(template_name,
                           version=v,
                           version_info=info,
                           user=user_dict,
                           current_user=user_dict,
                           csrf_token=session.get('csrf_token', ''))


@app.route('/api/student/save_profile', methods=['POST'])
@system_container('settings', require_auth='login')
def api_student_save_profile():
    """学生设置页 - 真实数据库保存 API
    注意：education_type（教育组别）由数据库锁定，不可通过此接口修改。
    如需变更组别，需通过 /api/student/apply_education_type 提交审批申请。
    审批流程：提交 → 2名及以上管理员批准 → 或 SA 直接批准 → 才最终落库。
    """
    if not session.get('username'):
        return jsonify({'success': False, 'error': '未登录'}), 401
    uid = session.get('user_id')
    if not uid:
        return jsonify({'success': False, 'error': '会话无效'}), 401
    data = request.get_json(silent=True) or {}
    username = session.get('username', '')
    if not username:
        return jsonify({'success': False, 'error': '会话无效'}), 401

    # ===== 教育组别锁定：禁止通过此接口修改 =====
    if 'education_type' in data:
        return jsonify({
            'success': False, 'error': 'EDU_TYPE_LOCKED',
            'message': '教育组别由数据库锁定，不可直接修改。请点击"申请变更教育组别"提交审批申请。'
        }), 403

    # 允许直接修改的字段
    allowed_fields = {
        'email': str,
        'phone': str,
        'grade': str,
        'education_stage': str,
        'signature': str,
    }
    updates = {}
    for field, caster in allowed_fields.items():
        if field in data:
            val = data[field]
            if val is not None:
                val = caster(val)[:500] if field != 'phone' else caster(val)[:20]
            updates[field] = val

    # ===== 3档教育一致性后端校验（防止绕过前端 JS 直接调 API）=====
    # 3档: K12 / higher / adult
    _TIER_GRADES = {
        'K12': ['一年级','二年级','三年级','四年级','五年级','六年级','初一','初二','初三','高一','高二','高三'],
        'higher': ['大一','大二','大三','大四','研一','研二','研三'],
        'adult': ['第一年','第二年','第三年','第四年'],
    }
    new_grade = updates.get('grade')
    new_stage = updates.get('education_stage')
    # 取当前 edu_type（session 或 db）
    cur_edu_type = ''
    try:
        with _get_conn(AUTH_DB) as conn:
            row = conn.execute(
                "SELECT education_type FROM users WHERE username=? COLLATE NOCASE LIMIT 1",
                (username,)
            ).fetchone()
            if row:
                cur_edu_type = (row['education_type'] or '').strip()
    except Exception:
        pass
    if not cur_edu_type:
        cur_edu_type = 'K12'
    # 标准化 tier
    tier = 'K12' if cur_edu_type.lower() == 'k12' else cur_edu_type
    conflicts = []
    if new_grade:
        expected = _TIER_GRADES.get(tier, [])
        if new_grade not in expected:
            conflicts.append(f'年级"{new_grade}"不属于{_EDUCATION_TYPE_CN.get(tier, tier)}组别，可选：{"、".join(expected)}')
    if conflicts:
        return jsonify({
            'success': False, 'error': 'EDU_CONFLICT',
            'message': '教育字段一致性校验失败：' + '；'.join(conflicts) + '。请调整年级到对应组别范围内，或申请变更教育组别。',
            'conflicts': conflicts, 'current_education_type': cur_edu_type,
        }), 400

    # ===== 保存允许直接修改的字段 =====
    if updates:
        try:
            from core.db_path import get_db_path
            sync_dbs = [AUTH_DB]
            for db_name in ['app.db', 'auth.db']:
                p = get_db_path(db_name)
                if p and os.path.exists(p) and p not in sync_dbs:
                    sync_dbs.append(p)
            total_affected = 0
            for db_path in sync_dbs:
                try:
                    with _get_conn(db_path) as conn:
                        for col, decl in [('grade', 'TEXT'), ('education_stage', 'TEXT'),
                                          ('signature', 'TEXT'), ('score', 'INTEGER DEFAULT 0'),
                                          ('email', 'TEXT'), ('phone', 'TEXT')]:
                            try:
                                conn.execute(f"ALTER TABLE users ADD COLUMN {col} {decl}")
                            except Exception:
                                pass
                        set_clause = ', '.join([f"{k} = ?" for k in updates])
                        values = list(updates.values()) + [datetime.now().strftime('%Y-%m-%d %H:%M:%S'), username]
                        cur = conn.execute(
                            f"UPDATE users SET {set_clause}, updated_at = ? WHERE username = ?",
                            values
                        )
                        conn.commit()
                        total_affected += cur.rowcount
                except Exception:
                    continue
            # 信息绑数据库：保存成功后同步 session
            for k, v in updates.items():
                try:
                    session[k] = v
                except Exception:
                    pass
            resp = {
                'success': True, 'message': '设置已保存', 'affected': total_affected,
                'updated_fields': updates,
                'user': {
                    'email': updates.get('email', session.get('email') or ''),
                    'phone': updates.get('phone', session.get('phone') or ''),
                    'grade': updates.get('grade', session.get('grade') or ''),
                    'education_stage': updates.get('education_stage', session.get('education_stage') or ''),
                    'signature': updates.get('signature', session.get('signature') or ''),
                },
            }
        except Exception as e:
            resp = {'success': False, 'error': f'保存失败: {str(e)}'}
    else:
        resp = {'success': True, 'message': '无需保存的字段'}

    return jsonify(resp)


@app.route('/api/student/apply_education_type', methods=['POST'])
@system_container('settings', require_auth='login')
def api_apply_education_type():
    """提交教育组别变更申请（3档：K12 / higher / adult）
    审批流程：提交 → 2名及以上管理员批准 → 或 SA 直接批准 → 才最终落库。
    """
    if not session.get('username'):
        return jsonify({'success': False, 'error': '未登录'}), 401
    username = session.get('username', '')
    uid = session.get('user_id')
    data = request.get_json(silent=True) or {}
    new_type = str(data.get('new_education_type') or '').strip()
    reason = str(data.get('reason') or '').strip()[:500]

    # 校验目标组别必须是3档之一
    if new_type not in _ADMIN_EDUCATION_TYPE_WHITELIST:
        return jsonify({
            'success': False,
            'error': 'INVALID_EDU_TYPE',
            'message': f'教育组别只能是：{"、".join(_EDUCATION_TYPE_CN.values())}',
        }), 400

    # 获取当前组别
    cur_type = ''
    try:
        with _get_conn(AUTH_DB) as conn:
            row = conn.execute(
                "SELECT education_type FROM users WHERE username=? COLLATE NOCASE LIMIT 1",
                (username,)
            ).fetchone()
            if row:
                cur_type = (row['education_type'] or '').strip()
    except Exception:
        pass
    if cur_type == new_type:
        return jsonify({'success': False, 'message': '您当前已是该组别'}), 400

    # 检查是否有待审批的申请
    try:
        with _get_conn(AUTH_DB) as conn:
            row = conn.execute(
                "SELECT education_apply_status FROM users WHERE username=? COLLATE NOCASE LIMIT 1",
                (username,)
            ).fetchone()
            if row and row['education_apply_status'] == 'pending':
                return jsonify({'success': False, 'message': '您已有待审批的教育组别申请，请等待审批结果'}), 409
    except Exception:
        pass

    # 提交申请 → 写入 pending_education_apply
    import json as _rj
    now_iso = datetime.now().isoformat()
    apply_json = _rj.dumps({
        'requested': new_type,
        'requested_cn': _EDUCATION_TYPE_CN.get(new_type, new_type),
        'reason': reason,
        'requested_at': now_iso,
        'status': 'pending',
        'approvers': [],
        'approved_count': 0,
        'sa_approved': False,
        'reviewed_at': None,
        'review_comment': None,
    }, ensure_ascii=False)
    try:
        with _get_conn(AUTH_DB) as conn:
            for col, decl in [('pending_education_apply', 'TEXT'),
                              ('education_apply_status', "TEXT DEFAULT 'none'"),
                              ('education_apply_approved_at', 'TEXT')]:
                try:
                    conn.execute(f"ALTER TABLE users ADD COLUMN {col} {decl}")
                except sqlite3.Error:
                    pass
            conn.execute(
                "UPDATE users SET pending_education_apply=?, education_apply_status='pending', "
                "updated_at=? WHERE username=? COLLATE NOCASE",
                (apply_json, now_iso, username)
            )
            conn.commit()
        return jsonify({
            'success': True,
            'message': f'✅ 已提交【{_EDUCATION_TYPE_CN.get(new_type, new_type)}】组别申请，需2名管理员或SA审批通过后生效',
            'pending': True,
            'applied_type': new_type,
            'applied_cn': _EDUCATION_TYPE_CN.get(new_type, new_type),
        })
    except Exception as e:
        return jsonify({'success': False, 'message': f'申请提交失败: {str(e)}'}), 500


@app.route('/api/admin/approve_education_type', methods=['POST'])
@system_container('admin_dashboard', require_auth='admin', allowed_roles=['admin', 'super_admin'])
def api_admin_approve_education_type():
    """管理员审批教育组别变更申请
    - 需2名及以上管理员批准 → 生效
    - SA 直接批准 → 生效
    """
    if not session.get('username'):
        return jsonify({'success': False, 'error': '未登录'}), 401
    approver = session.get('username', '')
    approver_role = (session.get('role') or '').lower()
    is_sa = approver == 'wuchenghao15' or approver_role in ('super_admin', 'sadmin')

    data = request.get_json(silent=True) or {}
    target_user = str(data.get('username') or '').strip()
    action = str(data.get('action') or '').strip()  # 'approve' or 'reject'
    comment = str(data.get('comment') or '').strip()[:500]

    if not target_user or action not in ('approve', 'reject'):
        return jsonify({'success': False, 'message': '参数不完整'}), 400

    # 读取用户申请
    import json as _rj
    try:
        with _get_conn(AUTH_DB) as conn:
            row = conn.execute(
                "SELECT id, pending_education_apply, education_apply_status FROM users WHERE username=? COLLATE NOCASE LIMIT 1",
                (target_user,)
            ).fetchone()
            if not row:
                return jsonify({'success': False, 'message': '用户不存在'}), 404
            if row['education_apply_status'] != 'pending':
                return jsonify({'success': False, 'message': '该用户没有待审批的申请'}), 400
            apply_data = _rj.loads(row['pending_education_apply'] or '{}')
    except Exception as e:
        return jsonify({'success': False, 'message': f'读取申请失败: {str(e)}'}), 500

    if action == 'reject':
        apply_data['status'] = 'rejected'
        apply_data['reviewed_at'] = datetime.now().isoformat()
        apply_data['review_comment'] = comment or '管理员驳回'
        apply_data['rejected_by'] = approver
        try:
            with _get_conn(AUTH_DB) as conn:
                conn.execute(
                    "UPDATE users SET pending_education_apply=?, education_apply_status='rejected', updated_at=? WHERE username=? COLLATE NOCASE",
                    (_rj.dumps(apply_data, ensure_ascii=False), datetime.now().strftime('%Y-%m-%d %H:%M:%S'), target_user)
                )
                conn.commit()
            return jsonify({'success': True, 'message': f'✅ 已驳回【{target_user}】的组别申请'})
        except Exception as e:
            return jsonify({'success': False, 'message': f'驳回失败: {str(e)}'}), 500

    # approve
    requested_type = apply_data.get('requested', '')
    approvers_list = apply_data.get('approvers', [])
    sa_approved = apply_data.get('sa_approved', False)

    # SA 直接批准 → 生效
    if is_sa:
        apply_data['sa_approved'] = True
        apply_data['approvers'].append(approver)
        apply_data['approved_count'] = len(set(apply_data['approvers']))
        apply_data['status'] = 'approved'
        apply_data['reviewed_at'] = datetime.now().isoformat()
        apply_data['review_comment'] = comment or 'SA批准'
        apply_data['approved_by'] = approver
        try:
            with _get_conn(AUTH_DB) as conn:
                conn.execute(
                    "UPDATE users SET education_type=?, pending_education_apply=?, education_apply_status='approved', education_apply_approved_at=?, updated_at=? WHERE username=? COLLATE NOCASE",
                    (requested_type, _rj.dumps(apply_data, ensure_ascii=False),
                     datetime.now().isoformat(), datetime.now().strftime('%Y-%m-%d %H:%M:%S'), target_user)
                )
                conn.commit()
            # 同步到 app.db
            from core.db_path import get_db_path
            for db_name in ['app.db']:
                p = get_db_path(db_name)
                if p and os.path.exists(p):
                    try:
                        with _get_conn(p) as conn2:
                            conn2.execute(
                                "UPDATE users SET education_type=?, updated_at=? WHERE username=? COLLATE NOCASE",
                                (requested_type, datetime.now().strftime('%Y-%m-%d %H:%M:%S'), target_user)
                            )
                            conn2.commit()
                    except Exception:
                        pass
            return jsonify({'success': True, 'message': f'✅ SA已批准【{target_user}】变更组别为【{_EDUCATION_TYPE_CN.get(requested_type, requested_type)}】', 'effective': True})
        except Exception as e:
            return jsonify({'success': False, 'message': f'批准失败: {str(e)}'}), 500

    # 普通管理员 → 累计批准
    if approver in approvers_list:
        return jsonify({'success': False, 'message': '您已批准过此申请'}), 400
    approvers_list.append(approver)
    apply_data['approvers'] = approvers_list
    apply_data['approved_count'] = len(set(approvers_list))

    # 检查是否达到2人
    if apply_data['approved_count'] >= 2:
        apply_data['status'] = 'approved'
        apply_data['reviewed_at'] = datetime.now().isoformat()
        apply_data['review_comment'] = comment or f'{apply_data["approved_count"]}名管理员批准'
        try:
            with _get_conn(AUTH_DB) as conn:
                conn.execute(
                    "UPDATE users SET education_type=?, pending_education_apply=?, education_apply_status='approved', education_apply_approved_at=?, updated_at=? WHERE username=? COLLATE NOCASE",
                    (requested_type, _rj.dumps(apply_data, ensure_ascii=False),
                     datetime.now().isoformat(), datetime.now().strftime('%Y-%m-%d %H:%M:%S'), target_user)
                )
                conn.commit()
            # 同步到 app.db
            from core.db_path import get_db_path
            for db_name in ['app.db']:
                p = get_db_path(db_name)
                if p and os.path.exists(p):
                    try:
                        with _get_conn(p) as conn2:
                            conn2.execute(
                                "UPDATE users SET education_type=?, updated_at=? WHERE username=? COLLATE NOCASE",
                                (requested_type, datetime.now().strftime('%Y-%m-%d %H:%M:%S'), target_user)
                            )
                            conn2.commit()
                    except Exception:
                        pass
            return jsonify({
                'success': True,
                'message': f'✅ 已批准【{target_user}】变更组别为【{_EDUCATION_TYPE_CN.get(requested_type, requested_type)}】（{apply_data["approved_count"]}/2 管理员）',
                'effective': True,
                'approved_count': apply_data['approved_count'],
            })
        except Exception as e:
            return jsonify({'success': False, 'message': f'批准失败: {str(e)}'}), 500
    else:
        # 未达2人，仅记录
        apply_data['reviewed_at'] = datetime.now().isoformat()
        apply_data['review_comment'] = comment or '已记录批准'
        try:
            with _get_conn(AUTH_DB) as conn:
                conn.execute(
                    "UPDATE users SET pending_education_apply=?, updated_at=? WHERE username=? COLLATE NOCASE",
                    (_rj.dumps(apply_data, ensure_ascii=False), datetime.now().strftime('%Y-%m-%d %H:%M:%S'), target_user)
                )
                conn.commit()
            return jsonify({
                'success': True,
                'message': f'✅ 已批准【{target_user}】（{apply_data["approved_count"]}/2 管理员批准，还需{2-apply_data["approved_count"]}人）',
                'effective': False,
                'approved_count': apply_data['approved_count'],
            })
        except Exception as e:
            return jsonify({'success': False, 'message': f'批准失败: {str(e)}'}), 500


