@app.route('/api/teacher/session_status')
@system_container('teacher_session_status', require_auth='login', allowed_roles={'super_admin', 'sadmin', 'admin', 'teacher'})
def api_teacher_session_status():
    """教师工作台会话状态：基于 system_heartbeat 表返回真实系统健康状态（禁止硬编码）"""
    _ensure_system_heartbeat_ddls()
    try:
        with _get_conn(APP_DB) as c:
            rows = c.execute(
                "SELECT h.status, h.last_beat_at, h.beat_interval_sec FROM system_heartbeat h "
                "INNER JOIN (SELECT component_name, MAX(id) AS mid FROM system_heartbeat "
                "GROUP BY component_name) m ON h.id=m.mid"
            ).fetchall()
        now_dt = datetime.now()
        alive = 0
        degraded = 0
        dead = 0
        for r in rows:
            d = dict(r)
            status = d.get('status') or 'ALIVE'
            try:
                last_ts = datetime.strptime((d.get('last_beat_at') or '')[:19], '%Y-%m-%d %H:%M:%S')
                interval = int(d.get('beat_interval_sec') or 30)
                if (now_dt - last_ts).total_seconds() > interval * 3:
                    status = 'DEAD'
            except Exception:
                pass
            if status == 'ALIVE':
                alive += 1
            elif status == 'DEGRADED':
                degraded += 1
            else:
                dead += 1
        total = alive + degraded + dead
        if total == 0:
            result = {'status': 'online', 'label': '教学在线', 'dot_color': 'success'}
        elif dead > 0:
            result = {'status': 'offline', 'label': '系统异常', 'dot_color': 'danger'}
        elif degraded > 0:
            result = {'status': 'degraded', 'label': '系统降级', 'dot_color': 'warning'}
        else:
            result = {'status': 'online', 'label': '教学在线', 'dot_color': 'success'}
        result['summary'] = f'共{total}个组件，存活{alive}，降级{degraded}，离线{dead}'
        return jsonify({'ok': True, 'data': result})
    except Exception as e:
        logger.warning(f'[teacher_session_status] err: {e}')
        return jsonify({'ok': False, 'data': {'status': 'online', 'label': '教学在线', 'dot_color': 'success', 'summary': ''}, 'message': str(e)})


