def _qa_load_approval(emp):
    """对齐衡远加载关联的审批/版本/变更 链路闭环"""
    out = {"request_no": "-", "change_id": "-", "version": "v1.0", "version_id": "?", "change_pk": "?"}
    try:
        with _get_conn(APP_DB) as conn:
            r1 = conn.execute(
                "SELECT linked_approval_id,linked_change_id FROM mtscos_ai_employees WHERE uid=?",
                (emp["uid"],)
            ).fetchone()
            aid = r1["linked_approval_id"] if r1 and r1["linked_approval_id"] else None
            cid = r1["linked_change_id"] if r1 and r1["linked_change_id"] else None
            if aid:
                a = conn.execute("SELECT request_no FROM approvals WHERE id=?", (aid,)).fetchone()
                if a: out["request_no"] = a["request_no"]
                v = conn.execute("SELECT id,version FROM mtscos_version_history WHERE approval_id=? ORDER BY id DESC LIMIT 1", (aid,)).fetchone()
                if v:
                    out["version_id"] = str(v["id"])
                    out["version"] = v["version"]
            if cid:
                out["change_id"] = cid
                c = conn.execute("SELECT id FROM change_audit_log WHERE change_id=? ORDER BY id DESC LIMIT 1", (cid,)).fetchone()
                if c: out["change_pk"] = str(c["id"])
    except Exception:
        pass
    return out


