@app.route('/api/student_portal/dashboard')
@system_container('student_portal', require_auth='login')
def api_student_portal_dashboard():
    """学生学习仪表盘真实数据 API（经验312498：全部来自真实 SQLite 表，禁止假数据）"""
    uid = session.get('user_id')
    if not uid:
        return jsonify({'success': False, 'error': '未登录'}), 401
    try:
        uid_int = int(uid)
    except Exception:
        uid_int = 0
    uid_str = str(uid)
    if uid_int <= 0:
        return jsonify({'success': False, 'error': '会话无效'}), 401

    today = datetime.now().date()
    week_start = (today - timedelta(days=6)).isoformat()

    # ----- 1. 可用考试 / 测试计数（跨库真实 COUNT）-----
    exam_count = 0
    test_count = 0
    for _p in [APP_DB, SPLIT_EXAM_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                for _tn, _sql in [('teacher_exams', "SELECT COUNT(*) FROM teacher_exams"),
                                  ('exams', "SELECT COUNT(*) FROM exams")]:
                    try:
                        if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (_tn,)).fetchone():
                            _r = _c.execute(_sql).fetchone()
                            if _r:
                                exam_count += int(_r[0] or 0)
                    except Exception:
                        pass
                try:
                    if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='papers'").fetchone():
                        _r = _c.execute("SELECT COUNT(*) FROM papers").fetchone()
                        if _r:
                            test_count += int(_r[0] or 0)
                except Exception:
                    pass
        except Exception:
            pass

    # ----- 2. 每日练习计数（当前用户 daily_practice 记录数）-----
    practice_count = 0
    for _p in [APP_DB, SPLIT_LEARNING_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='daily_practice'").fetchone():
                    _r = _c.execute("SELECT COUNT(*) FROM daily_practice WHERE user_id=?", (uid_int,)).fetchone()
                    if _r:
                        practice_count += int(_r[0] or 0)
                    break
        except Exception:
            pass

    # ----- 3. 学习积分（users.score 与 k12_game_points.total_points 取较大值）-----
    points = 0
    try:
        with _get_conn(AUTH_DB) as _c:
            _r = _c.execute("SELECT score FROM users WHERE id=?", (uid_int,)).fetchone()
            if _r and _r[0]:
                points = int(_r[0])
    except Exception:
        pass
    for _p in [APP_DB, SPLIT_LEARNING_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='k12_game_points'").fetchone():
                    _r = _c.execute("SELECT total_points FROM k12_game_points WHERE user_id=?", (uid_int,)).fetchone()
                    if _r and _r[0] and int(_r[0]) > points:
                        points = int(_r[0])
                    break
        except Exception:
            pass

    # ----- 4. 连续学习天数（daily_practice / learning_calendar 最大 streak_days）-----
    streak_days = 0
    for _p in [APP_DB, SPLIT_LEARNING_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                for _tn in ['daily_practice', 'learning_calendar']:
                    if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (_tn,)).fetchone():
                        _r = _c.execute(f"SELECT MAX(streak_days) FROM {_tn} WHERE user_id=?", (uid_int,)).fetchone()
                        if _r and _r[0] and int(_r[0]) > streak_days:
                            streak_days = int(_r[0])
            if streak_days > 0:
                break
        except Exception:
            pass

    # ----- 5. 近 7 日学习时长（分钟）：聚合 study_records / learning_stats / learning_calendar -----
    last_7_days_mins = [0, 0, 0, 0, 0, 0, 0]
    labels = []
    day_map = {}
    for i in range(6, -1, -1):
        _d = today - timedelta(days=i)
        day_map[_d.isoformat()] = 6 - i
        labels.append('今' if i == 0 else ('昨' if i == 1 else f'D-{i}'))
    for _p in [APP_DB, SPLIT_LEARNING_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='study_records'").fetchone():
                    for _r in _c.execute(
                        "SELECT created_at, duration FROM study_records WHERE user_id=? AND created_at >= ?",
                        (uid_str, week_start)
                    ).fetchall():
                        try:
                            _ts = str(_r[0] or '')[:10]
                            if _ts in day_map:
                                _dur = int(_r[1] or 0)
                                last_7_days_mins[day_map[_ts]] += (_dur // 60) if _dur >= 60 else _dur
                        except Exception:
                            pass
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='learning_stats'").fetchone():
                    for _r in _c.execute(
                        "SELECT stat_date, total_minutes FROM learning_stats WHERE user_id=? AND stat_date >= ?",
                        (uid_int, week_start)
                    ).fetchall():
                        try:
                            _ts = str(_r[0] or '')[:10]
                            if _ts in day_map:
                                last_7_days_mins[day_map[_ts]] += int(_r[1] or 0)
                        except Exception:
                            pass
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='learning_calendar'").fetchone():
                    for _r in _c.execute(
                        "SELECT checkin_date, study_minutes FROM learning_calendar WHERE user_id=? AND checkin_date >= ?",
                        (uid_int, week_start)
                    ).fetchall():
                        try:
                            _ts = str(_r[0] or '')[:10]
                            if _ts in day_map:
                                last_7_days_mins[day_map[_ts]] += int(_r[1] or 0)
                        except Exception:
                            pass
            if any(v > 0 for v in last_7_days_mins):
                break
        except Exception:
            pass

    # ----- 6. 学科掌握度（learning_progress.completed_units / total_units 聚合）-----
    mastery = {'chinese': 0, 'math': 0, 'english': 0, 'science': 0}
    subject_map = {
        '语文': 'chinese', 'chinese': 'chinese',
        '数学': 'math', 'math': 'math',
        '英语': 'english', 'english': 'english',
        '综合': 'science', 'science': 'science', '理化生': 'science', '物化生': 'science',
    }
    for _p in [APP_DB, SPLIT_LEARNING_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='learning_progress'").fetchone():
                    for _r in _c.execute(
                        "SELECT subject, total_units, completed_units FROM learning_progress WHERE user_id=?",
                        (uid_str,)
                    ).fetchall():
                        try:
                            _subj = str(_r[0] or '').strip()
                            _key = subject_map.get(_subj) or subject_map.get(_subj.lower())
                            if not _key:
                                continue
                            _tot = int(_r[1] or 0)
                            _comp = int(_r[2] or 0)
                            if _tot > 0:
                                _pct = int(_comp * 100 / _tot)
                                if _pct > mastery[_key]:
                                    mastery[_key] = _pct
                        except Exception:
                            pass
            if any(v > 0 for v in mastery.values()):
                break
        except Exception:
            pass

    weak_subjects = []
    for _name, _key, _icon in [('语文', 'chinese', 'book'), ('数学', 'math', 'square-root-variable'),
                                ('英语', 'english', 'language'), ('综合', 'science', 'flask')]:
        _m = mastery[_key]
        if 0 < _m < 75:
            weak_subjects.append({
                'name': _name, 'mastery': _m, 'level': 'mid' if _m >= 50 else 'high', 'icon': _icon
            })

    # ----- 7. 即将开始的考试（teacher_exams / exams，非 draft，按开始时间排序）-----
    upcoming_exams = []
    for _p in [APP_DB, SPLIT_EXAM_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='teacher_exams'").fetchone():
                    for _r in _c.execute(
                        "SELECT id, exam_name, subject, total_score, duration_min, start_time, end_time, status, questions_json "
                        "FROM teacher_exams WHERE status != 'draft' ORDER BY COALESCE(start_time, created_at) ASC LIMIT 10"
                    ).fetchall():
                        try:
                            _qj = _r[8] or '[]'
                            _qn = 0
                            try:
                                _parsed = json.loads(_qj) if isinstance(_qj, str) else _qj
                                _qn = len(_parsed) if isinstance(_parsed, list) else 0
                            except Exception:
                                pass
                            _tot_score = _r[3] or 100
                            upcoming_exams.append({
                                'id': _r[0], 'title': _r[1] or '未命名考试',
                                'subject': _r[2], 'total_score': _tot_score,
                                'duration': _r[4] or 60, 'start_time': _r[5] or '',
                                'end_time': _r[6] or '', 'status': _r[7] or '进行中',
                                'question_count': _qn,
                                'passing_score': int(_tot_score * 0.6),
                            })
                        except Exception:
                            pass
                if upcoming_exams:
                    break
        except Exception:
            pass

    # ----- 8. 最近通知（notifications 表，无则空列表）-----
    notifications = []
    try:
        with _get_conn(APP_DB) as _c:
            if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='notifications'").fetchone():
                for _r in _c.execute(
                    "SELECT id, title, content, notification_type, priority, is_read, created_at "
                    "FROM notifications ORDER BY created_at DESC LIMIT 10"
                ).fetchall():
                    try:
                        notifications.append({
                            'id': _r[0],
                            'title': _r[1] or '系统通知',
                            'content': _r[2] or '',
                            'type_label': _r[3] or 'info',
                            'priority': _r[4] or 'normal',
                            'is_read': int(_r[5] or 0),
                            'created_at': _r[6] or '',
                        })
                    except Exception:
                        pass
    except Exception:
        pass

    # ----- 9. 最近成就（k12_game_points.badges_json 解析，无则空列表）-----
    recent_achievements = []
    for _p in [APP_DB, SPLIT_LEARNING_DB, DATA_MTSCOS_DB]:
        if not (_p and os.path.exists(_p)):
            continue
        try:
            with _get_conn(_p) as _c:
                if _c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='k12_game_points'").fetchone():
                    _r = _c.execute(
                        "SELECT badges_json FROM k12_game_points WHERE user_id=?", (uid_int,)
                    ).fetchone()
                    if _r:
                        _bj = _r[0] or '[]'
                        try:
                            _badges = json.loads(_bj) if isinstance(_bj, str) else _bj
                        except Exception:
                            _badges = []
                        if isinstance(_badges, list):
                            for _b in _badges[:8]:
                                if isinstance(_b, dict):
                                    recent_achievements.append({
                                        'title': _b.get('title') or _b.get('name') or '成就徽章',
                                        'date': _b.get('date') or _b.get('earned_at') or '',
                                        'icon': _b.get('icon') or 'fa-medal',
                                        'tier': _b.get('tier') or 'purple',
                                        'is_new': bool(_b.get('is_new', False)),
                                    })
                    break
        except Exception:
            pass

    return jsonify({
        'success': True,
        'exam_count': exam_count,
        'test_count': test_count,
        'practice_count': practice_count,
        'stats': {
            'points': points,
            'streak_days': streak_days,
            'last_7_days_mins': last_7_days_mins,
            'last_7_days_labels': labels,
            'chinese_mastery': mastery['chinese'],
            'math_mastery': mastery['math'],
            'english_mastery': mastery['english'],
            'science_mastery': mastery['science'],
            'weak_subjects': weak_subjects,
        },
        'upcoming_exams': upcoming_exams,
        'notifications': notifications,
        'recent_achievements': recent_achievements,
    })


@app.route('/rss.xml')
def rss_feed():
    """RSS 订阅：返回系统更新与公告"""
    from datetime import datetime
    v, info, _ = get_version_info()
    items_xml = ''
    try:
        with _get_conn(AUTH_DB) as conn:
            rows = conn.execute(
                "SELECT * FROM system_versions ORDER BY rowid DESC LIMIT 10"
            ).fetchall() if os.path.exists(AUTH_DB) else []
        for row in rows:
            ver = dict(row) if row else {}
            title = f"v{ver.get('version', '?')} - {ver.get('codename', '')}"
            desc = ver.get('description', '') or ver.get('upgrade_notes', '') or ''
            dt = ver.get('build_date', '') or datetime.now().strftime('%Y-%m-%d')
            items_xml += f"""<item><title>{title}</title><description><![CDATA[{desc}]]></description><pubDate>{dt}</pubDate><guid>/history#{ver.get('version','')}</guid></item>"""
    except Exception:
        pass
    rss = f"""<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
<channel>
<title>MTSCOS AI 系统更新</title>
<link>{request.host_url}</link>
<description>MTSCOS AI 智能学习评估平台 - 版本更新与系统公告</description>
<language>zh-CN</language>
<lastBuild>{datetime.now().strftime('%a, %d %b %Y %H:%M:%S +0800')}</lastBuild>
{items_xml}
</channel>
</rss>"""
    from flask import Response
    return Response(rss, mimetype='application/rss+xml')


