@app.route('/api/ai_cluster_matrix', methods=['GET'])
@system_container('ai_cluster_matrix_api', require_auth='admin')
def api_ai_cluster_matrix():
    """AI 集群矩阵数据 API：全部从 app.db 真实表查询，禁止任何模拟数据。
    数据源（均在 APP_DB）：
      - ai_cluster_config / ai_cluster_employee → 集群清单 + 成员数
      - mtscos_ai_employees → AI 员工（Top 50，能力数/绩效分由 skills_json/scores_json 解析）
      - agent_registry → 注册 Agent 计数
      - ai_task_scheduler → 任务调度（表不存在时 _q/_safe_count 安全降级为空/0）
    """
    # ---- 统计数字（COUNT 查询）----
    clusters_count = _safe_count(APP_DB, "SELECT COUNT(*) FROM ai_cluster_config WHERE status='active'")
    employees_count = _safe_count(APP_DB, "SELECT COUNT(*) FROM mtscos_ai_employees WHERE is_active=1")
    agents_count = _safe_count(APP_DB, "SELECT COUNT(*) FROM agent_registry")
    pending_tasks = _safe_count(APP_DB, "SELECT COUNT(*) FROM ai_task_scheduler WHERE lower(status)='pending'")

    # ---- 集群清单 ----
    clusters = _q(APP_DB, "SELECT cluster_id, cluster_type, config, status, created_at, updated_at FROM ai_cluster_config ORDER BY cluster_id")
    membership = {}
    for link in _q(APP_DB, "SELECT cluster_id, COUNT(*) AS n FROM ai_cluster_employee GROUP BY cluster_id"):
        membership[link['cluster_id']] = link['n']
    for c in clusters:
        c['member_count'] = membership.get(c['cluster_id'], 0)

    # ---- AI 员工 Top 50（mtscos_ai_employees）----
    raw_emps = _q(APP_DB, "SELECT uid, name, role, dept, skills_json, scores_json, is_active, status FROM mtscos_ai_employees ORDER BY id DESC LIMIT 50")
    employee_list = []
    for e in raw_emps:
        # 能力数 = skills_json 数组长度
        cap_count = 0
        try:
            _skills = json.loads(e.get('skills_json') or '[]')
            cap_count = len(_skills) if isinstance(_skills, list) else 0
        except Exception:
            cap_count = 0
        # 绩效分 = scores_json["综合"] * 20（0-5 → 0-100）
        perf = 0.0
        try:
            _sj = json.loads(e.get('scores_json') or '{}')
            if isinstance(_sj, dict) and _sj:
                _overall = _sj.get('综合')
                if _overall is None:
                    _nums = [v for v in _sj.values() if isinstance(v, (int, float))]
                    _overall = (sum(_nums) / len(_nums)) if _nums else 0
                perf = round(float(_overall) * 20, 1)
        except Exception:
            perf = 0.0
        employee_list.append({
            'employee_id': e.get('uid') or '',
            'name': e.get('name') or '',
            'title': e.get('role') or '',
            'category': e.get('dept') or '',
            'cap_count': cap_count,
            'total_tasks': 0,
            'successful_tasks': 0,
            'failed_tasks': 0,
            'performance_score': perf,
            'is_enabled': e.get('is_active'),
            'status': e.get('status') or '',
        })

    # ---- 任务调度（ai_task_scheduler 表不存在时 _q 安全降级为 []）----
    task_list = _q(APP_DB, "SELECT * FROM ai_task_scheduler ORDER BY created_at DESC LIMIT 30")

    return jsonify({
        'success': True,
        'stats': {
            'clusters': clusters_count,
            'employees': employees_count,
            'agents': agents_count,
            'pending_tasks': pending_tasks,
        },
        'cluster_list': clusters,
        'employee_list': employee_list,
        'task_list': task_list,
    })


