def _table_exists(conn, table_name):
    """检查表是否存在"""
    try:
        r = conn.execute("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=?", (table_name,)).fetchone()
        return r[0] > 0
    except Exception:
        return False

