@app.route('/mobile/home')
@system_container('mobile_home', require_auth='login')
def mobile_home():
    u = _m_user_ctx()
    uid = u.get('id') or 0
    role = u.get('role') or 'user'
    grade = u.get('grade') or ''
    # 复用PC端数据查询
    exam_count, test_count, practice_count = 0, 0, 0
    upcoming = []
    notifs = []
    unread = 0
    try:
        if os.path.exists(APP_DB):
            with _get_conn(APP_DB) as conn:
                exam_count = conn.execute("SELECT COUNT(*) FROM exams WHERE status='published'").fetchone()[0] if _table_exists(conn, 'exams') else 0
                test_count = conn.execute("SELECT COUNT(*) FROM tests WHERE status='published'").fetchone()[0] if _table_exists(conn, 'tests') else 0
                upcoming = [dict(r) for r in conn.execute("SELECT * FROM exams WHERE status='published' ORDER BY id DESC LIMIT 5")] if _table_exists(conn, 'exams') else []
                if _table_exists(conn, 'notifications') and uid:
                    notifs = [dict(r) for r in conn.execute("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 5", (uid,))]
                    unread = conn.execute("SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0", (uid,)).fetchone()[0]
    except Exception:
        pass
    return render_template('mobile/home.html', user=u, grade=grade, exam_count=exam_count,
                         test_count=test_count, practice_count=practice_count,
                         upcoming_exams=upcoming, notifications=notifs,
                         unread_count=unread, stats=_m_stats(uid),
                         is_final_exam_period=False, tabbar_active='home')

