            with _get_conn(APP_DB) as conn:
                if _table_exists(conn, 'exam_categories'):
                    categories = [dict(r) for r in conn.execute("SELECT * FROM exam_categories ORDER BY id")]
                if _table_exists(conn, 'exams'):
                    sql = "SELECT * FROM exams WHERE status='published'"
                    args = []
                    if selected_category:
                        sql += " AND category=?"
                        args.append(selected_category)
                    sql += " ORDER BY id DESC"
