# ============= WebAuthn 指纹硬件认证 API =============
# 移动端管理员通过浏览器原生 WebAuthn API 调用终端指纹硬件（Touch ID/指纹传感器）
# 流程: 1.前端请求challenge → 2.navigator.credentials.get()调用硬件 → 3.提交签名 → 4.后端验证

import secrets as _secrets_mod
import json as _json_mod

# 内存存储 challenge（生产环境应使用数据库或Redis）
_FP_CHALLENGE_STORE = {}

@app.route('/api/mobile/fingerprint/challenge', methods=['POST'])
@system_container('mobile_fp_challenge', require_auth='guest')
def mobile_fingerprint_challenge():
    """生成 WebAuthn 挑战码，供前端调用指纹硬件"""
    try:
        data = request.get_json(silent=True) or {}
        username = (data.get('username') or '').strip().lower()

        if not username:
            return jsonify({'success': False, 'message': '请先输入用户名'}), 400

        # 检查用户是否存在且为超级管理员
        is_sa = (username == 'wuchenghao15')
        if not is_sa:
            # 非超管不需要指纹，但仍可生成挑战（用于普通管理员可选指纹）
            pass

        # 生成随机挑战码（32字节）
        challenge = _secrets_mod.token_hex(32)
        # 存储挑战码，5分钟有效期
        _FP_CHALLENGE_STORE[username] = {
            'challenge': challenge,
            'timestamp': time.time(),
            'expires_in': 300,
        }

        # 返回 WebAuthn 配置参数
        import time as _ch_t, uuid as _ch_u
        # 同时返回防重放 nonce 和时间戳（供前端登录时携带 auth_nonce + auth_timestamp）
        auth_nonce = _ch_u.uuid4().hex
        auth_timestamp = str(_ch_t.time())
        return jsonify({
            'success': True,
            'challenge': challenge,
            'auth_nonce': auth_nonce,        # 防重放 nonce（SA登录加固 Layer 0）
            'auth_timestamp': auth_timestamp, # 防重放时间戳
            'rp': {
                'name': 'MTSCOS AI',
                'id': request.host.split(':')[0],
            },
            'user': {
                'id': username,
                'name': username,
                'displayName': '超级管理员' if is_sa else username,
            },
            'authenticator_selection': {
                'authenticatorAttachment': 'platform',
                'userVerification': 'required',
                'requireResidentKey': False,
            },
            'pub_key_cred_params': [
                {'type': 'public-key', 'alg': -7},   # ES256
                {'type': 'public-key', 'alg': -257}, # RS256
            ],
            'timeout': 60000,
            'is_super_admin': is_sa,
        })
    except Exception as e:
        return jsonify({'success': False, 'message': f'生成挑战码失败: {e}'}), 500

@app.route('/api/mobile/fingerprint/verify', methods=['POST'])
@system_container('mobile_fp_verify', require_auth='guest')
def mobile_fingerprint_verify():
    """验证 WebAuthn 指纹签名，返回指纹数据供登录使用"""
    try:
        data = request.get_json(silent=True) or {}
        username = (data.get('username') or '').strip().lower()
        credential_id = data.get('credential_id') or ''
        authenticator_data = data.get('authenticator_data') or ''
        client_data_json = data.get('client_data_json') or ''
        signature = data.get('signature') or ''
        user_handle = data.get('user_handle') or ''

        if not username:
            return jsonify({'success': False, 'message': '用户名不能为空'}), 400

        # 验证挑战码
        stored = _FP_CHALLENGE_STORE.pop(username, None)
        if not stored:
            return jsonify({'success': False, 'message': '挑战码不存在或已使用，请重新获取'}), 400

        # 检查过期
        if time.time() - stored['timestamp'] > stored['expires_in']:
            return jsonify({'success': False, 'message': '挑战码已过期，请重新获取'}), 400

        # 验证签名数据存在
        if not all([credential_id, authenticator_data, signature]):
            return jsonify({'success': False, 'message': '指纹认证数据不完整'}), 400

        # 生成指纹数据摘要（将 WebAuthn 断言数据组合成指纹标识）
        # 实际生产应使用 cryptography 库验证签名，这里简化为数据完整性校验
        fp_hash = hashlib.sha256(
            f'{username}|{credential_id}|{authenticator_data}|{signature}'.encode()
        ).hexdigest()

        # 组合指纹数据（与数据库 fingerprint_template 格式对齐）
        fingerprint_data = f'webauthn:{fp_hash[:64]}'

        # 清理挑战码
        _FP_CHALLENGE_STORE.pop(username, None)

        return jsonify({
            'success': True,
            'message': '指纹认证成功',
            'fingerprint_data': fingerprint_data,
            'credential_id': credential_id[:100],  # 截断防止过长
            'verified_at': int(time.time()),
        })
    except Exception as e:
        return jsonify({'success': False, 'message': f'指纹验证失败: {e}'}), 500

@app.route('/api/mobile/fingerprint/status', methods=['GET'])
@system_container('mobile_fp_status', require_auth='guest')
def mobile_fingerprint_status():
    """查询用户指纹注册状态"""
    try:
        username = (request.args.get('username') or '').strip().lower()
        if not username:
            return jsonify({'success': False, 'message': '用户名不能为空'}), 400

        enabled = False
        registered_at = None
        device_id = None
        try:
            if os.path.exists(AUTH_DB):
                with _get_conn(AUTH_DB) as conn:
                    row = conn.execute(
                        "SELECT fingerprint_enabled, fingerprint_registered_at, fingerprint_device_id FROM users WHERE username=? COLLATE NOCASE LIMIT 1",
                        (username,)
                    ).fetchone()
                    if row:
                        enabled = bool(row['fingerprint_enabled'])
                        registered_at = row['fingerprint_registered_at']
                        device_id = row['fingerprint_device_id']
        except Exception:
            pass

        return jsonify({
            'success': True,
            'username': username,
            'fingerprint_enabled': enabled,
            'registered_at': registered_at,
            'device_id': device_id,
            'is_super_admin': username == 'wuchenghao15',
        })
    except Exception as e:
        return jsonify({'success': False, 'message': f'查询失败: {e}'}), 500

