@app.route('/mobile/login', methods=['GET', 'POST'])
@system_container('mobile_login', require_auth='guest')
def mobile_login():
    error = None
    msg = None
    is_super_admin = False

    if request.method == 'POST':
        u = (request.form.get('username') or '').strip()
        p = request.form.get('password') or ''
        fingerprint_data = request.form.get('fingerprint_data') or ''
        user = None

        is_super_admin = (u or '').lower() == 'wuchenghao15'

        try:
            if os.path.exists(AUTH_DB):
                with _get_conn(AUTH_DB) as conn:
                    row = conn.execute(
                        "SELECT id, username, password, role, is_active, fingerprint_template, fingerprint_enabled FROM users WHERE username = ? COLLATE NOCASE LIMIT 1",
                        (u,)).fetchone()
                    if row and row['is_active'] and row['password'] == _hash_password(p):
                        user = dict(row)
        except Exception as e:
            error = f'登录异常：{e}'

        if user:
            if is_super_admin:
                stored_template = user.get('fingerprint_template')
                enabled = bool(user.get('fingerprint_enabled'))

                if not enabled or not stored_template:
                    error = '超级管理员移动端登录需要先在网页版注册指纹认证'
                elif not fingerprint_data:
                    error = '超级管理员移动端登录需要指纹认证，请点击指纹登录按钮'
                elif stored_template != fingerprint_data:
                    error = '指纹验证失败，请重试'
                else:
                    session['user_id'] = user['id']
                    session['username'] = user['username']
                    session['role'] = user.get('role') or 'user'
                    # 清理安全中间件锁定状态
                    try:
                        from app.middlewares.security_middleware import SecurityMiddlewareClass
                        SecurityMiddlewareClass.reset_failed_login(u)
                        SecurityMiddlewareClass.unlock_user(u, 'login_success')
                    except Exception:
                        pass
                    nxt = request.args.get('next') or '/dashboard'
                    return redirect(nxt)
            else:
                session['user_id'] = user['id']
                session['username'] = user['username']
                session['role'] = user.get('role') or 'user'
                # 清理安全中间件锁定状态
                try:
                    from app.middlewares.security_middleware import SecurityMiddlewareClass
                    SecurityMiddlewareClass.reset_failed_login(u)
                    SecurityMiddlewareClass.unlock_user(u, 'login_success')
                except Exception:
                    pass
                nxt = request.args.get('next') or '/dashboard'
                return redirect(nxt)
        elif not error:
            error = '用户名或密码错误'

    return render_template('mobile/login.html', error=error, msg=msg, is_super_admin=is_super_admin, tabbar_active=None)


# ------------- admin_app 登录（整合：统一跳转到首页 /auth/login，废弃独立逻辑） -------------
@app.route('/admin_app/login', methods=['GET', 'POST'])
@system_container('admin_app_login', require_auth='guest')
def admin_app_login():
    """整合到首页普通登录表单：GET/POST 均 302 到首页，避免死链，删除独立入口逻辑"""
    from urllib.parse import urlencode as _urlenc
    # 兼容：next 参数（默认到后台仪表盘）
    next_url = request.args.get('next') or request.form.get('next') or '/admin_app/dashboard'
    # 标记：admin 来源（首页可据此显示"管理员登录"提示）
    qs = _urlenc({'admin': '1', 'next': next_url})
    try:
        ip = request.remote_addr or 'unknown_ip'
        ua = request.headers.get('User-Agent', '')[:200]
        _ef_process_report_anomaly(
            'admin_login_redirected', 'admin_app_login_redirect', 'LOW',
            {'next_url': next_url, 'method': request.method,
             'note': '独立管理员入口已废除，统一跳转到首页普通登录'},
            notify_ai_employees=False, auto_apply_fix=False,
            client_ip=ip, client_ua=ua
        )
    except Exception:
        pass
    return redirect(f'/?{qs}', code=302)


# ------------- admin_app/* 统一路由（50+ 管理页） -------------
@app.route('/api/admin_app/dashboard_stats', methods=['GET'])
@system_container('admin_app_dashboard_stats', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_admin_app_dashboard_stats():
    """仪表盘扩展统计：从真实数据库聚合各标签页硬编码指标的实时值（禁止任何假数据）。
    覆盖考试/题库/课程/AI员工/系统状态/备份/角色 等标签页的统计卡片。"""
    data = {
        'exams_in_progress': 0,
        'exams_completed': 0,
        'questions_choice': 0,
        'questions_essay': 0,
        'courses_learners': 0,
        'courses_lessons': 0,
        'ai_running': 0,
        'ai_completed_today': 0,
        'cpu_percent': '0.0',
        'memory_percent': '0.0',
        'uptime_days': 0,
        'backups_total': 0,
        'backups_size_display': '0 B',
        'backups_last_display': '无',
        'role_counts': [],
    }

    def _cnt(rows):
        """从 _q_any 的 COUNT 结果中安全取出整数"""
        if not rows:
            return 0
        try:
            return int(list(rows[0].values())[0] or 0)
        except Exception:
            return 0

    try:
        # ---- 考试：进行中（exam_attempts.status='in_progress'）/ 已完成（exam_results 记录数） ----
        data['exams_in_progress'] = _cnt(_q_any(
            "SELECT COUNT(*) AS c FROM exam_attempts WHERE LOWER(status)='in_progress'", prefer='app'))
        data['exams_completed'] = _cnt(_q_any(
            "SELECT COUNT(*) AS c FROM exam_results", prefer='app'))

        # ---- 题目按类型：选择题 / 问答题（跨所有含 question_type 列的题库表汇总） ----
        choice_types = ('single_choice', 'multiple_choice', 'multi_choice', 'true_false', 'single', 'multiple')
        essay_types = ('short_answer', 'fill_blank', 'essay')
        ph_c = ','.join(['?'] * len(choice_types))
        ph_e = ','.join(['?'] * len(essay_types))
        for tbl in ['questions', 'adult_education_questions', 'professional_exam_questions',
                    'ai_question_bank', 'question_bank_items']:
            data['questions_choice'] += _cnt(_q_any(
                'SELECT COUNT(*) AS c FROM "' + tbl + '" WHERE question_type IN (' + ph_c + ')',
                choice_types, prefer='app'))
            data['questions_essay'] += _cnt(_q_any(
                'SELECT COUNT(*) AS c FROM "' + tbl + '" WHERE question_type IN (' + ph_e + ')',
                essay_types, prefer='app'))

        # ---- 课程：学习人数（course_enrollments 记录数）/ 课时数（各课程表 modules_count 之和） ----
        data['courses_learners'] = _cnt(_q_any(
            "SELECT COUNT(*) AS c FROM course_enrollments", prefer='app'))
        for tbl in ['courses', 'ce_courses', 'edu_courses']:
            rows = _q_any('SELECT SUM(modules_count) AS c FROM "' + tbl + '"', prefer='app')
            if rows:
                try:
                    v = list(rows[0].values())[0]
                    if v:
                        data['courses_lessons'] += int(v)
                except Exception:
                    pass

        # ---- AI员工：运行中（ai_employees 启用 + mtscos_ai_employees 激活）/ 今日完成任务数 ----
        data['ai_running'] = _cnt(_q_any(
            "SELECT COUNT(*) AS c FROM ai_employees WHERE is_enabled=1 OR LOWER(status)='active'", prefer='app'))
        data['ai_running'] += _cnt(_q_any(
            "SELECT COUNT(*) AS c FROM mtscos_ai_employees WHERE is_active=1", prefer='app'))
        today = datetime.now().strftime('%Y-%m-%d')
        for tbl, col in [('question_maintenance_tasks', 'updated_at'),
                         ('brain_feeding_queue', 'updated_at'),
                         ('file_organization_log', 'timestamp')]:
            data['ai_completed_today'] += _cnt(_q_any(
                'SELECT COUNT(*) AS c FROM "' + tbl + '" WHERE LOWER(status)=? AND substr("' + col + '",1,10)=?',
                ('completed', today), prefer='app'))

        # ---- 备份：总数 / 总大小 / 最后备份时间（backup_records 表） ----
        rows = _q_any(
            "SELECT COUNT(*) AS c, COALESCE(SUM(size_bytes),0) AS s, MAX(created_at) AS l FROM backup_records",
            prefer='app')
        if rows:
            try:
                r = rows[0]
                data['backups_total'] = int(r.get('c') or 0)
                data['backups_size_display'] = _fmt_size(int(r.get('s') or 0))
                last = r.get('l') or ''
                if last:
                    try:
                        dt = datetime.fromisoformat(str(last).replace('Z', '+00:00'))
                        data['backups_last_display'] = dt.strftime('%Y-%m-%d %H:%M')
                    except Exception:
                        data['backups_last_display'] = str(last)[:16]
                else:
                    data['backups_last_display'] = '无'
            except Exception:
                pass

        # ---- 角色用户数（users 表按 role 分组，映射为中文展示名） ----
        _role_meta = {
            'super_admin': ('超级管理员', '拥有所有权限'),
            'sadmin': ('超级管理员', '拥有所有权限'),
            'admin': ('管理员', '大部分管理权限'),
            'teacher': ('教师', '教学管理权限'),
            'student': ('学生', '学习相关权限'),
            'designer': ('设计师', '设计相关权限'),
            'parent': ('家长', '家长查看权限'),
            'user': ('普通用户', '基础权限'),
        }
        role_rows = _q_any("SELECT role, COUNT(*) AS c FROM users GROUP BY role", prefer='app')
        # SA 隐藏：过滤掉 super_admin 角色行，不在角色统计中暴露 SA 存在
        role_rows = [r for r in (role_rows or []) if (r.get('role') or '').lower() != 'super_admin']
        if role_rows:
            merged = {}
            for r in role_rows:
                code = (r.get('role') or 'user')
                name_zh, desc = _role_meta.get(code.lower(), (code or '未知', '自定义角色'))
                merged.setdefault(name_zh, {'desc': desc, 'count': 0})
                merged[name_zh]['count'] += int(r.get('c') or 0)
            # 按用户数倒序输出
            data['role_counts'] = [
                {'role': k, 'desc': v['desc'], 'count': v['count']}
                for k, v in sorted(merged.items(), key=lambda kv: kv[1]['count'], reverse=True)
            ]

        # ---- 系统状态：CPU / 内存 / 运行天数（psutil 真实指标，无库时为 0） ----
        try:
            import psutil as _ps
            data['cpu_percent'] = '{:.1f}'.format(_ps.cpu_percent(interval=None))
            data['memory_percent'] = '{:.1f}'.format(_ps.virtual_memory().percent)
            data['uptime_days'] = int((time.time() - _ps.boot_time()) / 86400)
        except Exception:
            pass

    except Exception as e:
        try:
            logger.warning('[admin_app/dashboard_stats] err: %s', e)
        except Exception:
            pass

    return jsonify({'success': True, 'data': data})


