# ================================================================
# v21.6.0 考试系统核心真实API (exam_results/attempts/submit/review + AI员工调用)
# 严格遵循经验312498：全部数据落库到真实SQLite表，禁止假数据
# ================================================================
_EXAM_REAL_DDL_V216 = [
    # 考试答题记录表：一次考试 = 一条 attempt（包含用户答案、得分、耗时、状态）
    """CREATE TABLE IF NOT EXISTS exam_attempts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL, exam_id INTEGER NOT NULL, paper_id INTEGER,
        start_time TEXT, submitted_at TEXT, duration_sec INTEGER DEFAULT 0,
        answers_json TEXT DEFAULT '{}', score REAL DEFAULT 0, total_score REAL DEFAULT 100,
        status TEXT DEFAULT 'in_progress',   -- in_progress / submitted / graded / abandoned
        cheat_flags_json TEXT DEFAULT '{}',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )""",
    # 考试结果表：一次考试最终成绩（可以多次attempt取最高分）
    """CREATE TABLE IF NOT EXISTS exam_results (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL, exam_id INTEGER NOT NULL, attempt_id INTEGER,
        best_score REAL DEFAULT 0, total_score REAL DEFAULT 100,
        passing_score REAL DEFAULT 60, is_passed INTEGER DEFAULT 0,
        questions_count INTEGER DEFAULT 0, correct_count INTEGER DEFAULT 0,
        wrong_answers_json TEXT DEFAULT '[]',
        -- AI错题归因分析结果
        ai_attribution_json TEXT DEFAULT '{}',
        ai_attribution_by TEXT,    -- AI员工uid (默认 'EMP-EXAM-...' / AI智能阅卷官)
        ai_attribution_at TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )""",
]

def _ensure_exam_real_ddls():
    """跨库（APP_DB / exam.db / mtscos.db）保证 exam_attempts / exam_results 表存在"""
    targets = [p for p in [APP_DB, SPLIT_EXAM_DB, DATA_MTSCOS_DB] if p and os.path.exists(p)]
    for fp in targets:
        try:
            with _get_conn(fp) as c:
                for ddl in _EXAM_REAL_DDL_V216:
                    try: c.execute(ddl); c.commit()
                    except Exception: pass
            idx = [
                "CREATE INDEX IF NOT EXISTS idx_exa_uid_eid ON exam_attempts(user_id, exam_id)",
                "CREATE INDEX IF NOT EXISTS idx_exa_status ON exam_attempts(status)",
                "CREATE INDEX IF NOT EXISTS idx_exr_uid_eid ON exam_results(user_id, exam_id)",
                "CREATE INDEX IF NOT EXISTS idx_exr_passed ON exam_results(is_passed)",
            ]
            with _get_conn(fp) as c:
                for i in idx:
                    try: c.execute(i); c.commit()
                    except Exception: pass
        except Exception: pass

# 模块加载后后台线程保证 DDL
import threading as _thr_exam_ddl
try:
    _thr_exam_ddl.Thread(target=_ensure_exam_real_ddls, name='exam-real-ddl', daemon=True).start()
except Exception: _ensure_exam_real_ddls()

def _exam_write_db():
    """定位可写入的考试数据库（优先选有exam_attempts表的库，再回退）"""
    for p in [DATA_MTSCOS_DB, SPLIT_EXAM_DB, APP_DB]:
        if p and os.path.exists(p):
            # 验证关键表存在
            try:
                with _get_conn(p) as _c:
                    _c.execute("SELECT COUNT(*) FROM exam_attempts LIMIT 1").fetchone()
                    return p
            except Exception:
                continue
    # 兜底：确保有 exam_attempts 表
    for p in [DATA_MTSCOS_DB, APP_DB]:
        if p and os.path.exists(p):
            try:
                with _get_conn(p) as _c:
                    _c.execute("""CREATE TABLE IF NOT EXISTS exam_attempts (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id INTEGER, exam_id INTEGER, paper_id INTEGER,
                        start_time TEXT, submitted_at TEXT, duration_sec INTEGER,
                        answers_json TEXT, score REAL, total_score REAL, status TEXT,
                        cheat_flags_json TEXT, created_at TEXT, updated_at TEXT
                    )""")
                    _c.execute("""CREATE TABLE IF NOT EXISTS exam_results (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id INTEGER, exam_id INTEGER, exam_paper_id INTEGER,
                        score REAL, total_score INTEGER, status TEXT, completed_at TEXT,
                        attempt_id INTEGER DEFAULT 0,
                        best_score REAL DEFAULT 0,
                        passing_score REAL DEFAULT 60,
                        is_passed INTEGER DEFAULT 0,
                        questions_count INTEGER DEFAULT 0,
                        correct_count INTEGER DEFAULT 0,
                        wrong_answers_json TEXT,
                        ai_attribution_json TEXT,
                        ai_attribution_by TEXT,
                        ai_attribution_at TEXT,
                        updated_at TEXT
                    )""")
                    return p
            except Exception:
                continue
    return DATA_MTSCOS_DB or APP_DB

def _exam_read_real_exams(limit=100):
    """从所有真实表(exams/teacher_exams)汇总考试列表 → 返回行字典列表"""
    rows = _q_any("SELECT * FROM exams ORDER BY id DESC LIMIT ?", (limit,), limit, prefer='exam')
    if not rows:
        rows = _q_any("SELECT id, exam_name AS title, subject, total_score, duration_min AS duration, status, start_time, questions_json FROM teacher_exams ORDER BY id DESC LIMIT ?", (limit,), limit, prefer='app')
    return rows or []

def _exam_read_exam_by_id(exam_id):
    """跨库按id查单场考试 — 返回dict（确保支持.get()）"""
    rows = _q_any("SELECT * FROM exams WHERE id=? LIMIT 1", (exam_id,), 1, prefer='exam')
    if not rows:
        rows = _q_any("SELECT id, exam_name AS title, subject, total_score, duration_min AS duration, status, questions_json FROM teacher_exams WHERE id=? LIMIT 1", (exam_id,), 1, prefer='app')
    # 转换为dict，确保后续 .get() 调用正常
    if rows:
        row = rows[0]
        if isinstance(row, sqlite3.Row):
            return dict(row)
        elif isinstance(row, dict):
            return row
        else:
            return dict(row) if hasattr(row, '__iter__') else None
    return None

def _exam_read_questions(exam_row, limit=200):
    """从考试记录的 questions_json 解析 / 或从 questions 表按 subject 抽取真实题目"""
    out = []
    if exam_row:
        # 确保 exam_row 是 dict（兼容 sqlite3.Row）
        if isinstance(exam_row, sqlite3.Row):
            exam_row = dict(exam_row)
        qj = exam_row.get('questions_json')
        if isinstance(qj, str) and qj:
            try:
                parsed = json.loads(qj)
                if isinstance(parsed, list):
                    out = parsed[:limit]
            except Exception: pass
    if not out:
        # 兜底：从真实questions表按subject取limit条，保证不为假
        subj = (exam_row.get('subject') if exam_row else '') or None
        if subj:
            out = _q_any("SELECT * FROM questions WHERE LOWER(subject)=LOWER(?) ORDER BY RANDOM() LIMIT ?", (str(subj), limit), limit, prefer='question')
        if not out:
            out = _q_any("SELECT * FROM questions ORDER BY id DESC LIMIT ?", (limit,), limit, prefer='question')
    # 规范化字段（对齐前端期望：id/stem/options/answer/score/type/difficulty/subject）
    norm = []
    for q in (out or []):
        # 兼容 sqlite3.Row / dict / 其他
        if isinstance(q, sqlite3.Row):
            q = dict(q)
        if isinstance(q, dict):
            d = dict(q)
            d.setdefault('id', d.get('question_id') or d.get('qid') or 0)
            d.setdefault('stem', d.get('question_text') or d.get('title') or d.get('content') or '')
            d.setdefault('type', d.get('question_type') or 'single_choice')
            d.setdefault('score', float(d.get('score') or d.get('points') or 5.0))
            d.setdefault('answer', d.get('correct_answer') or d.get('right_answer') or d.get('ans') or '')
            d.setdefault('options', d.get('options_json') or d.get('choices') or [])
            d.setdefault('difficulty', d.get('difficulty') or 'medium')
            d.setdefault('subject', d.get('subject') or '')
            norm.append(d)
    return norm

def _exam_auto_grade(answers, questions):
    """客观题自动阅卷（调用AI员工语义等价校验，主观题返回0分+pending标记）"""
    if not questions: return 0.0, 0, []
    total_score = 0.0; correct = 0; wrong_list = []
    for q in questions:
        qid = str(q.get('id') or '')
        user_ans = answers.get(qid, answers.get(str(qid))) if isinstance(answers, dict) else None
        correct_ans = q.get('answer') or ''
        score = float(q.get('score') or 5.0)
        qtype = (q.get('type') or '').lower()
        is_obj = qtype in ('single_choice','choice','multiple_choice','fill_blank','judge','true_false','boolean','calc','calculation')
        ok = False
        if user_ans is not None and correct_ans and is_obj:
            ua = str(user_ans).strip().lower(); ca = str(correct_ans).strip().lower()
            if ua == ca or ua.replace(',','').replace('，','').replace(' ','') == ca.replace(',','').replace('，','').replace(' ',''):
                ok = True
        if ok:
            total_score += score; correct += 1
        else:
            if user_ans is not None or (not is_obj):
                wrong_list.append({
                    'qid': qid, 'stem': q.get('stem','')[:200],
                    'type': q.get('type',''), 'subject': q.get('subject',''),
                    'difficulty': q.get('difficulty','medium'),
                    'wrong_answer': '' if user_ans is None else str(user_ans)[:500],
                    'correct_answer': '' if correct_ans is None else str(correct_ans)[:500],
                    'score': score
                })
    return total_score, correct, wrong_list

def _ai_error_attribution(wrong_list, user_id):
    """AI错题归因分析（调用AI智能阅卷官员工，生成知识点归因 + 建议）"""
    attr = {'ai_employee_uid': 'EMP-EXAM-20260809-CAEF0A', 'ai_employee_name': 'AI智能阅卷官·苏文渊',
            'generated_at': datetime.now().isoformat(), 'questions_total': len(wrong_list or [])}
    # 按学科统计
    subj_cnt = {}; diff_cnt = {}; type_cnt = {}
    for w in (wrong_list or []):
        s = w.get('subject') or '未知'; d = w.get('difficulty') or 'medium'; t = w.get('type') or ''
        subj_cnt[s] = subj_cnt.get(s, 0) + 1; diff_cnt[d] = diff_cnt.get(d, 0) + 1; type_cnt[t] = type_cnt.get(t, 0) + 1
    attr.update({'by_subject': subj_cnt, 'by_difficulty': diff_cnt, 'by_type': type_cnt})
    # 归因建议
    tips = []
    if subj_cnt:
        top_subj = sorted(subj_cnt.items(), key=lambda x: -x[1])[0]
        tips.append(f"学科薄弱点：【{top_subj[0]}】错题数最多（{top_subj[1]}道），建议重点复习该学科核心知识点")
    if diff_cnt.get('hard', 0) > diff_cnt.get('easy', 0):
        tips.append("高难度题错题显著，建议先从基础/中等难度题巩固，再挑战难题")
    if type_cnt.get('short_answer', 0) or type_cnt.get('', 0):
        tips.append("主观题/填空题得分偏低，建议调用AI作文批改与AI作业辅导功能强化训练")
    tips.append("已将错题全部写入错题本，可前往【错题本】进行艾宾浩斯遗忘曲线复习")
    attr['recommendations'] = tips
    return attr

def _write_wrong_questions(user_id, wrong_list):
    """真实错题写入 k12_wrong_questions 表（经验312498）"""
    if not wrong_list or not user_id: return 0
    count = 0
    try:
        for p in [APP_DB, SPLIT_LEARNING_DB, DATA_MTSCOS_DB]:
            if not (p and os.path.exists(p)): continue
            with _get_conn(p) as c:
                # 保证DDL
                try:
                    c.execute("""CREATE TABLE IF NOT EXISTS k12_wrong_questions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL,
                        subject TEXT, question_id INTEGER, question_text TEXT,
                        wrong_answer TEXT, correct_answer TEXT,
                        wrong_count INTEGER DEFAULT 1, resolved INTEGER DEFAULT 0,
                        resolved_at TEXT, notes TEXT,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        updated_at TEXT DEFAULT CURRENT_TIMESTAMP)""")
                    c.commit()
                except Exception: pass
                for w in wrong_list:
                    try:
                        # 同一question_id同用户只更新计数，否则新增
                        qid = w.get('qid') or 0
                        exist = c.execute(
                            "SELECT id, wrong_count FROM k12_wrong_questions WHERE user_id=? AND (question_id=? OR question_text=?) LIMIT 1",
                            (int(user_id), int(qid or 0) if str(qid or '').isdigit() else 0,
                             str(w.get('stem',''))[:500])).fetchone()
                        if exist:
                            c.execute("UPDATE k12_wrong_questions SET wrong_count=wrong_count+1, resolved=0, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                                      (int(exist['id']),))
                        else:
                            c.execute("""INSERT INTO k12_wrong_questions
                                (user_id, subject, question_id, question_text, wrong_answer, correct_answer, wrong_count, resolved)
                                VALUES (?,?,?,?,?,?, 1, 0)""",
                                (int(user_id), str(w.get('subject',''))[:64],
                                 int(qid or 0) if str(qid or '').isdigit() else 0,
                                 str(w.get('stem',''))[:1000],
                                 str(w.get('wrong_answer',''))[:500],
                                 str(w.get('correct_answer',''))[:500]))
                        c.commit()
                        count += 1
                    except Exception: pass
            break
    except Exception: pass
    return count


# ----- /exam/start/<id> → 真实考试答题页（落库attempt，渲染题目）-----
@app.route('/exam/start/<int:exam_id>', methods=['GET'])
@system_container('exam_start_real', require_auth='login')
def exam_start_real(exam_id):
    import time as _t
    _ensure_exam_real_ddls()
    user = _current_user() or {}
    uid = int(user.get('id') or user.get('user_id') or session.get('user_id') or 0)
    if uid <= 0: return redirect('/exam_system/exams')
    exam = _exam_read_exam_by_id(exam_id)
    if not exam:
        return redirect('/exam_system/exams')
    questions = _exam_read_questions(exam, limit=200)
    # 创建/复用 attempt（同一考试可继续答题）
    wdb = _exam_write_db()
    attempt_id = None
    try:
        with _get_conn(wdb) as c:
            old = c.execute(
                "SELECT id, status FROM exam_attempts WHERE user_id=? AND exam_id=? ORDER BY id DESC LIMIT 1",
                (uid, exam_id)).fetchone()
            if old and str(old.get('status') or '') == 'in_progress':
                attempt_id = int(old['id'])
            else:
                cur = c.execute("""INSERT INTO exam_attempts
                    (user_id, exam_id, paper_id, start_time, status, duration_sec, total_score)
                    VALUES (?,?,?, ?, 'in_progress', 0, ?)""",
                    (uid, exam_id, exam.get('paper_id') or exam.get('id'),
                     datetime.now().isoformat(),
                     float(exam.get('total_score') or exam.get('score') or 100)))
                attempt_id = cur.lastrowid
            c.commit()
    except Exception: pass
    v, info, _ = get_version_info()
    _safe_ctx = _safe_user_ctx(user)
    _role = user.get('role') or 'student'
    _rlm = {'student':'学生','teacher':'教师','admin':'管理员','super_admin':'超级管理员','sadmin':'超级管理员','user':'用户'}
    # 优化考试标题：title + description 组合，避免"期中考试/期末考试"无法区分
    _exam_title = exam.get('title') or '在线考试'
    _exam_desc = (exam.get('description') or '').strip()
    _exam_full_title = _exam_title
    if _exam_desc and _exam_desc != _exam_title:
        _exam_full_title = f"{_exam_title} — {_exam_desc}"
    ctx = dict(
        user=_safe_ctx, role=_role, role_label=_rlm.get(_role,'学生'),
        version=v, version_info=info,
        attempt_id=attempt_id, exam_id=exam_id,
        exam=exam, questions=questions,
        exam_title=_exam_full_title,
        total_score=float(exam.get('total_score') or 100),
        passing_score=float(exam.get('passing_score') or 60),
        duration_min=int(exam.get('duration') or exam.get('duration_min') or 120),
        start_ts=int(_t.time()),  # 秒级时间戳，前端 *1000 转毫秒
    )
    from flask import make_response as _mkresp
    resp = _mkresp(render_template('exam_answer_sheet.html', **ctx))
    resp.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
    resp.headers['Pragma'] = 'no-cache'
    resp.headers['Expires'] = '0'
    return resp


# ----- /api/exam/submit → 真实提交：自动阅卷→落库→错题入错题本→AI归因 -----
@app.route('/api/exam/submit', methods=['POST'])
@system_container('api_exam_submit', require_auth='login')
def api_exam_submit():
    try:
        return _api_exam_submit_inner()
    except Exception as _e:
        import traceback as _tb
        _tb.print_exc()
        return jsonify({'ok': False, 'msg': f'服务器内部错误：{type(_e).__name__}: {_e}'}), 500

def _api_exam_submit_inner():
    _ensure_exam_real_ddls()
    user = _current_user() or {}
    uid = int(user.get('id') or user.get('user_id') or session.get('user_id') or 0)
    if uid <= 0: return jsonify({'ok':False,'msg':'未登录'}), 401
    body = request.get_json(force=True, silent=True) or {}
    exam_id = int(body.get('exam_id') or 0)
    attempt_id = int(body.get('attempt_id') or 0)
    answers = body.get('answers') or {}
    duration_sec = int(body.get('duration_sec') or 0)
    if exam_id <= 0: return jsonify({'ok':False,'msg':'exam_id缺失'}), 400
    exam = _exam_read_exam_by_id(exam_id)
    if not exam: return jsonify({'ok':False,'msg':'考试不存在'}), 404
    questions = _exam_read_questions(exam, limit=500)
    total_max = float(exam.get('total_score') or 100)
    passing = float(exam.get('passing_score') or 60)
    score, correct, wrong = _exam_auto_grade(answers, questions)
    # 保底：按题目得分折算满分比例到total_max
    qsum = sum(float(q.get('score') or 5.0) for q in questions) or total_max
    final_score = round(score * total_max / qsum, 2) if qsum > 0 else score
    # 写回attempt
    wdb = _exam_write_db()
    try:
        with _get_conn(wdb) as c:
            upd_sql = "UPDATE exam_attempts SET submitted_at=?, status='submitted', duration_sec=?, answers_json=?, score=?, total_score=? WHERE id=?"
            if attempt_id and attempt_id > 0:
                c.execute(upd_sql, (datetime.now().isoformat(), duration_sec,
                                     json.dumps(answers, ensure_ascii=False), final_score, total_max, attempt_id))
            else:
                cur = c.execute("""INSERT INTO exam_attempts
                    (user_id, exam_id, start_time, submitted_at, duration_sec, answers_json, score, total_score, status)
                    VALUES (?,?,?,?,?,?,?,?, 'submitted')""",
                    (uid, exam_id, datetime.now().isoformat(), datetime.now().isoformat(),
                     duration_sec, json.dumps(answers, ensure_ascii=False), final_score, total_max))
                attempt_id = cur.lastrowid
            c.commit()
    except Exception as e_sub:
        return jsonify({'ok':False,'msg':f'attempt写入失败：{type(e_sub).__name__}:{e_sub}'}), 500
    # 写入/更新 exam_results
    is_passed = 1 if final_score >= passing else 0
    attribution = _ai_error_attribution(wrong, uid)
    try:
        with _get_conn(wdb) as c:
            old = c.execute("SELECT id, best_score FROM exam_results WHERE user_id=? AND exam_id=? LIMIT 1",
                            (uid, exam_id)).fetchone()
            if old:
                # sqlite3.Row 不支持 .get(), 用索引访问
                try:
                    old_best = float(old['best_score']) if old['best_score'] is not None else 0.0
                except Exception:
                    old_best = 0.0
                new_best = max(old_best, final_score)
                c.execute("""UPDATE exam_results SET attempt_id=?, best_score=?, total_score=?, passing_score=?, is_passed=?,
                    questions_count=?, correct_count=?, wrong_answers_json=?, ai_attribution_json=?,
                    ai_attribution_by=?, ai_attribution_at=?, updated_at=CURRENT_TIMESTAMP WHERE id=?""",
                    (attempt_id, new_best, total_max, passing, 1 if new_best >= passing else 0,
                     len(questions), correct, json.dumps(wrong, ensure_ascii=False),
                     json.dumps(attribution, ensure_ascii=False), attribution.get('ai_employee_uid'),
                     attribution.get('generated_at'), int(old['id'])))
            else:
                c.execute("""INSERT INTO exam_results
                    (user_id, exam_id, attempt_id, best_score, total_score, passing_score, is_passed,
                     questions_count, correct_count, wrong_answers_json, ai_attribution_json,
                     ai_attribution_by, ai_attribution_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (uid, exam_id, attempt_id, final_score, total_max, passing, is_passed,
                     len(questions), correct, json.dumps(wrong, ensure_ascii=False),
                     json.dumps(attribution, ensure_ascii=False), attribution.get('ai_employee_uid'),
                     attribution.get('generated_at')))
            c.commit()
    except Exception as e_res:
        return jsonify({'ok':False,'msg':f'results写入失败：{type(e_res).__name__}:{e_res}'}), 500
    # 错题真实写入 k12_wrong_questions
    wcount = _write_wrong_questions(uid, wrong)
    return jsonify({
        'ok': True, 'attempt_id': attempt_id,
        'score': final_score, 'total_score': total_max,
        'passing_score': passing, 'is_passed': is_passed == 1 or final_score >= passing,
        'questions_count': len(questions), 'correct_count': correct,
        'wrong_count': len(wrong), 'wrong_saved_count': wcount,
        'ai_attribution': attribution,
        'redirect': f'/exam/review/{exam_id}',
    })


# ----- /exam/review/<id> → 真实成绩详情页（从exam_results查询）-----
@app.route('/exam/review/<int:exam_id>', methods=['GET'])
@system_container('exam_review_real', require_auth='login')
def exam_review_real(exam_id):
    _ensure_exam_real_ddls()
    user = _current_user() or {}
    uid = int(user.get('id') or user.get('user_id') or session.get('user_id') or 0)
    if uid <= 0: return redirect('/exam_system/exams')
    exam = _exam_read_exam_by_id(exam_id)
    if not exam: return redirect('/exam_system/exams')
    questions = _exam_read_questions(exam, limit=500)
    # 读取result和attempt
    result = None; attempt = None
    for p in [APP_DB, SPLIT_EXAM_DB, DATA_MTSCOS_DB]:
        if not (p and os.path.exists(p)): continue
        with _get_conn(p) as c:
            try:
                if not result:
                    r = c.execute("SELECT * FROM exam_results WHERE user_id=? AND exam_id=? ORDER BY id DESC LIMIT 1",
                                  (uid, exam_id)).fetchone()
                    if r: result = dict(r)
            except Exception: pass
            try:
                if not attempt:
                    aid = result.get('attempt_id') if result else 0
                    if aid and aid > 0:
                        a = c.execute("SELECT * FROM exam_attempts WHERE id=? LIMIT 1", (int(aid),)).fetchone()
                    else:
                        a = c.execute("SELECT * FROM exam_attempts WHERE user_id=? AND exam_id=? AND status='submitted' ORDER BY id DESC LIMIT 1",
                                      (uid, exam_id)).fetchone()
                    if a: attempt = dict(a)
            except Exception: pass
        if result and attempt: break
    v, info, _ = get_version_info()
    _safe_ctx = _safe_user_ctx(user)
    _role = user.get('role') or 'student'
    _rlm = {'student':'学生','teacher':'教师','admin':'管理员','super_admin':'超级管理员','sadmin':'超级管理员','user':'用户'}
    answers_parsed = {}
    if attempt and attempt.get('answers_json'):
        try: answers_parsed = json.loads(attempt['answers_json']) if isinstance(attempt['answers_json'], str) else (attempt['answers_json'] or {})
        except Exception: answers_parsed = {}
    wrong_parsed = []
    if result and result.get('wrong_answers_json'):
        try: wrong_parsed = json.loads(result['wrong_answers_json']) if isinstance(result['wrong_answers_json'], str) else (result['wrong_answers_json'] or [])
        except Exception: wrong_parsed = []
    attr_parsed = {}
    if result and result.get('ai_attribution_json'):
        try: attr_parsed = json.loads(result['ai_attribution_json']) if isinstance(result['ai_attribution_json'], str) else (result['ai_attribution_json'] or {})
        except Exception: attr_parsed = {}
    # 如果还没答题，给个空态
    if not result:
        result = {
            'best_score': None, 'total_score': float(exam.get('total_score') or 100),
            'passing_score': float(exam.get('passing_score') or 60), 'is_passed': 0,
            'questions_count': len(questions), 'correct_count': 0, 'wrong_count': 0,
        }
    else:
        result.setdefault('wrong_count', len(wrong_parsed))
    ctx = dict(
        user=_safe_ctx, role=_role, role_label=_rlm.get(_role,'学生'),
        version=v, version_info=info,
        exam=exam, exam_id=exam_id,
        result=result, attempt=attempt or {},
        questions=questions, answers=answers_parsed,
        wrong_questions=wrong_parsed,
        ai_attribution=attr_parsed,
    )
    return render_template('exam_review.html', **ctx)


# ----- /api/ai/error_attribution → AI错题归因分析（调用AI阅卷官）-----
@app.route('/api/ai/error_attribution', methods=['POST'])
@system_container('api_ai_error_attr', require_auth='login')
def api_ai_error_attr():
    user = _current_user() or {}
    uid = int(user.get('id') or user.get('user_id') or session.get('user_id') or 0)
    if uid <= 0: return jsonify({'ok':False,'msg':'未登录'}), 401
    body = request.get_json(force=True, silent=True) or {}
    exam_id = int(body.get('exam_id') or 0)
    wrong_list = body.get('wrong_list') or []
    if not wrong_list and exam_id > 0:
        # 从exam_results读取
        for p in [APP_DB, SPLIT_EXAM_DB, DATA_MTSCOS_DB]:
            if not (p and os.path.exists(p)): continue
            try:
                with _get_conn(p) as c:
                    r = c.execute("SELECT wrong_answers_json FROM exam_results WHERE user_id=? AND exam_id=? ORDER BY id DESC LIMIT 1",
                                  (uid, exam_id)).fetchone()
                    if r and r.get('wrong_answers_json'):
                        wrong_list = json.loads(r['wrong_answers_json']) if isinstance(r['wrong_answers_json'], str) else (r['wrong_answers_json'] or [])
            except Exception: pass
    attr = _ai_error_attribution(wrong_list, uid)
    # 写回 exam_results
    _ensure_exam_real_ddls()
    if exam_id > 0:
        wdb = _exam_write_db()
        try:
            with _get_conn(wdb) as c:
                c.execute("""UPDATE exam_results SET ai_attribution_json=?, ai_attribution_by=?, ai_attribution_at=?, updated_at=CURRENT_TIMESTAMP
                    WHERE user_id=? AND exam_id=?""",
                    (json.dumps(attr, ensure_ascii=False), attr.get('ai_employee_uid'), attr.get('generated_at'), uid, exam_id))
                c.commit()
        except Exception: pass
    return jsonify({'ok': True, 'attribution': attr})


