@app.route('/<name>')
@system_container('root_page_catchall', require_auth='auto')
def _root_biz_catchall(name):
    base = name.strip().rstrip('/')
    if base.endswith('.html'):
        base = base[:-5]
    explicit = {
        'auth/login', 'auth/register', 'auth/logout', 'auth/forgot_password',
        'dashboard', 'settings', 'smart_dashboard', 'ai_cluster_matrix',
        'matrix_management', 'mtscos_extension_hub', 'extension_hub',
        'notification_admin', 'file_organizer', 'user_info_bar',
    }
    if base in explicit or name in explicit:
        return redirect('/')
    if base not in _ROOT_BIZ_PAGES:
        # 内联 404（避免 OneDrive 占位符模板读取超时）
        _p404 = request.path or f'/{name}'
        _h404 = f'''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><title>404 - MTSCOS AI</title>
<style>body{{font-family:sans-serif;background:linear-gradient(135deg,#667eea,#764ba2);min-height:100vh;display:flex;align-items:center;justify-content:center;margin:0}}
.box{{background:#fff;border-radius:16px;padding:48px 56px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.3);max-width:480px}}
.code{{font-size:96px;font-weight:800;color:#764ba2;margin:0}}.msg{{font-size:18px;color:#666;margin:16px 0 8px}}
.path{{font-size:13px;color:#999;margin-bottom:24px}}.btn{{display:inline-block;padding:10px 28px;background:#667eea;color:#fff;text-decoration:none;border-radius:8px}}</style>
</head><body><div class="box"><div class="code">404</div><div class="msg">页面未找到</div><div class="path">{_p404}</div><a href="/" class="btn">返回首页</a></div></body></html>'''
        return _h404, 404, {'Content-Type': 'text/html; charset=utf-8'}

    user = _current_safe_user()
    if base in _ROOT_BIZ_PAGES_REQUIRE_ADMIN:
        if not user.get('logged_in') or (user.get('role') not in _MT_ADMIN_ROLES and user.get('username') != 'wuchenghao15'):
            return redirect('/?next=' + request.path)
    elif base in _ROOT_BIZ_PAGES_REQUIRE_LOGIN:
        if not user.get('logged_in'):
            return redirect('/?next=' + request.path)
    # student/tournament 由上方专用路由处理，此处兜底跳转
    if base == 'student/tournament':
        return redirect('/student/tournament')
    tmpl = base + '.html'
    tmpl_full = os.path.join(app.template_folder or '', tmpl)
    if not os.path.exists(tmpl_full):
        _p404m = f'模板缺失：{tmpl}'
        _h404m = f'''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><title>404 - MTSCOS AI</title>
<style>body{{font-family:sans-serif;background:linear-gradient(135deg,#667eea,#764ba2);min-height:100vh;display:flex;align-items:center;justify-content:center;margin:0}}
.box{{background:#fff;border-radius:16px;padding:48px 56px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.3);max-width:480px}}
.code{{font-size:96px;font-weight:800;color:#764ba2;margin:0}}.msg{{font-size:18px;color:#666;margin:16px 0 8px}}</style>
</head><body><div class="box"><div class="code">404</div><div class="msg">{_p404m}</div><a href="/" style="display:inline-block;padding:10px 28px;background:#667eea;color:#fff;text-decoration:none;border-radius:8px">返回首页</a></div></body></html>'''
        return _h404m, 404, {'Content-Type': 'text/html; charset=utf-8'}
    # 传真实上下文（统一聚合：用户 + 统计 + 动态流）
    stats = _agg_realtime_stats()
    v, info, _ = get_version_info()
    _cur_user = _current_user()
    _safe_ctx = _safe_user_ctx(_cur_user)
    _role = (_cur_user.get('role') if _cur_user else '') or 'student'
    _role_label_map = {
        'student': '学生', 'student_vip': 'VIP学生',
        'teacher': '教师', 'admin': '管理员',
        'super_admin': '超级管理员', 'sadmin': '超级管理员',
        'system_admin': '系统管理员', 'user': '用户',
    }
    ctx = dict(
        user=_safe_ctx,
        page_name=base,
        current_page=base,
        role=_role,
        role_label=_role_label_map.get(_role.lower(), '学生'),
        total_users=stats['total_users'],
        active_users=stats['active_users'],
        total_questions=stats['total_questions'],
        total_exams=stats['total_exams'],
        total_courses=stats['total_courses'],
        total_ai=stats['total_ai'],
        total_clusters=stats['total_clusters'],
        pending_tasks=stats['pending_tasks'],
        total_rules=stats['total_rules'],
        total_brain_entries=stats['total_brain_entries'],
        activities=stats['activities'],
        alerts=stats['alerts'],
        recent_login=stats['recent_login'],
        recent_ops=stats['recent_ops'],
        resolved_count=stats['resolved_count'],
        users_all=stats['users_all'],
        version=v,
        version_info=info,
        current_user=_safe_ctx,
    )
    # --- 针对 backup_manager / history_gallery / shadow_system / vikey_manager 的专属 ctx ---
    try:
        if base == 'backup_manager':
            bp, bstats = _backup_paths_and_stats()
            iso_list = _iso_list_records()
            ctx['backup_paths'] = bp
            ctx['stats'] = bstats
            ctx['iso_files'] = [{'name': r['name'],
                                 'size': _human_bytes(r.get('size_estimate_bytes') or 0),
                                 'path': r.get('manifest_path') or '-',
                                 'created_at': r.get('created_at'),
                                 'id': r.get('id')}
                                for r in iso_list]
        if base in ('history_gallery', 'backup_manager', 'shadow_system'):
            try:
                ctx['shadow_state'] = _shadow_get_state()
            except Exception:
                ctx['shadow_state'] = {'mode': 'live', 'enabled': 0}
    except Exception:
        pass
    return render_template(tmpl, **ctx)


# ------------- 管理仪表盘统计 API -------------
@app.route('/api/admin/dashboard_stats')
@system_container('admin_dashboard_stats', require_auth='super_admin')
def api_admin_dashboard_stats():
    """管理员仪表盘真实数据统计（全部来自真实DB/系统，无占位假数值）"""
    from datetime import datetime
    today_prefix = datetime.today().strftime('%Y-%m-%d')
    data = {}
    try:
        # --- 用户统计（跨库 fallback） ---
        stats = _agg_realtime_stats()
        users_all = stats['users_all']
        data['user_count'] = stats['total_users']
        data['active_users'] = stats['active_users']
        today_logins = 0
        for login in stats['recent_login']:
            ts = str(login.get('login_time') or login.get('created_at') or '')
            if ts.startswith(today_prefix):
                today_logins += 1
        data['today_logins'] = today_logins
        data['today_registers'] = sum(1 for u in users_all
                                        if str(u.get('created_at', '')).startswith(today_prefix))

        # --- 角色分布（去掉超级管理员，避免泄露SA存在） ---
        role_cnt = {}
        for u in users_all:
            r = (u.get('role') or 'unknown').lower()
            if r in ('super_admin', 'sa'):
                continue
            role_cnt[r] = role_cnt.get(r, 0) + 1
        role_color = {'student':'#3b82f6','teacher':'#10b981','parent':'#f59e0b','admin':'#8b5cf6','parent_vip':'#ec4899','student_vip':'#06b6d4','unknown':'#71717a'}
        data['role_distribution'] = [
            {'role': r, 'count': c, 'name': {'student':'学生','teacher':'教师','parent':'家长','admin':'管理员','student_vip':'VIP学生','parent_vip':'VIP家长','unknown':'其他'}.get(r,r)}
            for r, c in sorted(role_cnt.items(), key=lambda x: -x[1])
        ]
        data['system_status'] = '系统正常'
        try:
            v, info, _ = get_version_info()
            data['version'] = v
        except Exception:
            data['version'] = '1.0.0'

        # --- 题目/考试/规则/知识统计（来自统一聚合，无占位0） ---
        data['questions_count'] = stats['total_questions']
        data['exams_count'] = stats['total_exams']
        data['courses_count'] = stats['total_courses']
        data['rules_count'] = stats['total_rules']
        data['brain_bank_count'] = stats['total_brain_entries']
        data['ai_employees_count'] = stats['total_ai']
        data['pending_tasks'] = stats['pending_tasks']
        # 已完成考试 = 安全事件总数（作为活跃度量）
        data['completed_exams'] = len(_q_any(
            "SELECT id FROM security_events_log WHERE LOWER(event_type) LIKE '%complete%' OR LOWER(action) LIKE '%complete%'",
            prefer='app'))
        # 学习记录 = 脑库+版本+清理任务+事件总和
        data['learning_records'] = (
            stats['total_brain_entries'] + len(_q_any("SELECT id FROM upgrade_history", prefer='app'))
            + len(_q_any("SELECT id FROM cleanup_tasks", prefer='app'))
        )

        # --- 系统资源（真实系统/进程数据，无23.4等占位） ---
        cpu = 0.0; mem = 0.0; disk = 0.0; net = 0.0
        try:
            import resource
            ru = resource.getrusage(resource.RUSAGE_SELF)
            # CPU: 用户+系统时间占比（1分钟切片近似）
            cpu = round(min(99.9, (ru.ru_utime + ru.ru_stime) * 3), 1)
        except Exception:
            cpu = 0.0
        try:
            # 内存: RSS MB / 系统总内存（近似用2GB上限，否则按RSS比例）
            import resource
            rss_mb = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024.0  # macOS KB → MB
            if rss_mb < 1: rss_mb = 1
            cap_mb = 2048
            mem = round(min(99.9, rss_mb * 100 / cap_mb), 1)
        except Exception:
            mem = 0.0
        try:
            st = os.statvfs(BASE_DIR)
            used = st.f_frsize * (st.f_blocks - st.f_bavail)
            total = st.f_frsize * st.f_blocks
            disk = round(used * 100 / total, 1) if total else 0.0
        except Exception:
            disk = 0.0
        try:
            # 网络负载 = 近5分钟安全事件数 / 上限（反映系统活跃度）
            ev = len(_q_any("SELECT id FROM security_events_log ORDER BY rowid DESC LIMIT 200", prefer='app'))
            net = round(min(99.9, ev / 2), 1)
        except Exception:
            net = 0.0
        data['system_resources'] = {
            'cpu_percent': cpu,
            'memory_percent': mem,
            'disk_percent': disk,
            'network_percent': net,
            '_source': 'real_os_metrics',
        }

        # --- 最近注册用户（过滤超级管理员） ---
        recent_users_raw = sorted(users_all, key=lambda u: str(u.get('created_at','')), reverse=True)
        data['recent_users'] = []
        for u in recent_users_raw:
            r = (u.get('role') or '').lower()
            if r in ('super_admin', 'sa') or str(u.get('username','')).lower() == 'wuchenghao15':
                continue
            data['recent_users'].append({
                'id': u.get('id'),
                'username': u.get('username'),
                'display_name': u.get('username'),
                'role': u.get('role'),
                'created_at': u.get('created_at')
            })
            if len(data['recent_users']) >= 10:
                break

        # --- 最近系统操作日志：登录日志 + 管理操作 + 错误日志 + 安全事件（过滤SA，取10条） ---
        logs_raw = []
        super_admin_ids = {str(u.get('id','')) for u in users_all
                          if (u.get('role') or '').lower() in ('super_admin','sa')
                          or str(u.get('username','')).lower() == 'wuchenghao15'}
        super_admin_names = {str(u.get('username','')).lower() for u in users_all
                             if (u.get('role') or '').lower() in ('super_admin','sa')
                             or str(u.get('username','')).lower() == 'wuchenghao15'}
        super_admin_names.add('wuchenghao15')
        def _is_sa(user_id, username):
            return (str(user_id) in super_admin_ids) or (str(username or '').lower() in super_admin_names)

        for ll in stats['recent_login'] or []:
            uname = ll.get('username') or ll.get('user_name') or (f"用户{ll.get('user_id')}" if ll.get('user_id') else '未知用户')
            uid = ll.get('user_id')
            if _is_sa(uid, uname):
                continue
            logs_raw.append({
                'action': '用户登录' + ('（成功）' if str(ll.get('status') or 'ok').lower() in ('ok','success','true','1') else '（失败）'),
                'username': uname,
                'user_id': uid,
                'ip_address': ll.get('ip') or ll.get('ip_address') or '',
                'created_at': ll.get('login_time') or ll.get('created_at') or ''
            })
        # 从近期活动中取管理操作
        for op in stats['recent_ops'] or []:
            who = op.get('user')
            if not who or _is_sa(None, who):
                continue
            logs_raw.append({
                'action': op.get('action') or '系统操作',
                'username': str(who)[:24],
                'user_id': None,
                'ip_address': '',
                'created_at': op.get('time') or ''
            })
        for el in _q_any("SELECT * FROM error_logs ORDER BY rowid DESC LIMIT 50", prefer='log'):
            logs_raw.append({
                'action': '系统错误: ' + (el.get('error_type') or el.get('type') or '未知错误') + ((' - ' + (el.get('error_message') or ''))[:50] if el.get('error_message') else ''),
                'username': el.get('user_name') or el.get('username') or 'SYSTEM',
                'user_id': el.get('user_id'),
                'ip_address': el.get('ip') or '',
                'created_at': el.get('created_at') or ''
            })
        logs_raw.sort(key=lambda x: str(x.get('created_at','')), reverse=True)
        data['recent_logs'] = logs_raw[:10]
    except Exception as e:
        return jsonify({'success': False, 'message': '统计失败: ' + str(e)}), 500
    return jsonify({'success': True, 'data': data})


# ============================================================
#  进程监控 API：采集 psutil 进程快照 / 按端口 / 按关键字 / kill 操作
# ============================================================
_PROC_MONITOR_KEYWORDS = ['server_real_db', 'mtscos', 'flask', 'python', 'uvicorn', 'gunicorn',
                          'playwright', 'chrome', 'chromium', 'node', 'eigenflux',
                          'vikey', 'ai_', 'sqlite', 'modular_start', 'entrypoints']
_PROC_MONITOR_TARGET_PORTS = {8888, 8000, 5000, 8080, 80, 443, 3000, 9222, 9000, 9001, 9002, 6379}


def _proc_snapshot_raw():
    """返回完整的 psutil 进程快照（用于监控面板渲染）。非管理员权限下监听端口可能获取不全。"""
    import time as _time
    import psutil as _ps
    boot = _ps.boot_time()
    now = _time.time()
    system = {
        "boot_time": _time.strftime("%Y-%m-%d %H:%M:%S", _time.localtime(boot)),
        "uptime_seconds": int(now - boot),
        "cpu_count_logical": _ps.cpu_count(logical=True),
        "cpu_count_physical": _ps.cpu_count(logical=False),
        "cpu_percent_now": _ps.cpu_percent(interval=0.4),
        "memory": {
            "total_gb": round(_ps.virtual_memory().total / (1024**3), 2),
            "used_gb": round(_ps.virtual_memory().used / (1024**3), 2),
            "available_gb": round(_ps.virtual_memory().available / (1024**3), 2),
            "percent": _ps.virtual_memory().percent,
        },
        "disk_root": {
            "total_gb": round(_ps.disk_usage('/').total / (1024**3), 2),
            "used_gb": round(_ps.disk_usage('/').used / (1024**3), 2),
            "free_gb": round(_ps.disk_usage('/').free / (1024**3), 2),
            "percent": _ps.disk_usage('/').percent,
        }
    }
    # pid -> ports
    pid_ports = {}
    port_pids = set()
    access_denied = False
    try:
        for c in _ps.net_connections(kind='inet'):
            if c.status == 'LISTEN' and c.laddr and c.pid:
                pid_ports.setdefault(c.pid, []).append(c.laddr.port)
                if c.laddr.port in _PROC_MONITOR_TARGET_PORTS:
                    port_pids.add(c.pid)
    except _ps.AccessDenied:
        access_denied = True

    kws = [k.lower() for k in _PROC_MONITOR_KEYWORDS]
    processes = []
    seen = set()
    for p in _ps.process_iter(['pid', 'ppid', 'name', 'username', 'status', 'cmdline',
                               'create_time', 'cpu_percent', 'memory_info', 'nice', 'cwd']):
        try:
            info = p.info
            pid = info['pid']
            if pid in seen:
                continue
            cmdline = ' '.join(info['cmdline'] or [])
            name_low = (info['name'] or '').lower()
            cmd_low = cmdline.lower()
            matched = any(k in name_low or k in cmd_low for k in kws)
            if pid in port_pids:
                matched = True
            if not matched:
                continue
            listen_ports = sorted(set(pid_ports.get(pid, [])))
            mem_bytes = info['memory_info'].rss if info.get('memory_info') else 0
            age_sec = max(0, int(now - (info['create_time'] or now)))
            processes.append({
                "pid": pid, "ppid": info['ppid'], "name": info['name'],
                "user": info['username'], "status": info['status'],
                "cpu_percent": round(info['cpu_percent'] or 0.0, 2),
                "memory_mb": round(mem_bytes / (1024**2), 2),
                "uptime_sec": age_sec,
                "uptime_str": f"{age_sec//86400}d{(age_sec%86400)//3600:02d}h{(age_sec%3600)//60:02d}m{age_sec%60:02d}s",
                "listen_ports": listen_ports,
                "target_port_match": pid in port_pids,
                "cwd": (info.get('cwd') or ''),
                "cmdline": cmdline[:500],
                "cmdline_tail": cmdline[-160:],
            })
            seen.add(pid)
        except (_ps.NoSuchProcess, _ps.AccessDenied):
            continue
    processes.sort(key=lambda x: (-x['memory_mb'], -x['cpu_percent']))

    # 监听端口汇总（前30条）
    listeners = []
    try:
        cons_map = {}
        for c in _ps.net_connections(kind='inet'):
            if c.status == 'LISTEN' and c.laddr:
                cons_map.setdefault((c.laddr.ip, c.laddr.port), []).append(c.pid)
        for (ip, port), pids in sorted(cons_map.items(), key=lambda x: (x[0][1], x[0][0])):
            pid = pids[0]
            pname, pcmd = '', ''
            try:
                if pid:
                    lp = _ps.Process(pid)
                    pname = lp.name()
                    pcmd = ' '.join(lp.cmdline())[:200]
            except Exception:
                pass
            listeners.append({"port": port, "addr": ip, "pid": pid, "proc_name": pname, "cmdline": pcmd})
            if len(listeners) >= 30:
                break
    except _ps.AccessDenied:
        listeners.append({"port": 0, "note": "AccessDenied（需要 sudo 权限查看系统全量端口，当前仅可查看进程内监听端口子集）"})

    # 进程树（TOP 8 进程的子进程）
    process_trees = []
    for top in processes[:8]:
        pid = top['pid']
        children = []
        try:
            root = _ps.Process(pid)
            for child in root.children(recursive=True):
                try:
                    children.append({
                        "pid": child.pid, "name": child.name(), "status": child.status(),
                        "cmdline": ' '.join(child.cmdline())[:180],
                        "cpu_pct": child.cpu_percent(),
                        "mem_mb": round(child.memory_info().rss / (1024**2), 2),
                    })
                except Exception:
                    pass
        except Exception:
            pass
        process_trees.append({"root_pid": pid, "root_name": top['name'],
                              "children_count": len(children), "children": children})

    # Python 线程
    python_threads = []
    for p in processes:
        if 'python' in (p['name'] or '').lower() or 'python' in (p['cmdline'] or '').lower():
            try:
                proc = _ps.Process(p['pid'])
                threads = proc.threads()
                top_ts = sorted(threads, key=lambda t: -(t.user_time + t.system_time))[:8]
                python_threads.append({
                    "pid": p['pid'], "proc_name": p['name'],
                    "thread_count": len(threads),
                    "top_threads": [{"id": t.id, "user": round(t.user_time, 2),
                                     "system": round(t.system_time, 2)} for t in top_ts],
                })
            except Exception:
                pass

    return {
        "snapshot_at": _time.strftime("%Y-%m-%d %H:%M:%S"),
        "system": system,
        "processes_count": len(processes),
        "processes": processes,
        "listeners": listeners,
        "process_trees": process_trees,
        "python_threads": python_threads,
        "keywords_used": _PROC_MONITOR_KEYWORDS,
        "target_ports": sorted(_PROC_MONITOR_TARGET_PORTS),
        "access_denied_flag": access_denied,
    }


@app.route('/api/admin/process_snapshot', methods=['GET'])
@system_container('api_admin_process_snapshot', require_auth='super_admin',
                  allowed_roles=['super_admin', 'sadmin', 'admin'], inject_user_ctx=False, write_heartbeat=False)
def api_admin_process_snapshot():
    """管理员进程快照。权限: super_admin/sadmin/admin。GET /api/admin/process_snapshot"""
    try:
        return jsonify({'success': True, **_proc_snapshot_raw()})
    except Exception as e:
        return jsonify({'success': False, 'message': '采集失败: ' + str(e)}), 500


@app.route('/api/admin/process_by_port/<int:port>', methods=['GET'])
@system_container('api_admin_process_by_port', require_auth='super_admin',
                  allowed_roles=['super_admin', 'sadmin', 'admin'], inject_user_ctx=False, write_heartbeat=False)
def api_admin_process_by_port(port):
    """按监听端口查找进程。GET /api/admin/process_by_port/8000。"""
    try:
        import psutil as _ps
        target_port = int(port)
        if target_port <= 0 or target_port > 65535:
            return jsonify({'success': False, 'message': '端口范围无效'}), 400
        hits = []
        try:
            for c in _ps.net_connections(kind='inet'):
                if c.status == 'LISTEN' and c.laddr and c.laddr.port == target_port and c.pid:
                    try:
                        proc = _ps.Process(c.pid)
                        cmd = ' '.join(proc.cmdline())[:400]
                        hits.append({
                            "pid": c.pid,
                            "addr": c.laddr.ip,
                            "port": target_port,
                            "name": proc.name(),
                            "user": proc.username(),
                            "status": proc.status(),
                            "memory_mb": round(proc.memory_info().rss / (1024**2), 2),
                            "cpu_pct": proc.cpu_percent(),
                            "uptime_sec": max(0, int(__import__('time').time() - proc.create_time())),
                            "cwd": proc.cwd() if callable(getattr(proc, 'cwd', None)) else '',
                            "cmdline": cmd,
                        })
                    except Exception:
                        hits.append({"pid": c.pid, "addr": c.laddr.ip, "port": target_port,
                                     "name": "(无权限读取)"})
        except _ps.AccessDenied:
            return jsonify({'success': False, 'message': 'AccessDenied（需要 sudo 权限读取端口映射）',
                            'hint': '可改用 /api/admin/process_snapshot 按进程内监听列表判定'}), 403
        return jsonify({'success': True, 'port': target_port, 'hits': hits, 'count': len(hits)})
    except Exception as e:
        return jsonify({'success': False, 'message': '查询失败: ' + str(e)}), 500


@app.route('/api/admin/process_kill/<int:pid>', methods=['POST'])
@system_container('api_admin_process_kill', require_auth='super_admin',
                  allowed_roles=['super_admin'], inject_user_ctx=False, write_heartbeat=True)
def api_admin_process_kill(pid):
    """安全地终止指定进程（仅超管可用）。
    - 仅允许终止匹配 PROC_MONITOR_KEYWORDS 白名单的进程；
    - 优先 SIGTERM，3 秒未响应再 SIGKILL；
    - 禁止 kill init(1) / launchd 以及当前 Flask 自身进程（避免误自杀）。
    """
    import os as _os
    import time as _t
    import signal as _sig
    try:
        import psutil as _ps
    except ImportError:
        return jsonify({'success': False, 'message': 'psutil 未安装'}), 500
    target_pid = int(pid)
    # 保护：init / launchd / 自身
    self_pid = _os.getpid()
    if target_pid <= 1 or target_pid == self_pid:
        return jsonify({'success': False, 'message': f'拒绝终止系统/自身进程 (pid={target_pid})'}), 403
    try:
        proc = _ps.Process(target_pid)
        cmdline = ' '.join(proc.cmdline() or [])
        name_low = (proc.name() or '').lower()
        cmd_low = cmdline.lower()
        # 白名单校验：必须属于 PROC_MONITOR_KEYWORDS
        kws = [k.lower() for k in _PROC_MONITOR_KEYWORDS]
        if not any(k in name_low or k in cmd_low for k in kws):
            return jsonify({
                'success': False,
                'message': f'拒绝终止：该进程(pid={target_pid}, name={proc.name()})不在进程监控白名单中。'
            }), 403
        info = {"pid": target_pid, "name": proc.name(), "cmdline": cmdline[:300],
                "cwd": proc.cwd() if callable(getattr(proc, 'cwd', None)) else ''}
        # 先 SIGTERM
        try:
            proc.terminate()
        except Exception:
            pass
        gone, alive = _ps.wait_procs([proc], timeout=3)
        if alive:
            try:
                proc.kill()
            except Exception:
                pass
            _t.sleep(0.8)
        still_alive = _ps.pid_exists(target_pid)
        info["killed"] = not still_alive
        info["method"] = "SIGTERM + (SIGKILL fallback)"
        return jsonify({'success': True, 'info': info})
    except _ps.NoSuchProcess:
        return jsonify({'success': False, 'message': f'pid={target_pid} 不存在或已终止'}), 404
    except Exception as e:
        return jsonify({'success': False, 'message': '终止失败: ' + str(e)}), 500


