@app.route('/api/auth/check_sa_username', methods=['POST', 'GET'])
def api_check_sa_username():
    """登录页实时检测用户名：极密L0 — 仅Vikey在位时才返回SA标识，不暴露SA存在"""
    try:
        if request.method == 'GET':
            uname = str(request.args.get('username') or '').strip()
        else:
            d = request.get_json(silent=True) or {}
            uname = str((d or {}).get('username') or '').strip()

        # 极密L0：SA存在性不对外暴露
        # 仅当Vikey物理在位时才返回is_super_admin=true
        vikey_in_place = False
        try:
            v_ok, _, _ = _vikey_check_bound_present()
            vikey_in_place = v_ok
        except Exception:
            pass

        is_sa = False
        if vikey_in_place:
            # Vikey在位时才检测SA身份
            is_sa = (uname.lower() in {u.lower() for u in _SA_HARDCODED_USERNAMES})
            if not is_sa and uname:
                try:
                    from core.db_path import get_db_path
                    import sqlite3 as _sq
                    with _sq.connect(get_db_path('admin.db'), timeout=1) as c:
                        r = c.execute(
                            "SELECT role, super_admin_approved FROM users WHERE lower(username)=? LIMIT 1",
                            (uname.lower(),)
                        ).fetchone()
                        if r and (r[1] or (r[0] or '').lower() == 'super_admin'):
                            is_sa = True
                except Exception:
                    pass

        # 非Vikey状态：永远返回false，不暴露SA存在
        return jsonify({
            'success': True,
            'username': uname,
            'is_super_admin': is_sa,
            'ui': {
                'show_super_admin_label': is_sa,
                'hide_password_box': is_sa,
                'username_box_type': 'text',
                'username_box_value': '尊敬的超级管理员' if is_sa else uname
            }
        }), 200
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


