def _sa_write_activity_log(username, action, detail='', risk_level='info'):
    """SA活动审计直写数据库（不留本地痕迹）"""
    try:
        log_id = f'sa_log_{int(time.time()*1000)}_{username}'
        client_ip = request.environ.get('HTTP_X_REAL_IP', request.remote_addr or '') if request else ''
        user_agent = request.headers.get('User-Agent', '')[:200] if request else ''
        session_id = session.get('__mt_sid', '') if session else ''
        # 检测Vikey是否在位
        vikey_present = 0
        try:
            v_ok, _, _ = _vikey_check_bound_present(username=username)
            vikey_present = 1 if v_ok else 0
        except Exception:
            pass
        with _get_conn(APP_DB) as c:
            c.execute(
                "INSERT INTO mt_sa_activity_log(log_id, username, action, detail, client_ip, user_agent, session_id, vikey_present, risk_level, created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",
                (log_id, username, action, str(detail)[:2000], client_ip, user_agent, session_id, vikey_present, risk_level, _mtscos_now()))
            c.commit()
        return log_id
    except Exception as e:
        logger.warning(f'[SA][activity_log] write failed: {e}')
        return None


@app.route('/api/auth/sa_heartbeat', methods=['POST'])
@system_container('sa_heartbeat', require_auth='login')
def api_sa_heartbeat():
    """SA心跳保活：客户端每15秒调用，服务器续期+校验Vikey+返回权限快照"""
    try:
        user = _current_safe_user()
        username = user.get('username', '')
        is_sa = _mt_resolve_is_super_admin()
        if not is_sa:
            return jsonify({'success': False, 'message': '非超级管理员', 'code': 'NOT_SA'}), 403

        # 校验Vikey在位
        vikey_ok = False
        vikey_serial = None
        try:
            v_ok, v_reason, v_dev = _vikey_check_bound_present(username=username)
            vikey_ok = v_ok
            vikey_serial = v_dev.get('serial') if v_dev else None
        except Exception:
            vikey_ok = False

        # 续期session
        session['sa_heartbeat_at'] = _mtscos_now()
        session['sa_vikey_present'] = vikey_ok

        # 写活动审计
        _sa_write_activity_log(username, 'heartbeat', f'vikey_ok={vikey_ok}', 'info')

        # 生成权限快照并持久化
        permissions = {
            'can_use_vikey': True,
            'can_see_vikey_tab': True,
            'can_edit_sa_settings': True,
            'can_override_rules': True,
            'can_trigger_eigenflux': True,
            'can_access_all_apis': True,
            'can_view_audit_logs': True,
            'can_manage_ai_employees': True,
            'can_approve_proposals': True,
            'can_system_scan': True,
        }
        snapshot = {
            'username': username,
            'role': 'super_admin',
            'permissions': permissions,
            'vikey_present': vikey_ok,
            'vikey_serial': vikey_serial,
            'heartbeat_at': _mtscos_now(),
            'expires_at': (_dt_now() + timedelta(seconds=60)).strftime('%Y-%m-%d %H:%M:%S'),
        }
        # 持久化到数据库
        try:
            with _get_conn(APP_DB) as c:
                # 旧快照置为inactive
                c.execute("UPDATE mt_sa_permission_snapshot SET is_active=0 WHERE username=?", (username,))
                # 写入新快照
                c.execute(
                    "INSERT INTO mt_sa_permission_snapshot(username, snapshot_json, vikey_serial, session_id, expires_at, created_at, is_active) VALUES(?,?,?,?,?,?,1)",
                    (username, _rj.dumps(snapshot, ensure_ascii=False), vikey_serial,
                     session.get('__mt_sid', ''), snapshot['expires_at'], _mtscos_now()))
                c.commit()
        except Exception:
            pass

        return jsonify({
            'success': True,
            'data': {
                'sa_active': True,
                'vikey_present': vikey_ok,
                'vikey_serial': vikey_serial,
                'heartbeat_at': snapshot['heartbeat_at'],
                'expires_at': snapshot['expires_at'],
                'permissions': permissions,
                'next_heartbeat_sec': 15,
            }
        }), 200
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


