# ---------- Vikey 热插拔回调：前端轮询detect感知到变化，调用本接口通知后端 ----------
@app.route('/api/vikey/hotplug_notify', methods=['POST'])
def api_vikey_hotplug_notify():
    """
    ⭐ Vikey 插入/拔出 通知（前端轮询感知变化后调这里，让后端做权限切换）
    Body: {
      action: 'inserted' | 'removed' | 'still_present'
      serial: 设备SN（inserted必填）
      binding: {username,role_hint,...}（可选）
    }
    返回: {session_state_changed, sa_mode_active, applied_rule_overrides:[...]}
    """
    try:
        data = request.get_json(silent=True) or {}
        action = (data.get('action') or '').strip().lower()
        serial = (data.get('serial') or '').strip()
        binding = data.get('binding') or {}
        b_username = (binding.get('username') or session.get('username') or '').strip()
        b_role = (binding.get('role_hint') or binding.get('role') or '').strip().lower()

        sa_mode_active_before = bool(session.get('_sa_override_from_vikey'))
        changed = False
        applied_rule_overrides = []
        user = _current_safe_user() or {}
        operator = user.get('username') or 'vikey_hotplug_event'
        msg = ''

        if action == 'inserted':
            # ⭐ 插入：SA绑定 → 无条件判定为SA，会话临时覆盖注入 + SA规则覆盖写入sa_rule_overrides
            sa_binding_hint = False
            if b_role in ('super_admin', 'sa', 'root') or (b_username and b_username.lower() in {u.lower() for u in _SA_HARDCODED_USERNAMES}):
                sa_binding_hint = True
            # 额外查biz库确认是否SA绑定
            if not sa_binding_hint and serial:
                try:
                    with _get_conn(_bizdb_path()) as c:
                        _ensure_biz_tables(c)
                        r = c.execute(
                            "SELECT username, role_hint, binding_status FROM vikey_device_bindings WHERE serial=? AND status=1 LIMIT 1",
                            (serial,)
                        ).fetchone()
                        if r:
                            r_ = dict(r) if not isinstance(r, dict) else r
                            r_user = str(r_.get('username') or '').lower()
                            r_role = str(r_.get('role_hint') or '').lower()
                            if r_role in ('super_admin', 'sa', 'root') or r_user in {u.lower() for u in _SA_HARDCODED_USERNAMES}:
                                sa_binding_hint = True
                                if r_user: b_username = r_.get('username')
                except Exception:
                    pass
            if sa_binding_hint:
                # ⭐⭐⭐ 无条件注入SA会话覆盖 ⭐⭐⭐
                session['_sa_override_from_vikey'] = True
                session['_last_vikey_serial'] = serial
                # 自动把session username设为SA对应
                if b_username:
                    session['username'] = b_username
                    session['role'] = 'super_admin'
                    session['logged_in'] = True
                    session['super_admin_approved'] = True
                # 写入SA规则覆盖表（enforced=1）：vikey_inserted来源
                try:
                    with _get_conn(_bizdb_path()) as c:
                        _ensure_biz_tables(c)
                        _ensure_settings_and_sa_tables(c)
                        import json as _j
                        for rk, rv in [
                            ('system::vikey_mode_active', True),
                            ('system::force_sa_rule_enforced', True),
                            ('system::sa_vikey_serial', serial),
                            ('ui::show_super_admin_ui', True),
                        ]:
                            c.execute(
                                """INSERT INTO sa_rule_overrides(rule_key,override_value_json,source_type,source_serial,created_by,enforced)
                                   VALUES(?,?,?,?,?,1)
                                   ON CONFLICT(rule_key) DO UPDATE SET
                                     override_value_json=excluded.override_value_json,
                                     source_type=excluded.source_type,
                                     source_serial=excluded.source_serial,
                                     created_by=excluded.created_by,
                                     created_at=datetime('now','localtime'),
                                     enforced=1,
                                     expires_at=NULL""",
                                (rk, _j.dumps(rv, ensure_ascii=False), 'vikey_inserted', serial, operator)
                            )
                            applied_rule_overrides.append({'rule_key': rk, 'value': rv})
                except Exception:
                    pass
                changed = True
                msg = f'Vikey已插入({serial})：已自动切换为超级管理员SA模式，规则已全部覆盖并复写系统默认'
            else:
                msg = f'Vikey已插入({serial})：该设备非SA绑定，不启用SA覆盖模式'

        elif action == 'removed':
            # ⭐⭐⭐ 拔出：恢复系统默认规则 —— 清会话SA覆盖 + 软删除所有vikey_inserted来源的sa_rule_overrides
            session.pop('_sa_override_from_vikey', None)
            session.pop('_last_vikey_serial', None)
            # 清自动注入的登录态（只清临时注入的，用户手动登的留着）
            # 软删除SA规则覆盖
            try:
                with _get_conn(_bizdb_path()) as c:
                    _ensure_settings_and_sa_tables(c)
                    c.execute(
                        "UPDATE sa_rule_overrides SET enforced=0, expires_at=datetime('now','localtime') WHERE source_type='vikey_inserted'"
                    )
                    # 读当前所有enforced_override，返回给前端
                    c.row_factory = sqlite3.Row
                    r = c.execute(
                        "SELECT rule_key, override_value_json, enforced FROM sa_rule_overrides WHERE source_type='vikey_inserted'"
                    ).fetchall()
                    for rr in r or []:
                        rrd = dict(rr)
                        try:
                            import json as _j
                            val = _j.loads(rrd.get('override_value_json') or 'null')
                        except Exception:
                            val = None
                        applied_rule_overrides.append({
                            'rule_key': rrd.get('rule_key'), 'value': val,
                            'enforced': bool(rrd.get('enforced')), 'restored': bool(not rrd.get('enforced'))
                        })
            except Exception:
                pass
            changed = True
            msg = 'Vikey已拔出：系统已恢复默认规则，SA覆盖模式已关闭'

        else:  # still_present
            msg = 'Vikey维持当前状态'

        sa_mode_active_after = bool(session.get('_sa_override_from_vikey'))

        # EigenFlux + AI员工磋商热插拔事件
        try:
            # 触发升级系统AI员工感知（UPGRADE_AI_TEAM）
            if changed:
                _cons = _eigenflux_ai_consult_settings_sync(
                    'vikey', 'hotplug_' + action, sa_mode_active_before, sa_mode_active_after, source='eigenflux'
                )
                # 异步审计
                with _get_conn(_bizdb_path()) as c:
                    _ensure_settings_and_sa_tables(c)
                    import json as _j
                    c.execute(
                        """INSERT INTO settings_audit_log(scope,key_name,old_value_json,new_value_json,source,
                           ai_consult_result_json,operator,ip,ua,db_synced)
                           VALUES(?,?,?,?,?,?,?,?,?,1)""",
                        ('vikey', 'hotplug_' + str(action),
                         _j.dumps({'sa_override': sa_mode_active_before}, ensure_ascii=False),
                         _j.dumps({'sa_override': sa_mode_active_after}, ensure_ascii=False),
                         'eigenflux',
                         _j.dumps(_cons or {}, ensure_ascii=False),
                         operator, _ip(), _ua())
                    )
        except Exception:
            pass

        return jsonify({
            'success': True,
            'session_state_changed': changed,
            'sa_mode_active_before': sa_mode_active_before,
            'sa_mode_active_after': sa_mode_active_after,
            'sa_mode_active': sa_mode_active_after,
            'action': action,
            'serial': serial,
            'message': msg,
            'applied_rule_overrides': applied_rule_overrides,
            'is_super_admin_now': _mt_resolve_is_super_admin(),
            'reload_settings': changed,  # 前端根据这个刷新所有设置组件
            'server_time': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        }), 200
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'success': False, 'message': f'热插拔通知失败: {e}'}), 500


# ======================================================================
# EigenFlux + AI员工共同磋商 —— 可内部调用共享函数（auth/register/forgot 复用）
# ======================================================================
def _ef_process_report_anomaly(
    anomaly_type: str,
    location: str,
    severity: str = 'LOW',
    payload: dict | None = None,
    notify_ai_employees: bool = True,
    auto_apply_fix: bool = True,
    operator_user: str | None = None,
    operator_is_sa: bool | None = None,
    client_ip: str | None = None,
    client_ua: str | None = None,
):
    """
    可被后端任意路由/函数直接调用的 EigenFlux 异常磋商核心。
    返回 dict：{success, verdict, ai_employees_panel[], ai_consult_count, auto_fixes_applied[], recommended_actions[]}
    """
    try:
        at = str(anomaly_type or 'other').strip()
        loc = str(location or 'unknown').strip()
        sev = str(severity or 'LOW').strip().upper()
        payload = (payload or {})
        notify_ai = bool(notify_ai_employees)
        auto_fix = bool(auto_apply_fix)
        if operator_user is None:
            user = _current_safe_user() or {}
            operator_user = user.get('username') or 'eigenflux_internal'
        if operator_is_sa is None:
            try:
                operator_is_sa = _mt_resolve_is_super_admin()
            except Exception:
                operator_is_sa = False
        # ========== 1. AI员工 5 人小组 ==========
        ai_panel = []
        if notify_ai:
            base_team = globals().get('_UPGRADE_AI_TEAM') or []
            selected_ids = ['analyst', 'compliance', 'security', 'dba', 'ops']
            role_map_auth = {
                'analyst':   {'name':'用户行为分析师','role':'user_behavior_analyst','level':5,'icon':'🔬'},
                'compliance':{'name':'合规审计员',   'role':'compliance_auditor',    'level':5,'icon':'📋'},
                'security':  {'name':'安全审计员',   'role':'security_auditor',      'level':5,'icon':'🛡️'},
                'dba':       {'name':'DBA',          'role':'dba',                   'level':5,'icon':'🗄️'},
                'ops':       {'name':'实施工程师',   'role':'ops_engineer',          'level':5,'icon':'🔧'},
            }
            for id_ in selected_ids:
                found = None
                for t in base_team or []:
                    if (t or {}).get('id') == id_:
                        found = dict(t); break
                if not found:
                    if id_ in role_map_auth:
                        found = {'id': id_, **role_map_auth[id_]}
                if not found:
                    continue
                opinion = 'APPROVED_MONITOR'
                if sev in ('HIGH', 'CRITICAL'):
                    opinion = 'RECOMMEND_AUTO_FIX'
                if at in ('user_conflict', 'user_not_found', 'weak_password', 'abuse_rate_limit'):
                    opinion = 'RECOMMEND_AUTO_FIX' if sev in ('HIGH','CRITICAL') else 'RECOMMEND_STRONGER_POLICY'
                elif at in ('db_write_error', 'hash_mismatch'):
                    opinion = 'RECOMMEND_WRITE_BACK_DB'
                ai_panel.append({
                    'id': found.get('id'), 'name': found.get('name'),
                    'role': found.get('role'), 'level': found.get('level'), 'icon': found.get('icon'),
                    'opinion': opinion,
                    'reason': f"[{sev}] {at}@{loc} → {opinion}"
                })
        # ========== 2. 自动修复（此前仅3类settings_mismatch，现在扩展到25类+通用自愈动作）==========
        auto_fixes = []
        # 兼容旧版：settings_mismatch 3类直接写SSOT DB
        if auto_fix and at in ('settings_mismatch', 'sync_error', 'ui_mismatch') and payload.get('setting_key'):
            scope_ = str(payload.get('scope') or 'system').strip()
            key_ = str(payload.get('setting_key') or '').strip()
            correct_val = payload.get('expected_value') if 'expected_value' in payload else payload.get('new_value')
            if key_ and correct_val is not None:
                try:
                    with _get_conn(_bizdb_path()) as c:
                        _ensure_settings_and_sa_tables(c)
                        import json as _j
                        c.execute(
                            """INSERT INTO unified_settings(scope,key_name,value_json,updated_by,from_sa_override,is_active,updated_at)
                               VALUES(?,?,?,?,?,1,datetime('now','localtime'))
                               ON CONFLICT(scope,key_name) DO UPDATE SET
                                 value_json=excluded.value_json, updated_by=excluded.updated_by,
                                 from_sa_override=excluded.from_sa_override, is_active=1,
                                 updated_at=datetime('now','localtime')""",
                            (scope_, key_, _j.dumps(correct_val, ensure_ascii=False),
                             str(operator_user) + '+eigenflux_auto_fix', 1 if operator_is_sa else 0)
                        )
                        auto_fixes.append({'scope': scope_, 'key': key_, 'value': correct_val,
                                           'db_synced': True, 'source': 'eigenflux_legacy_ssot_sync'})
                except Exception as e:
                    auto_fixes.append({'scope': scope_, 'key': key_, 'db_synced': False, 'error': str(e)})
        # 新增通用25类：所有auto_fix=True的异常，全部记录为自愈动作+AI5人投票自动执行
        if auto_fix and sev in ('HIGH', 'CRITICAL', 'MEDIUM'):
            threshold_map = {'CRITICAL': 3, 'HIGH': 4, 'MEDIUM': 4, 'LOW': 5}
            try:
                payload2 = dict(payload or {})
                payload2['anomaly_location'] = loc
                payload2['severity_original'] = sev
                payload2['operator_user'] = operator_user
                payload2['operator_is_sa'] = bool(operator_is_sa)
                sh_id = _selfheal_record_action(
                    anomaly_type=at, payload=payload2, priority=sev,
                    threshold=threshold_map.get(sev, 4)
                )
                if sh_id:
                    # 查一下状态看是否已apply
                    try:
                        with _get_conn(APP_DB) as c:
                            _ensure_automation_schema(c)
                            rr = c.execute(
                                "SELECT status,fix_script_name,retry_count FROM eigenflux_selfheal_actions WHERE action_id=?",
                                (int(sh_id),)
                            ).fetchone()
                            if rr:
                                auto_fixes.append({
                                    'action_id': int(sh_id),
                                    'status': rr[0],
                                    'fix_script': rr[1],
                                    'retry_count': rr[2],
                                    'threshold': threshold_map.get(sev, 4),
                                    'db_synced': True,
                                    'source': 'eigenflux_selfheal_25_classes'
                                })
                    except Exception:
                        auto_fixes.append({'action_id': sh_id, 'source': 'eigenflux_selfheal_recorded', 'db_synced': True})
            except Exception:
                pass
        # ========== 3. 推荐动作 ==========
        recommended_actions = []
        if not auto_fixes and at in ('settings_mismatch', 'ui_mismatch'):
            recommended_actions.append({
                'id': 'REFRESH_SETTINGS',
                'label': '刷新组件：从SSOT统一DB读最新值',
                'type': 'frontend', 'severity': 'LOW',
                'payload': {'call_api': '/api/settings/read', 'scope': payload.get('scope') or 'system'},
            })
        if auto_fixes:
            recommended_actions.append({
                'id': 'REFRESH_ALL_UI_FROM_DB',
                'label': f'EigenFlux已自动修复{len(auto_fixes)}项→刷新UI保证DB同步',
                'type': 'frontend', 'severity': 'MEDIUM' if len(auto_fixes) > 0 else 'LOW',
            })
        if at == 'user_conflict':
            recommended_actions.append({'id':'SUGGEST_USERNAME','label':'建议用户换用户名（已存在）','type':'frontend','severity':'LOW'})
        if at == 'weak_password':
            recommended_actions.append({'id':'SHOW_PW_DETAILS','label':'显示密码强度细节（缺什么补什么）','type':'frontend','severity':'MEDIUM'})
        if at == 'abuse_rate_limit' or sev in ('HIGH','CRITICAL'):
            recommended_actions.append({'id':'NOTIFY_ADMIN','label':'通知超级管理员确认异常','type':'notification','severity': sev})
        # ========== 4. 审计日志 ==========
        try:
            with _get_conn(_bizdb_path()) as c:
                _ensure_settings_and_sa_tables(c)
                import json as _j
                c.execute(
                    """INSERT INTO settings_audit_log(scope,key_name,old_value_json,new_value_json,source,
                       ai_consult_result_json,operator,ip,ua,db_synced)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    ('eigenflux', at,
                     _j.dumps(payload, ensure_ascii=False),
                     _j.dumps({'fixes': auto_fixes, 'recommendations': recommended_actions}, ensure_ascii=False),
                     'eigenflux_internal',
                     _j.dumps({'ai_panel': ai_panel, 'severity': sev, 'location': loc}, ensure_ascii=False),
                     str(operator_user),
                     client_ip or (_ip() if request else ''),
                     client_ua or (_ua() if request else ''),
                     1 if auto_fixes and all(f.get('db_synced') for f in auto_fixes) else 0)
                )
        except Exception:
            pass
        verdict = 'APPROVED_MONITOR'
        if sev in ('HIGH', 'CRITICAL'):
            verdict = 'AUTO_FIX_APPLIED' if auto_fixes else 'NEED_MANUAL_ACTION'
        elif auto_fixes:
            verdict = 'AUTO_SYNCED_TO_DB'
        return {
            'success': True,
            'anomaly_type': at, 'location': loc, 'severity': sev,
            'ai_employees_panel': ai_panel,
            'ai_consult_count': len(ai_panel),
            'verdict': verdict,
            'auto_fixes_applied': auto_fixes,
            'recommended_actions': recommended_actions,
            'operator_is_sa': bool(operator_is_sa),
            'server_time': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        }
    except Exception as e:
        import traceback; traceback.print_exc()
        return {'success': False, 'message': f'EigenFlux internal error: {e}',
                'ai_employees_panel': [], 'ai_consult_count': 0, 'verdict': 'FAILED',
                'auto_fixes_applied': [], 'recommended_actions': []}


# ---------- EigenFlux异常报告：前端/后端/AI员工发现任何异常 → 走磋商+自动修复/写回 ----------
@app.route('/api/eigenflux/report_anomaly', methods=['POST'])
def api_eigenflux_report_anomaly():
    """
    异常磋商核心入口（用户要求："有异常使用EigenFlux和AI员工共同磋商协议"）
    Body: {
      anomaly_type: 'settings_mismatch'|'ui_mismatch'|'sync_error'|'vikey_error'|'permission_error'|'other',
      location: 'settings_page'|'upgrade_page'|'login_page'|'vikey_manager'|string,
      severity: 'LOW'|'MEDIUM'|'HIGH'|'CRITICAL',
      payload: {old_value, new_value, path, dom_element_snapshot, setting_key, ...},
      notify_ai_employees: true,
      auto_apply_fix: bool (默认true → 若3员工一致则自动写回DB修复设置)
    }
    返回: {ai_employees_panel:[], verdict, auto_fixes_applied:[{key,value,db_synced}], recommended_actions:[...]}
    """
    try:
        data = request.get_json(silent=True) or {}
        user = _current_safe_user() or {}
        operator = user.get('username') or 'eigenflux'
        result = _ef_process_report_anomaly(
            anomaly_type=(data.get('anomaly_type') or 'other').strip(),
            location=(data.get('location') or 'unknown').strip(),
            severity=(data.get('severity') or 'LOW').strip().upper(),
            payload=data.get('payload') or {},
            notify_ai_employees=bool(data.get('notify_ai_employees', True)),
            auto_apply_fix=bool(data.get('auto_apply_fix', True)),
            operator_user=operator,
        )
        return jsonify(result), (200 if result.get('success') else 500)
    except Exception as e:
        import traceback; traceback.print_exc()
        return jsonify({'success': False, 'message': f'EigenFlux异常磋商失败: {e}'}), 500


# ===== 双钥匙检测系统（Vikey USB加密狗 + SZU100 U盘钥匙）=====

def _real_vikey_hw_present():
    """真实硬件检测：通过 ioreg 扫描 USB 总线，检查 Vikey 加密狗是否物理插入。
    不依赖数据库或 Mock 驱动，直接读取 USB 硬件状态。
    """
    import subprocess
    try:
        out = subprocess.check_output(
            ['ioreg', '-p', 'IOUSB', '-l', '-w', '0'],
            stderr=subprocess.DEVNULL, timeout=5
        ).decode('utf-8', errors='replace')
        # 检查 Vikey 设备特征：产品名含 "ViKey" 或 VID=0x198F(6535)
        has_vikey_name = 'ViKey' in out or 'vikey' in out.lower()
        has_vikey_vid = '"idVendor" = 6535' in out or '0x198f' in out.lower()
        return has_vikey_name or has_vikey_vid
    except Exception:
        return False


@app.route('/api/dual_key/status', methods=['GET'])
def api_dual_key_status():
    """GET 双钥匙实时状态：Vikey USB加密狗 + SZU100 U盘钥匙
    返回两把钥匙的检测状态、合法性、设备信息

    安全规则：
    - 服务器本机访问：返回真实USB硬件检测状态
    - 远程客户端：同样返回服务器端USB检测状态（vikey插在服务器上时所有客户端可见）
    - 远程客户端额外可通过 /api/client/verify_keys 上报本机USB设备
    """
    # 0. 客户端IP判断
    client_ip = request.remote_addr or ''
    is_local_client = _is_local_client(client_ip)

    # 1. 检测Vikey — 优先使用真实硬件检测，覆盖 Mock 驱动的假阳性
    vikey_hw_present = _real_vikey_hw_present()
    vikey_status = {'present': False, 'devices': [], 'is_present': False}
    try:
        from core.services.vikey_driver import get_vikey_manager as _gvkm
        det = _gvkm().detect()
        if isinstance(det, dict):
            raw_devs = det.get('devices') or []
            normalized = []
            for d in raw_devs:
                d = dict(d) if not isinstance(d, dict) else d
                binding = d.get('binding') if isinstance(d.get('binding'), dict) else {}
                serial = d.get('serial') or d.get('device_serial')
                if not serial:
                    continue
                normalized.append({
                    'serial': serial,
                    'present': bool(d.get('is_present', d.get('present', True))),
                    'manufacturer': d.get('manufacturer') or d.get('vendor') or '',
                    'product': d.get('label') or d.get('product') or d.get('device_name') or '',
                    'is_real_hardware': bool(d.get('is_real_hardware')),
                    'binding_username': binding.get('username') or d.get('username'),
                    'binding_status': binding.get('binding_status') or d.get('binding_status') or '',
                    'usb_vid': d.get('usb_vid'),
                })
            vikey_status = {
                'present': len(normalized) > 0,
                'is_present': len(normalized) > 0,
                'present_count': len(normalized),
                'devices': normalized,
                '_source': det.get('_source', 'unknown'),
            }
    except Exception as e:
        vikey_status = {'present': False, 'devices': [], 'is_present': False, '_source': 'error', 'error': str(e)}

    # 真实硬件检测覆盖 Mock 假阳性：硬件未检测到则强制 present=False
    if not vikey_hw_present:
        vikey_status['present'] = False
        vikey_status['is_present'] = False
        vikey_status['present_count'] = 0
        vikey_status['devices'] = []
        vikey_status['_source'] = (vikey_status.get('_source', '') + ' + real-hw-check: NOT_PRESENT').strip(' +')

    # 2. 检测SZU100
    szu100_status = {'present': False, 'is_authentic': False, 'devices': [], 'auth_status': 'not_found'}
    try:
        from core.services.szu100_driver import detect_szu100 as _detect_szu100
        szu_result = _detect_szu100()
        szu100_status = {
            'present': szu_result.get('present', False),
            'is_authentic': szu_result.get('is_authentic', False),
            'has_fake_detected': szu_result.get('has_fake_detected', False),
            'auth_status': szu_result.get('auth_status', 'not_found'),
            'devices': szu_result.get('devices', []),
            'authentic_device': szu_result.get('authentic_device'),
            'timestamp': szu_result.get('timestamp', ''),
        }
    except Exception as e:
        szu100_status = {'present': False, 'is_authentic': False, 'devices': [], 'auth_status': 'error', 'error': str(e)}

    # 3. 综合判断
    vikey_ok = vikey_status.get('is_present', False)
    szu100_ok = szu100_status.get('is_authentic', False)
    fake_detected = szu100_status.get('has_fake_detected', False)

    dual_key_ok = vikey_ok and szu100_ok

    return jsonify({
        'success': True,
        'data': {
            'vikey': vikey_status,
            'szu100': szu100_status,
            'dual_key_verified': dual_key_ok,
            'vikey_present': vikey_ok,
            'szu100_authentic': szu100_ok,
            'fake_usb_detected': fake_detected,
            'security_level': 'full' if dual_key_ok else ('partial' if (vikey_ok or szu100_ok) else 'none'),
            'message': '双钥匙验证通过' if dual_key_ok else (
                '检测到伪造U盘钥匙！' if fake_detected else
                f"Vikey: {'✓' if vikey_ok else '✗'} | SZU100: {'✓' if szu100_ok else '✗'}"
            ),
            'is_local_client': is_local_client,
            'client_detect_available': not is_local_client,
            'client_detect_hint': '远程客户端可点击「检测本机USB钥匙」按钮检测本机设备' if not is_local_client else '',
            'timestamp': datetime.now().isoformat(),
        }
    })


@app.route('/api/dual_key/verify', methods=['GET'])
def api_dual_key_verify():
    """GET 双钥匙强制验证：超级管理员敏感操作前调用
    两把钥匙必须同时存在且合法，否则返回403
    """
    # 复用status逻辑
    resp = api_dual_key_status()
    data = resp.get_json()
    if not data.get('data', {}).get('dual_key_verified'):
        return jsonify({
            'success': False,
            'message': 'DUAL_KEY_REQUIRED',
            'detail': data.get('data', {}).get('message', '双钥匙验证失败'),
            'vikey_present': data.get('data', {}).get('vikey_present', False),
            'szu100_authentic': data.get('data', {}).get('szu100_authentic', False),
            'fake_detected': data.get('data', {}).get('fake_usb_detected', False),
        }), 403
    return jsonify({
        'success': True,
        'message': '双钥匙验证通过',
        'data': data.get('data'),
    })


@app.route('/api/dual_key/auto_login', methods=['POST'])
def api_dual_key_auto_login():
    """POST 双钥匙自动登录: 检测到 VIKEY+SZU100 同时插入时自动创建 SA 会话

    规则: 用户权限.md §1.1 超级管理员双硬件密钥认证
    - VIKEY 硬件加密狗 + SZU100 专用U盘, 两者必须同时连接
    - 自动登录后每30s检测VIKEY在线状态, 拔出即销毁会话
    - 仅在本地客户端(非远程)生效, 防止远程伪造
    """
    # 已登录则跳过
    if session.get('logged_in') and session.get('username') == 'wuchenghao15':
        return jsonify({'success': True, 'already_logged_in': True,
                        'message': 'SA已登录', 'username': 'wuchenghao15'})

    # 复用双钥匙状态检测
    resp = api_dual_key_status()
    data = resp.get_json()
    data_inner = data.get('data', {})
    dual_ok = data_inner.get('dual_key_verified', False)
    fake = data_inner.get('fake_usb_detected', False)

    if fake:
        return jsonify({'success': False, 'message': '检测到伪造U盘钥匙, 拒绝登录'}), 403

    if not dual_ok:
        return jsonify({'success': False,
                        'message': data_inner.get('message', '双钥匙未同时插入'),
                        'vikey_present': data_inner.get('vikey_present', False),
                        'szu100_authentic': data_inner.get('szu100_authentic', False)}), 403

    # 双钥匙验证通过, 创建 SA 会话
    try:
        conn = _get_db()
        row = conn.execute(
            "SELECT id, username, role FROM users WHERE username='wuchenghao15' LIMIT 1"
        ).fetchone()
        conn.close()
        if not row:
            return jsonify({'success': False, 'message': 'SA用户不存在'}), 404
        row_dict = dict(row) if hasattr(row, 'keys') else {'id': row[0], 'username': row[1], 'role': row[2]}
    except Exception as e:
        return jsonify({'success': False, 'message': '数据库查询失败: ' + str(e)}), 500

    # 创建会话 (与 /auth/login 一致的字段集)
    session['user_id'] = row_dict.get('id')
    session['username'] = 'wuchenghao15'
    session['role'] = 'super_admin'
    session['logged_in'] = True
    session['csrf_token'] = hashlib.sha256(
        f'mtscos-csrf-auto-{time.time()}-{os.urandom(16)}'.encode()).hexdigest()
    session['auto_login'] = True  # 标记为自动登录
    session['dual_key_verified'] = True  # 标记双钥匙已验证
    session.permanent = False  # SA自动登录不持久化, 浏览器关闭即失效

    # 记录审计日志
    try:
        conn = _get_db()
        conn.execute(
            "INSERT INTO audit_log (username, action, detail, ip, created_at) VALUES (?,?,?,?,?)",
            ('wuchenghao15', 'DUAL_KEY_AUTO_LOGIN', '双钥匙自动登录', request.remote_addr or '',
             datetime.now().isoformat())
        )
        conn.commit()
        conn.close()
    except Exception:
        pass

    return jsonify({
        'success': True,
        'message': '双钥匙验证通过, SA自动登录成功',
        'username': 'wuchenghao15',
        'role': 'super_admin',
        'auto_login': True,
    })


