def _scan_code_issues():
    """代码巡检：扫描代码库中的异常、错误和Bug"""
    issues = []
    critical_count = 0

    try:
        for root, dirs, files in os.walk(BASE_DIR):
            for filename in files:
                if filename.endswith('.py'):
                    filepath = os.path.join(root, filename)
                    try:
                        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                            content = f.read()
                            lines = content.split('\n')

                            for i, line in enumerate(lines, 1):
                                if 'raise Exception' in line or 'raise ValueError' in line:
                                    issues.append({
                                        'file': filepath,
                                        'line': i,
                                        'type': 'exception',
                                        'severity': 'medium',
                                        'message': f'异常抛出: {line.strip()[:50]}',
                                    })
                                if 'print(' in line and 'debug' in line.lower():
                                    issues.append({
                                        'file': filepath,
                                        'line': i,
                                        'type': 'debug',
                                        'severity': 'low',
                                        'message': f'调试代码残留: {line.strip()[:50]}',
                                    })
                                if 'TODO' in line or 'FIXME' in line:
                                    issues.append({
                                        'file': filepath,
                                        'line': i,
                                        'type': 'todo',
                                        'severity': 'low',
                                        'message': f'待处理任务: {line.strip()[:50]}',
                                    })
                    except Exception:
                        pass
    except Exception:
        pass

    critical_count = sum(1 for i in issues if i['severity'] == 'high')

    return {
        'total_issues': len(issues),
        'critical_count': critical_count,
        'issues': issues[:20],
        'scan_time': datetime.now().isoformat(),
    }


def _scan_vulnerabilities():
    """漏洞扫描：扫描系统中的安全漏洞"""
    vulnerabilities = []
    critical_count = 0

    try:
        for root, dirs, files in os.walk(BASE_DIR):
            for filename in files:
                filepath = os.path.join(root, filename)
                if filename.endswith('.py'):
                    try:
                        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                            content = f.read()

                            if 'password' in content.lower() and ('=' in content or ': ' in content):
                                vulnerabilities.append({
                                    'file': filepath,
                                    'type': 'hardcoded_password',
                                    'severity': 'critical',
                                    'message': '可能存在硬编码密码',
                                })
                                critical_count += 1

                            if 'secret' in content.lower() and ('=' in content or ': ' in content):
                                vulnerabilities.append({
                                    'file': filepath,
                                    'type': 'hardcoded_secret',
                                    'severity': 'critical',
                                    'message': '可能存在硬编码密钥',
                                })
                                critical_count += 1

                            if 'exec(' in content or 'eval(' in content:
                                vulnerabilities.append({
                                    'file': filepath,
                                    'type': 'code_execution',
                                    'severity': 'high',
                                    'message': '存在代码执行风险',
                                })

                            if 'subprocess' in content and 'shell=True' in content:
                                vulnerabilities.append({
                                    'file': filepath,
                                    'type': 'shell_injection',
                                    'severity': 'high',
                                    'message': '存在Shell注入风险',
                                })
                    except Exception:
                        pass
    except Exception:
        pass

    return {
        'vulnerabilities': len(vulnerabilities),
        'critical_count': critical_count,
        'vulnerabilities_list': vulnerabilities[:10],
        'scan_time': datetime.now().isoformat(),
    }


def _monitor_log_errors():
    """日志监控：监控控制台错误日志"""
    errors = []
    latest_error = ''

    try:
        log_dir = os.path.join(BASE_DIR, 'logs')
        if os.path.exists(log_dir):
            for filename in os.listdir(log_dir):
                if filename.endswith('.log'):
                    filepath = os.path.join(log_dir, filename)
                    try:
                        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                            lines = f.readlines()[-50:]
                            for line in lines:
                                if 'ERROR' in line or 'Exception' in line or 'Traceback' in line:
                                    errors.append({
                                        'log_file': filename,
                                        'message': line.strip()[:100],
                                        'timestamp': line[:25] if len(line) > 25 else '',
                                    })
                                    if not latest_error:
                                        latest_error = line.strip()[:80]
                    except Exception:
                        pass
    except Exception:
        pass

    return {
        'errors_found': len(errors),
        'latest_error': latest_error,
        'errors': errors[:10],
        'monitor_time': datetime.now().isoformat(),
    }


