# ========== EigenFlux 项目修复工程 API ==========

def _eigenflux_scan_project_issues():
    """EigenFlux 扫描项目问题：路由断裂、导入错误、模板缺失、资源 404"""
    issues = []

    # 1. 检查模板文件是否存在
    template_dir = os.path.join(BASE_DIR, 'templates')
    for root, dirs, files in os.walk(template_dir):
        for f in files:
            if f.endswith('.html'):
                fpath = os.path.join(root, f)
                rel = os.path.relpath(fpath, template_dir)
                try:
                    with open(fpath, 'r', encoding='utf-8', errors='ignore') as fh:
                        content = fh.read()
                    # 检查是否有未闭合的 Jinja 块
                    opens = content.count('{% block')
                    closes = content.count('{% endblock')
                    if opens != closes:
                        issues.append({
                            'category': 'template_error',
                            'severity': 'high',
                            'file': rel,
                            'message': f'Jinja block 未配对: {opens} 个 block, {closes} 个 endblock',
                        })
                except Exception as e:
                    issues.append({
                        'category': 'template_error',
                        'severity': 'medium',
                        'file': rel,
                        'message': str(e)[:200],
                    })

    # 2. 检查静态资源引用
    static_dir = os.path.join(BASE_DIR, 'static')
    for root, dirs, files in os.walk(template_dir):
        for f in files:
            if f.endswith('.html'):
                fpath = os.path.join(root, f)
                rel = os.path.relpath(fpath, template_dir)
                try:
                    with open(fpath, 'r', encoding='utf-8', errors='ignore') as fh:
                        content = fh.read()
                    import re as _re
                    # 查找 /assets/ 引用
                    for m in _re.finditer(r'(?:href|src)=["\'](/assets/[^"\']+)["\']', content):
                        asset_path = m.group(1).lstrip('/')
                        full = os.path.join(static_dir, asset_path)
                        if not os.path.exists(full):
                            issues.append({
                                'category': 'http_404',
                                'severity': 'medium',
                                'file': rel,
                                'message': f'静态资源缺失: /{asset_path}',
                            })
                except Exception:
                    pass

    # 3. 检查 EigenFlux 规则引擎验证
    try:
        from core.services.eigenflux_rules import EigenFluxRulesEngine
        engine = EigenFluxRulesEngine()
        report = engine.validate_project()
        if not report.get('success'):
            for v in report.get('violations', []):
                issues.append({
                    'category': 'rule_violation',
                    'severity': v.get('severity', 'medium'),
                    'file': v.get('file', ''),
                    'message': f"[{v.get('rule_id', '?')}] {v.get('message', '')}",
                })
    except Exception as e:
        issues.append({
            'category': 'import_error',
            'severity': 'high',
            'file': 'core/services/eigenflux_rules.py',
            'message': f'EigenFlux 规则引擎加载失败: {e}',
        })

    return issues


@app.route('/api/eigenflux/repair_project', methods=['POST'])
def api_eigenflux_repair_project():
    """EigenFlux 项目修复工程 — 扫描+修复+验证"""
    try:
        # 1. 扫描项目问题
        issues = _eigenflux_scan_project_issues()

        # 2. 使用 EigenFlux 自动修复服务
        from services.ai.eigenflux_auto_repair_service import (
            EigenFluxAutoRepairService, EXCEPTION_CATEGORIES as _EX_CATS,
        )
        repair_svc = EigenFluxAutoRepairService()
        repair_svc.init_tables()

        repaired = []
        failed = []
        skipped = []

        for issue in issues:
            cat = issue.get('category', 'unknown')
            cat_info = _EX_CATS.get(cat, {})
            if not cat_info.get('auto_repairable', False):
                skipped.append(issue)
                continue

            # 注册异常（detect_exception 会自动分类）
            detect_result = repair_svc.detect_exception(
                error_message=issue['message'],
                source=issue.get('file', ''),
                file_path=issue.get('file', ''),
            )

            exc_id = detect_result.get('exception_id') if detect_result.get('success') else None

            if exc_id:
                result = repair_svc.auto_repair(exc_id)
                if result.get('success'):
                    repaired.append({
                        'issue': issue,
                        'exception_id': exc_id,
                        'result': result,
                    })
                else:
                    failed.append({
                        'issue': issue,
                        'exception_id': exc_id,
                        'error': result.get('error', 'unknown'),
                    })
            else:
                skipped.append(issue)

        # 3. 向 EigenFlux 广播修复结果
        try:
            from app.services.eigenflux_adapter import send_broadcast_message
            send_broadcast_message(
                sender_id='eigenflux_repair_project',
                content=json.dumps({
                    'event': 'project_repair_completed',
                    'total_issues': len(issues),
                    'repaired': len(repaired),
                    'failed': len(failed),
                    'skipped': len(skipped),
                    'timestamp': datetime.now().isoformat(),
                }, ensure_ascii=False),
                topic='mtscos/repair/project_repair',
            )
        except Exception:
            pass

        return jsonify({
            'success': True,
            'data': {
                'total_issues': len(issues),
                'repaired': len(repaired),
                'failed': len(failed),
                'skipped': len(skipped),
                'issues': issues,
                'repair_results': {
                    'repaired': repaired,
                    'failed': failed,
                    'skipped': skipped,
                },
            },
        })
    except Exception as e:
        logger.error(f"EigenFlux 项目修复失败: {e}")
        return jsonify({'success': False, 'message': str(e)}), 500


