@app.route('/api/ai/system-upgrade/quick', methods=['POST'])
def api_ai_system_upgrade_quick():
    """快速执行单次升级迭代"""
    user = _current_safe_user()
    if not user.get('logged_in'):
        return jsonify({'success': False, 'error': '未登录'}), 401

