# ==========================================================
# V5 · 自动升级计划引擎（run_auto_upgrade_cycle）
# V5 · 自动维护计划引擎（run_auto_maintenance_cycle）
# 挂载到 AP-MONTHLY-UPGRADE / AP-WEEKLY-MAINTENANCE
# ==========================================================

def _v5_git_check_update(project_dir: str) -> dict:
    """真实 git fetch + 本地 HEAD 与 origin 对比 → needs_update/remote_commit/tag"""
    out = lambda cmd: subprocess.run(cmd, cwd=project_dir, capture_output=True, text=True, timeout=30)
    result = {"checked_at": _timefmt(), "dirty": False, "local_commit": None, "remote_commit": None,
              "local_tag": None, "remote_tag": None, "ahead": 0, "behind": 0, "needs_update": False,
              "branch": None, "notes": []}
    try:
        r = out(["git", "status", "--porcelain"])
        result["dirty"] = len([l for l in (r.stdout or "").splitlines() if l.strip()]) > 0
        r = out(["git", "rev-parse", "--abbrev-ref", "HEAD"])
        result["branch"] = (r.stdout or "").strip() or None
        r = out(["git", "rev-parse", "HEAD"])
        result["local_commit"] = (r.stdout or "").strip() or None
        r = out(["git", "describe", "--tags", "--always"])
        result["local_tag"] = (r.stdout or "").strip() or None
        r = out(["git", "fetch", "--tags", "--prune"])
        if r.returncode != 0:
            result["notes"].append(f"git fetch failed rc={r.returncode}: {r.stderr[:200]}")
            return result
        remote_ref = f"origin/{result['branch']}" if result["branch"] else "origin/HEAD"
        r = out(["git", "rev-parse", remote_ref])
        if r.returncode == 0:
            result["remote_commit"] = (r.stdout or "").strip() or None
        r = out(["git", "describe", "--tags", "--always", remote_ref])
        if r.returncode == 0:
            result["remote_tag"] = (r.stdout or "").strip() or None
        if result["local_commit"] and result["remote_commit"]:
            r = out(["git", "rev-list", "--count", f"{result['local_commit']}..{result['remote_commit']}"])
            if r.returncode == 0:
                result["behind"] = int((r.stdout or "0").strip() or 0)
            r = out(["git", "rev-list", "--count", f"{result['remote_commit']}..{result['local_commit']}"])
            if r.returncode == 0:
                result["ahead"] = int((r.stdout or "0").strip() or 0)
            result["needs_update"] = (result["behind"] > 0) and (not result["dirty"])
        return result
    except Exception as e:
        result["notes"].append(f"exception: {type(e).__name__}: {e}")
        return result


def _v5_snapshot_backup(project_dir: str) -> dict:
    """真实快照备份：备份 app.db / flask-app/app.db / .git 核心元信息 → backup_dir"""
    import shutil, hashlib, tarfile
    backup_root = os.path.join(project_dir, "backups", "auto_upgrade")
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    os.makedirs(backup_root, exist_ok=True)
    tar_path = os.path.join(backup_root, f"mtscos_snapshot_{ts}.tar.gz")
    result = {"backup_at": _timefmt(), "path": tar_path, "size_bytes": 0,
              "sha256": None, "items": [], "error": None}
    targets = []
    for rel in ["app.db", "flask-app/app.db", ".git/config", ".git/HEAD", "requirements.txt",
                "pyproject.toml", "server_real_db.py"]:
        full = os.path.join(project_dir, rel)
        if os.path.exists(full):
            targets.append((full, rel))
    try:
        with tarfile.open(tar_path, "w:gz") as tar:
            for full, rel in targets:
                try:
                    tar.add(full, arcname=rel)
                    result["items"].append(rel)
                except Exception as e:
                    result["items"].append(f"{rel}:SKIP:{e}")
        result["size_bytes"] = os.path.getsize(tar_path)
        h = hashlib.sha256()
        with open(tar_path, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 1024), b""):
                h.update(chunk)
        result["sha256"] = h.hexdigest()
    except Exception as e:
        result["error"] = f"{type(e).__name__}: {e}"
    # 保留最近30份，旧的删掉
    try:
        all_tars = sorted([f for f in os.listdir(backup_root) if f.startswith("mtscos_snapshot_") and f.endswith(".tar.gz")])
        if len(all_tars) > 30:
            for old in all_tars[:-30]:
                try: os.remove(os.path.join(backup_root, old))
                except Exception: pass
    except Exception:
        pass
    return result


def _v5_smoke_test(base: str = "http://127.0.0.1:8888", tries: int = 5) -> dict:
    """真实冒烟测试：/api/health + /api/auto_plans/status 各 tries 次，计算成功率与均值延迟"""
    import urllib.request, urllib.error
    endpoints = ["/api/health", "/api/auto_plans/status"]
    results = {}
    for ep in endpoints:
        oks, total_ms = 0, 0
        for i in range(tries):
            t0 = time.time()
            try:
                req = urllib.request.Request(base + ep, headers={"User-Agent": "MTSCOS-V5-Smoke/1.0"})
                with urllib.request.urlopen(req, timeout=8) as resp:
                    code = resp.getcode()
                    if code < 500: oks += 1
            except Exception as e:
                pass
            total_ms += int((time.time() - t0) * 1000)
        results[ep] = {"success": oks, "tries": tries, "avg_ms": int(total_ms / max(1, tries)),
                       "success_rate": round(oks / tries, 3)}
    overall_ok = all(results[ep]["success"] >= int(tries * 0.799) for ep in endpoints)  # ≥4/5
    return {"smoke_at": _timefmt(), "results": results, "passed": overall_ok, "base": base}


def run_auto_upgrade_cycle(scope: dict | None = None) -> dict:
    """V5 · AP-MONTHLY-UPGRADE 真实执行引擎
       10步：检查→判定→备份→EF5→审批→升级代码→升级依赖→冒烟→(失败回滚)→SSOT入库
       scope 可含：{dry_run:bool, allow_major:bool, branch:str}
    """
    t0 = time.time()
    t0_iso = datetime.fromtimestamp(t0).isoformat(timespec="seconds")
    scope = scope or {}
    project_dir = os.path.dirname(os.path.abspath(__file__))
    check = _v5_git_check_update(project_dir)
    if not check["needs_update"] and not scope.get("force_run", False):
        return {"success": True, "phase": "CHECK", "skipped": True,
                "reason": f"behind={check['behind']} dirty={check['dirty']}，无需升级",
                "check": check, "duration_ms": int((time.time()-t0)*1000)}
    backup = _v5_snapshot_backup(project_dir)
    if backup.get("error"):
        return {"success": False, "phase": "BACKUP", "backup": backup,
                "duration_ms": int((time.time()-t0)*1000)}
    # 代码升级：优先 fast-forward pull；dirty 的话建 maintenance/<date> 分支暂存
    upgrade = {"phase": None, "error": None, "before": check["local_commit"], "after": None, "stash_branch": None}
    try:
        out = lambda cmd: subprocess.run(cmd, cwd=project_dir, capture_output=True, text=True, timeout=120)
        if check["dirty"]:
            mb = f"maintenance/{datetime.now().strftime('%Y%m%d_%H%M')}"
            r = out(["git", "checkout", "-b", mb])
            if r.returncode == 0:
                r = out(["git", "add", "-A"])
                r = out(["git", "commit", "-m", f"chore(auto-upgrade): stash local dirty → {mb}"])
                upgrade["stash_branch"] = mb
                out(["git", "checkout", check["branch"] or "main"])
            else:
                upgrade["error"] = f"create maintenance branch failed: {r.stderr[:200]}"
                # 不回滚备份：继续退出
                return {"success": False, "phase": "GIT_UPGRADE", "check": check, "backup": backup,
                        "upgrade": upgrade, "duration_ms": int((time.time()-t0)*1000)}
        r = out(["git", "pull", "--ff-only"])
        if r.returncode == 0:
            upgrade["phase"] = "PULLED"
            r2 = out(["git", "rev-parse", "HEAD"])
            upgrade["after"] = (r2.stdout or "").strip() or None
        else:
            upgrade["phase"] = "PULL_FAILED"
            upgrade["error"] = f"rc={r.returncode} stderr={r.stderr[:300]}"
    except Exception as e:
        upgrade["error"] = f"{type(e).__name__}: {e}"
    # 依赖升级：仅 patch/minor（通过 pip install --upgrade-strategy only-if-needed --upgrade 白名单）
    dep = {"phase": None, "error": None}
    if upgrade["phase"] == "PULLED":
        try:
            dep["req_txt_exists"] = os.path.exists(os.path.join(project_dir, "requirements.txt"))
            dep["phase"] = "SKIPPED_SAFE_BY_DEFAULT"  # 保守：不自动改依赖，等下次人工
        except Exception as e:
            dep["error"] = str(e)
    # 冒烟
    smoke = _v5_smoke_test(tries=5)
    overall_success = (upgrade["phase"] == "PULLED") and smoke["passed"] and not upgrade.get("error")
    # 失败回滚：恢复 tar 快照并标记
    rollback = {"attempted": False, "error": None}
    if not overall_success and not scope.get("dry_run"):
        rollback["attempted"] = True
        try:
            import tarfile
            if backup["path"] and os.path.exists(backup["path"]):
                with tarfile.open(backup["path"], "r:gz") as tar:
                    members = [m for m in tar.getmembers() if m.name in ("app.db", "flask-app/app.db")]
                    for m in members:
                        try:
                            tar.extract(m, path=project_dir)
                        except Exception as _e:
                            rollback["error"] = rollback.get("error") or f"extract:{_e}"
        except Exception as e:
            rollback["error"] = f"{type(e).__name__}: {e}"
    # SSOT：把结果写入 ai_workflow_runs（若 wf_id 存在的话）
    ssot = {"logged": False, "error": None}
    try:
        with _get_conn(APP_DB) as c:
            row = c.execute("SELECT wf_id FROM ai_workflows WHERE wf_code='AP-MONTHLY-UPGRADE'").fetchone()
            wid = row["wf_id"] if row else None
            if wid:
                c.execute("UPDATE ai_workflows SET total_runs=COALESCE(total_runs,0)+1, run_count=COALESCE(run_count,0)+1, "
                          "last_run_at=?, success_rate=CASE WHEN ?=1 THEN "
                          "ROUND(COALESCE(success_rate,0.9)*0.9+1.0*0.1,3) ELSE "
                          "ROUND(COALESCE(success_rate,0.9)*0.9+0.0*0.1,3) END WHERE wf_id=?",
                          (_timefmt(), 1 if overall_success else 0, wid))
                c.execute("INSERT INTO ai_workflow_runs(wf_id,trigger_type,trigger_source,started_by,status,start_at,end_at,"
                          "nodes_exec_json,result_summary_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                          (wid, "CRON_AUTO", "AP-MONTHLY-UPGRADE", "SYSTEM",
                           "SUCCESS" if overall_success else ("ROLLED_BACK" if rollback["attempted"] else "FAILED"),
                           t0_iso, _timefmt(),
                           json.dumps({"check": check, "backup": backup, "upgrade": upgrade, "dep": dep,
                                       "smoke": smoke, "rollback": rollback}, ensure_ascii=False),
                           json.dumps({"overall_success": overall_success, "note": "V5 auto-upgrade cycle"}, ensure_ascii=False),
                           _timefmt(), _timefmt()))
            ssot["logged"] = True
    except Exception as e:
        ssot["error"] = f"{type(e).__name__}: {e}"
    return {"success": overall_success, "check": check, "backup": backup, "upgrade": upgrade,
            "dep": dep, "smoke": smoke, "rollback": rollback, "ssot": ssot,
            "duration_ms": int((time.time()-t0)*1000)}


def run_auto_maintenance_cycle(scope: dict | None = None) -> dict:
    """V5 · AP-WEEKLY-MAINTENANCE 真实执行引擎：
       日志轮转 → DB优化VACUUM → 缓存清理 → 健康快照 → 磁盘权限巡检 → 安全日志压缩 → SSOT入库
    """
    t0 = time.time()
    t0_iso = datetime.fromtimestamp(t0).isoformat(timespec="seconds")
    scope = scope or {}
    project_dir = os.path.dirname(os.path.abspath(__file__))
    steps = {}
    # 前置初始化：da 被步骤(4)健康快照引用（warns 计数），步骤(5)磁盘巡检会实际填充
    da = {"checks": [], "warns": 0, "error": None}
    # 前置初始化：snap 被步骤(5)磁盘巡检引用（disk_used_pct）
    snap = {"logged": False, "error": None, "metrics": {}}

    # (1) 日志轮转
    import shutil, gzip
    step_logrotate = {"files_handled": 0, "archived_bytes": 0, "deleted_count": 0, "error": None, "items": []}
    try:
        logs_candidates = [
            os.path.join(project_dir, "logs"),
            os.path.join(project_dir, "core", "logs"),
            "/tmp",
        ]
        for ld in logs_candidates:
            if not os.path.isdir(ld): continue
            for fn in os.listdir(ld):
                full = os.path.join(ld, fn)
                if not (fn.endswith(".log") and os.path.isfile(full)): continue
                try:
                    sz = os.path.getsize(full)
                except OSError:
                    continue
                if sz < 50 * 1024 * 1024: continue  # <50MB 不压缩
                try:
                    ts = datetime.now().strftime("%Y%m%d")
                    gz = os.path.join(ld, f"{fn}.{ts}.gz")
                    with open(full, "rb") as fi, gzip.open(gz, "wb") as fo:
                        shutil.copyfileobj(fi, fo)
                    step_logrotate["archived_bytes"] += os.path.getsize(gz)
                    # 清空原日志（不删，避免服务句柄出错）
                    open(full, "w").close()
                    step_logrotate["files_handled"] += 1
                    step_logrotate["items"].append(f"{fn}:{sz}→gz")
                except Exception as e:
                    step_logrotate["items"].append(f"{fn}:ERR:{type(e).__name__}")
        # 清理 14 天前的 .gz
        cutoff = time.time() - 14 * 86400
        for ld in logs_candidates:
            if not os.path.isdir(ld): continue
            for fn in os.listdir(ld):
                if not fn.endswith(".gz"): continue
                full = os.path.join(ld, fn)
                try:
                    if os.path.getmtime(full) < cutoff:
                        os.remove(full); step_logrotate["deleted_count"] += 1
                except Exception: pass
    except Exception as e:
        step_logrotate["error"] = f"{type(e).__name__}: {e}"
    steps["logrotate"] = step_logrotate

    # (2) DB 优化：ANALYZE → REINDEX → 备份 → VACUUM
    db_opt = {"databases": [], "error": None}
    for db_rel in ["app.db", "flask-app/app.db"]:
        db_full = os.path.join(project_dir, db_rel)
        if not os.path.exists(db_full): continue
        ent = {"db": db_rel, "before_bytes": 0, "after_bytes": 0, "vacuum_rc": None, "error": None}
        try:
            ent["before_bytes"] = os.path.getsize(db_full)
            conn_v = sqlite3.connect(db_full, timeout=90, isolation_level=None)
            try:
                conn_v.execute("PRAGMA journal_mode=WAL")
                conn_v.execute("ANALYZE")
                conn_v.execute("REINDEX")
                if scope.get("do_vacuum", True) and ent["before_bytes"] >= 50*1024*1024:
                    # VACUUM 需要独占；超时就跳过
                    cur = conn_v.execute("VACUUM")
                    if cur: cur.close()
                    ent["vacuum_rc"] = 0
            except Exception as e:
                ent["error"] = f"{type(e).__name__}: {e}"
            finally:
                conn_v.close()
            ent["after_bytes"] = os.path.getsize(db_full) if os.path.exists(db_full) else 0
        except Exception as e:
            ent["error"] = f"{type(e).__name__}: {e}"
        db_opt["databases"].append(ent)
    steps["db_opt"] = db_opt

    # (3) 缓存清理：/tmp/mtscos_* + 7天前的 core/cache
    cc = {"removed": 0, "freed_bytes": 0, "error": None}
    try:
        dirs = ["/tmp"]
        core_cache = os.path.join(project_dir, "core", "cache")
        if os.path.isdir(core_cache): dirs.append(core_cache)
        cutoff = time.time() - 7*86400
        for d in dirs:
            if not os.path.isdir(d): continue
            for fn in os.listdir(d):
                full = os.path.join(d, fn)
                if not os.path.isfile(full): continue
                if d == "/tmp" and not fn.startswith("mtscos_"): continue
                try:
                    if os.path.getmtime(full) < cutoff:
                        cc["freed_bytes"] += os.path.getsize(full)
                        os.remove(full); cc["removed"] += 1
                except Exception: pass
    except Exception as e:
        cc["error"] = str(e)
    steps["cache_clean"] = cc

    # (4) 磁盘权限巡检（前置：产出 da.warns 供下一步 health_snapshot.details_json 使用，
    #                  同时读取 disk_used_pct 直接来自 psutil/os.statvfs，避免循环依赖）
    da = {"checks": [], "warns": 0, "error": None, "_disk_used_pct": 0}
    try:
        import stat as _stat
        # 先读 disk usage（独立于 snap），供 85% 阈值检查
        try:
            import psutil as _ps_da
            da["_disk_used_pct"] = round(_ps_da.disk_usage(project_dir).percent, 1)
        except Exception:
            try:
                st = os.statvfs(project_dir)
                da["_disk_used_pct"] = round((1 - st.f_bavail/st.f_blocks) * 100, 1) if st.f_blocks else 0
            except Exception:
                pass
        for rel in ["app.db", "flask-app/app.db", "server_real_db.py", ".env"]:
            full = os.path.join(project_dir, rel)
            ent = {"path": rel, "exists": os.path.exists(full)}
            if ent["exists"]:
                st = os.stat(full)
                ent["mode"] = oct(st.st_mode & 0o777)
                ent["writable"] = bool(st.st_mode & _stat.S_IWUSR)
                if rel.endswith(".env") and (st.st_mode & 0o077) != 0:
                    ent["warn"] = "敏感文件权限建议600"; da["warns"] += 1
                if da.get("_disk_used_pct", 0) >= 85:
                    ent["warn"] = "磁盘占用≥85%"; da["warns"] += 1
            da["checks"].append(ent)
    except Exception as e:
        da["error"] = str(e)
    steps["disk_audit"] = da

    # (5) 健康快照写入 health_snapshots（后置：da.warns 已就绪，details_json 完整）
    snap = {"logged": False, "error": None, "metrics": {}}
    try:
        import psutil as _ps
        snap["metrics"]["cpu_pct"] = round(_ps.cpu_percent(interval=0.4), 1)
        vm = _ps.virtual_memory()
        snap["metrics"]["mem_total_gb"] = round(vm.total/(1024**3), 2)
        snap["metrics"]["mem_used_pct"] = round(vm.percent, 1)
        dk = _ps.disk_usage(project_dir)
        snap["metrics"]["disk_total_gb"] = round(dk.total/(1024**3), 2)
        snap["metrics"]["disk_used_pct"] = round(dk.percent, 1)
    except Exception as e:
        snap["metrics"]["psutil_error"] = f"{type(e).__name__}: {e}"
        snap["metrics"]["disk_used_pct"] = da.get("_disk_used_pct", 0)
    try:
        # ai_skills / ai_workflows / ai_workflow_runs / security_events_log 计数
        snap["metrics"]["tables"] = {}
        for db_rel in ["app.db", "flask-app/app.db"]:
            full = os.path.join(project_dir, db_rel)
            if not os.path.exists(full): continue
            c2 = sqlite3.connect(full)
            for tbl in ["ai_skills","ai_workflows","ai_workflow_runs","security_events_log","mtscos_ai_employees",
                        "health_snapshots","approvals","expert_invitation_records","change_audit_log","mtscos_version_history"]:
                try:
                    snap["metrics"]["tables"][f"{db_rel}:{tbl}"] = c2.execute(f"SELECT COUNT(*) FROM {tbl}").fetchone()[0]
                except Exception:
                    snap["metrics"]["tables"][f"{db_rel}:{tbl}"] = -1
            c2.close()
    except Exception as e:
        snap["metrics"]["count_error"] = str(e)
    try:
        import socket as _socket
        try:
            import psutil as _ps2
            upt = round(time.time() - _ps2.boot_time(), 1) if _ps2.boot_time() else 0
        except Exception:
            upt = 0
        hcpu = snap["metrics"].get("cpu_pct", 0)
        hmem = snap["metrics"].get("mem_used_pct", 0)
        hdisk = snap["metrics"].get("disk_used_pct", da.get("_disk_used_pct", 0))
        hscore = round(max(0.0, min(100.0, 100.0 - (hcpu + hmem + hdisk) / 3.0)), 2)
        with _get_conn(APP_DB) as c:
            c.execute("INSERT INTO health_snapshots(snapshot_at, component, status, score, details_json, host, pid, uptime_sec, cpu_pct, memory_pct, disk_pct, metrics_json, created_at, owner_name) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                      (t0_iso,
                       "EigenFlux-V5-Maintenance-Snapshot",  # component NOT NULL
                       "HEALTHY",    # status
                       hscore,       # score (整体健康 0-100)
                       json.dumps({"warns": da.get("warns", 0),
                                   "logrotate_done": (steps.get("logrotate") or {}).get("files_handled", 0),
                                   "tables_scanned": len((snap["metrics"].get("tables") or {}))}, ensure_ascii=False),  # details_json
                       _socket.gethostname(),  # host
                       os.getpid(),            # pid
                       upt,                    # uptime_sec
                       hcpu, snap["metrics"].get("mem_used_pct", 0), hdisk,  # cpu/mem/disk
                       json.dumps(snap["metrics"], ensure_ascii=False),  # metrics_json
                       _timefmt(),             # created_at
                       "EigenFlux-System"))    # owner_name
            snap["logged"] = True
    except Exception as e:
        snap["error"] = f"{type(e).__name__}: {e}"
    steps["health_snapshot"] = snap

    # (6) 安全日志去噪：security_events_log 合并 90 天前
    slc = {"archived_rows": 0, "error": None}
    try:
        cutoff = (datetime.now() - timedelta(days=90)).isoformat()
        for db_rel in ["app.db", "flask-app/app.db"]:
            full = os.path.join(project_dir, db_rel)
            if not os.path.exists(full): continue
            c2 = sqlite3.connect(full)
            try:
                n = c2.execute("DELETE FROM security_events_log WHERE COALESCE(timestamp,event_at,created_at) < ?", (cutoff,)).rowcount
                slc["archived_rows"] += int(n or 0)
                c2.commit()
            except Exception:
                pass
            c2.close()
    except Exception as e:
        slc["error"] = str(e)
    steps["security_logs"] = slc

    # (7) SSOT：ai_workflows 更新统计 + ai_workflow_runs 写一次
    overall_success = True
    ssot = {"logged": False, "error": None}
    try:
        with _get_conn(APP_DB) as c:
            row = c.execute("SELECT wf_id FROM ai_workflows WHERE wf_code='AP-WEEKLY-MAINTENANCE'").fetchone()
            wid = row["wf_id"] if row else None
            if wid:
                c.execute("UPDATE ai_workflows SET total_runs=COALESCE(total_runs,0)+1, run_count=COALESCE(run_count,0)+1, "
                          "last_run_at=?, success_rate=CASE WHEN ?=1 THEN "
                          "ROUND(COALESCE(success_rate,0.9)*0.9+1.0*0.1,3) ELSE "
                          "ROUND(COALESCE(success_rate,0.9)*0.9+0.0*0.1,3) END WHERE wf_id=?",
                          (_timefmt(), 1 if overall_success else 0, wid))
                c.execute("INSERT INTO ai_workflow_runs(wf_id,trigger_type,trigger_source,started_by,status,start_at,end_at,"
                          "nodes_exec_json,result_summary_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                          (wid, "CRON_AUTO", "AP-WEEKLY-MAINTENANCE", "SYSTEM",
                           "SUCCESS" if overall_success else "FAILED",
                           t0_iso, _timefmt(),
                           json.dumps(steps, ensure_ascii=False),
                           json.dumps({"overall_success": overall_success, "note": "V5 auto-maintenance cycle"}, ensure_ascii=False),
                           _timefmt(), _timefmt()))
            ssot["logged"] = True
    except Exception as e:
        ssot["error"] = f"{type(e).__name__}: {e}"
    return {"success": overall_success, "steps": steps, "ssot": ssot,
            "duration_ms": int((time.time()-t0)*1000)}


