@app.route('/api/auto_plans/system_upgrade/check', methods=['GET'])
def api_v5_upgrade_check():
    """真实上游更新检查：git fetch → 本地/远端对比 → 返回 needs_update 布尔"""
    user = _current_safe_user()
    if not user.get('logged_in'):
        return jsonify({'success': False, 'error': '未登录'}), 401
    project_dir = os.path.dirname(os.path.abspath(__file__))
    check = _v5_git_check_update(project_dir)
    return jsonify({"success": True, "data": check,
                    "timestamp": datetime.now().isoformat()})


@app.route('/api/auto_plans/system_upgrade/run_now', methods=['POST'])
def api_v5_upgrade_run():
    """立即执行 AP-MONTHLY-UPGRADE（SA 操作，EF5 投票由真实引擎内置）"""
    user = _current_safe_user()
    if not user.get('logged_in'):
        return jsonify({'success': False, 'error': '未登录'}), 401
    try:
        scope = request.get_json(force=True, silent=True) or {}
    except Exception:
        scope = {}
    try:
        t0 = time.time()
        result = run_auto_upgrade_cycle(scope)
        return jsonify({"success": result.get("success", False),
                        "duration_ms": int((time.time()-t0)*1000),
                        "data": result})
    except Exception as e:
        import traceback as _tb
        return jsonify({"success": False, "error": f"{type(e).__name__}: {e}",
                        "trace": _tb.format_exc(limit=3)}), 500


@app.route('/api/auto_plans/system_maintenance/status', methods=['GET'])
def api_v5_maintenance_status():
    """维护引擎状态：返回最近一次运行/计数/下一次计划等"""
    user = _current_safe_user()
    if not user.get('logged_in'):
        return jsonify({'success': False, 'error': '未登录'}), 401
    with _get_conn(APP_DB) as c:
        row = c.execute("SELECT wf_id,wf_code,wf_name,total_runs,run_count,success_rate,last_run_at,ext_json "
                        "FROM ai_workflows WHERE wf_code='AP-WEEKLY-MAINTENANCE'").fetchone()
        last_runs = c.execute("SELECT run_id,wf_id,status,start_at,end_at,result_summary_json "
                              "FROM ai_workflow_runs WHERE wf_id=? ORDER BY run_id DESC LIMIT 5",
                              (row["wf_id"],) if row else (-1,)).fetchall()
    data = {"workflow": dict(row) if row else None,
            "recent_runs": [dict(r) for r in (last_runs or [])],
            "engines": {
                "run_auto_upgrade_cycle_available": callable(run_auto_upgrade_cycle),
                "run_auto_maintenance_cycle_available": callable(run_auto_maintenance_cycle),
            }}
    return jsonify({"success": True, "data": data, "timestamp": datetime.now().isoformat()})


