    """检查 session 中 6 字段：uid/username/role/logged_in/is_guest/is_super_admin"""
    try:
        uid = session.get('user_id')
        uname = session.get('username')
        role = session.get('role') or _MT_GUEST_ROLE
        logged_in = bool(session.get('logged_in'))
        is_guest = not logged_in
        is_sa = _mt_resolve_is_super_admin()
        if require_login and (not uid or not uname or not logged_in):
            return None
        return {
            'uid': str(uid) if uid else None,
            'username': uname,
            'role': role,
            'logged_in': logged_in,
            'is_guest': is_guest,
            'is_super_admin': is_sa,
        }
    except Exception:
        return None


