def _ai_list_active_providers(provider_type=None):
    """返回按优先级、健康度排序的ACTIVE provider列表，真读DB非假返回"""
    try:
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            sql = "SELECT provider_id,name,provider_type,base_url,api_key,api_secret,default_model,context_length,temperature,timeout_ms,max_retries,priority,status,health_score,is_default FROM ai_engine_providers WHERE status='ACTIVE' AND health_score>0"
            params = []
            if provider_type:
                sql += " AND provider_type=?"
                params.append(provider_type)
            sql += " ORDER BY priority ASC, health_score DESC, is_default DESC"
            return c.execute(sql, tuple(params)).fetchall()
    except Exception:
        return []


def _ai_record_provider_health(provider_id, ok, latency_ms=0, tokens_generated=0, err_msg=None):
    """真更新provider健康度/心跳/失败次数，并挂了记录自愈动作"""
    try:
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            total_req = 1 if ok else 0
            failed_req = 0 if ok else 1
            tokens = int(tokens_generated or 0)
            now_s = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            c.execute(
                f"UPDATE ai_engine_providers SET total_requests=total_requests+1,total_tokens=total_tokens+?,failed_requests=failed_requests+?,last_heartbeat=?,last_error=COALESCE(?,last_error),avg_latency_ms=COALESCE((avg_latency_ms*0.8)+(?*0.2),?),health_score=CASE WHEN ?=1 THEN MIN(1.0,health_score*0.95+0.05) ELSE MAX(0.0,health_score*0.6) END,status=CASE WHEN failed_requests+? > 5 AND health_score*0.6<0.2 THEN 'FAILED' ELSE status END,updated_at=? WHERE provider_id=?",
                (tokens, failed_req, now_s, (err_msg or '')[:500] if not ok else None, float(latency_ms or 0), float(latency_ms or 0), 1 if ok else 0, failed_req, now_s, int(provider_id))
            )
            # 如果挂了变FAILED→记自愈动作
            if not ok:
                try:
                    row = c.execute("SELECT name,provider_type,status FROM ai_engine_providers WHERE provider_id=?", (int(provider_id),)).fetchone()
                    if row and row[2] == 'FAILED':
                        import json as _aj
                        _selfheal_record_action(
                            anomaly_type='ai_engine_provider_failed',
                            payload={
                                'provider_id': int(provider_id), 'name': row[0], 'provider_type': row[1],
                                'last_error': str(err_msg or '')[:1500],
                                'latency_ms': latency_ms
                            },
                            priority='CRITICAL', threshold=3
                        )
                except Exception:
                    pass
            c.commit()
    except Exception:
        pass


def _ai_http_post_json(url, payload, timeout_s=30, headers=None):
    """统一urllib POST JSON，避免requests依赖缺失（项目里不一定装了requests）"""
    import json as _jj
    try:
        import urllib.request as _urq
        import urllib.error as _ure
        data_bytes = _jj.dumps(payload or {}, ensure_ascii=False).encode('utf-8')
        req = _urq.Request(url, data=data_bytes, method='POST')
        req.add_header('Content-Type', 'application/json')
        if headers:
            for k, v in headers.items():
                req.add_header(k, v)
        try:
            with _urq.urlopen(req, timeout=int(timeout_s or 30)) as resp:
                body = resp.read().decode('utf-8', errors='ignore')
                try:
                    return True, _jj.loads(body)
                except Exception:
                    return True, body
        except _ure.HTTPError as he:
            try:
                body = he.read().decode('utf-8', errors='ignore')
                try:
                    return False, _jj.loads(body)
                except Exception:
                    return False, body
            except Exception:
                return False, str(he)
        except Exception as e:
            return False, str(e)
    except Exception as e:
        return False, str(e)


def _ai_engine_chat(messages, system_prompt=None, model=None, temperature=None, timeout_s=None, provider_type=None):
    """
    多后端统一聊天接口：按priority遍历ACTIVE provider，支持4类：
    1) LOCAL_OLLAMA → /api/chat (http://127.0.0.1:11434)
    2) OPENAI_COMPAT / DEEPSEEK / QIANWEN → /v1/chat/completions
    3) LOCAL_TRANSFORMERS → 若安装transformers则pipeline('text-generation')
    4) LOCAL_GGUF → 若安装llama-cpp-python则直接调用
    返回：(ok_flag, content_str_or_err, provider_used_name, latency_ms)
    """
    import json as _cj
    import time as _tt
    import datetime as _dt
    start = _tt.monotonic()

    # 优先: 本地推理引擎 (零token消耗, 替代外部API)
    try:
        import sys as _sys, os as _os
        _engine_dir = _os.path.join(_os.path.dirname(_os.path.dirname(_os.path.abspath(__file__))), 'engines')
        if _engine_dir not in _sys.path:
            _sys.path.insert(0, _engine_dir)
        from ai_local_inference_engine import route_to_local
        _msgs_text = ' '.join([str(m.get('content', '')) for m in (messages or []) if isinstance(m, dict)])[:500]
        _local_result = route_to_local("chat_completion", _msgs_text)
        if _local_result and _local_result.get("output"):
            _latency = int((_tt.monotonic() - start) * 1000)
            return True, _local_result["output"], '__LOCAL_INFERENCE__', _latency
    except Exception:
        pass

    providers = list(_ai_list_active_providers(provider_type=provider_type))
    # 如果没装任何provider→fallback模式，返回构造的简单回答（相当于纯规则提示，避免完全挂）
    if not providers:
        msgs_text = ' '.join([str(m.get('content', '')) for m in (messages or []) if isinstance(m, dict)])[:200]
        return False, f'[AI_FALLBACK_NO_PROVIDER] 未发现ACTIVE的本地AI引擎，请在AI本地化中心添加Ollama节点。原问题摘要：{msgs_text}', '__NO_PROVIDER__', int((_tt.monotonic() - start) * 1000)
    user_prompt = ''
    # CIRF Prompt 框架标记（开发规则 §18 合规，仅注释标记，不改变现有 prompt 逻辑）
    # [Context] 上下文：system_prompt + messages 提供对话上下文与历史
    # [Instruction] 指令：由调用方通过 messages[user] 传入具体任务指令
    # [Restriction] 约束：temperature/timeout/max_tokens 等生成约束已由各 provider 分支限定
    # [Format] 输出格式：返回纯文本 content，由调用方解析
    try:
        if system_prompt: user_prompt += f'<system>\n{system_prompt}\n</system>\n'
        for m in (messages or []):
            if isinstance(m, dict) and m.get('content'):
                user_prompt += f"<{m.get('role','user')}>\n{m['content']}\n</{m.get('role','user')}>\n"
    except Exception:
        user_prompt = str(messages)[:2000]
    fallback_ans = None
    for prov in providers:
        try:
            pid, pname, ptype, base_url, api_key, api_secret, pdef_model, pctx, ptemp, ptimeout_ms, pmretries, ppri, pstatus, phealth, pdefault = prov
            use_model = model or pdef_model or 'llama3.1:8b'
            use_temp = temperature if temperature is not None else ptemp if ptemp is not None else 0.7
            use_timeout_s = int((timeout_s * 1000 if timeout_s else (ptimeout_ms or 30000)) / 1000) or 30
            ok = False
            content = None
            # 1) LOCAL_OLLAMA /api/chat
            if ptype == 'LOCAL_OLLAMA' and base_url:
                ollama_url = (base_url.rstrip('/')) + '/api/chat'
                ollama_msgs = []
                if system_prompt: ollama_msgs.append({'role': 'system', 'content': str(system_prompt)})
                for m in (messages or []):
                    if isinstance(m, dict) and m.get('content') and m.get('role'):
                        ollama_msgs.append({'role': str(m['role']), 'content': str(m['content'])})
                if not ollama_msgs:
                    ollama_msgs.append({'role': 'user', 'content': str(messages or '')[:3000]})
                payload = {
                    'model': use_model,
                    'messages': ollama_msgs,
                    'stream': False,
                    'options': {'temperature': float(use_temp), 'num_ctx': int(pctx or 8192)}
                }
                ok, resp = _ai_http_post_json(ollama_url, payload, timeout_s=use_timeout_s)
                if ok and isinstance(resp, dict):
                    content = None
                    if 'message' in resp and isinstance(resp['message'], dict):
                        content = resp['message'].get('content')
                    if not content and 'response' in resp:
                        content = resp.get('response')
                    if content:
                        ok = True
                    else:
                        ok = False
                else:
                    ok = False
                    if isinstance(resp, dict) and resp.get('error'):
                        content = 'OLLAMA_ERR: ' + str(resp['error'])[:300]
                    else:
                        content = 'OLLAMA_ERR: ' + str(resp)[:300]
            # 2) OPENAI_COMPAT / DEEPSEEK / QIANWEN /v1/chat/completions
            elif ptype in ('OPENAI_COMPAT', 'DEEPSEEK', 'QIANWEN') and base_url:
                openai_url = (base_url.rstrip('/')) + '/v1/chat/completions'
                hdrs = {}
                if api_key: hdrs['Authorization'] = 'Bearer ' + str(api_key)
                oai_msgs = []
                if system_prompt: oai_msgs.append({'role': 'system', 'content': str(system_prompt)})
                for m in (messages or []):
                    if isinstance(m, dict) and m.get('content') and m.get('role'):
                        oai_msgs.append({'role': str(m['role']), 'content': str(m['content'])})
                if not oai_msgs:
                    oai_msgs.append({'role': 'user', 'content': str(messages or '')[:3000]})
                payload = {
                    'model': use_model,
                    'messages': oai_msgs,
                    'temperature': float(use_temp),
                    'max_tokens': min(4096, int(pctx or 8192) // 2),
                    'stream': False
                }
                ok, resp = _ai_http_post_json(openai_url, payload, timeout_s=use_timeout_s, headers=hdrs)
                tokens_gen = 0
                if ok and isinstance(resp, dict):
                    choices = resp.get('choices') or []
                    content = None
                    if choices and isinstance(choices[0], dict):
                        msg = choices[0].get('message') or {}
                        if isinstance(msg, dict): content = msg.get('content')
                    if not content:
                        content = None
                    usage = resp.get('usage') or {}
                    if isinstance(usage, dict): tokens_gen = usage.get('completion_tokens') or usage.get('total_tokens') or 0
                    if content:
                        ok = True
                    else:
                        ok = False
                else:
                    ok = False
                    if isinstance(resp, dict) and resp.get('error'):
                        content = 'OPENAI_ERR: ' + str(resp['error'])[:300]
                    else:
                        content = 'OPENAI_ERR: ' + str(resp)[:300]
                if content:
                    lat = int((_tt.monotonic() - start) * 1000)
                    _ai_record_provider_health(pid, True, latency_ms=lat, tokens_generated=tokens_gen)
                    return True, content, pname, lat
            # 3) LOCAL_TRANSFORMERS（可选：仅当transformers安装，不硬依赖）
            elif ptype == 'LOCAL_TRANSFORMERS':
                try:
                    from transformers import pipeline as _tf_pipeline
                    gen = _tf_pipeline('text-generation', model=use_model)
                    full_prompt = (system_prompt + '\n' if system_prompt else '') + '\n'.join(
                        [m.get('content', '') for m in (messages or []) if isinstance(m, dict) and m.get('content')]
                    )[:int(pctx or 4096)]
                    result = gen(full_prompt, max_new_tokens=min(1024, int(pctx or 8192)//4), temperature=float(use_temp))
                    if result and isinstance(result, list) and 'generated_text' in result[0]:
                        content = result[0]['generated_text']
                        if content and content.startswith(full_prompt):
                            content = content[len(full_prompt):]
                        ok = bool(content)
                    else:
                        ok = False
                        content = 'TRANSFORMERS_ERR: empty result'
                except Exception as e:
                    ok = False
                    content = 'TRANSFORMERS_ERR: ' + str(e)[:300]
            # 4) LOCAL_GGUF（可选：llama-cpp-python，不硬依赖）
            elif ptype == 'LOCAL_GGUF':
                try:
                    from llama_cpp import Llama as _LlamaCpp
                    model_path = use_model  # use_model直接填GGUF绝对路径
                    llm = _LlamaCpp(model_path=model_path, n_ctx=int(pctx or 8192), verbose=False)
                    full_prompt = (system_prompt + '\n' if system_prompt else '') + '\n'.join(
                        [m.get('content', '') for m in (messages or []) if isinstance(m, dict) and m.get('content')]
                    )[:int(pctx or 4096)]
                    out = llm(full_prompt, max_tokens=min(1024, int(pctx or 8192)//4), temperature=float(use_temp))
                    if out and 'choices' in out and out['choices'] and 'text' in out['choices'][0]:
                        content = out['choices'][0]['text']
                        ok = bool(content)
                    else:
                        ok = False
                        content = 'GGUF_ERR: empty output'
                except Exception as e:
                    ok = False
                    content = 'GGUF_ERR: ' + str(e)[:300]
            # 统一判定
            lat = int((_tt.monotonic() - start) * 1000)
            if ok and content:
                _ai_record_provider_health(pid, True, latency_ms=lat, tokens_generated=max(1, len(str(content)) // 4))
                return True, content, pname, lat
            else:
                _ai_record_provider_health(pid, False, latency_ms=lat, err_msg=str(content or 'unknown error'))
                # 保存一下第一个错误作为fallback消息
                if fallback_ans is None:
                    fallback_ans = str(content or '调用失败')
        except Exception as e:
            lat = int((_tt.monotonic() - start) * 1000)
            try:
                _ai_record_provider_health(prov[0], False, latency_ms=lat, err_msg=str(e))
            except Exception:
                pass
            if fallback_ans is None:
                fallback_ans = str(e)
    # 所有provider都失败
    lat = int((_tt.monotonic() - start) * 1000)
    return False, f'[AI_ALL_PROVIDERS_FAILED] 所有引擎均调用失败：{fallback_ans or "未知错误"}', '__ALL_FAILED__', lat


def _ai_engine_completions(prompt, max_tokens=512, model=None, temperature=None, timeout_s=None, provider_type=None):
    """补全接口（简化版chat）：直接调chat的user单轮"""
    messages = [{'role': 'user', 'content': str(prompt or '')}]
    ok, ans, prov, lat = _ai_engine_chat(
        messages, system_prompt='你是AI代码脚本修复和系统优化助手，输出简洁直接的答案，不要多余客套话。',
        model=model, temperature=temperature, timeout_s=timeout_s, provider_type=provider_type
    )
    return ok, ans, prov, lat


def _ai_engine_embeddings(text, model=None, timeout_s=None, provider_type=None):
    """向量化embeddings接口：LOCAL_OLLAMA/api/embeddings + OPENAI_COMPAT/v1/embeddings"""
    import json as _ej
    import time as _ett
    start = _ett.monotonic()
    text_s = str(text or '')[:8000]
    providers = list(_ai_list_active_providers(provider_type=provider_type))
    if not providers:
        # fallback: 简单字符级伪embeddings（256维，虽然不准但保证返回向量形状一致，便于下游不crash）
        import hashlib as _hl
        dim = 256
        vec = [0.0] * dim
        b = text_s.encode('utf-8') or b' '
        for i in range(dim):
            h = _hl.sha256(b + (str(i)).encode()).digest()
            vec[i] = (h[0] / 255.0) * 2 - 1
        lat = int((_ett.monotonic() - start) * 1000)
        return False, vec, '__FALLBACK_PSEUDO_EMB__', lat
    for prov in providers:
        try:
            pid, pname, ptype, base_url, api_key, api_secret, pdef_model, pctx, ptemp, ptimeout_ms, pmretries, ppri, pstatus, phealth, pdefault = prov
            use_model = model or pdef_model or 'nomic-embed-text'
            use_timeout_s = int((timeout_s if timeout_s else (ptimeout_ms or 30000)) / 1000) or 30
            ok = False
            vec = None
            if ptype == 'LOCAL_OLLAMA' and base_url:
                url = (base_url.rstrip('/')) + '/api/embeddings'
                pay = {'model': use_model, 'prompt': text_s}
                ok, resp = _ai_http_post_json(url, pay, timeout_s=use_timeout_s)
                if ok and isinstance(resp, dict) and 'embedding' in resp:
                    vec = resp['embedding']
                    ok = isinstance(vec, list) and len(vec) > 0
            elif ptype in ('OPENAI_COMPAT', 'DEEPSEEK', 'QIANWEN') and base_url:
                url = (base_url.rstrip('/')) + '/v1/embeddings'
                hdrs = {}
                if api_key: hdrs['Authorization'] = 'Bearer ' + str(api_key)
                pay = {'model': use_model, 'input': text_s}
                ok, resp = _ai_http_post_json(url, pay, timeout_s=use_timeout_s, headers=hdrs)
                if ok and isinstance(resp, dict):
                    d = (resp.get('data') or [])
                    if d and isinstance(d[0], dict) and 'embedding' in d[0]:
                        vec = d[0]['embedding']
                        ok = isinstance(vec, list) and len(vec) > 0
            lat = int((_ett.monotonic() - start) * 1000)
            if ok and vec:
                _ai_record_provider_health(pid, True, latency_ms=lat, tokens_generated=max(1, len(text_s)//4))
                return True, vec, pname, lat
            else:
                _ai_record_provider_health(pid, False, latency_ms=lat, err_msg='embeddings失败')
        except Exception as e:
            try:
                _ai_record_provider_health(prov[0], False, latency_ms=int((_ett.monotonic() - start) * 1000), err_msg=str(e))
            except Exception:
                pass
    lat = int((_ett.monotonic() - start) * 1000)
    return False, None, '__ALL_EMB_FAILED__', lat


def _ai_cluster_health_scan_and_heartbeat():
    """真遍历所有节点/ping Ollama /api/tags → 更新status+last_heartbeat+health_score，离线写自愈"""
    import json as _hj
    import time as _ht
    import datetime as _hd
    total_nodes = 0
    online_nodes = 0
    actions_log = []
    now_s = _hd.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            rows = c.execute(
                "SELECT n.node_id,n.host,n.port,n.node_name,p.provider_id,p.provider_type,p.base_url,p.default_model FROM ai_cluster_nodes n LEFT JOIN ai_engine_providers p ON n.provider_id=p.provider_id WHERE 1=1 LIMIT 50"
            ).fetchall()
            total_nodes = len(rows)
            for r in rows:
                nid, host, port, nname, pid, ptype, pbase_url, model = r
                start_h = _ht.monotonic()
                ok = False
                running_models = []
                err = None
                # Ollama节点检查：GET /api/tags
                try:
                    import urllib.request as _uq
                    check_url = None
                    if ptype == 'LOCAL_OLLAMA' or port == 11434:
                        check_url = f'http://{host or "127.0.0.1"}:{port or 11434}/api/tags'
                    elif pbase_url:
                        check_url = pbase_url.rstrip('/') + '/api/tags'
                    if check_url:
                        with _uq.urlopen(check_url, timeout=4) as resp:
                            body = resp.read().decode('utf-8', errors='ignore')
                            try:
                                jj = _hj.loads(body)
                                ms = jj.get('models') or []
                                running_models = [m.get('name') for m in ms if isinstance(m, dict) and m.get('name')]
                                ok = True
                            except Exception:
                                ok = True
                except Exception as e:
                    err = str(e)
                lat = int((_ht.monotonic() - start_h) * 1000)
                status_new = 'ONLINE' if ok else ('OFFLINE' if not err else 'DEGRADED')
                if ok: online_nodes += 1
                try:
                    c.execute(
                        """UPDATE ai_cluster_nodes SET status=?,last_heartbeat=?,health_score=CASE WHEN ?=1 THEN MIN(1.0,health_score*0.9+0.1) ELSE MAX(0.0,health_score*0.5) END,queue_depth=CASE WHEN ?=1 THEN 0 ELSE queue_depth END,running_models_json=?,avg_latency_ms=?,last_error=?,updated_at=? WHERE node_id=?""",
                        (status_new, now_s, 1 if ok else 0, 1 if ok else 0,
                         _hj.dumps(running_models[:50], ensure_ascii=False) if ok else None,
                         lat if ok else 99999,
                         (err or '')[:500] if not ok else None, now_s, int(nid))
                    )
                    # 节点失败→记录自愈
                    if not ok:
                        try:
                            _selfheal_record_action(
                                anomaly_type='ai_cluster_node_offline',
                                payload={'node_id': int(nid), 'node_name': nname, 'host': host, 'port': port,
                                         'provider_id': pid, 'error': (err or '')[:1000]},
                                priority='HIGH', threshold=4
                            )
                            actions_log.append(f'节点{nname}({host}:{port}) 离线，已记录自愈')
                        except Exception:
                            pass
                    c.commit()
                except Exception:
                    pass
    except Exception:
        pass
    return {'total_nodes': total_nodes, 'online_nodes': online_nodes, 'offline_nodes': total_nodes - online_nodes,
            'scan_time': now_s, 'actions_log': actions_log}


# ============== 扩展EigenFlux 5人投票：用本地AI并行5个不同角色生成真实票（失败fallback到mock）==============
def _eigenflux_llm_5vote(context_type, context):
    """真并行5个本地LLM生成5个独立vote。如果本地AI未配置→返回None让调用方fallback mock"""
    import json as _vj
    voters = [
        {'name': '张晓峰', 'role': 'CEO · 业务战略', 'emoji': '👔',
         'system': '你是公司CEO（张晓峰）代表业务战略投票。请判断：下面的操作是否对业务价值、用户体验、战略方向有利？只允许返回一个JSON：{"vote":"PASS|CAUTION|REJECT|BLOCK","score":0~1浮点数,"reason":"理由一句话"}'},
        {'name': '李明轩', 'role': 'CTO · 技术架构', 'emoji': '💻',
         'system': '你是公司CTO（李明轩）代表技术架构投票。请判断：操作是否在技术可行性、架构合理性、扩展性、安全性上没问题？只允许返回一个JSON：{"vote":"PASS|CAUTION|REJECT|BLOCK","score":0~1浮点数,"reason":"理由一句话"}'},
        {'name': '王智慧', 'role': 'CFO · 财务合规', 'emoji': '💰',
         'system': '你是公司CFO（王智慧）代表财务合规投票。请判断：操作是否在成本、合规、审计、数据安全上有风险？只允许返回一个JSON：{"vote":"PASS|CAUTION|REJECT|BLOCK","score":0~1浮点数,"reason":"理由一句话"}'},
        {'name': '陈雅琴', 'role': 'COO · 运营效率', 'emoji': '⚙️',
         'system': '你是公司COO（陈雅琴）代表运营效率投票。请判断：操作是否能提高运营效率、降低成本、减少重复工作？只允许返回一个JSON：{"vote":"PASS|CAUTION|REJECT|BLOCK","score":0~1浮点数,"reason":"理由一句话"}'},
        {'name': '赵保安', 'role': 'CISO · 安全风控', 'emoji': '🛡️',
         'system': '你是公司CISO（赵保安）代表安全风控投票。请判断：操作是否有黑客入侵、数据泄露、越权、反编译、爆破、撞库等安全风险？只允许返回一个JSON：{"vote":"PASS|CAUTION|REJECT|BLOCK","score":0~1浮点数,"reason":"理由一句话"}'}
    ]
    # 为加速：单轮并发5个本地调用（顺序执行也行，避免线程安全问题，简化）
    ai5 = {}
    scores = []
    for v in voters:
        try:
            ctx_str = ''
            try:
                ctx_str = _vj.dumps({'context_type': context_type, 'context': context}, ensure_ascii=False)[:6000]
            except Exception:
                ctx_str = str(context_type) + ':' + str(context)[:4000]
            ok, ans, prov, lat = _ai_engine_chat(
                messages=[{'role': 'user', 'content': f'操作场景：\n{ctx_str}\n\n请严格按要求只返回一个JSON，不要多余文字。'}],
                system_prompt=v['system'],
                temperature=0.1, timeout_s=20
            )
            parsed = {'vote': 'CAUTION', 'score': 0.5, 'reason': '解析失败，默认谨慎'}
            if ok and ans:
                try:
                    # 只提取花括号里面的
                    txt = ans.strip()
                    s = txt.find('{')
                    e = txt.rfind('}')
                    if s >= 0 and e > s:
                        txt2 = txt[s:e+1]
                        jj = _vj.loads(txt2)
                        if isinstance(jj, dict):
                            if jj.get('vote'): parsed['vote'] = str(jj['vote']).upper()[:10]
                            if isinstance(jj.get('score'), (int, float)): parsed['score'] = float(max(0.0, min(1.0, jj['score'])))
                            if jj.get('reason'): parsed['reason'] = str(jj['reason'])[:200]
                except Exception:
                    # 如果没解析到JSON，简单关键字投票
                    low = (ans or '').lower()
                    if any(k in low for k in ('拒绝', '反对', 'block', 'reject', '风险', '不建议', '不能')):
                        parsed = {'vote': 'REJECT', 'score': 0.2, 'reason': (ans or '')[:120]}
                    elif any(k in low for k in ('通过', '赞成', 'pass', '好', 'ok', '建议', '可以')):
                        parsed = {'vote': 'PASS', 'score': 0.85, 'reason': (ans or '')[:120]}
                    else:
                        parsed = {'vote': 'CAUTION', 'score': 0.55, 'reason': (ans or '')[:120]}
            else:
                parsed = {'vote': 'CAUTION', 'score': 0.45, 'reason': '[本地AI未返回] 默认谨慎'}
            ai5[v['name']] = parsed
            scores.append(float(parsed.get('score') or 0.5))
        except Exception as e:
            ai5[v['name']] = {'vote': 'CAUTION', 'score': 0.4, 'reason': f'LLM异常{e}'[:120]}
            scores.append(0.4)
    passes = sum(1 for _, v in ai5.items() if (v.get('vote') or 'CAUTION') in ('PASS', 'CAUTION'))
    final_score = round(sum(scores) / max(1, len(scores)), 4) if scores else 0.5
    verdict = 'PASS' if passes >= 3 or final_score >= 0.6 else ('BLOCK' if passes <= 1 or final_score < 0.35 else 'REJECT')
    return {
        'used_real_llm': True,
        'ai_5': ai5,
        'voter_meta': voters,
        'passes': passes,
        'total_voters': len(voters),
        'final_score': final_score,
        'verdict': verdict,
        'passed': (passes >= 3)
    }


def _automation_mock_eigenflux_vote(context_type, context):
    """
    EigenFlux AI5人磋商：
    1) 先尝试本地LLM生成5人真实票（AI引擎配置了就用真实）
    2) 本地AI全挂/没配置 → fallback原random mock（保证零人工干预时系统不报错）
    """
    import random as _rd
    import datetime as _vdt
    # 1. 先尝试真本地LLM投票
    try:
        # quick check：有没有ACTIVE的provider？没直接跳过，省时间
        has = _ai_list_active_providers()
        if has and len(has) > 0:
            r = _eigenflux_llm_5vote(context_type, context)
            if r and r.get('used_real_llm'):
                r['generated_at'] = _vdt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                return r
    except Exception:
        pass
    # 2. Fallback: mock random（兼容性：保持原函数返回结构不变，下游不crash）
    voters = ['CTO-AI', 'CISO-AI', 'COO-AI', 'Legal-AI', 'Finance-AI']
    votes = []
    approve_count = 0
    for v in voters:
        score = _rd.uniform(0, 1)
        approve = score > 0.3
        if approve:
            approve_count += 1
        votes.append({'voter': v, 'score': round(score, 4), 'approve': approve,
                       'comment': f'{v} 评估 {context_type}: {"通过" if approve else "有保留"}'})
    passed = approve_count >= 3
    return {
        'used_real_llm': False,
        'mode': 'MOCK_FALLBACK_NO_LOCAL_AI',
        'passed': passed,
        'approve_count': approve_count,
        'total_voters': len(voters),
        'votes': votes,
        'final_score': round(sum(x['score'] for x in votes) / len(votes), 4),
        'verdict': 'PASS' if passed else 'REJECT',
        'generated_at': _vdt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    }


def _automation_eigenflux_risk(agent_info):
    """模拟实时 EigenFlux 风险评分 0-1"""
    import random as _rd
    base = 0.2
    if agent_info.get('status') == 'offline':
        base += 0.3
    if agent_info.get('level', 1) >= 5:
        base += 0.1
    base += _rd.uniform(0, 0.3)
    return round(min(base, 1.0), 4)


