def _mt_102_voter(name_or_id):
    """按 name 或 id 取单个选民资料"""
    if isinstance(name_or_id, int):
        for v in _MT_102_ALL:
            if int(v.get('id') or 0) == int(name_or_id): return v
        return None
    nm = str(name_or_id or '').strip()
    return _MT_102_NAME_INDEX.get(nm)


def _mt_102_simulate_ballots(context_type, context, *, seed=None):
    """
    根据上下文为 102 人自动模拟投票（初始化投票时调用；人类用户可后期覆盖）。
    返回结构: {
      'ballots_group_a_main': {name: {'vote':'APPROVE|REJECT|ABSTAIN','score':0-1,'reason':'...'}},
      'ballots_group_b_suspend': {name: {'vote':'SUPPORT_SUSPEND|OPPOSE_SUSPEND|ABSTAIN','score':0-1,'reason':'...'}},
      'wuchenghao15_may_veto': True/False (建议),
      'zhangxiaofeng_may_suspend': True/False (建议),
      'discussion_notes': [{'panel':'...', 'comment':'...'}],
    }
    """
    import random as _r
    rng = _r.Random(seed) if seed is not None else _r
    import datetime as _dt
    import json as _jj
    # 先跑一遍 EigenFlux 5 人原小组，作为背景信号（AI员工意见摘要）
    try:
        ef5 = _automation_mock_eigenflux_vote(context_type, context) or {}
        base_approve = float(ef5.get('final_score') or 0.5)
    except Exception:
        base_approve = 0.55
    # A 组 51 票模拟：AI员工/业务代表倾向跟随 EigenFlux 结论，特邀专家更谨慎，特殊人默认不表态
    ballots_a = {}
    for v in _MT_102_VOTERS_GROUP_A_MAIN:
        nm = str(v.get('name'))
        bias = 0.0
        if v.get('ai_employee'): bias = (base_approve - 0.5) * 1.2
        if v.get('is_expert'): bias = -0.12
        if nm in ('wuchenghao15', _MT_VOTE_SPECIAL_SUSPEND_USER):
            # 特殊权限人：模拟时弃权（真实人类行使权力）
            ballots_a[nm] = {'vote': 'ABSTAIN', 'score': 0.5, 'reason': '特殊权限人，初始弃权，最终由其本人实票'}
            continue
        p = base_approve + bias + rng.uniform(-0.2, 0.2)
        p = max(0.05, min(0.95, p))
        r = rng.random()
        if r < p:
            ballots_a[nm] = {'vote': 'APPROVE', 'score': round(rng.uniform(0.55, 0.98), 4),
                             'reason': f'{v.get("role_cn")}评估：本提案整体收益 > 风险，支持'}
        elif r < (p + 0.12):
            ballots_a[nm] = {'vote': 'ABSTAIN', 'score': round(rng.uniform(0.4, 0.6), 4),
                             'reason': f'{v.get("role_cn")}评估：信息不足，暂弃权'}
        else:
            ballots_a[nm] = {'vote': 'REJECT', 'score': round(rng.uniform(0.02, 0.45), 4),
                             'reason': f'{v.get("role_cn")}评估：存在未覆盖风险/成本过高，不建议通过'}
    # B 组 51 票模拟（对是否支持张晓峰行使暂缓权的表决）——越接近"有争议"，支持暂缓比例越高
    controversy = 0.5 + abs(base_approve - 0.5) * -1.0  # 50-50时争议最大
    ballots_b = {}
    for v in _MT_102_VOTERS_GROUP_B_SUSPEND:
        nm = str(v.get('name'))
        p_suspend = 0.45 + (controversy - 0.5) * 0.6 + rng.uniform(-0.15, 0.15)
        p_suspend = max(0.1, min(0.85, p_suspend))
        rr = rng.random()
        if rr < p_suspend:
            ballots_b[nm] = {'vote': 'SUPPORT_SUSPEND', 'score': round(rng.uniform(0.55, 0.95), 4),
                             'reason': f'{v.get("role_cn")}立场：建议张晓峰暂缓，交由wuchenghao15终审'}
        elif rr < (p_suspend + 0.1):
            ballots_b[nm] = {'vote': 'ABSTAIN', 'score': 0.5,
                             'reason': f'{v.get("role_cn")}立场：对暂缓事宜保留意见，弃权'}
        else:
            ballots_b[nm] = {'vote': 'OPPOSE_SUSPEND', 'score': round(rng.uniform(0.02, 0.45), 4),
                             'reason': f'{v.get("role_cn")}立场：反对暂缓，提案应按A组票数即时生效'}
    # 讨论面板意见
    notes = []
    notes.append({'panel': 'EigenFlux 引擎',
                  'comment': f'EF5基础分 {round(base_approve,3)}；AI5人原小组结论：{ef5.get("verdict","N/A")}（{ef5.get("approve_count","?")}/5 通过）。'
                             f'建议：若 A 组存在显著分歧，可由张晓峰启用暂缓权交由 wuchenghao15 定夺。'})
    notes.append({'panel': _MT_VOTE_INVITED_EXPERT,
                  'comment': '【邀请专家】建议从合规+用户长期价值两方面复核；如遇边界情形，优先上报 wuchenghao15 终审。'})
    notes.append({'panel': '本地AI员工团',
                  'comment': '【AI员工】已检索 mtscos_ai_employees 中 ACTIVE 员工记录，后续随讨论线程动态补充。'})
    return {
        'generated_at': _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        'version': _MT_VOTE_SYSTEM_VERSION,
        'base_ef5_score': round(base_approve, 4),
        'ballots_group_a_main': ballots_a,
        'ballots_group_b_suspend': ballots_b,
        'discussion_notes': notes,
        'special_powers_initial': {
            'wuchenghao15_may_veto': None,      # None = 未行使
            'zhangxiaofeng_may_suspend': None,  # None = 未行使
        }
    }


def _mt_102_calculate_result(ballots_a, ballots_b, *,
                             wuchenghao15_use_veto=None,
                             zhangxiaofeng_use_suspend=None,
                             context_summary=''):
    """
    102人大会【最终结果计算算法】——严格按用户规则：
    规则清单：
    1. A组 51人参加【提案】举手表决
    2. wuchenghao15 有 1 票驳回权（一票即 REJECTED_BY_VETO）
    3. 张晓峰 有 1 票暂缓权：
       a) 若 wuchenghao15 未驳回 且 张晓峰启用暂缓 → 结果为 SUSPENDED_TO_WUCHENGHAO15（交wuchenghao15定夺）
       b) 例外：除 wuchenghao15 票外，A 组【超半票】(>50%, 即 ≥26 票/50 人 ) 通过，张晓峰暂缓不生效（即时 APPROVED）
       c) B 组 51 人对"张晓峰是否应使用暂缓权"进行举手表决，超过半数支持暂缓 → 加强暂缓建议
    4. wuchenghao15 未行使驳回权 → 张晓峰可行使一票暂缓权→提交 wuchenghao15 定夺；如仍有"意义争议"（歧义/接近票/外部争议）→ 一律交 wuchenghao15 定夺
    5. 最终结果入地上报数据库 + 历史档案馆
    :param ballots_a: dict name -> {'vote': 'APPROVE|REJECT|ABSTAIN', ...}
    :param ballots_b: dict name -> {'vote': 'SUPPORT_SUSPEND|OPPOSE_SUSPEND|ABSTAIN', ...}
    :param wuchenghao15_use_veto: True/False/None(=未行使)
    :param zhangxiaofeng_use_suspend: True/False/None(=未行使)
    :return: dict with final_status + counts + rule trace
    """
    import datetime as _dt
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    rule_trace = []  # 记录命中的规则

    # ------------- A 组计票（去掉 wuchenghao15 的"除他之外"超半票） -------------
    a_total = 0; a_approve = 0; a_reject = 0; a_abstain = 0
    for v in _MT_102_VOTERS_GROUP_A_MAIN:
        nm = str(v.get('name'))
        bal = ballots_a.get(nm) or {}
        vv = str(bal.get('vote') or 'ABSTAIN').upper()
        a_total += 1
        if vv == 'APPROVE': a_approve += 1
        elif vv == 'REJECT': a_reject += 1
        else: a_abstain += 1
    # 除 wuchenghao15 之外的 A 组计票（用于超半票判断）
    a_without_sa = 0; a_approve_without_sa = 0; a_reject_without_sa = 0
    for v in _MT_102_VOTERS_GROUP_A_MAIN:
        nm = str(v.get('name'))
        if nm == _MT_VOTE_SPECIAL_VETO_USER: continue
        bal = ballots_a.get(nm) or {}
        vv = str(bal.get('vote') or 'ABSTAIN').upper()
        a_without_sa += 1
        if vv == 'APPROVE': a_approve_without_sa += 1
        elif vv == 'REJECT': a_reject_without_sa += 1
    # A组 超半票 (>50% of 除SA外) 通过阈值： A组除SA共 50 人 > 25 = 26 票
    supermajority_threshold = (a_without_sa // 2) + 1  # 50 -> 26
    a_supermajority_pass = (a_approve_without_sa >= supermajority_threshold)
    rule_trace.append(f'[A组] 赞成{a_approve}/反对{a_reject}/弃权{a_abstain}/总{a_total}；'
                      f'除 wuchenghao15 外：赞成{a_approve_without_sa}/反对{a_reject_without_sa}/总{a_without_sa}；'
                      f'超半票阈值 ≥{supermajority_threshold} → 是否超半通过 = {a_supermajority_pass}')

    # ------------- B 组计票（是否支持张晓峰使用暂缓权） -------------
    b_total = 0; b_support = 0; b_oppose = 0; b_abstain = 0
    for v in _MT_102_VOTERS_GROUP_B_SUSPEND:
        nm = str(v.get('name'))
        bal = ballots_b.get(nm) or {}
        vv = str(bal.get('vote') or 'ABSTAIN').upper()
        b_total += 1
        if vv == 'SUPPORT_SUSPEND': b_support += 1
        elif vv == 'OPPOSE_SUSPEND': b_oppose += 1
        else: b_abstain += 1
    b_majority_support_suspend = b_support > (b_total // 2)  # 51 > 25 → ≥26
    rule_trace.append(f'[B组] 支持暂缓{b_support}/反对{b_oppose}/弃权{b_abstain}/总{b_total}；'
                      f'是否多数支持暂缓 = {b_majority_support_suspend}')

    # ------------- 特殊权限 1：wuchenghao15 一票驳回权 -------------
    status = 'DRAFT'; final_note = ''; decision_by = 'system'
    if wuchenghao15_use_veto is True:
        status = 'REJECTED_BY_VETO'
        decision_by = _MT_VOTE_SPECIAL_VETO_USER
        final_note = '⭐ wuchenghao15 行使一票驳回权（规则2），提案立即驳回，无论任何票数。'
        rule_trace.append(final_note)
    else:
        # ------------- 特殊权限 2：张晓峰 一票暂缓权（规则3） -------------
        # 先判断是否"无条件暂缓"的例外（规则 3b：除SA外超半通过 = 暂缓不生效）
        zs_override = a_supermajority_pass
        if zs_override:
            rule_trace.append(f'[例外规则3b] 除 wuchenghao15 外 A 组超半通过（{a_approve_without_sa}≥{supermajority_threshold}），'
                              f'张晓峰暂缓权不生效。')
        # wuchenghao15没驳回 + 张晓峰启用暂缓权（除非被例外 override 覆盖）
        if (zhangxiaofeng_use_suspend is True) and (not zs_override):
            # 结果：交 wuchenghao15 定夺（规则 3a / 规则 4）
            status = 'SUSPENDED_TO_WUCHENGHAO15'
            decision_by = _MT_VOTE_SPECIAL_SUSPEND_USER + '→' + _MT_VOTE_SPECIAL_VETO_USER
            final_note = '⏸️ 张晓峰行使一票暂缓权（规则 3a），提案暂缓并交由 wuchenghao15 终审。'
            if b_majority_support_suspend:
                final_note += f'（另B组 51 人多数【{b_support}/{b_total}】支持暂缓，加强暂缓建议。）'
            rule_trace.append(final_note)
        else:
            # 正常 A 组表决：>50% (≥26 of 51，或按有效票) 视作普通通过
            normal_approve = (a_approve > (a_total // 2))  # 51 → >25.5 即 26
            # 有意义交 wuchenghao15 定夺 = 接近票（赞成/反对差 ≤ 3 票 或 弃权≥15 或 B组多数支持暂缓但张没行使）
            close_vote = abs(a_approve - a_reject) <= 3 or a_abstain >= 15 or b_majority_support_suspend
            if normal_approve or a_supermajority_pass:
                status = 'APPROVED'
                decision_by = 'GROUP_A_MAJORITY'
                final_note = (f'✅ A组多数通过（赞成{a_approve}/{a_total}）。'
                              f'{"wuchenghao15未使用驳回权；张晓峰暂缓未启用。" if (wuchenghao15_use_veto is not True and zhangxiaofeng_use_suspend is not True) else ""}')
                rule_trace.append(final_note)
                # 仍"有意义交wuchenghao15定夺"—— 接近票
                if close_vote:
                    rule_trace.append(f'[规则4 意义定夺] 票数接近/争议（赞成-反对差≤3 或 弃权≥15 或 B组多数支持暂缓），'
                                      f'建议流程仍报告 wuchenghao15 进行最终确认，但当前状态仍为 APPROVED。')
                    status = 'APPROVED_MEANING_REVIEW_BY_SA'
                    decision_by = _MT_VOTE_SPECIAL_VETO_USER + ' (建议确认)'
            else:
                status = 'REJECTED_BY_GROUP_A'
                decision_by = 'GROUP_A_MAJORITY'
                final_note = f'❌ A组多数未通过（赞成{a_approve}/{a_total} < 反对{a_reject}，或赞成不过半）。'
                rule_trace.append(final_note)
                if close_vote:
                    status = 'REJECTED_MEANING_REVIEW_BY_SA'
                    decision_by = _MT_VOTE_SPECIAL_VETO_USER + ' (建议确认)'
                    rule_trace.append(f'[规则4 意义定夺] 票数有争议 → 建议 wuchenghao15 终审。')
    return {
        'calculated_at': now,
        'version': _MT_VOTE_SYSTEM_VERSION,
        'final_status': status,
        'final_note': final_note,
        'decision_by': decision_by,
        'context_summary': context_summary,
        'counts': {
            'group_a': {'total': a_total, 'approve': a_approve, 'reject': a_reject, 'abstain': a_abstain},
            'group_a_without_wuchenghao15': {'total': a_without_sa, 'approve': a_approve_without_sa,
                                             'reject': a_reject_without_sa,
                                             'supermajority_threshold': supermajority_threshold,
                                             'is_supermajority_pass': a_supermajority_pass},
            'group_b_suspend': {'total': b_total, 'support_suspend': b_support,
                                'oppose_suspend': b_oppose, 'abstain': b_abstain,
                                'majority_support_suspend': b_majority_support_suspend},
        },
        'special_powers_applied': {
            'wuchenghao15_veto_applied': (wuchenghao15_use_veto is True),
            'zhangxiaofeng_suspend_applied': (zhangxiaofeng_use_suspend is True),
            'suspend_overridden_by_supermajority': zs_override if 'zs_override' in dir() else False,
        },
        'rule_trace': rule_trace,
        'meaning_review_required': bool('MEANING_REVIEW' in status),
    }


# ================== 102 人投票：DB 表结构初始化 + 归档写入 + API ==================

def _ensure_mt_102_vote_schema(conn):
    """初始化 102 人投票相关表：大会提案 / 个人票 / 结果快照 / 归档 / 讨论记录 / 版本升级日志"""
    c = conn.cursor()
    c.execute("""CREATE TABLE IF NOT EXISTS mt_102_vote_sessions (
        session_id      INTEGER PRIMARY KEY AUTOINCREMENT,
        session_key     TEXT UNIQUE NOT NULL,
        title           TEXT NOT NULL,
        context_type    TEXT,
        context_summary TEXT,
        context_json    TEXT,
        discussion_json TEXT,
        ballots_a_json  TEXT NOT NULL DEFAULT '{}',
        ballots_b_json  TEXT NOT NULL DEFAULT '{}',
        special_powers_json TEXT NOT NULL DEFAULT '{}',
        result_json     TEXT,
        final_status    TEXT DEFAULT 'DRAFT',
        decision_by     TEXT,
        created_at      TEXT,
        updated_at      TEXT,
        created_by      TEXT,
        archived_to_history INTEGER DEFAULT 0,
        archive_ref_id  INTEGER,
        change_audit_id INTEGER,
        eigenflux_ref   TEXT,
        round_a_status  TEXT DEFAULT 'PENDING',   /* PENDING/IN_PROGRESS/COMPLETED */
        round_a_result  TEXT,                     /* APPROVED/REJECTED/SUSPEND_TRIGGERED */
        round_a_completed_at TEXT,
        zhangxiaofeng_suspend_decision TEXT,      /* USE_SUSPEND/NOT_USE_SUSPEND/None */
        round_b_status  TEXT DEFAULT 'PENDING',   /* PENDING/IN_PROGRESS/COMPLETED/SKIPPED */
        round_b_result  TEXT,                     /* SUSPEND_APPROVED/SUSPEND_REJECTED */
        round_b_completed_at TEXT,
        sa_report_status TEXT DEFAULT 'PENDING'   /* PENDING/REPORTED/APPROVED */
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS mt_102_vote_ballots (
        ballot_id       INTEGER PRIMARY KEY AUTOINCREMENT,
        session_key     TEXT NOT NULL,
        voter_name      TEXT NOT NULL,
        voter_id        INTEGER,
        voter_group     TEXT,
        vote_kind       TEXT,
        score           REAL DEFAULT 0.5,
        reason          TEXT,
        cast_by_human   INTEGER DEFAULT 0,
        cast_at         TEXT,
        cast_by         TEXT,
        round           TEXT DEFAULT 'A',          /* A | B */
        UNIQUE(session_key, voter_name, round)
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS mt_102_vote_results (
        result_id        INTEGER PRIMARY KEY AUTOINCREMENT,
        session_key      TEXT UNIQUE NOT NULL,
        final_status     TEXT NOT NULL,
        decision_by      TEXT,
        counts_json      TEXT NOT NULL,
        rule_trace_json  TEXT NOT NULL,
        meaning_review   INTEGER DEFAULT 0,
        snapshotted_at   TEXT,
        snapshotted_by   TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS mt_102_vote_history_archive (
        archive_id      INTEGER PRIMARY KEY AUTOINCREMENT,
        session_key     TEXT UNIQUE NOT NULL,
        title           TEXT,
        context_type    TEXT,
        final_status    TEXT,
        decision_by     TEXT,
        session_json    TEXT,
        archive_note    TEXT,
        archived_at     TEXT,
        archived_by     TEXT DEFAULT 'system'
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS mt_102_vote_discussions (
        discussion_id   INTEGER PRIMARY KEY AUTOINCREMENT,
        session_key     TEXT NOT NULL,
        round           TEXT NOT NULL,             /* A | B */
        panel_name      TEXT NOT NULL,             /* EigenFlux/邀请专家/本地AI员工/张晓峰/... */
        panel_kind      TEXT,                      /* engine/expert/ai_employees/suspend_user/... */
        comment         TEXT,
        recorded_at     TEXT,
        recorded_by     TEXT DEFAULT 'system'
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS mt_dev_version_log (
        log_id          INTEGER PRIMARY KEY AUTOINCREMENT,
        version         TEXT NOT NULL,
        trigger_reason  TEXT,
        changes_summary TEXT,
        git_commit_hash TEXT,
        git_pushed      INTEGER DEFAULT 0,
        triggered_at    TEXT,
        triggered_by    TEXT DEFAULT 'system'
    )""")
    # 1000 次测试结果与修复记录表
    c.execute("""CREATE TABLE IF NOT EXISTS mt_test_results (
        test_id          TEXT PRIMARY KEY,
        category         TEXT,
        sub_category     TEXT,
        description      TEXT,
        input_summary    TEXT,
        expected_result  TEXT,
        actual_result    TEXT,
        status           TEXT,
        vulnerability_type TEXT,
        severity         TEXT,
        fix_applied      TEXT,
        timestamp        TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS mt_test_fixes (
        fix_id             INTEGER PRIMARY KEY AUTOINCREMENT,
        test_id            TEXT,
        vulnerability_type TEXT,
        severity           TEXT,
        fix_description    TEXT,
        fixed_at           TEXT,
        fixed_by           TEXT
    )""")
    for sql in [
        "CREATE INDEX IF NOT EXISTS idx_mt102_sess_status ON mt_102_vote_sessions(final_status, created_at)",
        "CREATE INDEX IF NOT EXISTS idx_mt102_ballot_sess   ON mt_102_vote_ballots(session_key, voter_group)",
        "CREATE INDEX IF NOT EXISTS idx_mt102_res_sess      ON mt_102_vote_results(session_key)",
        "CREATE INDEX IF NOT EXISTS idx_mt102_arch_key      ON mt_102_vote_history_archive(session_key)",
        "CREATE INDEX IF NOT EXISTS idx_mt102_arch_status   ON mt_102_vote_history_archive(final_status, archived_at)",
        "CREATE INDEX IF NOT EXISTS idx_mt102_disc_sess     ON mt_102_vote_discussions(session_key, round)",
        "CREATE INDEX IF NOT EXISTS idx_mtdevver_log_ver    ON mt_dev_version_log(version)",
        "CREATE INDEX IF NOT EXISTS idx_mt_test_results_cat ON mt_test_results(category, severity)",
        "CREATE INDEX IF NOT EXISTS idx_mt_test_fixes_tid   ON mt_test_fixes(test_id)",
    ]:
        try: c.execute(sql)
        except sqlite3.Error: pass
    try: conn.commit()
    except Exception: pass


def _mt_102_db(dbpath=None):
    dbp = dbpath or APP_DB
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
    except Exception: pass
    return dbp


def _mt_102_archive_session(session_key, *, archived_by='system', note=''):
    """功能：落地上报 → mt_102_vote_history_archive 历史档案馆 + change_audit_log（系统治理4张表）"""
    import json as _jj
    import datetime as _dt
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    dbp = _mt_102_db()
    session = None
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute("SELECT * FROM mt_102_vote_sessions WHERE session_key=?", (session_key,))
            row = cur.fetchone()
            if not row: return None
            cols = [d[0] for d in cur.description]
            session = dict(zip(cols, row))
    except Exception as e:
        print(f'[MT102-ARCHIVE] 读session失败: {e}')
        return None
    full_json = _jj.dumps(session, ensure_ascii=False)
    arch_id = None
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute(
                """INSERT OR REPLACE INTO mt_102_vote_history_archive
                   (session_key,title,context_type,final_status,decision_by,session_json,archive_note,archived_at,archived_by)
                   VALUES (?,?,?,?,?,?,?,?,?)""",
                (str(session_key), str(session.get('title') or '')[:200],
                 str(session.get('context_type') or '')[:100],
                 str(session.get('final_status') or 'DRAFT'),
                 str(session.get('decision_by') or ''),
                 full_json, str(note or '')[:500], now, str(archived_by or 'system'))
            )
            arch_id = cur.lastrowid
            c.execute(
                "UPDATE mt_102_vote_sessions SET archived_to_history=1, archive_ref_id=?, updated_at=? WHERE session_key=?",
                (arch_id, now, str(session_key))
            )
            c.commit()
    except Exception as e:
        print(f'[MT102-ARCHIVE] 写历史档案馆失败: {e}')
        return None
    # 同步写入：change_audit_log（系统治理 4 张表中的一张）与 mtscos_ai_employees 邀请记录
    try:
        # 尝试写入 AUTH_DB 或 APP_DB 中的 change_audit_log，找能写的
        ca_id = None
        for tdb in [AUTH_DB, APP_DB, dbp]:
            try:
                with _get_conn(tdb) as c:
                    cc = c.execute(
                        "INSERT INTO change_audit_log (change_id,operator,operator_role,change_category,status,result_summary,applied_at,created_at,updated_at,ef5_voted,expert_invited) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                        (str(session_key), str(archived_by or 'system'), 'mt_102_vote_system',
                         '102人大会投票归档', 'COMPLETED',
                         f'final={session.get("final_status")}, decision_by={session.get("decision_by")}, title={session.get("title")}',
                         now, now, now, 1, 1)
                    )
                    ca_id = cc.lastrowid
                    c.commit()
                    if ca_id: break
            except Exception:
                continue
        if ca_id:
            with _get_conn(dbp) as c:
                c.execute("UPDATE mt_102_vote_sessions SET change_audit_id=? WHERE session_key=?",
                          (int(ca_id), str(session_key)))
                c.commit()
        # 再写入 expert_invitation_records (邀请专家 + EigenFlux + AI员工团被邀请)
        for tdb in [AUTH_DB, APP_DB, dbp]:
            try:
                with _get_conn(tdb) as c:
                    for expert_name in ('邀请专家', 'EigenFlux 引擎', '本地AI员工团'):
                        try:
                            c.execute(
                                "INSERT INTO expert_invitation_records (invitation_id, expert_name, change_id, status, invited_at, responded_at) VALUES (?,?,?,?,?,?)",
                                (f"mt102_{session_key}_{expert_name}", expert_name, str(session_key),
                                 'INVITED_AND_ATTENDED', now, now)
                            )
                        except sqlite3.Error: pass
                    c.commit()
                break
            except Exception:
                continue
    except Exception as e:
        print(f'[MT102-ARCHIVE] 治理表写入失败(不致命): {e}')
    return {'archive_id': arch_id, 'archived_at': now, 'session_key': session_key}


def _mt_102_record_discussion(session_key, round_label, panel_name, panel_kind, comment, *, recorded_by='system', conn=None):
    """记录讨论意见到 mt_102_vote_discussions 表（所有讨论必须记录数据库）"""
    import datetime as _dt
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    def _do_insert(c):
        c.execute(
            "INSERT INTO mt_102_vote_discussions (session_key,round,panel_name,panel_kind,comment,recorded_at,recorded_by) VALUES (?,?,?,?,?,?,?)",
            (str(session_key), str(round_label), str(panel_name)[:100], str(panel_kind or '')[:50],
             str(comment)[:2000], now, str(recorded_by or 'system')[:64])
        )
    try:
        if conn is not None:
            _ensure_mt_102_vote_schema(conn)
            _do_insert(conn)
        else:
            dbp = _mt_102_db()
            with _get_conn(dbp) as c:
                _ensure_mt_102_vote_schema(c)
                _do_insert(c)
                c.commit()
    except Exception as e:
        print(f'[MT102-DISC] 讨论记录写入失败(不致命): {e}')
    return True


def _mt_dev_trigger_version_upgrade(version, reason, changes_summary, *, triggered_by='system', git_commit_hash=None, git_pushed=0):
    """每次开发触发版本升级条件并记录到 mt_dev_version_log 表"""
    import datetime as _dt
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    dbp = APP_DB
    log_id = None
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute(
                "INSERT INTO mt_dev_version_log (version,trigger_reason,changes_summary,git_commit_hash,git_pushed,triggered_at,triggered_by) VALUES (?,?,?,?,?,?,?)",
                (str(version), str(reason)[:500], str(changes_summary)[:2000],
                 str(git_commit_hash or '')[:64], int(git_pushed), now, str(triggered_by or 'system')[:64])
            )
            log_id = cur.lastrowid
            c.commit()
    except Exception as e:
        print(f'[MT-DEV-VER] 版本升级日志写入失败(不致命): {e}')
    return {'log_id': log_id, 'version': version, 'triggered_at': now}


def _mt_102_sa_report(session_key, *, report_type='ROUND_A_NO_SUSPEND', summary='', actor='system'):
    """上报超级管理员(wuchenghao15)报备记录"""
    import datetime as _dt
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    dbp = _mt_102_db()
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            c.execute(
                "UPDATE mt_102_vote_sessions SET sa_report_status='REPORTED', updated_at=? WHERE session_key=?",
                (now, str(session_key))
            )
            c.commit()
    except Exception:
        pass
    return {'session_key': session_key, 'report_type': report_type, 'reported_at': now, 'reported_to': _MT_VOTE_SPECIAL_VETO_USER}


