@app.route('/api/vote102/create', methods=['POST'])
@system_container('vote102_create', require_auth='login')
def api_vote102_create():
    """
    POST 创建 102 人大会投票并自动模拟初始票。
    请求体：
        title: str (必填)
        context_type: str
        context_summary: str
        context: any (JSON 可序列化，提案正文/变更说明)
        seed: int（可选，复现随机结果时用）
    """
    import json as _jj
    import datetime as _dt
    import secrets as _sc
    import time as _t
    u = _safe_user_ctx(_current_user()) or {}
    uname = str(u.get('username') or session.get('username') or 'anonymous')
    data = request.get_json(silent=True) or {}
    title = _safe_str(data.get('title'), max_len=200).strip()
    if not title:
        return jsonify({'success': False, 'message': '提案标题 title 必填'}), 400
    ctype = _safe_str(data.get('context_type') or data.get('type'), max_len=100) or 'general'
    csumm = _safe_str(data.get('context_summary') or data.get('summary'), max_len=1000)
    ctx = data.get('context') if data.get('context') is not None else {}
    seed = data.get('seed') if isinstance(data.get('seed'), int) else None
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    sk = f'vote_{int(_t.time())}_{_sc.token_hex(4)}'
    # 1) EigenFlux 讨论 + 本地AI员工介入：调用模拟函数生成 ballots 和讨论记录
    sim = _mt_102_simulate_ballots(ctype, ctx, seed=seed)
    ballots_a = sim['ballots_group_a_main']
    ballots_b = sim['ballots_group_b_suspend']
    discussion_json = _jj.dumps({
        'panel': _MT_102_DISCUSSION_PANEL,
        'notes': sim.get('discussion_notes') or [],
        'ef5_base_score': sim.get('base_ef5_score'),
        'eigenflux_joined': True,
        'expert_invited_joined': True,
        'local_ai_employees_joined': True,
    }, ensure_ascii=False)
    ba_str = _jj.dumps(ballots_a, ensure_ascii=False)
    bb_str = _jj.dumps(ballots_b, ensure_ascii=False)
    ctx_str = _jj.dumps({'context': ctx}, ensure_ascii=False)
    sp_str = _jj.dumps(sim.get('special_powers_initial') or {}, ensure_ascii=False)
    dbp = _mt_102_db()
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            c.execute(
                """INSERT INTO mt_102_vote_sessions
                   (session_key,title,context_type,context_summary,context_json,discussion_json,ballots_a_json,ballots_b_json,special_powers_json,final_status,created_at,updated_at,created_by,round_a_status)
                   VALUES (?,?,?,?,?,?,?,?,?,'DRAFT',?,?,?,'IN_PROGRESS')""",
                (sk, title, ctype, csumm, ctx_str, discussion_json, ba_str, bb_str, sp_str, now, now, uname)
            )
            # 同时写入 ballots 明细表
            rows_ins = []
            for nm, bal in ballots_a.items():
                vinfo = _mt_102_voter(nm) or {}
                rows_ins.append((sk, nm, int(vinfo.get('id') or 0), 'A',
                                 str(bal.get('vote') or 'ABSTAIN'),
                                 float(bal.get('score') or 0.5),
                                 _safe_str(bal.get('reason'), max_len=500),
                                 0, now, 'AI-simulated', 'A'))
            for nm, bal in ballots_b.items():
                vinfo = _mt_102_voter(nm) or {}
                rows_ins.append((sk, nm, int(vinfo.get('id') or 0), 'B',
                                 str(bal.get('vote') or 'ABSTAIN'),
                                 float(bal.get('score') or 0.5),
                                 _safe_str(bal.get('reason'), max_len=500),
                                 0, now, 'AI-simulated', 'B'))
            c.executemany(
                """INSERT OR IGNORE INTO mt_102_vote_ballots
                   (session_key,voter_name,voter_id,voter_group,vote_kind,score,reason,cast_by_human,cast_at,cast_by,round)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?)""", rows_ins)
            c.commit()
    except Exception as e:
        return jsonify({'success': False, 'message': f'写入投票DB失败: {e}'}), 500
    # 记录讨论到数据库（所有讨论必须记录数据库）
    for note in (sim.get('discussion_notes') or []):
        _mt_102_record_discussion(sk, 'A', note.get('panel',''), '',
                                  note.get('comment',''), recorded_by=uname)
    # 触发版本升级记录
    _mt_dev_trigger_version_upgrade(_MT_VOTE_SYSTEM_VERSION, 'vote102_create',
        f'创建投票会议 {sk}，A轮讨论启动(EigenFlux+邀请专家+本地AI员工)', triggered_by=uname)
    return jsonify({
        'success': True, 'session_key': sk, 'created_at': now, 'created_by': uname,
        'version': _MT_VOTE_SYSTEM_VERSION,
        'title': title, 'context_type': ctype, 'context_summary': csumm,
        'round_a_status': 'IN_PROGRESS',
        'discussion_panel_joined': _MT_102_DISCUSSION_PANEL,
        'note': (f'已自动调用 EigenFlux 磋商引擎，邀请有关专家、本地相关AI员工介入讨论（已记录数据库），'
                 f'并为 102 人(A组51+B组51)生成初始模拟票。A轮进行中，等待张晓峰当场表决是否使用暂缓权。'),
        'ballots_count': {'a_group': len(ballots_a), 'b_group': len(ballots_b)},
    })


@app.route('/api/vote102/<session_key>/ballot', methods=['POST'])
@system_container('vote102_cast', require_auth='login')
def api_vote102_cast(session_key):
    """
    POST 人工作废/覆盖某位选民的票（用于 wuchenghao15 行使驳回、张晓峰行使暂缓、及其他人类实票）。
    请求体：{ voter_name, vote_kind(APPROVE/REJECT/ABSTAIN|SUPPORT_SUSPEND/OPPOSE_SUSPEND/ABSTAIN), score?, reason? }
          或特殊：{ voter_name='wuchenghao15', use_veto:True } 直接设 veto flag
          或特殊：{ voter_name='张晓峰',     use_suspend:True } 直接设 suspend flag
    """
    import json as _jj
    import datetime as _dt
    u = _safe_user_ctx(_current_user()) or {}
    uname = str(u.get('username') or session.get('username') or 'anonymous')
    data = request.get_json(silent=True) or {}
    vnm = _safe_str(data.get('voter_name'), max_len=64).strip()
    if not vnm:
        return jsonify({'success': False, 'message': 'voter_name 必填'}), 400
    sk = _safe_str(session_key, max_len=64).strip()
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    dbp = _mt_102_db()
    # 权限控制：只有本人或管理员才能覆盖某人名下的票
    is_sa = (uname.lower() == _MT_VOTE_SPECIAL_VETO_USER)
    is_admin = is_sa or ((u.get('role') or '') in _MT_ADMIN_ROLES)
    self_vote = (uname.lower() == vnm.lower())
    # 特殊：wuchenghao15 驳回权 → 写入 special_powers_json
    use_veto = data.get('use_veto')
    use_suspend = data.get('use_suspend')
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute("SELECT special_powers_json,ballots_a_json,ballots_b_json,final_status "
                            "FROM mt_102_vote_sessions WHERE session_key=?", (sk,))
            row = cur.fetchone()
            if not row:
                return jsonify({'success': False, 'message': 'session_key 不存在'}), 404
            _sp = {}; _ba = {}; _bb = {}
            try: _sp = _jj.loads(row[0] or '{}') or {}
            except Exception: _sp = {}
            try: _ba = _jj.loads(row[1] or '{}') or {}
            except Exception: _ba = {}
            try: _bb = _jj.loads(row[2] or '{}') or {}
            except Exception: _bb = {}
            _st = str(row[3] or 'DRAFT')
            _sp = _sp or {}; _ba = _ba or {}; _bb = _bb or {}
            # 处理 use_veto / use_suspend 特殊 flag
            changed_flag = False
            if vnm == _MT_VOTE_SPECIAL_VETO_USER and use_veto is not None:
                if not (vnm == uname or is_sa or is_admin):
                    return jsonify({'success': False, 'message': '只有 wuchenghao15 本人或超级管理员可设置驳回权 flag'}), 403
                _sp['wuchenghao15_veto'] = bool(use_veto)
                changed_flag = True
            if vnm == _MT_VOTE_SPECIAL_SUSPEND_USER and use_suspend is not None:
                if not (vnm == uname or is_sa or is_admin):
                    return jsonify({'success': False, 'message': '只有 张晓峰 本人或超级管理员可设置暂缓权 flag'}), 403
                _sp['zhangxiaofeng_suspend'] = bool(use_suspend)
                changed_flag = True
            # 处理普通覆盖投票
            vk = _safe_str(data.get('vote_kind'), max_len=40).upper().strip()
            if vk:
                # 权限：自己投自己 或 管理员覆盖
                if not (self_vote or is_admin or is_sa):
                    return jsonify({'success': False, 'message': f'您无权覆盖 {vnm} 的实票（仅本人或管理员）'}), 403
                info = _mt_102_voter(vnm) or {}
                group = str(info.get('group') or '').upper()
                if group == 'A':
                    if vk not in ('APPROVE','REJECT','ABSTAIN'):
                        return jsonify({'success': False, 'message': 'A组票类型必须是 APPROVE / REJECT / ABSTAIN'}), 400
                    _ba[vnm] = {
                        'vote': vk, 'score': float(data.get('score', (0.8 if vk=='APPROVE' else (0.2 if vk=='REJECT' else 0.5)))),
                        'reason': _safe_str(data.get('reason') or (f'{uname} 于 {now} 实票：{vk}'), max_len=500),
                    }
                elif group == 'B':
                    if vk not in ('SUPPORT_SUSPEND','OPPOSE_SUSPEND','ABSTAIN'):
                        return jsonify({'success': False, 'message': 'B组票类型必须是 SUPPORT_SUSPEND / OPPOSE_SUSPEND / ABSTAIN'}), 400
                    _bb[vnm] = {
                        'vote': vk, 'score': float(data.get('score', (0.8 if vk=='SUPPORT_SUSPEND' else (0.2 if vk=='OPPOSE_SUSPEND' else 0.5)))),
                        'reason': _safe_str(data.get('reason') or (f'{uname} 于 {now} 实票：{vk}'), max_len=500),
                    }
                else:
                    return jsonify({'success': False, 'message': f'未知选民组或选民【{vnm}】不在名册中'}), 404
                # 写入 ballots 明细表（human=1）
                vinfo = info
                c.execute(
                    """INSERT INTO mt_102_vote_ballots
                       (session_key,voter_name,voter_id,voter_group,vote_kind,score,reason,cast_by_human,cast_at,cast_by)
                       VALUES (?,?,?,?,?,?,?,?,?,?)
                       ON CONFLICT(session_key,voter_name) DO UPDATE SET
                         vote_kind=excluded.vote_kind,score=excluded.score,reason=excluded.reason,
                         cast_by_human=1,cast_at=excluded.cast_at,cast_by=excluded.cast_by""",
                    (sk, vnm, int(vinfo.get('id') or 0), group, vk,
                     float(data.get('score', 0.5)),
                     _safe_str(data.get('reason') or (f'{uname} 于 {now} 实票：{vk}'), max_len=500),
                     1, now, uname)
                )
                changed_flag = True
            if not changed_flag:
                return jsonify({'success': False, 'message': '未识别到有效变更（需要 vote_kind 或 use_veto/use_suspend 之一）'}), 400
            # 更新主表
            c.execute(
                "UPDATE mt_102_vote_sessions SET special_powers_json=?, ballots_a_json=?, ballots_b_json=?, updated_at=? WHERE session_key=?",
                (_jj.dumps(_sp, ensure_ascii=False),
                 _jj.dumps(_ba, ensure_ascii=False),
                 _jj.dumps(_bb, ensure_ascii=False),
                 now, sk)
            )
            c.commit()
            return jsonify({'success': True, 'session_key': sk, 'updated_at': now,
                            'special_powers': _sp,
                            'changed': {'voter': vnm, 'vote_kind': vk or None,
                                        'veto': bool(use_veto) if use_veto is not None else None,
                                        'suspend': bool(use_suspend) if use_suspend is not None else None}})
    except Exception as e:
        return jsonify({'success': False, 'message': f'投票写入失败: {e}'}), 500


@app.route('/api/vote102/<session_key>/calculate', methods=['POST'])
@system_container('vote102_calc', require_auth='login')
def api_vote102_calculate(session_key):
    """
    POST 根据当前所有票 + special_powers flag 计算最终结果；
    写入 mt_102_vote_results；最后执行归档至历史档案馆（落地上报）。
    """
    import json as _jj
    import datetime as _dt
    u = _safe_user_ctx(_current_user()) or {}
    uname = str(u.get('username') or session.get('username') or 'anonymous')
    sk = _safe_str(session_key, max_len=64).strip()
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    dbp = _mt_102_db()
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute(
                "SELECT session_key,title,context_type,context_summary,special_powers_json,ballots_a_json,ballots_b_json "
                "FROM mt_102_vote_sessions WHERE session_key=?", (sk,)
            )
            row = cur.fetchone()
            if not row:
                return jsonify({'success': False, 'message': 'session_key 不存在'}), 404
            sp = {}; ba = {}; bb = {}
            try: sp = _jj.loads(row[4] or '{}') or {}
            except Exception: sp = {}
            try: ba = _jj.loads(row[5] or '{}') or {}
            except Exception: ba = {}
            try: bb = _jj.loads(row[6] or '{}') or {}
            except Exception: bb = {}
            result = _mt_102_calculate_result(
                ba, bb,
                wuchenghao15_use_veto=sp.get('wuchenghao15_veto') if isinstance(sp, dict) else None,
                zhangxiaofeng_use_suspend=sp.get('zhangxiaofeng_suspend') if isinstance(sp, dict) else None,
                context_summary=(f'{row[2] or ""} {row[3] or ""}'.strip()[:200])
            )
            final_status = result.get('final_status') or 'DRAFT'
            counts_j = _jj.dumps(result.get('counts') or {}, ensure_ascii=False)
            trace_j = _jj.dumps(result.get('rule_trace') or [], ensure_ascii=False)
            meaning = 1 if result.get('meaning_review_required') else 0
            decision_by = result.get('decision_by') or ''
            # 写入结果表
            c.execute(
                """INSERT OR REPLACE INTO mt_102_vote_results
                   (session_key,final_status,decision_by,counts_json,rule_trace_json,meaning_review,snapshotted_at,snapshotted_by)
                   VALUES (?,?,?,?,?,?,?,?)""",
                (sk, final_status, decision_by, counts_j, trace_j, meaning, now, uname)
            )
            # 同时更新 session 主表最终状态
            c.execute(
                "UPDATE mt_102_vote_sessions SET final_status=?, decision_by=?, result_json=?, updated_at=? WHERE session_key=?",
                (final_status, decision_by, _jj.dumps(result, ensure_ascii=False), now, sk)
            )
            c.commit()
    except Exception as e:
        return jsonify({'success': False, 'message': f'结果计算失败: {e}'}), 500
    # 最后：落地上报 → 历史档案馆 + 治理表
    arch = _mt_102_archive_session(sk, archived_by=uname,
                                   note=f'102人大会投票结果落地上报，最终状态 {final_status}，decision_by {decision_by}')
    return jsonify({
        'success': True,
        'session_key': sk,
        'result': result,
        'counts': result.get('counts'),
        'rule_trace': result.get('rule_trace'),
        'meaning_review_required': result.get('meaning_review_required'),
        'archived_to_history': arch is not None,
        'archive': arch or None,
    })


@app.route('/api/vote102/<session_key>/round_a/finalize', methods=['POST'])
@system_container('vote102_round_a', require_auth='login')
def api_vote102_round_a_finalize(session_key):
    """
    POST A轮终结：张晓峰必须参加A轮讨论并当场表决是否使用暂缓权。
    请求体：{
        use_suspend: bool (必填) —— 张晓峰当场表决：true=使用暂缓权进入B轮, false=不使用
        zhangxiaofeng_comment: str (可选) —— 张晓峰的讨论意见
    }
    流程：
      - use_suspend=false → A轮结果直接生效，上报数据库+超级管理员报备
      - use_suspend=true  → A轮结束，进入B轮讨论(B组51人表决暂缓权，张晓峰不参加)
    """
    import json as _jj
    import datetime as _dt
    u = _safe_user_ctx(_current_user()) or {}
    uname = str(u.get('username') or session.get('username') or 'anonymous')
    sk = _safe_str(session_key, max_len=64).strip()
    if not _validate_session_key(sk):
        return jsonify({'success': False, 'message': 'Invalid session_key'}), 400
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    data = request.get_json(silent=True) or {}
    use_suspend = data.get('use_suspend')
    if use_suspend is None:
        return jsonify({'success': False, 'message': 'use_suspend 必填（张晓峰必须当场表决是否使用暂缓权）'}), 400
    use_suspend = bool(use_suspend)
    zf_comment = _safe_str(data.get('zhangxiaofeng_comment') or data.get('comment'), max_len=1000)
    is_sa = (uname.lower() == _MT_VOTE_SPECIAL_VETO_USER)
    is_admin = is_sa or ((u.get('role') or '') in _MT_ADMIN_ROLES)
    is_zxf = (uname == _MT_VOTE_SPECIAL_SUSPEND_USER)
    if not (is_zxf or is_sa or is_admin):
        return jsonify({'success': False, 'message': '只有张晓峰本人或超级管理员可执行A轮终结'}), 403
    dbp = _mt_102_db()
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute("SELECT round_a_status,ballots_a_json,ballots_b_json,special_powers_json "
                            "FROM mt_102_vote_sessions WHERE session_key=?", (sk,))
            row = cur.fetchone()
            if not row:
                return jsonify({'success': False, 'message': 'session_key 不存在'}), 404
            if str(row[0] or '') == 'COMPLETED':
                return jsonify({'success': False, 'message': 'A轮已终结，不可重复操作'}), 400
            ba = {}; bb = {}; sp = {}
            try: ba = _jj.loads(row[1] or '{}') or {}
            except: ba = {}
            try: bb = _jj.loads(row[2] or '{}') or {}
            except: bb = {}
            try: sp = _jj.loads(row[3] or '{}') or {}
            except: sp = {}
            # 记录张晓峰A轮讨论意见到数据库
            _mt_102_record_discussion(sk, 'A', _MT_VOTE_SPECIAL_SUSPEND_USER, 'suspend_user',
                f'【张晓峰A轮当场表决】{"使用暂缓权，进入B轮讨论" if use_suspend else "不使用暂缓权，A轮结果直接生效"}。意见：{zf_comment or "无附加意见"}',
                recorded_by=uname, conn=c)
            if use_suspend:
                # 张晓峰使用暂缓权 → A轮结束，进入B轮
                sp['zhangxiaofeng_suspend'] = True
                c.execute(
                    "UPDATE mt_102_vote_sessions SET round_a_status='COMPLETED', round_a_result='SUSPEND_TRIGGERED', "
                    "zhangxiaofeng_suspend_decision='USE_SUSPEND', round_b_status='IN_PROGRESS', "
                    "special_powers_json=?, updated_at=? WHERE session_key=?",
                    (_jj.dumps(sp, ensure_ascii=False), now, sk))
                c.commit()
                _mt_dev_trigger_version_upgrade(_MT_VOTE_SYSTEM_VERSION, 'round_a_finalize_suspend',
                    f'投票 {sk} A轮终结：张晓峰使用暂缓权，进入B轮讨论', triggered_by=uname)
                return jsonify({
                    'success': True, 'session_key': sk, 'round': 'A',
                    'round_a_status': 'COMPLETED', 'round_a_result': 'SUSPEND_TRIGGERED',
                    'round_b_status': 'IN_PROGRESS',
                    'zhangxiaofeng_decision': 'USE_SUSPEND',
                    'message': '张晓峰行使暂缓权，A轮终结，进入B轮讨论（B组51人对暂缓权表决，张晓峰不参加）'
                })
            else:
                # 张晓峰不使用暂缓权 → A轮结果直接生效，上报数据库+超级管理员报备
                sp['zhangxiaofeng_suspend'] = False
                # 计算A轮结果
                result = _mt_102_calculate_result(ba, bb,
                    wuchenghao15_use_veto=sp.get('wuchenghao15_veto') if isinstance(sp, dict) else None,
                    zhangxiaofeng_use_suspend=False,
                    context_summary='A轮终结-张晓峰不使用暂缓权')
                final_status = result.get('final_status') or 'APPROVED'
                c.execute(
                    "UPDATE mt_102_vote_sessions SET round_a_status='COMPLETED', round_a_result=?, "
                    "zhangxiaofeng_suspend_decision='NOT_USE_SUSPEND', round_b_status='SKIPPED', "
                    "special_powers_json=?, final_status=?, decision_by=?, result_json=?, "
                    "sa_report_status='REPORTED', updated_at=? WHERE session_key=?",
                    (final_status, _jj.dumps(sp, ensure_ascii=False), final_status,
                     result.get('decision_by',''), _jj.dumps(result, ensure_ascii=False),
                     now, sk))
                # 写结果表
                c.execute(
                    "INSERT OR REPLACE INTO mt_102_vote_results "
                    "(session_key,final_status,decision_by,counts_json,rule_trace_json,meaning_review,snapshotted_at,snapshotted_by) "
                    "VALUES (?,?,?,?,?,?,?,?)",
                    (sk, final_status, result.get('decision_by',''),
                     _jj.dumps(result.get('counts',{}), ensure_ascii=False),
                     _jj.dumps(result.get('rule_trace',[]), ensure_ascii=False),
                     1 if result.get('meaning_review_required') else 0, now, uname))
                c.commit()
                # 上报超级管理员报备
                sa_report = _mt_102_sa_report(sk, report_type='ROUND_A_NO_SUSPEND',
                    summary=f'A轮终结：张晓峰不使用暂缓权，结果={final_status}', actor=uname)
                # 归档
                arch = _mt_102_archive_session(sk, archived_by=uname,
                    note=f'A轮终结(不使用暂缓权)，结果={final_status}，已报备超级管理员')
                _mt_dev_trigger_version_upgrade(_MT_VOTE_SYSTEM_VERSION, 'round_a_finalize_no_suspend',
                    f'投票 {sk} A轮终结：张晓峰不使用暂缓权，结果={final_status}，已报备SA', triggered_by=uname)
                return jsonify({
                    'success': True, 'session_key': sk, 'round': 'A',
                    'round_a_status': 'COMPLETED', 'round_a_result': final_status,
                    'round_b_status': 'SKIPPED',
                    'zhangxiaofeng_decision': 'NOT_USE_SUSPEND',
                    'final_status': final_status,
                    'result': result,
                    'sa_report': sa_report,
                    'archived_to_history': arch is not None,
                    'archive': arch,
                    'message': f'张晓峰不使用暂缓权，A轮结果直接生效({final_status})，已上报数据库和超级管理员报备'
                })
    except Exception as e:
        return jsonify({'success': False, 'message': f'A轮终结失败: {e}'}), 500


@app.route('/api/vote102/<session_key>/round_b/finalize', methods=['POST'])
@system_container('vote102_round_b', require_auth='login')
def api_vote102_round_b_finalize(session_key):
    """
    POST B轮终结：B组51人对张晓峰暂缓权使用与否进行举手表决（张晓峰不参加）。
    流程：
      - B轮通过(多数支持暂缓) → 上报超级管理员报备审批
      - B轮不通过(多数反对暂缓) → 提案通过，报备超级管理员
    所有讨论记录数据库。
    """
    import json as _jj
    import datetime as _dt
    u = _safe_user_ctx(_current_user()) or {}
    uname = str(u.get('username') or session.get('username') or 'anonymous')
    sk = _safe_str(session_key, max_len=64).strip()
    if not _validate_session_key(sk):
        return jsonify({'success': False, 'message': 'Invalid session_key'}), 400
    now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    dbp = _mt_102_db()
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute("SELECT round_a_status,round_b_status,ballots_a_json,ballots_b_json,special_powers_json "
                            "FROM mt_102_vote_sessions WHERE session_key=?", (sk,))
            row = cur.fetchone()
            if not row:
                return jsonify({'success': False, 'message': 'session_key 不存在'}), 404
            if str(row[0] or '') != 'COMPLETED':
                return jsonify({'success': False, 'message': 'A轮尚未终结，无法执行B轮终结'}), 400
            if str(row[1] or '') in ('COMPLETED', 'SKIPPED'):
                return jsonify({'success': False, 'message': 'B轮已终结或已跳过'}), 400
            ba = {}; bb = {}; sp = {}
            try: ba = _jj.loads(row[2] or '{}') or {}
            except: ba = {}
            try: bb = _jj.loads(row[3] or '{}') or {}
            except: bb = {}
            try: sp = _jj.loads(row[4] or '{}') or {}
            except: sp = {}
            # B组计票（张晓峰不参加B轮，但张晓峰在A组不在B组，所以B组天然不含张晓峰）
            b_total = 0; b_support = 0; b_oppose = 0; b_abstain = 0
            for v in _MT_102_VOTERS_GROUP_B_SUSPEND:
                nm = str(v.get('name'))
                bal = bb.get(nm) or {}
                vv = str(bal.get('vote') or 'ABSTAIN').upper()
                b_total += 1
                if vv == 'SUPPORT_SUSPEND': b_support += 1
                elif vv == 'OPPOSE_SUSPEND': b_oppose += 1
                else: b_abstain += 1
            b_pass = b_support > (b_total // 2)  # 多数支持暂缓 = B轮通过
            # 记录B轮讨论到数据库
            _mt_102_record_discussion(sk, 'B', 'B组51人表决结果', 'group_b',
                f'B组51人对暂缓权表决：支持暂缓{b_support}/反对{b_oppose}/弃权{b_abstain}/总{b_total}；'
                f'是否多数支持暂缓={b_pass}（张晓峰不参加B轮）', recorded_by=uname, conn=c)
            # 计算最终结果
            result = _mt_102_calculate_result(ba, bb,
                wuchenghao15_use_veto=sp.get('wuchenghao15_veto') if isinstance(sp, dict) else None,
                zhangxiaofeng_use_suspend=True,
                context_summary='B轮终结-张晓峰已使用暂缓权')
            if b_pass:
                # B轮通过(支持暂缓) → 上报超级管理员报备审批
                final_status = 'SUSPENDED_TO_WUCHENGHAO15'
                round_b_result = 'SUSPEND_APPROVED'
                decision_by = _MT_VOTE_SPECIAL_SUSPEND_USER + '→' + _MT_VOTE_SPECIAL_VETO_USER
                sa_report_type = 'ROUND_B_SUSPEND_APPROVED'
                message = f'B轮通过(支持暂缓{b_support}/{b_total})，上报超级管理员审批'
            else:
                # B轮不通过(反对暂缓) → 提案通过，报备超级管理员
                final_status = 'APPROVED_BY_B_ROUND_REJECT_SUSPEND'
                round_b_result = 'SUSPEND_REJECTED'
                decision_by = 'GROUP_B_MAJORITY_REJECT_SUSPEND→' + _MT_VOTE_SPECIAL_VETO_USER
                sa_report_type = 'ROUND_B_SUSPEND_REJECTED'
                message = f'B轮不通过(反对暂缓{b_oppose}/{b_total})，提案通过，报备超级管理员'
            result['final_status'] = final_status
            result['decision_by'] = decision_by
            result['final_note'] = message
            c.execute(
                "UPDATE mt_102_vote_sessions SET round_b_status='COMPLETED', round_b_result=?, "
                "final_status=?, decision_by=?, result_json=?, sa_report_status='REPORTED', updated_at=? WHERE session_key=?",
                (round_b_result, final_status, decision_by,
                 _jj.dumps(result, ensure_ascii=False), now, sk))
            c.execute(
                "INSERT OR REPLACE INTO mt_102_vote_results "
                "(session_key,final_status,decision_by,counts_json,rule_trace_json,meaning_review,snapshotted_at,snapshotted_by) "
                "VALUES (?,?,?,?,?,?,?,?)",
                (sk, final_status, decision_by,
                 _jj.dumps(result.get('counts',{}), ensure_ascii=False),
                 _jj.dumps(result.get('rule_trace',[]), ensure_ascii=False),
                 1 if result.get('meaning_review_required') else 0, now, uname))
            c.commit()
            # 上报超级管理员
            sa_report = _mt_102_sa_report(sk, report_type=sa_report_type,
                summary=message, actor=uname)
            # 归档
            arch = _mt_102_archive_session(sk, archived_by=uname,
                note=f'B轮终结：{message}，已报备超级管理员')
            _mt_dev_trigger_version_upgrade(_MT_VOTE_SYSTEM_VERSION, 'round_b_finalize',
                f'投票 {sk} B轮终结：{message}', triggered_by=uname)
            return jsonify({
                'success': True, 'session_key': sk, 'round': 'B',
                'round_b_status': 'COMPLETED', 'round_b_result': round_b_result,
                'b_counts': {'support': b_support, 'oppose': b_oppose, 'abstain': b_abstain, 'total': b_total,
                             'b_pass': b_pass},
                'final_status': final_status,
                'decision_by': decision_by,
                'sa_report': sa_report,
                'archived_to_history': arch is not None,
                'archive': arch,
                'message': message + '，已落地上报数据库和历史档案馆'
            })
    except Exception as e:
        return jsonify({'success': False, 'message': f'B轮终结失败: {e}'}), 500


@app.route('/api/vote102/<session_key>', methods=['GET'])
def api_vote102_get(session_key):
    """GET 查看某个投票会议详情（含所有票 + 结果 + 归档状态）"""
    import json as _jj
    sk = _safe_str(session_key, max_len=64).strip()
    dbp = _mt_102_db()
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute(
                "SELECT * FROM mt_102_vote_sessions WHERE session_key=?", (sk,)
            )
            row = cur.fetchone()
            if not row:
                return jsonify({'success': False, 'message': 'session_key 不存在'}), 404
            cols = [d[0] for d in cur.description]
            d = dict(zip(cols, row))
            # 解析 JSON 字段
            for k in ('context_json','discussion_json','ballots_a_json','ballots_b_json','special_powers_json','result_json'):
                if d.get(k):
                    try: d[k.replace('_json','')] = _jj.loads(d[k]) or {}
                    except Exception: d[k.replace('_json','')] = {}
            # 拉取归档记录
            try:
                arc = c.execute("SELECT * FROM mt_102_vote_history_archive WHERE session_key=?", (sk,)).fetchone()
                if arc:
                    acols = [x[0] for x in c.execute("SELECT * FROM mt_102_vote_history_archive LIMIT 1").description]
                    d['history_archive'] = dict(zip(acols, arc))
                    d['history_archive'].pop('session_json', None)  # 完整JSON太大，不返回默认
                else:
                    d['history_archive'] = None
            except Exception:
                d['history_archive'] = None
            return jsonify({'success': True, 'data': d, 'version': _MT_VOTE_SYSTEM_VERSION})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/vote102/list', methods=['GET'])
def api_vote102_list():
    """GET 投票会议列表（按创建时间倒序）"""
    import json as _jj
    dbp = _mt_102_db()
    page = max(1, request.args.get('page', 1, type=int))
    size = max(1, min(200, request.args.get('size', 20, type=int)))
    offset = (page - 1) * size
    status = _safe_str(request.args.get('final_status') or request.args.get('status'), max_len=50)
    where = []; params = []
    if status:
        where.append("final_status=?"); params.append(status)
    wsql = (" WHERE " + " AND ".join(where)) if where else ""
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            tot = c.execute(f"SELECT COUNT(*) FROM mt_102_vote_sessions{wsql}", params).fetchone()[0] or 0
            rows = []
            cur = c.execute(
                f"SELECT session_key,title,context_type,context_summary,final_status,decision_by,"
                f"created_at,updated_at,created_by,archived_to_history,archive_ref_id "
                f"FROM mt_102_vote_sessions{wsql} "
                f"ORDER BY session_id DESC LIMIT ? OFFSET ?", params + [size, offset])
            cols = [d[0] for d in cur.description]
            for r in cur.fetchall():
                rows.append(dict(zip(cols, r)))
            return jsonify({'success': True, 'data': rows, 'total': tot, 'page': page, 'size': size})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/vote102/<session_key>/archive_detail', methods=['GET'])
def api_vote102_archive_detail(session_key):
    """GET 历史档案馆中的【完整归档快照 JSON】（落地证明）"""
    import json as _jj
    sk = _safe_str(session_key, max_len=64).strip()
    dbp = _mt_102_db()
    try:
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            row = c.execute(
                "SELECT archive_id,session_key,title,context_type,final_status,decision_by,"
                "session_json,archive_note,archived_at,archived_by "
                "FROM mt_102_vote_history_archive WHERE session_key=?", (sk,)
            ).fetchone()
            if not row:
                return jsonify({'success': False, 'message': '该 session_key 尚未归档，或未创建。'}), 404
            cols = [d[0] for d in c.description]
            d = dict(zip(cols, row))
            try:
                sj = _jj.loads(row[6] or '{}') or {}
            except Exception:
                sj = {}
            d['session_full'] = sj
            d.pop('session_json', None)
            return jsonify({'success': True,
                            '落地上报_历史档案馆_完整快照': d,
                            '落地证明': {
                                'archive_id': d.get('archive_id'),
                                'archived_at': d.get('archived_at'),
                                'archived_by': d.get('archived_by'),
                                'archive_note': d.get('archive_note'),
                            }})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


# ========== 1000次测试结果上报 API ==========
@app.route('/api/test1000/results', methods=['GET'])
@system_container('test1000_results', require_auth='login')
def api_test1000_results():
    """获取1000次测试结果摘要（从 mt_test_results 表读取结果，返回统计摘要和漏洞列表）"""
    try:
        sk = _safe_str(request.args.get('session_key'), max_len=64).strip()
        if sk and not _validate_session_key(sk):
            return jsonify({'success': False, 'message': 'Invalid session_key'}), 400
        dbp = _mt_102_db()
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute(
                "SELECT test_id,category,sub_category,description,input_summary,expected_result,"
                "actual_result,status,vulnerability_type,severity,fix_applied,timestamp "
                "FROM mt_test_results ORDER BY timestamp DESC LIMIT 1000"
            )
            cols = [d[0] for d in cur.description]
            rows = [dict(zip(cols, r)) for r in cur.fetchall()]
        # 统计摘要
        summary = {
            'total': len(rows),
            'by_status': {},
            'by_severity': {},
            'by_category': {},
            'vulnerabilities': [r for r in rows if str(r.get('status') or '').upper() in ('FAIL', 'VULNERABILITY', 'VULN')],
        }
        for r in rows:
            for field in ('status', 'severity', 'category'):
                val = str(r.get(field) or 'UNKNOWN')
                key = f'by_{field}'
                summary[key][val] = summary[key].get(val, 0) + 1
        return jsonify({'success': True, 'session_key': sk or None, 'summary': summary, 'results': rows})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/test1000/fixes', methods=['POST'])
@system_container('test1000_fixes', require_auth='admin')
def api_test1000_fixes():
    """上报漏洞修复记录到 mt_test_fixes 表"""
    import datetime as _dt
    try:
        u = _safe_user_ctx(_current_user()) or {}
        uname = str(u.get('username') or session.get('username') or 'system')
        data = request.get_json(silent=True) or {}
        test_id = _safe_str(data.get('test_id'), max_len=128).strip()
        if not test_id:
            return jsonify({'success': False, 'message': 'test_id 必填'}), 400
        vulnerability_type = _safe_str(data.get('vulnerability_type'), max_len=100)
        severity = _safe_str(data.get('severity'), max_len=32) or 'MEDIUM'
        fix_description = _safe_str(data.get('fix_description') or data.get('description'), max_len=2000)
        if not fix_description:
            return jsonify({'success': False, 'message': 'fix_description 必填'}), 400
        now = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        dbp = _mt_102_db()
        with _get_conn(dbp) as c:
            _ensure_mt_102_vote_schema(c)
            cur = c.execute(
                "INSERT INTO mt_test_fixes (test_id,vulnerability_type,severity,fix_description,fixed_at,fixed_by) "
                "VALUES (?,?,?,?,?,?)",
                (test_id, vulnerability_type, severity, fix_description, now, uname)
            )
            fix_id = cur.lastrowid
            # 同步更新 mt_test_results.fix_applied
            c.execute(
                "UPDATE mt_test_results SET fix_applied=? WHERE test_id=?",
                (fix_description[:500], test_id)
            )
            c.commit()
        return jsonify({'success': True, 'fix_id': fix_id, 'test_id': test_id,
                        'fixed_at': now, 'fixed_by': uname})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


# ========== API组1 /api/automation/plans/* (8个) ==========

@app.route('/api/automation/plans', methods=['GET'])
def api_automation_plans_list():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        page = request.args.get('page', 1, type=int)
        size = request.args.get('size', 20, type=int)
        plan_type = request.args.get('plan_type')
        status = request.args.get('status')
        offset = (page - 1) * size
        rows, total = [], 0
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                where = []
                params = []
                if plan_type:
                    where.append("plan_type=?")
                    params.append(plan_type)
                if status:
                    where.append("status=?")
                    params.append(status)
                where_sql = (" WHERE " + " AND ".join(where)) if where else ""
                r = c.execute(f"SELECT COUNT(*) FROM automation_plans{where_sql}", params).fetchone()
                total = r[0] or 0
                cols = ['plan_id','name','plan_type','priority','cron','tasks_json','status','enabled','last_run','next_run','created_by','coverage_score','efficiency_score','eigenflux_vote_result']
                cur = c.execute(f"SELECT {','.join(cols)} FROM automation_plans{where_sql} ORDER BY priority DESC, next_run IS NULL, next_run LIMIT ? OFFSET ?", params + [size, offset])
                for row in cur.fetchall():
                    d = dict(zip(cols, row))
                    try:
                        d['tasks'] = json.loads(d['tasks_json']) if d.get('tasks_json') else []
                    except Exception:
                        d['tasks'] = []
                    d.pop('tasks_json', None)
                    try:
                        d['eigenflux_vote'] = json.loads(d['eigenflux_vote_result']) if d.get('eigenflux_vote_result') else None
                    except Exception:
                        d['eigenflux_vote'] = None
                    d.pop('eigenflux_vote_result', None)
                    rows.append(d)
        except Exception as _e:
            _automation_report_anomaly('automation_plans_list_db', str(_e))
        ef = _automation_mock_eigenflux_vote('plans_list', {'count': len(rows), 'page': page})
        return jsonify({'success': True, 'data': {'items': rows, 'total': total, 'page': page, 'size': size}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/plans', methods=['POST'])
def api_automation_plans_create():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        data = request.get_json(force=True, silent=True) or {}
        name = (data.get('name') or '').strip()
        plan_type = (data.get('plan_type') or 'custom').strip()
        priority = int(data.get('priority') or 5)
        cron = data.get('cron')
        tasks = data.get('tasks') or []
        if not name:
            return jsonify({'success': False, 'message': 'name 必填'}), 400
        plan_id = f'plan_{int(time.time())}_{secrets.token_hex(4)}'
        created_by = user.get('username') or 'system'
        tasks_json = json.dumps(tasks, ensure_ascii=False)
        # 根据 priority 决定审批层级：>=8 走7步，>=5 走5步，其余3步
        need_steps = 7 if priority >= 8 else (5 if priority >= 5 else 3)
        ef = _automation_mock_eigenflux_vote('plan_create', {'name': name, 'priority': priority, 'steps': need_steps})
        ef_vote_json = json.dumps(ef, ensure_ascii=False)
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                c.execute(
                    "INSERT INTO automation_plans (plan_id,name,plan_type,priority,cron,tasks_json,status,enabled,last_run,next_run,created_by,coverage_score,efficiency_score,eigenflux_vote_result) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (plan_id, name, plan_type, priority, cron, tasks_json, 'draft', 1, None, None, created_by, 0, 0, ef_vote_json)
                )
                c.commit()
        except Exception as _e:
            _automation_report_anomaly('automation_plans_create_db', str(_e))
            return jsonify({'success': False, 'message': f'DB 错误: {_e}'}), 500
        # 自动创建 rule_proposal 走审批（根据 priority）
        try:
            from app.services.rule_approval import create_proposal as _cp
            try:
                _cp(
                    rule_code=f'AUTOPLAN_{plan_id[:16]}',
                    title=f'自动化计划创建审批：{name}',
                    proposed_content=json.dumps({'plan_id': plan_id, 'tasks': tasks, 'priority': priority}, ensure_ascii=False),
                    proposer_id=int(user.get('uid') or 0),
                    proposer_name=created_by,
                    reason=f'自动化计划需要{need_steps}步审批（priority={priority}）',
                    change_mode='approval_required'
                )
            except Exception:
                pass
        except Exception:
            pass
        _automation_write_log('plans', f'创建计划 {name} (id={plan_id}), priority={priority}, 审批={need_steps}步, EigenFlux={ef["verdict"]}', level='INFO', plan_id=plan_id)
        return jsonify({'success': True, 'data': {'plan_id': plan_id, 'approval_steps': need_steps, 'eigenflux': ef}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


