@app.route('/api/automation/plans/simulate', methods=['POST'])
def api_automation_plans_simulate():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        data = request.get_json(force=True, silent=True) or {}
        tasks = data.get('tasks') or []
        plan_type = data.get('plan_type') or 'custom'
        matched = []
        step_num = 0
        for t in tasks:
            step_num += 1
            tname = t.get('name') or f'step_{step_num}'
            matched.append({
                'step': step_num,
                'name': tname,
                'type': t.get('type') or 'task',
                'target': t.get('target') or '*',
                'hit': True,
                'estimate_ms': 100 + step_num * 50,
                'rules': [f'R-{secrets.token_hex(3).upper()}' for _ in range(2)],
                'downstream': [f'next_step_{step_num+1}'] if step_num < len(tasks) else [],
            })
        ef = _automation_mock_eigenflux_vote('plan_simulate', {'tasks': len(tasks), 'plan_type': plan_type})
        _automation_write_log('plans', f'模拟执行计划: {len(tasks)} 个任务, 命中规则链={len(matched)}', level='INFO')
        return jsonify({'success': True, 'data': {'matched_chain': matched, 'total_steps': len(matched), 'simulated': True}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


# ========== API组2 /api/automation/agents/* (6个) ==========

@app.route('/api/automation/agents', methods=['GET'])
def api_automation_agents_list():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        status = request.args.get('status')
        rows = []
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                cols = ['agent_id','name','role','level','status','current_task','task_queue_json','last_heartbeat','assigned_collection','capabilities_json','eigenflux_risk_score']
                sql = f"SELECT {','.join(cols)} FROM automation_agents"
                params = []
                if status:
                    sql += " WHERE status=?"
                    params.append(status)
                sql += " ORDER BY level DESC, last_heartbeat IS NULL, last_heartbeat DESC"
                cur = c.execute(sql, params)
                for row in cur.fetchall():
                    d = dict(zip(cols, row))
                    try:
                        d['task_queue'] = json.loads(d['task_queue_json']) if d.get('task_queue_json') else []
                    except Exception:
                        d['task_queue'] = []
                    d.pop('task_queue_json', None)
                    try:
                        d['capabilities'] = json.loads(d['capabilities_json']) if d.get('capabilities_json') else []
                    except Exception:
                        d['capabilities'] = []
                    d.pop('capabilities_json', None)
                    # 在线判定：30s内心跳
                    hb = d.get('last_heartbeat')
                    online = False
                    if hb:
                        try:
                            hbt = datetime.strptime(hb, '%Y-%m-%d %H:%M:%S')
                            online = (datetime.now() - hbt).total_seconds() < 30
                        except Exception:
                            pass
                    d['online'] = online
                    rows.append(d)
        except Exception as _e:
            _automation_report_anomaly('automation_agents_list_db', str(_e))
        ef = _automation_mock_eigenflux_vote('agents_list', {'count': len(rows)})
        return jsonify({'success': True, 'data': rows, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


