@app.route('/api/automation/background/jobs', methods=['GET'])
def api_automation_background_jobs():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        status = request.args.get('status')
        module = request.args.get('module')
        limit = request.args.get('limit', 100, type=int)
        rows = []
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                cols = ['job_id','name','job_type','module','action','status','progress','payload_json','result_json','submitted_by','submitted_at','started_at','completed_at','error_msg','retry_count']
                where = []
                params = []
                if status:
                    where.append("status=?")
                    params.append(status)
                if module:
                    where.append("module=?")
                    params.append(module)
                where_sql = (" WHERE " + " AND ".join(where)) if where else ""
                cur = c.execute(f"SELECT {','.join(cols)} FROM automation_background_jobs{where_sql} ORDER BY submitted_at DESC LIMIT ?", params + [limit])
                for row in cur.fetchall():
                    d = dict(zip(cols, row))
                    try:
                        d['payload'] = json.loads(d['payload_json']) if d.get('payload_json') else {}
                    except Exception:
                        d['payload'] = {}
                    d.pop('payload_json', None)
                    try:
                        d['result'] = json.loads(d['result_json']) if d.get('result_json') else None
                    except Exception:
                        d['result'] = None
                    d.pop('result_json', None)
                    rows.append(d)
        except Exception as _e:
            _automation_report_anomaly('automation_bg_jobs_db', str(_e))
        ef = _automation_mock_eigenflux_vote('bg_jobs_list', {'count': len(rows), 'status': status})
        return jsonify({'success': True, 'data': rows, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


