@app.route('/api/automation/background/jobs/<jid>/cancel', methods=['POST'])
def api_automation_background_cancel(jid):
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        ef = _automation_mock_eigenflux_vote('bg_job_cancel', {'job_id': jid})
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                row = c.execute("SELECT name,status FROM automation_background_jobs WHERE job_id=?", (jid,)).fetchone()
                if not row:
                    return jsonify({'success': False, 'message': 'Job不存在'}), 404
                if row[1] in ('success', 'failed', 'cancelled'):
                    return jsonify({'success': False, 'message': f'Job已处于 {row[1]} 状态，无法取消'}), 400
                now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                c.execute(
                    "UPDATE automation_background_jobs SET status='cancelled', completed_at=?, error_msg=? WHERE job_id=?",
                    (now, f'手动取消 by {user.get("username")}', jid)
                )
                c.commit()
                job_name = row[0]
        except Exception as _e:
            _automation_report_anomaly('automation_bg_cancel_db', str(_e))
            return jsonify({'success': False, 'message': f'DB 错误: {_e}'}), 500
        _automation_write_log('background', f'取消任务: {job_name} (jid={jid}), 操作人={user.get("username")}', level='WARN', job_id=jid)
        return jsonify({'success': True, 'data': {'job_id': jid, 'cancelled': True}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/background/jobs/<jid>/progress', methods=['GET'])
def api_automation_background_progress(jid):
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        use_sse = request.args.get('sse', '0') == '1'
        info = {'job_id': jid, 'status': 'unknown', 'progress': 0, 'result': None, 'error': None}
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                row = c.execute(
                    "SELECT status,progress,result_json,error_msg,submitted_at,started_at,completed_at FROM automation_background_jobs WHERE job_id=?",
                    (jid,)
                ).fetchone()
                if not row:
                    return jsonify({'success': False, 'message': 'Job不存在'}), 404
                info['status'] = row[0]
                info['progress'] = row[1] or 0
                try:
                    info['result'] = json.loads(row[2]) if row[2] else None
                except Exception:
                    info['result'] = None
                info['error'] = row[3]
                info['submitted_at'] = row[4]
                info['started_at'] = row[5]
                info['completed_at'] = row[6]
        except Exception as _e:
            _automation_report_anomaly('automation_bg_progress_db', str(_e))
        # 模拟推进 pending/running
        if info['status'] in ('pending', 'running'):
            import random as _rd
            new_progress = min(100, int(info['progress']) + _rd.randint(1, 20))
            new_status = 'running'
            if new_progress >= 100:
                new_status = 'success'
            try:
                with _get_conn(APP_DB) as c:
                    _ensure_automation_schema(c)
                    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                    updates = [new_status, new_progress]
                    sql = "UPDATE automation_background_jobs SET status=?, progress=?"
                    if new_status == 'running' and not info.get('started_at'):
                        sql += ", started_at=?"
                        updates.append(now)
                    if new_status == 'success':
                        sql += ", completed_at=?, result_json=?"
                        updates.extend([now, json.dumps({'simulated': True, 'ok': True}, ensure_ascii=False)])
                    sql += " WHERE job_id=?"
                    updates.append(jid)
                    c.execute(sql, updates)
                    c.commit()
                info['status'] = new_status
                info['progress'] = new_progress
            except Exception:
                pass
        ef = _automation_mock_eigenflux_vote('bg_job_progress', {'job_id': jid, 'status': info['status']})
        if use_sse:
            from flask import Response
            import json as _sj
            def _gen():
                yield f"data: {_sj.dumps({'event': 'progress', 'data': info, '_eigenflux': ef}, ensure_ascii=False)}\n\n"
                yield f"data: {_sj.dumps({'event': 'done', 'data': info}, ensure_ascii=False)}\n\n"
            return Response(_gen(), mimetype='text/event-stream')
        return jsonify({'success': True, 'data': info, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


