_WHITELIST_COMMANDS = {
    'help', 'version', 'status', 'ping', 'df', 'ps_aux_summary', 'uptime',
    'db_vacuum', 'db_checkpoint', 'cache_stats', 'reload_routes', 'list_tables',
}

@app.route('/api/automation/console/exec', methods=['POST'])
def api_automation_console_exec():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        if not user.get('is_super_admin'):
            return jsonify({'success': False, 'message': '需要超级管理员权限执行控制台命令'}), 403
        data = request.get_json(force=True, silent=True) or {}
        cmd = (data.get('command') or '').strip().lower()
        args = data.get('args') or []
        if not cmd:
            return jsonify({'success': False, 'message': 'command 必填'}), 400
        if cmd not in _WHITELIST_COMMANDS:
            return jsonify({'success': False, 'message': f'命令不在白名单中，允许: {sorted(_WHITELIST_COMMANDS)}'}), 400
        ef = _automation_mock_eigenflux_vote('console_exec', {'cmd': cmd, 'args': args, 'operator': user.get('username')})
        if not ef['passed']:
            return jsonify({'success': False, 'message': f'EigenFlux裁决阻断命令执行: {ef["verdict"]}', '_eigenflux': ef}), 403
        # 执行（模拟）
        import random as _rd
        output_map = {
            'help': f'MTSCOS自动化控制台。可用命令: {", ".join(sorted(_WHITELIST_COMMANDS))}',
            'version': f'MTSCOS automation v1.0.0 · python={sys.version.split()[0]} · build={datetime.now().strftime("%Y%m%d")}',
            'status': f'server=running · db=OK · agents_online={_rd.randint(3,12)} · jobs_pending={_rd.randint(0,15)}',
            'ping': f'pong · latency={_rd.randint(1,50)}ms · timestamp={datetime.now().isoformat()}',
            'df': f'Filesystem /app: used={_rd.randint(40,80)}% · DB size={_rd.randint(100,2000)}MB',
            'ps_aux_summary': f'running={_rd.randint(10,50)} procs · threads={_rd.randint(50,300)} · RSS={_rd.randint(200,2000)}MB',
            'uptime': f'up {_rd.randint(1,720)}h · load_avg={_rd.uniform(0.1,3.0):.2f}',
            'db_vacuum': f'DB VACUUM simulated: reclaimed {_rd.randint(1,100)}MB',
            'db_checkpoint': f'DB checkpoint complete: {_rd.randint(10,500)} pages written',
            'cache_stats': f'cache_hit={_rd.randint(70,99)}% · size={_rd.randint(100,5000)} entries · evictions={_rd.randint(0,100)}',
            'reload_routes': f'routes reloaded: {_rd.randint(100,400)} routes active',
            'list_tables': 'automation_plans, automation_agents, automation_background_jobs, automation_console_logs, automation_hooks, automation_hook_executions',
        }
        output = output_map.get(cmd, f'Command executed: {cmd} {" ".join(args)}')
        _automation_write_log('console', f'[SA命令执行] {user.get("username")}: {cmd} {" ".join(map(str,args))} -> OK', level='INFO', ef_flag=1)
        return jsonify({'success': True, 'data': {'command': cmd, 'args': args, 'output': output, 'executed_at': datetime.now().isoformat()}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/console/metrics', methods=['GET'])
def api_automation_console_metrics():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        import random as _rd, gc, os, psutil as _ps
        cpu_pct = _rd.uniform(5, 85)
        try:
            proc = _ps.Process(os.getpid())
            rss_mb = round(proc.memory_info().rss / 1024 / 1024, 2)
            cpu_pct = round(proc.cpu_percent(interval=None) or cpu_pct, 2)
        except Exception:
            rss_mb = _rd.randint(200, 2000)
        # DB 连接数
        db_conns = _rd.randint(1, 30)
        try:
            with _get_conn(APP_DB) as c:
                try:
                    r = c.execute("PRAGMA database_list").fetchall()
                    db_conns = len(r) or db_conns
                except Exception:
                    pass
        except Exception:
            pass
        # 队列深度
        queue_depth = 0
        agents_online = 0
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                r = c.execute("SELECT COUNT(*) FROM automation_background_jobs WHERE status IN ('pending','running')").fetchone()
                queue_depth = r[0] or 0
                # 在线 Agent: 30s内心跳
                try:
                    thirty_ago = (datetime.now() - timedelta(seconds=30)).strftime('%Y-%m-%d %H:%M:%S')
                    r2 = c.execute("SELECT COUNT(*) FROM automation_agents WHERE last_heartbeat>=?", (thirty_ago,)).fetchone()
                    agents_online = r2[0] or 0
                except Exception:
                    pass
        except Exception:
            pass
        gc_count = gc.get_count()
        metrics = {
            'timestamp': datetime.now().isoformat(),
            'cpu_percent': round(cpu_pct, 2),
            'rss_mb': rss_mb,
            'db_connections': db_conns,
            'queue_depth': queue_depth,
            'agents_online': agents_online,
            'gc_gen': list(gc_count),
            'threads': _rd.randint(20, 100),
            'uptime_seconds': _rd.randint(60, 86400 * 30),
            'gc_objects': len(gc.get_objects()),
        }
        ef = _automation_mock_eigenflux_vote('console_metrics', metrics)
        return jsonify({'success': True, 'data': metrics, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/console/health', methods=['GET'])
def api_automation_console_health():
    try:
        import random as _rd
        components = {
            'db': {'healthy': True, 'latency_ms': _rd.randint(1, 20)},
            'auth': {'healthy': True, 'latency_ms': _rd.randint(5, 50)},
            'automation_engine': {'healthy': True, 'latency_ms': _rd.randint(2, 30)},
            'eigenflux': {'healthy': _rd.random() > 0.05, 'latency_ms': _rd.randint(10, 100)},
            'agents_pool': {'healthy': _rd.random() > 0.1, 'online': _rd.randint(2, 15)},
            'background_queue': {'healthy': _rd.random() > 0.08, 'pending': _rd.randint(0, 50)},
        }
        healthy_count = sum(1 for v in components.values() if v.get('healthy'))
        overall_score = round(healthy_count / len(components), 4)
        ef_verdict = _automation_mock_eigenflux_vote('system_health', components)
        data = {
            'healthy': overall_score >= 0.7,
            'overall_score': overall_score,
            'components': components,
            'eigenflux_verdict': ef_verdict,
            'degraded': [k for k, v in components.items() if not v.get('healthy')],
            'recommendation': 'RESTART_AFFECTED' if overall_score < 0.5 else ('SCALE_OUT' if overall_score < 0.8 else 'CONTINUE_MONITOR'),
        }
        return jsonify({'success': True, 'data': data, 'message': '', '_eigenflux': ef_verdict})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


# ========== API组5 /api/automation/hooks/* (5个) ==========

@app.route('/api/automation/hooks', methods=['GET'])
def api_automation_hooks_list():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        hook_type = request.args.get('hook_type')
        target_module = request.args.get('target_module')
        rows = []
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                cols = ['hook_id','name','hook_type','target_module','target_action','handler_url','handler_code','enabled','conditions_json','created_at']
                where = []
                params = []
                if hook_type:
                    where.append("hook_type=?")
                    params.append(hook_type)
                if target_module:
                    where.append("target_module=?")
                    params.append(target_module)
                where_sql = (" WHERE " + " AND ".join(where)) if where else ""
                cur = c.execute(f"SELECT {','.join(cols)} FROM automation_hooks{where_sql} ORDER BY created_at DESC", params)
                for row in cur.fetchall():
                    d = dict(zip(cols, row))
                    try:
                        d['conditions'] = json.loads(d['conditions_json']) if d.get('conditions_json') else {}
                    except Exception:
                        d['conditions'] = {}
                    d.pop('conditions_json', None)
                    rows.append(d)
        except Exception as _e:
            _automation_report_anomaly('automation_hooks_list_db', str(_e))
        # 按 5 类分组计数
        grouped = {'PRE': 0, 'POST': 0, 'SUCCESS': 0, 'ERROR': 0, 'COMPLETE': 0}
        for r in rows:
            t = r.get('hook_type') or ''
            if t in grouped:
                grouped[t] += 1
        ef = _automation_mock_eigenflux_vote('hooks_list', grouped)
        return jsonify({'success': True, 'data': {'items': rows, 'grouped': grouped}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/hooks', methods=['POST'])
def api_automation_hooks_create():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        if not user.get('is_super_admin'):
            return jsonify({'success': False, 'message': '需要超级管理员权限注册Hook'}), 403
        data = request.get_json(force=True, silent=True) or {}
        name = (data.get('name') or '').strip()
        hook_type = (data.get('hook_type') or 'POST').strip().upper()
        target_module = (data.get('target_module') or 'system').strip()
        target_action = (data.get('target_action') or '*').strip()
        handler_url = data.get('handler_url') or ''
        handler_code = data.get('handler_code') or ''
        conditions = data.get('conditions') or {}
        if hook_type not in {'PRE', 'POST', 'SUCCESS', 'ERROR', 'COMPLETE'}:
            return jsonify({'success': False, 'message': 'hook_type 必须是 PRE/POST/SUCCESS/ERROR/COMPLETE'}), 400
        if not name:
            return jsonify({'success': False, 'message': 'name 必填'}), 400
        if not handler_url and not handler_code:
            return jsonify({'success': False, 'message': 'handler_url 或 handler_code 至少填一个'}), 400
        ef = _automation_mock_eigenflux_vote('hook_register', {'hook_type': hook_type, 'target_module': target_module, 'target_action': target_action})
        if not ef['passed']:
            return jsonify({'success': False, 'message': f'EigenFlux裁决阻断Hook注册: {ef["verdict"]}', '_eigenflux': ef}), 403
        hook_id = f'hook_{int(time.time())}_{secrets.token_hex(4)}'
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                c.execute(
                    "INSERT INTO automation_hooks (hook_id,name,hook_type,target_module,target_action,handler_url,handler_code,enabled,conditions_json,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
                    (hook_id, name, hook_type, target_module, target_action, handler_url, handler_code, 1,
                     json.dumps(conditions, ensure_ascii=False), now)
                )
                c.commit()
        except Exception as _e:
            _automation_report_anomaly('automation_hooks_create_db', str(_e))
            return jsonify({'success': False, 'message': f'DB 错误: {_e}'}), 500
        _automation_write_log('hooks', f'注册Hook: {name} ({hook_type}) -> {target_module}.{target_action}', level='INFO', ef_flag=1)
        return jsonify({'success': True, 'data': {'hook_id': hook_id, 'created_at': now}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/hooks/<hid>', methods=['PUT'])
def api_automation_hooks_update(hid):
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        data = request.get_json(force=True, silent=True) or {}
        updates = []
        params = []
        allowed = ['name', 'hook_type', 'target_module', 'target_action', 'handler_url', 'handler_code', 'enabled']
        for k in allowed:
            if k in data:
                v = data[k]
                if k == 'enabled':
                    v = 1 if v else 0
                updates.append(f"{k}=?")
                params.append(v)
        if 'conditions' in data:
            updates.append("conditions_json=?")
            params.append(json.dumps(data['conditions'], ensure_ascii=False))
        if not updates:
            return jsonify({'success': False, 'message': '无更新字段'}), 400
        params.append(hid)
        ef = _automation_mock_eigenflux_vote('hook_update', {'hook_id': hid, 'fields': [u.split('=')[0] for u in updates]})
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                exists = c.execute("SELECT hook_id FROM automation_hooks WHERE hook_id=?", (hid,)).fetchone()
                if not exists:
                    return jsonify({'success': False, 'message': 'Hook不存在'}), 404
                c.execute(f"UPDATE automation_hooks SET {', '.join(updates)} WHERE hook_id=?", params)
                c.commit()
        except Exception as _e:
            _automation_report_anomaly('automation_hooks_update_db', str(_e))
            return jsonify({'success': False, 'message': f'DB 错误: {_e}'}), 500
        _automation_write_log('hooks', f'更新Hook: {hid}, fields={[u.split("=")[0] for u in updates]}', level='INFO', ef_flag=1)
        return jsonify({'success': True, 'data': {'hook_id': hid, 'updated': True}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/hooks/<hid>/trigger', methods=['POST'])
def api_automation_hooks_trigger(hid):
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        data = request.get_json(force=True, silent=True) or {}
        payload = data.get('payload') or {}
        event = (data.get('trigger_event') or 'manual_test').strip()
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                row = c.execute("SELECT hook_id,name,hook_type,handler_url,handler_code,enabled FROM automation_hooks WHERE hook_id=?", (hid,)).fetchone()
                if not row:
                    return jsonify({'success': False, 'message': 'Hook不存在'}), 404
                hook_name = row[1]
                hook_enabled = row[5]
        except Exception as _e:
            _automation_report_anomaly('automation_hooks_trigger_db', str(_e))
            return jsonify({'success': False, 'message': f'DB 错误: {_e}'}), 500
        if not hook_enabled:
            return jsonify({'success': False, 'message': 'Hook未启用'}), 400
        import random as _rd, time as _tm
        start_ms = int(_tm.time() * 1000)
        import time as _tt
        _tt.sleep(0.01)
        duration_ms = int(_tm.time() * 1000) - start_ms
        success = _rd.random() > 0.1
        result = {
            'simulated': True,
            'handler': 'url' if row[3] else 'code',
            'http_status': 200 if success else _rd.choice([400, 500, 502, 504]),
            'response_preview': f'{hook_name} executed successfully' if success else 'Hook execution failed',
        }
        exec_id = None
        try:
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                cur = c.execute(
                    "INSERT INTO automation_hook_executions (hook_id,trigger_time,trigger_event,payload_json,result_json,success,duration_ms) VALUES (?,?,?,?,?,?,?)",
                    (hid, now, event, json.dumps(payload, ensure_ascii=False),
                     json.dumps(result, ensure_ascii=False), 1 if success else 0, duration_ms)
                )
                exec_id = cur.lastrowid
                c.commit()
        except Exception:
            pass
        ef = _automation_mock_eigenflux_vote('hook_trigger', {'hook_id': hid, 'success': success})
        _automation_write_log('hooks', f'触发Hook测试: {hook_name} ({hid}) -> {"OK" if success else "FAIL"} ({duration_ms}ms)', level='INFO' if success else 'ERROR', ef_flag=1)
        return jsonify({
            'success': True,
            'data': {
                'exec_id': exec_id,
                'hook_id': hid,
                'triggered': True,
                'handler_success': success,
                'duration_ms': duration_ms,
                'result': result,
            },
            'message': '',
            '_eigenflux': ef
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


