@app.route('/api/automation/selfheal_retry_action/<action_id>', methods=['POST'])
def api_automation_selfheal_retry_action(action_id):
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        if not user.get('is_super_admin'):
            return jsonify({'success': False, 'message': '需要超级管理员权限重试自愈'}), 403
        id_ = int(action_id)
        ef = _automation_mock_eigenflux_vote('selfheal_retry', {'action_id': id_, 'operator': user.get('username')})
        ok, log = _selfheal_apply_action(id_, force=True, _retry=True)
        with _get_conn(APP_DB) as c:
            r = c.execute(
                "SELECT action_id,status,fix_script_name,retry_count,max_retries,apply_log FROM eigenflux_selfheal_actions WHERE action_id=?",
                (id_,)
            ).fetchone()
            if not r:
                return jsonify({'success': False, 'message': '自愈动作不存在'}), 404
        return jsonify({
            'success': True,
            'data': {
                'action_id': r[0], 'status': r[1], 'fix_script_name': r[2],
                'retry_count': r[3], 'max_retries': r[4],
                'apply_log': (r[5] or '')[:500],
                'script_ok': bool(ok), 'script_log': log[:500] if log else ''
            },
            '_eigenflux': ef,
            'message': '重试完成'
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/automation/selfheal_retry_all', methods=['POST'])
def api_automation_selfheal_retry_all():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录或会话失效'}), 401
        if not user.get('is_super_admin'):
            return jsonify({'success': False, 'message': '需要超级管理员权限重试所有自愈'}), 403
        ef = _automation_mock_eigenflux_vote('selfheal_retry_all', {'operator': user.get('username')})
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            ids = c.execute(
                "SELECT action_id FROM eigenflux_selfheal_actions WHERE status='FAILED' AND (max_retries IS NULL OR retry_count<max_retries) LIMIT 50"
            ).fetchall()
        results = []
        for (id_,) in ids:
            try:
                ok, log = _selfheal_apply_action(id_, force=True, _retry=True)
                results.append({'action_id': id_, 'ok': bool(ok), 'log': (log or '')[:200]})
            except Exception as e:
                results.append({'action_id': id_, 'ok': False, 'log': str(e)[:200]})
        success_n = sum(1 for r in results if r['ok'])
        return jsonify({
            'success': True,
            'data': {'total': len(ids), 'success': success_n, 'failed': len(ids) - success_n, 'detail': results},
            '_eigenflux': ef,
            'message': f'批量重试完成 {success_n}/{len(ids)} 成功'
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


