# AI本地化集群 + AI引擎核心：12个后端API（cluster_* 6个 + local_* 6个）
# ======================================================================
def _ai_check_session(require_login=True, require_sa=False):
    user = _automation_check_session(require_login=require_login)
    if not user:
        return None, (jsonify({'success': False, 'message': '未登录或会话失效'}), 401)
    if require_sa and not user.get('is_super_admin'):
        return None, (jsonify({'success': False, 'message': '需要超级管理员权限'}), 403)
    return user, None


