@app.route('/api/ai/cluster_status', methods=['GET'])
def api_ai_cluster_status():
    try:
        user, err = _ai_check_session(require_login=True)
        if not user: return err
        scan = _ai_cluster_health_scan_and_heartbeat()
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            total_prov = c.execute("SELECT COUNT(*) FROM ai_engine_providers").fetchone()[0]
            active_prov = c.execute("SELECT COUNT(*) FROM ai_engine_providers WHERE status='ACTIVE'").fetchone()[0]
            failed_prov = c.execute("SELECT COUNT(*) FROM ai_engine_providers WHERE status='FAILED'").fetchone()[0]
            total_nodes = c.execute("SELECT COUNT(*) FROM ai_cluster_nodes").fetchone()[0]
            online_nodes = c.execute("SELECT COUNT(*) FROM ai_cluster_nodes WHERE status='ONLINE'").fetchone()[0]
            degraded = c.execute("SELECT COUNT(*) FROM ai_cluster_nodes WHERE status='DEGRADED'").fetchone()[0]
            offline = c.execute("SELECT COUNT(*) FROM ai_cluster_nodes WHERE status='OFFLINE'").fetchone()[0]
            total_req = c.execute("SELECT COALESCE(SUM(total_requests),0) FROM ai_engine_providers").fetchone()[0]
            total_fail = c.execute("SELECT COALESCE(SUM(failed_requests),0) FROM ai_engine_providers").fetchone()[0]
            total_tokens = c.execute("SELECT COALESCE(SUM(total_tokens),0) FROM ai_engine_providers").fetchone()[0]
        return jsonify({
            'success': True,
            'data': {
                'providers': {'total': total_prov, 'active': active_prov, 'failed': failed_prov},
                'nodes': {'total': total_nodes, 'online': online_nodes, 'degraded': degraded, 'offline': offline,
                          'scan_log': scan.get('actions_log') or [], 'scan_time': scan.get('scan_time')},
                'requests': {'total': int(total_req or 0), 'failed': int(total_fail or 0), 'total_tokens_1k': round(int(total_tokens or 0) / 1000.0, 2)}
            },
            'message': ''
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/ai/cluster_nodes', methods=['GET'])
def api_ai_cluster_nodes_list():
    try:
        user, err = _ai_check_session(require_login=True)
        if not user: return err
        from flask import request as _rq
        status = str(_rq.args.get('status') or '').strip()
        limit = min(int(_rq.args.get('limit') or 200), 2000)
        where = []
        params = []
        if status:
            where.append("n.status=?"); params.append(status)
        sql = f"""SELECT n.node_id,n.provider_id,n.host,n.port,n.node_name,n.node_type,n.gpu_info,n.total_vram_gb,n.free_vram_gb,
                        n.total_ram_gb,n.free_ram_gb,n.cpu_usage_pct,n.gpu_usage_pct,n.running_models_json,n.capabilities_json,
                        n.status,n.last_heartbeat,n.health_score,n.total_inferences,n.avg_latency_ms,n.queue_depth,n.last_error,
                        p.name,p.provider_type,p.base_url,p.default_model,p.priority,p.status as prov_status
                 FROM ai_cluster_nodes n LEFT JOIN ai_engine_providers p ON n.provider_id=p.provider_id
                 {'WHERE '+' AND '.join(where) if where else ''}
                 ORDER BY n.status='ONLINE' DESC, n.health_score DESC, n.node_id DESC LIMIT ?"""
        params.append(limit)
        import json as _nj
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            rows = c.execute(sql, tuple(params)).fetchall()
        items = []
        for r in rows:
            running = None
            try:
                if r[13]: running = _nj.loads(r[13])
            except Exception:
                running = r[13]
            caps = None
            try:
                if r[14]: caps = _nj.loads(r[14])
            except Exception:
                caps = r[14]
            items.append({
                'node_id': r[0], 'provider_id': r[1], 'host': r[2], 'port': r[3], 'node_name': r[4],
                'node_type': r[5], 'gpu_info': r[6],
                'total_vram_gb': r[7], 'free_vram_gb': r[8], 'total_ram_gb': r[9], 'free_ram_gb': r[10],
                'cpu_usage_pct': r[11], 'gpu_usage_pct': r[12],
                'running_models': running, 'capabilities': caps,
                'status': r[15], 'last_heartbeat': r[16], 'health_score': r[17],
                'total_inferences': r[18], 'avg_latency_ms': r[19], 'queue_depth': r[20], 'last_error': r[21],
                'provider_name': r[22], 'provider_type': r[23], 'provider_base_url': r[24],
                'provider_default_model': r[25], 'provider_priority': r[26], 'provider_status': r[27] if len(r) > 27 else None
            })
        return jsonify({'success': True, 'data': items, 'message': f'共{len(items)}个节点'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/ai/cluster_nodes', methods=['POST'])
def api_ai_cluster_nodes_add():
    try:
        user, err = _ai_check_session(require_login=True, require_sa=True)
        if not user: return err
        from flask import request as _rq
        j = _rq.get_json(silent=True, force=False) or {}
        node_name = str(j.get('node_name') or '').strip()
        host = str(j.get('host') or '127.0.0.1').strip()
        port = int(j.get('port') or 11434)
        provider_id = j.get('provider_id')
        node_type = str(j.get('node_type') or 'INFERENCE').strip() or 'INFERENCE'
        if not node_name:
            return jsonify({'success': False, 'message': 'node_name必填'}), 400
        ef = _automation_mock_eigenflux_vote('ai_cluster_node_add', j)
        if not ef['passed']:
            return jsonify({'success': False, 'message': f'EigenFlux裁决阻断节点添加: {ef["verdict"]}', '_eigenflux': ef}), 403
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            cur = c.execute(
                """INSERT INTO ai_cluster_nodes(provider_id,host,port,node_name,node_type,gpu_info,total_ram_gb,status,health_score,total_inferences,avg_latency_ms,queue_depth,capabilities_json,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,datetime('now','localtime'),datetime('now','localtime'))""",
                (int(provider_id) if provider_id else None, host, int(port), node_name, node_type,
                 str(j.get('gpu_info') or '')[:200] if j.get('gpu_info') else None,
                 float(j.get('total_ram_gb')) if j.get('total_ram_gb') else None,
                 'OFFLINE', 0.0, 0, 0, 0,
                 None)
            )
            node_id = cur.lastrowid
            c.commit()
        return jsonify({'success': True, 'data': {'node_id': node_id, 'node_name': node_name, 'host': host, 'port': port},
                        '_eigenflux': ef, 'message': '节点已添加'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


