@app.route('/api/ai/cluster_nodes/<nid>/toggle', methods=['POST'])
def api_ai_cluster_nodes_toggle(nid):
    try:
        user, err = _ai_check_session(require_login=True, require_sa=True)
        if not user: return err
        id_ = int(nid)
        from flask import request as _rq
        j = _rq.get_json(silent=True, force=False) or {}
        new_status = str(j.get('status') or j.get('new_status') or 'MAINTENANCE').strip() or 'MAINTENANCE'
        allowed = {'ONLINE', 'OFFLINE', 'BUSY', 'DEGRADED', 'MAINTENANCE'}
        if new_status not in allowed:
            return jsonify({'success': False, 'message': 'status必须是' + '/'.join(allowed)}), 400
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            c.execute(
                "UPDATE ai_cluster_nodes SET status=?,updated_at=datetime('now','localtime'),health_score=CASE WHEN ?='ONLINE' THEN MAX(0.7,health_score) ELSE health_score END WHERE node_id=?",
                (new_status, new_status, id_)
            )
            c.commit()
            r = c.execute("SELECT node_name,status FROM ai_cluster_nodes WHERE node_id=?", (id_,)).fetchone()
        return jsonify({'success': True, 'data': {'node_id': id_, 'node_name': r[0] if r else None, 'new_status': r[1] if r else new_status},
                        'message': f'节点状态已设为{new_status}'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


