@app.route('/api/ai/local_chat', methods=['POST'])
def api_ai_local_chat():
    try:
        user, err = _ai_check_session(require_login=True)
        if not user: return err
        from flask import request as _rq
        j = _rq.get_json(silent=True, force=False) or {}
        messages = j.get('messages')
        if not messages:
            return jsonify({'success': False, 'message': 'messages必填: [{role,content},...]'}), 400
        if not isinstance(messages, list):
            return jsonify({'success': False, 'message': 'messages必须是数组'}), 400
        system_prompt = j.get('system_prompt')
        model = j.get('model')
        temperature = float(j['temperature']) if j.get('temperature') is not None else None
        timeout_s = int(j['timeout_s']) if j.get('timeout_s') is not None else None
        provider_type = j.get('provider_type')
        ok, content, prov_name, lat_ms = _ai_engine_chat(
            messages=messages, system_prompt=system_prompt, model=model,
            temperature=temperature, timeout_s=timeout_s, provider_type=provider_type
        )
        return jsonify({
            'success': bool(ok),
            'data': {
                'content': content,
                'provider_used': prov_name,
                'latency_ms': lat_ms,
                'model': model,
                'tokens_estimated': max(1, len(str(content or '')) // 4)
            },
            'message': '' if ok else '调用失败: ' + str(content or '')[:200]
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


