@app.route('/api/ai/local_models', methods=['GET'])
def api_ai_local_models_list():
    """返回providers列表和各provider关联节点的running models（如果Ollama节点在线就调/api/tags）"""
    try:
        user, err = _ai_check_session(require_login=True)
        if not user: return err
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            provs = c.execute(
                "SELECT provider_id,name,provider_type,base_url,default_model,context_length,temperature,timeout_ms,priority,status,health_score,is_default,total_requests,failed_requests,last_heartbeat,last_error,avg_latency_ms FROM ai_engine_providers ORDER BY priority ASC, health_score DESC"
            ).fetchall()
            nodes = c.execute(
                "SELECT node_id,provider_id,host,port,node_name,status,health_score,running_models_json,last_heartbeat FROM ai_cluster_nodes ORDER BY status='ONLINE' DESC, node_id"
            ).fetchall()
        pitems = []
        for p in provs:
            pitems.append({
                'provider_id': p[0], 'name': p[1], 'provider_type': p[2],
                'base_url': p[3], 'default_model': p[4], 'context_length': p[5],
                'temperature': p[6], 'timeout_ms': p[7], 'priority': p[8],
                'status': p[9], 'health_score': p[10], 'is_default': bool(p[11]),
                'total_requests': p[12], 'failed_requests': p[13], 'last_heartbeat': p[14],
                'last_error': (p[15] or '')[:200], 'avg_latency_ms': p[16]
            })
        import json as _mj
        nitems = []
        for n in nodes:
            rmodels = None
            try:
                if n[7]: rmodels = _mj.loads(n[7])
            except Exception:
                pass
            nitems.append({
                'node_id': n[0], 'provider_id': n[1], 'host': n[2], 'port': n[3],
                'node_name': n[4], 'status': n[5], 'health_score': n[6],
                'running_models': rmodels, 'last_heartbeat': n[8]
            })
        # 额外：如果有LOCAL_OLLAMA节点在线，快速返回/api/tags作为安装模型列表
        ollama_models = []
        try:
            import urllib.request as _uq
            for n in nitems:
                if (n.get('status') == 'ONLINE') and (n.get('host') and n.get('port')):
                    try:
                        with _uq.urlopen(f"http://{n['host']}:{n['port']}/api/tags", timeout=3) as resp:
                            body = resp.read().decode('utf-8', errors='ignore')
                            try:
                                jj = _mj.loads(body)
                                for m in (jj.get('models') or []):
                                    ollama_models.append({
                                        'name': m.get('name'),
                                        'model': m.get('model'),
                                        'size_gb': round((m.get('size') or 0) / 1024 ** 3, 3) if m.get('size') else None,
                                        'modified_at': m.get('modified_at'),
                                        'from_node': n['node_name']
                                    })
                            except Exception:
                                pass
                    except Exception:
                        pass
                if ollama_models: break
        except Exception:
            pass
        return jsonify({
            'success': True,
            'data': {
                'providers': pitems, 'nodes': nitems, 'ollama_installed_models': ollama_models
            },
            'message': f'提供者{len(pitems)}个 · 节点{len(nitems)}个 · Ollama已安装模型{len(ollama_models)}个'
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/ai/local_switch_provider', methods=['POST'])
def api_ai_local_switch_provider():
    try:
        user, err = _ai_check_session(require_login=True, require_sa=True)
        if not user: return err
        from flask import request as _rq
        j = _rq.get_json(silent=True, force=False) or {}
        provider_id = j.get('provider_id')
        if provider_id is None:
            return jsonify({'success': False, 'message': 'provider_id必填'}), 400
        pid = int(provider_id)
        ef = _automation_mock_eigenflux_vote('ai_switch_default_provider', j)
        if not ef['passed']:
            return jsonify({'success': False, 'message': f'EigenFlux裁决阻断切换: {ef["verdict"]}', '_eigenflux': ef}), 403
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            rr = c.execute("SELECT name,status FROM ai_engine_providers WHERE provider_id=?", (pid,)).fetchone()
            if not rr:
                return jsonify({'success': False, 'message': 'provider不存在'}), 404
            if rr[1] not in ('ACTIVE', 'STANDBY'):
                return jsonify({'success': False, 'message': f'Provider状态为{rr[1]}，无法设为默认'}), 400
            c.execute("UPDATE ai_engine_providers SET is_default=0 WHERE 1=1")
            c.execute("UPDATE ai_engine_providers SET is_default=1,priority=1,status='ACTIVE',updated_at=datetime('now','localtime') WHERE provider_id=?", (pid,))
            c.commit()
        return jsonify({'success': True, 'data': {'provider_id': pid, 'now_default_name': rr[0]}, '_eigenflux': ef,
                        'message': f'已切换默认Provider为{rr[0]}'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/ai/local_settings', methods=['GET', 'POST'])
def api_ai_local_provider_settings():
    try:
        user, err = _ai_check_session(require_login=True, require_sa=True)
        if not user: return err
        from flask import request as _rq
        if _rq.method == 'GET':
            with _get_conn(APP_DB) as c:
                _ensure_automation_schema(c)
                rows = c.execute(
                    "SELECT provider_id,name,provider_type,base_url,api_key,api_secret,default_model,context_length,temperature,timeout_ms,max_retries,priority,status,weight,concurrency_limit,is_default FROM ai_engine_providers ORDER BY priority ASC, provider_id ASC"
                ).fetchall()
            items = [{'provider_id': r[0], 'name': r[1], 'provider_type': r[2],
                      'base_url': r[3], 'api_key': ('***' + (r[4][-4:] if r[4] else '')) if r[4] else None,
                      'api_secret': ('***' + (r[5][-4:] if r[5] else '')) if r[5] else None,
                      'default_model': r[6], 'context_length': r[7], 'temperature': r[8],
                      'timeout_ms': r[9], 'max_retries': r[10], 'priority': r[11],
                      'status': r[12], 'weight': r[13], 'concurrency_limit': r[14], 'is_default': bool(r[15])}
                     for r in rows]
            return jsonify({'success': True, 'data': items, 'message': f'共{len(items)}个provider配置（密钥已脱敏）'})
        # POST: 更新或新增
        j = _rq.get_json(silent=True, force=False) or {}
        provider_id = j.get('provider_id')
        allowed_types = {'LOCAL_OLLAMA', 'LOCAL_GGUF', 'LOCAL_TRANSFORMERS', 'OPENAI_COMPAT', 'DEEPSEEK', 'QIANWEN'}
        ptype = str(j.get('provider_type') or 'LOCAL_OLLAMA').strip() or 'LOCAL_OLLAMA'
        if ptype not in allowed_types:
            return jsonify({'success': False, 'message': 'provider_type必须是: ' + '/'.join(allowed_types)}), 400
        name = str(j.get('name') or '').strip()
        if not name:
            return jsonify({'success': False, 'message': 'name必填'}), 400
        ef = _automation_mock_eigenflux_vote('ai_provider_update', j)
        if not ef['passed']:
            return jsonify({'success': False, 'message': f'EigenFlux裁决阻断Provider修改: {ef["verdict"]}', '_eigenflux': ef}), 403
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            fields = ['name=?','provider_type=?','base_url=?','api_key=?','api_secret=?','default_model=?',
                      'context_length=?','temperature=?','timeout_ms=?','max_retries=?','priority=?','status=?',
                      'weight=?','concurrency_limit=?','is_default=?']
            vals = [
                name, ptype,
                str(j.get('base_url') or '')[:300] if j.get('base_url') else None,
                str(j.get('api_key') or '')[:200] if j.get('api_key') else None,
                str(j.get('api_secret') or '')[:200] if j.get('api_secret') else None,
                str(j.get('default_model') or 'llama3.1:8b')[:200],
                int(j.get('context_length') or 8192),
                float(j.get('temperature') or 0.7),
                int(j.get('timeout_ms') or 60000),
                int(j.get('max_retries') or 3),
                int(j.get('priority') or 10),
                str(j.get('status') or 'ACTIVE')[:20],
                float(j.get('weight') or 1.0),
                int(j.get('concurrency_limit') or 4),
                1 if j.get('is_default') else 0,
            ]
            if provider_id is None:
                # 新增
                fields_insert = ['name','provider_type','base_url','api_key','api_secret','default_model',
                                 'context_length','temperature','timeout_ms','max_retries','priority','status',
                                 'weight','concurrency_limit','is_default','created_at','updated_at']
                placeholders = ','.join(['?'] * (len(fields_insert)))
                vals2 = list(vals) + [datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                                      datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')]
                # 如果is_default=1→先把其他全改为0
                if j.get('is_default'):
                    c.execute("UPDATE ai_engine_providers SET is_default=0 WHERE 1=1")
                cur = c.execute(
                    f"INSERT INTO ai_engine_providers({','.join(fields_insert)}) VALUES({placeholders})",
                    tuple(vals2)
                )
                pid = cur.lastrowid
            else:
                pid = int(provider_id)
                if j.get('is_default'):
                    c.execute("UPDATE ai_engine_providers SET is_default=0 WHERE 1=1")
                fields.append("updated_at=datetime('now','localtime')")
                vals.append(pid)
                c.execute(f"UPDATE ai_engine_providers SET {','.join(fields)} WHERE provider_id=?", tuple(vals))
            c.commit()
        return jsonify({'success': True, 'data': {'provider_id': pid, 'name': name}, '_eigenflux': ef,
                        'message': f'Provider {name} 已{"新增" if provider_id is None else "更新"}'})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


# ======================================================================
# 安全系统：6张安全表 + 辅助函数 + 20个安全防护API
# ======================================================================

def _ensure_security_schema(conn):
    """幂等创建7张安全表：sec_bruteforce_locks / sec_hacking_events / sec_credential_stuffing_logs /
    sec_decompile_watermarks / sec_known_weak_password_hashes / sec_rate_limit_buckets / sec_decompile_tamper_logs"""
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS sec_bruteforce_locks (
            lock_id INTEGER PRIMARY KEY AUTOINCREMENT,
            ip_addr TEXT,
            username TEXT,
            locked_until TEXT,
            reason TEXT,
            unlock_code TEXT,
            eigenflux_flag INTEGER DEFAULT 0,
            created_at TEXT DEFAULT (datetime('now','localtime'))
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS sec_hacking_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp TEXT DEFAULT (datetime('now','localtime')),
            ip_addr TEXT,
            user_agent TEXT,
            path TEXT,
            attack_type TEXT,
            payload_excerpt TEXT,
            blocked INTEGER DEFAULT 0,
            eigenflux_verdict TEXT
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS sec_credential_stuffing_logs (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            ip_addr TEXT,
            batch_count INTEGER DEFAULT 0,
            unique_accounts_attempted INTEGER DEFAULT 0,
            detected_at TEXT DEFAULT (datetime('now','localtime')),
            blocked INTEGER DEFAULT 0,
            eigenflux_severity TEXT
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS sec_decompile_watermarks (
            mark_id INTEGER PRIMARY KEY AUTOINCREMENT,
            watermark_token TEXT UNIQUE,
            injected_at TEXT DEFAULT (datetime('now','localtime')),
            last_verified_at TEXT,
            verified_count INTEGER DEFAULT 0,
            tamper_detected_count INTEGER DEFAULT 0
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS sec_known_weak_password_hashes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sha256_hash TEXT UNIQUE,
            source_name TEXT,
            added_at TEXT DEFAULT (datetime('now','localtime'))
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS sec_rate_limit_buckets (
            bucket_key TEXT PRIMARY KEY,
            window_start TEXT,
            request_count INTEGER DEFAULT 0,
            last_touch TEXT
        )""")
        # 新增：反编译篡改日志表（api_security_decompile_tamper_logs API 读取）
        conn.execute("""CREATE TABLE IF NOT EXISTS sec_decompile_tamper_logs (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp TEXT DEFAULT (datetime('now','localtime')),
            ip_addr TEXT,
            user_agent TEXT,
            path TEXT,
            tamper_type TEXT,
            tamper_detail TEXT,
            eigenflux_flag INTEGER DEFAULT 1
        )""")
        try:
            default_wm = 'MTSCOS_SEC_DEFAULT_WM_2026'
            conn.execute(
                "INSERT OR IGNORE INTO sec_decompile_watermarks (watermark_token, injected_at, verified_count, tamper_detected_count) VALUES (?, datetime('now','localtime'), 0, 0)",
                (default_wm,)
            )
        except Exception:
            pass
        conn.commit()
    except Exception:
        pass


# ============================================================
# 【STEP_7 SSL证书绑定】建表 + users迁移 + 6个辅助函数 + 盾牌第5项
# flow_id: flow_20260809110706_de34de
# ============================================================
def _ensure_ssl_binding_schema(conn):
    """幂等创建2张SSL绑定表 + users表迁移3字段（老库容错ALTER）"""
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS user_ssl_cert_bindings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            binding_id TEXT UNIQUE NOT NULL,
            user_id INTEGER NOT NULL,
            username TEXT NOT NULL,
            ssl_fingerprint TEXT NOT NULL,
            fingerprint_algo TEXT DEFAULT 'sha256',
            cert_serial TEXT,
            cert_subject_cn TEXT,
            cert_issuer TEXT,
            cert_not_before TEXT,
            cert_not_after TEXT,
            cert_pem TEXT,
            is_primary INTEGER DEFAULT 0,
            is_active INTEGER DEFAULT 1,
            revoked INTEGER DEFAULT 0,
            revoked_reason TEXT,
            revoked_by TEXT,
            revoked_at TEXT,
            bound_at TEXT DEFAULT CURRENT_TIMESTAMP,
            approved_by_hardware_admin TEXT,
            approved_at_hardware_admin TEXT,
            approved_by_super_admin TEXT,
            approved_at_super_admin TEXT,
            last_used_at TEXT,
            last_used_ip TEXT,
            use_count INTEGER DEFAULT 0,
            eigenflux_flag INTEGER DEFAULT 0
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ssl_bind_user ON user_ssl_cert_bindings(user_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ssl_bind_fp ON user_ssl_cert_bindings(ssl_fingerprint)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ssl_bind_active ON user_ssl_cert_bindings(user_id, is_active, revoked)")
        conn.execute("""CREATE TABLE IF NOT EXISTS ssl_cert_revocation_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            binding_id TEXT NOT NULL,
            user_id INTEGER NOT NULL,
            username TEXT NOT NULL,
            ssl_fingerprint TEXT NOT NULL,
            revoke_reason TEXT NOT NULL,
            operator TEXT NOT NULL,
            eigenflux_verdict TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )""")
        # users 表迁移：3字段（老库容错，已存在则跳过）
        for col_ddl in [
            ("ssl_binding_status", "TEXT DEFAULT 'unbound'"),
            ("ssl_binding_count", "INTEGER DEFAULT 0"),
            ("ssl_grace_period_until", "TEXT"),
        ]:
            try:
                conn.execute(f"ALTER TABLE users ADD COLUMN {col_ddl[0]} {col_ddl[1]}")
            except sqlite3.OperationalError:
                pass  # 字段已存在
        conn.commit()
    except Exception:
        pass


def _bind_user_ssl_cert(user_id, username, fp, cert_pem=None, ip=None, is_primary=False):
    """绑定SSL证书到用户（最多3个），返回 binding_id 或 None"""
    try:
        import uuid as _uu
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        binding_id = 'ssl_' + _uu.uuid4().hex[:16]
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            # 检查绑定数量上限（默认3）
            cnt = c.execute(
                "SELECT COUNT(*) FROM user_ssl_cert_bindings WHERE user_id=? AND is_active=1 AND revoked=0",
                (user_id,)
            ).fetchone()[0]
            if cnt >= 3:
                return None  # 超过上限
            # 如果设为主证书，先清除其他主证书
            if is_primary:
                c.execute("UPDATE user_ssl_cert_bindings SET is_primary=0 WHERE user_id=? AND is_active=1", (user_id,))
            c.execute("""INSERT INTO user_ssl_cert_bindings
                (binding_id, user_id, username, ssl_fingerprint, cert_pem, is_primary, is_active, revoked, bound_at, last_used_ip)
                VALUES (?,?,?,?,?,?,1,0,?,?)""",
                (binding_id, user_id, username, fp, (cert_pem or '')[:8192], 1 if is_primary else 0, now, ip or ''))
            # 更新 users 表绑定状态
            c.execute("UPDATE users SET ssl_binding_status='bound', ssl_binding_count=ssl_binding_count+1 WHERE id=?", (user_id,))
            c.commit()
        return binding_id
    except Exception:
        return None


def _verify_ssl_binding(user_id, fp):
    """校验SSL指纹是否绑定到用户且有效，返回 (ok: bool, reason: str)"""
    try:
        if not fp or not user_id:
            return False, 'ssl_fp_missing'
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            row = c.execute(
                "SELECT id, is_active, revoked FROM user_ssl_cert_bindings WHERE user_id=? AND ssl_fingerprint=? AND is_active=1 AND revoked=0 LIMIT 1",
                (user_id, fp)
            ).fetchone()
            if not row:
                return False, 'ssl_binding_mismatch'
            return True, 'ok'
    except Exception:
        return False, 'ssl_check_error'


def _revoke_ssl_cert(binding_id, operator, reason):
    """吊销SSL证书（需双审批+EigenFlux磋商，此处仅记录吊销动作）"""
    try:
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            row = c.execute("SELECT user_id, username, ssl_fingerprint FROM user_ssl_cert_bindings WHERE binding_id=?", (binding_id,)).fetchone()
            if not row:
                return False
            c.execute("UPDATE user_ssl_cert_bindings SET revoked=1, revoked_reason=?, revoked_by=?, revoked_at=?, is_active=0 WHERE binding_id=?",
                      (reason, operator, now, binding_id))
            c.execute("UPDATE users SET ssl_binding_count=MAX(0, ssl_binding_count-1) WHERE id=?", (row[0],))
            c.execute("INSERT INTO ssl_cert_revocation_logs (binding_id, user_id, username, ssl_fingerprint, revoke_reason, operator) VALUES (?,?,?,?,?,?)",
                      (binding_id, row[0], row[1], row[2], reason, operator))
            c.commit()
        return True
    except Exception:
        return False


def _list_user_ssl_bindings(user_id):
    """列出用户所有SSL证书绑定（脱敏cert_pem）"""
    try:
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            rows = c.execute(
                "SELECT binding_id, ssl_fingerprint, is_primary, is_active, revoked, bound_at, last_used_at, last_used_ip, use_count, cert_not_after FROM user_ssl_cert_bindings WHERE user_id=? ORDER BY is_primary DESC, bound_at DESC",
                (user_id,)
            ).fetchall()
            return [dict(zip([d[0] for d in c.execute("SELECT * FROM user_ssl_cert_bindings LIMIT 0").description], r)) for r in rows] if rows else []
    except Exception:
        return []


def _ssl_grace_period_check(user_id):
    """检查用户是否在SSL宽限期内，返回 bool"""
    try:
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            row = c.execute("SELECT ssl_binding_status, ssl_grace_period_until FROM users WHERE id=?", (user_id,)).fetchone()
            if not row:
                return True  # 用户不存在，默认放行
            status = row[0] or 'unbound'
            grace_until = row[1]
            if status == 'bound':
                return False  # 已绑定，无需宽限期
            if not grace_until:
                return True  # 未设置宽限期，默认放行（历史用户首次登录时设置）
            now_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            return grace_until > now_str
    except Exception:
        return True


def _security_check_ssl_binding():
    """4合1盾牌第5项：登录请求校验SSL指纹是否在用户绑定列表中（仅对已绑定用户生效）"""
    try:
        p = (request.path or '').lower()
        if not p.endswith('/login') or request.method != 'POST':
            return {'blocked': False}
        data = request.get_json(force=True, silent=True) or {}
        form = request.form or {}
        uname = (data.get('username') or form.get('username') or '').strip()
        fp = (data.get('ssl_fingerprint') or form.get('ssl_fingerprint') or '').strip()
        if not uname:
            return {'blocked': False}
        # SA 例外：wuchenghao15 不因SSL缺失阻断（vikey 7要素覆盖）
        if uname.lower() in _SA_HIDDEN_NAMES_LOWER:
            return {'blocked': False}
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            row = c.execute("SELECT id, ssl_binding_status FROM users WHERE username=?", (uname,)).fetchone()
            if not row:
                return {'blocked': False}  # 用户不存在，交给后续路由处理
            user_id, bind_status = row[0], row[1] or 'unbound'
            if bind_status == 'bound':
                # 已绑定用户：必须提供匹配的SSL指纹
                if not fp:
                    try:
                        _security_report_anomaly('ssl_binding_missing', {'username': uname, 'ip': request.remote_addr})
                    except Exception:
                        pass
                    return {'blocked': True, 'reason': 'ssl_binding_missing'}
                ok, reason = _verify_ssl_binding(user_id, fp)
                if not ok:
                    try:
                        _security_report_anomaly('ssl_binding_mismatch', {'username': uname, 'fp': fp[:32], 'ip': request.remote_addr})
                    except Exception:
                        pass
                    return {'blocked': True, 'reason': reason}
            # 未绑定用户：宽限期内放行
        return {'blocked': False}
    except Exception:
        return {'blocked': False}


def _security_report_anomaly(event_code, details):
    """安全异常上报 EigenFlux，失败静默"""
    try:
        import requests as _rq
        payload = {
            'event_code': str(event_code or ''),
            'details': details or {},
            'reported_at': datetime.now().isoformat(),
            'source': 'security_system'
        }
        try:
            _rq.post('http://127.0.0.1:8888/api/eigenflux/report_anomaly', json=payload, timeout=2)
        except Exception:
            pass
    except Exception:
        pass


def _security_is_weak_password(plain):
    """弱密码检测：内置top20 + sec_known_weak_password_hashes表查询"""
    try:
        if not plain or not isinstance(plain, str):
            return True
        pw = plain.strip()
        if len(pw) < 6:
            return True
        top20 = {
            'admin', '123456', 'password', 'abc123', 'qwerty123',
            '12345678', '123456789', '123123', '111111', '000000',
            'qwerty', '123321', 'password123', 'iloveyou', 'admin123',
            'letmein', 'welcome', '666666', '888888', '123456a'
        }
        if pw.lower() in top20:
            return True
        try:
            import hashlib as _hl
            sha = _hl.sha256(pw.encode('utf-8')).hexdigest()
            with _get_conn(APP_DB) as c:
                _ensure_security_schema(c)
                r = c.execute(
                    "SELECT 1 FROM sec_known_weak_password_hashes WHERE sha256_hash=? LIMIT 1",
                    (sha,)
                ).fetchone()
                if r:
                    return True
        except Exception:
            pass
    except Exception:
        pass
    return False


def _security_lockout_time(level):
    """5级惩罚时间(min): level1=10min / level2=1h / level3=6h / level4=24h / level5=永久"""
    try:
        level = int(level or 1)
        mapping = {1: 10, 2: 60, 3: 360, 4: 1440, 5: 99999999}
        return mapping.get(level, 10)
    except Exception:
        return 10


def _security_audit_log(source, level, message, **kwargs):
    """安全审计日志：写入 automation_console_logs (source='security_system', eigenflux_flag=1)"""
    try:
        ts = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        src_full = f'security_{source}' if source else 'security_system'
        msg_full = str(message or '')[:2000]
        if kwargs:
            try:
                extra = json.dumps(kwargs, ensure_ascii=False)[:2000]
                if len(msg_full) + len(extra) + 3 < 4000:
                    msg_full = f"{msg_full} | extra={extra}"
            except Exception:
                pass
        with _get_conn(APP_DB) as c:
            _ensure_automation_schema(c)
            c.execute(
                "INSERT INTO automation_console_logs (timestamp,level,source,message,job_id,agent_id,plan_id,eigenflux_flag) VALUES (?,?,?,?,?,?,?,?)",
                (ts, str(level or 'INFO'), src_full, msg_full, None, None, None, 1)
            )
            c.commit()
    except Exception:
        pass


def _security_super_admin_vikey_check():
    """SA+VIKEY双重检查：username=='wuchenghao15' + _mt_vikey_lock_check 通过"""
    try:
        uname = str(session.get('username') or '').strip().lower()
        if uname != 'wuchenghao15':
            return False, '非超级管理员账户'
        is_sa = _mt_resolve_is_super_admin()
        if not is_sa:
            return False, '超级管理员权限校验失败'
        try:
            from core.services.vikey_api import get_vikey_api
            vk = get_vikey_api()
            st = vk.get_lock_state()
            if st.get('locked'):
                return False, 'VIKEY未插入或已锁定'
        except Exception:
            pass
        return True, 'OK'
    except Exception as e:
        return False, str(e)


