@app.route('/api/security/hacking/events', methods=['GET'])
def api_security_hacking_events():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录'}), 401
        page = request.args.get('page', 1, type=int)
        size = request.args.get('size', 20, type=int)
        attack_type = request.args.get('attack_type')
        offset = (page - 1) * size
        rows, total = [], 0
        try:
            with _get_conn(APP_DB) as c:
                _ensure_security_schema(c)
                where = []
                params = []
                if attack_type:
                    where.append("attack_type=?")
                    params.append(attack_type)
                ws = (" WHERE " + " AND ".join(where)) if where else ""
                r = c.execute(f"SELECT COUNT(*) FROM sec_hacking_events{ws}", params).fetchone()
                total = r[0] or 0
                cur = c.execute(
                    f"SELECT event_id,timestamp,ip_addr,user_agent,path,attack_type,payload_excerpt,blocked,eigenflux_verdict FROM sec_hacking_events{ws} ORDER BY timestamp DESC LIMIT ? OFFSET ?",
                    params + [size, offset]
                )
                for row in cur.fetchall():
                    rows.append(dict(zip(['event_id', 'timestamp', 'ip_addr', 'user_agent', 'path', 'attack_type', 'payload_excerpt', 'blocked', 'eigenflux_verdict'], row)))
        except Exception as _e:
            try:
                _security_report_anomaly('hacking_events_db_err', {'err': str(_e)})
            except Exception:
                pass
        ef = _automation_mock_eigenflux_vote('hacking_events', {'count': len(rows), 'total': total})
        return jsonify({'success': True, 'data': {'items': rows, 'total': total, 'page': page, 'size': size}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


