@app.route('/api/security/stuffing/import_weak_passwords', methods=['POST'])
def api_security_stuffing_import_weak_passwords():
    try:
        if not session.get('logged_in'):
            return jsonify({'success': False, 'message': '未登录'}), 401
        role = str(session.get('role') or 'user').lower()
        if role not in {'admin', 'super_admin'}:
            return jsonify({'success': False, 'message': '权限不足'}), 403
        data = request.get_json(force=True, silent=True) or {}
        hashes = data.get('hashes') or []
        source = (data.get('source_name') or 'manual_import').strip()[:50]
        if not isinstance(hashes, list):
            return jsonify({'success': False, 'message': 'hashes必须为数组'}), 400
        imported = 0
        invalid = 0
        try:
            import re as _re
            with _get_conn(APP_DB) as c:
                _ensure_security_schema(c)
                for h in hashes:
                    hs = str(h or '').strip().lower()
                    if len(hs) != 64 or not _re.match(r'^[0-9a-f]{64}$', hs):
                        invalid += 1
                        continue
                    try:
                        c.execute(
                            "INSERT OR IGNORE INTO sec_known_weak_password_hashes (sha256_hash, source_name) VALUES (?, ?)",
                            (hs, source)
                        )
                        if c.total_changes > 0:
                            imported += 1
                    except Exception:
                        invalid += 1
                c.commit()
        except Exception as _e:
            try:
                _security_report_anomaly('stuffing_import_db_err', {'err': str(_e)})
            except Exception:
                pass
            return jsonify({'success': False, 'message': f'DB错误: {_e}'}), 500
        try:
            _security_audit_log('credential_stuffing', 'INFO', f'导入弱密码哈希: 成功{imported}条/失败{invalid}条 source={source}', operator=session.get('username'))
        except Exception:
            pass
        ef = _automation_mock_eigenflux_vote('stuffing_import_weak', {'imported': imported, 'invalid': invalid})
        return jsonify({'success': True, 'data': {'imported': imported, 'invalid': invalid, 'source_name': source}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/security/stuffing/weak_check', methods=['POST'])
def api_security_stuffing_weak_check():
    try:
        if not session.get('logged_in'):
            return jsonify({'success': False, 'message': '未登录'}), 401
        role = str(session.get('role') or 'user').lower()
        if role not in {'admin', 'super_admin'}:
            return jsonify({'success': False, 'message': '权限不足'}), 403
        data = request.get_json(force=True, silent=True) or {}
        items = data.get('items') or []
        if not isinstance(items, list):
            return jsonify({'success': False, 'message': 'items必须为数组'}), 400
        results = []
        for item in items[:500]:
            uname = str(item.get('username') or '')
            pwd = str(item.get('password') or '')
            weak = _security_is_weak_password(pwd)
            results.append({'username': uname, 'weak': weak, 'password_length': len(pwd)})
        weak_count = sum(1 for r in results if r['weak'])
        try:
            _security_audit_log('credential_stuffing', 'INFO', f'批量弱密码检查: {len(results)}条中{weak_count}条弱密码', operator=session.get('username'))
        except Exception:
            pass
        ef = _automation_mock_eigenflux_vote('stuffing_weak_check', {'total': len(results), 'weak': weak_count})
        return jsonify({'success': True, 'data': {'items': results, 'weak_count': weak_count, 'total': len(results)}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/security/stuffing/stats', methods=['GET'])
def api_security_stuffing_stats():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录'}), 401
        result = {'top_ips': [], 'total_attempts': 0, 'blocked_count': 0, 'success_rate': '0.00%'}
        try:
            with _get_conn(APP_DB) as c:
                _ensure_security_schema(c)
                r = c.execute("SELECT COUNT(*), SUM(CASE WHEN blocked=1 THEN 1 ELSE 0 END) FROM sec_credential_stuffing_logs").fetchone()
                result['total_attempts'] = r[0] or 0
                result['blocked_count'] = r[1] or 0
                if result['total_attempts'] > 0:
                    succ = max(0, result['total_attempts'] - result['blocked_count'])
                    result['success_rate'] = f"{succ * 100.0 / result['total_attempts']:.2f}%"
                cur = c.execute(
                    "SELECT ip_addr, SUM(unique_accounts_attempted) as u FROM sec_credential_stuffing_logs GROUP BY ip_addr ORDER BY u DESC LIMIT 10"
                )
                for row in cur.fetchall():
                    result['top_ips'].append({'ip': row[0] or 'unknown', 'accounts_attempted': row[1] or 0})
        except Exception as _e:
            try:
                _security_report_anomaly('stuffing_stats_db_err', {'err': str(_e)})
            except Exception:
                pass
        ef = _automation_mock_eigenflux_vote('stuffing_stats', result)
        return jsonify({'success': True, 'data': result, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


@app.route('/api/security/stuffing/ip_block', methods=['POST'])
@system_container('security_stuffing_ip_block', require_auth='super_admin')
def api_security_stuffing_ip_block():
    try:
        if not session.get('logged_in'):
            return jsonify({'success': False, 'message': '未登录'}), 401
        ok, msg = _security_super_admin_vikey_check()
        if not ok:
            return jsonify({'success': False, 'message': f'SA+VIKEY校验失败: {msg}'}), 403
        data = request.get_json(force=True, silent=True) or {}
        cidr = (data.get('cidr') or '').strip()
        reason = (data.get('reason') or 'cidr_block').strip()[:100]
        if not cidr:
            return jsonify({'success': False, 'message': '缺少cidr'}), 400
        ips_blocked = []
        try:
            import ipaddress as _ipa
            net = _ipa.ip_network(cidr, strict=False)
            with _get_conn(APP_DB) as c:
                _ensure_security_schema(c)
                cnt = 0
                if net.num_addresses <= 256:
                    for ip in net.hosts():
                        s = str(ip)
                        try:
                            c.execute(
                                "INSERT INTO sec_bruteforce_locks (ip_addr,username,locked_until,reason,unlock_code,eigenflux_flag) VALUES (?,?,?,?,?,1)",
                                (s, None, '9999-12-31 23:59:59', f'{reason}_cidr_{cidr}', hashlib.md5(os.urandom(16)).hexdigest()[:16])
                            )
                            if c.total_changes > 0:
                                cnt += 1
                                ips_blocked.append(s)
                        except Exception:
                            pass
                else:
                    try:
                        c.execute(
                            "INSERT INTO sec_bruteforce_locks (ip_addr,username,locked_until,reason,unlock_code,eigenflux_flag) VALUES (?,?,?,?,?,1)",
                            (cidr, None, '9999-12-31 23:59:59', f'{reason}_cidr_{cidr}_range', hashlib.md5(os.urandom(16)).hexdigest()[:16])
                        )
                        cnt = c.total_changes or 0
                        ips_blocked.append(cidr)
                    except Exception:
                        pass
                c.commit()
        except ValueError as ve:
            return jsonify({'success': False, 'message': f'CIDR格式错误: {ve}'}), 400
        except Exception as _e:
            try:
                _security_report_anomaly('stuffing_ipblock_db_err', {'err': str(_e)})
            except Exception:
                pass
            return jsonify({'success': False, 'message': f'DB错误: {_e}'}), 500
        try:
            _security_audit_log('credential_stuffing', 'CRITICAL', f'CIDR封禁: {cidr} 共{len(ips_blocked)}条', operator=session.get('username'))
        except Exception:
            pass
        ef = _automation_mock_eigenflux_vote('stuffing_ip_block', {'cidr': cidr, 'blocked_count': len(ips_blocked)})
        return jsonify({'success': True, 'data': {'cidr': cidr, 'blocked': len(ips_blocked), 'ips': ips_blocked[:20]}, 'message': '', '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


