def _ensure_approval_schema(c):
    """通用审批 3 张核心表 + 索引"""
    c.execute("""
        CREATE TABLE IF NOT EXISTS approvals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            request_no TEXT UNIQUE,
            flow_type TEXT NOT NULL,              -- 6类：RULE_CHANGE/RULE_BYPASS/...
            title TEXT NOT NULL,
            subject_key TEXT,                     -- 去重key（rule_id/config_key/...）
            proposer TEXT NOT NULL,
            proposer_uid INTEGER DEFAULT 0,
            current_step TEXT NOT NULL DEFAULT 'DRAFT',
            status TEXT NOT NULL DEFAULT 'DRAFT', -- DRAFT/PENDING_*/APPROVED/REJECTED/...
            priority TEXT DEFAULT 'normal',       -- low/normal/high/critical
            payload_json TEXT,                    -- 审批内容JSON
            reason TEXT,
            approver_admin_ids TEXT DEFAULT '[]', -- 已通过管理员列表(JSON数组)
            approver_admin_count INTEGER DEFAULT 0,
            ef5_votes TEXT DEFAULT '{}',          -- AI5人投票 JSON (role -> pass/reason)
            ef5_pass_count INTEGER DEFAULT 0,
            sa_approver TEXT,
            sa_vikey_sn TEXT,
            approved_at TEXT,
            rejected_at TEXT,
            cancelled_at TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            sla_deadline TEXT,
            result_summary TEXT,
            attest_hash TEXT,                     -- 全链防篡改哈希
            readback_ok INTEGER DEFAULT 0,
            writeback_ok INTEGER DEFAULT 0,
            ext_json TEXT DEFAULT '{}'
        )
    """)
    c.execute("CREATE INDEX IF NOT EXISTS idx_approvals_flow_status ON approvals(flow_type, status)")
    c.execute("CREATE INDEX IF NOT EXISTS idx_approvals_proposer ON approvals(proposer)")
    c.execute("CREATE INDEX IF NOT EXISTS idx_approvals_subject ON approvals(flow_type, subject_key, status)")
    c.execute("CREATE INDEX IF NOT EXISTS idx_approvals_sla ON approvals(status, sla_deadline)")

    c.execute("""
        CREATE TABLE IF NOT EXISTS approval_timeline (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            approval_id INTEGER NOT NULL,
            actor TEXT,
            actor_role TEXT,
            action TEXT,                           -- create/approve/reject/cancel/urge/transfer/efvote/sa_final
            from_step TEXT,
            to_step TEXT,
            comment TEXT,
            attest_hash TEXT,
            created_at TEXT NOT NULL,
            ef_payload TEXT DEFAULT '{}'
        )
    """)
    c.execute("CREATE INDEX IF NOT EXISTS idx_aptl_aid ON approval_timeline(approval_id)")
    c.execute("CREATE INDEX IF NOT EXISTS idx_aptl_time ON approval_timeline(created_at)")

    c.execute("""
        CREATE TABLE IF NOT EXISTS approval_subjects_snapshot (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            approval_id INTEGER UNIQUE NOT NULL,
            before_json TEXT,                     -- 审批前快照
            after_json TEXT,                      -- 审批后目标态
            diff_json TEXT,
            created_at TEXT NOT NULL
        )
    """)

def _approval_attest(data_dict: dict) -> str:
    """审批操作防篡改哈希（基于当前用户+审批id+动作+时间）"""
    raw = '|'.join([
        str(data_dict.get('aid', '')),
        str(data_dict.get('actor', '')),
        str(data_dict.get('action', '')),
        str(data_dict.get('ts', 0)),
        str(session.get('_csrf_tok', 'mt')),
        'MTSCOS_APPROVAL_V1',
    ])
    return hashlib.sha256(raw.encode()).hexdigest()[:32]

def _approval_report_ef(event_code: str, aid, detail: dict = None):
    """审批异常 → EigenFlux 上报"""
    try:
        matrix = _MT_APPROVAL_EF_MATRIX.get(event_code, {})
        d = detail or {}
        d.update({'approval_id': aid, 'matrix': matrix})
        d.setdefault('severity', matrix.get('severity', 'MEDIUM'))
        d.setdefault('responsible_ai', matrix.get('responsible_ai', 'COO陈雅琴'))
        d.setdefault('fix_suggestions', matrix.get('fix', []))
        # 兼容已有规则上报函数，否则自愈中心入队
        if '_ef_report_rule_event' in globals():
            try:
                _ef_report_rule_event(event_code, d)
                return
            except Exception:
                pass
        # 兜底：写自愈任务
        try:
            with _get_conn(APP_DB) as _c:
                _c.execute("""
                    INSERT INTO eigenflux_selfheal_actions
                    (component, action_code, description, severity, params_json, status, created_at)
                    VALUES (?,?,?,?,?,?,?)
                """, (
                    'approval_system', event_code,
                    f'审批异常[{aid}]：{event_code}',
                    d.get('severity', 'MEDIUM'),
                    json.dumps(d, ensure_ascii=False),
                    'OPEN',
                    datetime.now().isoformat(timespec='seconds'),
                ))
        except Exception:
            pass
    except Exception:
        pass

def _approval_push_timeline(c, aid, actor, actor_role, action, from_step, to_step, comment='', ef_payload=None):
    now_iso = datetime.now().isoformat(timespec='seconds')
    attest = _approval_attest({'aid': aid, 'actor': actor, 'action': action, 'ts': now_iso})
    c.execute("""
        INSERT INTO approval_timeline
        (approval_id, actor, actor_role, action, from_step, to_step, comment, attest_hash, created_at, ef_payload)
        VALUES (?,?,?,?,?,?,?,?,?,?)
    """, (aid, actor, actor_role, action, from_step, to_step, comment, attest, now_iso,
          json.dumps(ef_payload or {}, ensure_ascii=False)))

def _approval_check_sla_and_timeout(c):
    """启动时/API访问时检查超时 → 写入自愈 + 推进状态"""
    try:
        now = datetime.now()
        rows = c.execute("""
            SELECT id, request_no, flow_type, current_step, status, updated_at, sla_deadline
            FROM approvals
            WHERE status IN ('PENDING_ADMIN1','PENDING_ADMIN2','PENDING_EF5','PENDING_SA')
        """).fetchall()
        for r in rows:
            sla = r['sla_deadline']
            if not sla:
                continue
            try:
                d = datetime.fromisoformat(sla)
            except Exception:
                continue
            if now >= d:
                _approval_report_ef('approval_sla_timeout', r['id'], {
                    'request_no': r['request_no'],
                    'flow_type': r['flow_type'],
                    'current_step': r['current_step'],
                    'sla_deadline': sla,
                })
    except Exception:
        pass

