# ---------- API 13：审批模拟预检 ----------
@app.route('/api/approvals/simulate', methods=['POST'])
@system_container('approval_simulate', require_auth='login')
def api_approval_simulate():
    try:
        user = _automation_check_session(require_login=True)
        if not user:
            return jsonify({'success': False, 'message': '未登录'}), 401
        body = request.get_json(force=True, silent=True) or {}
        flow_type = body.get('flow_type')
        payload = body.get('payload') or {}
        proposer = (user or {}).get('username') or (session and session.get('username')) or ''
        if flow_type not in _MT_APPROVAL_FLOW_DEFS:
            return jsonify({'success': False, 'message': f'无效审批类型: {flow_type}'}), 400
        flow_def = _MT_APPROVAL_FLOW_DEFS[flow_type]
        # EF预评估
        ef = _automation_mock_eigenflux_vote(f'approval_sim_{flow_type}', {
            'flow_type': flow_type, 'payload': payload, 'proposer': proposer,
        })
        warnings = []
        will_block = False
        need_admin_n = 0
        need_sa = False
        need_ef5_n = 0
        for s in flow_def['steps']:
            if s[2] == 'admin': need_admin_n += s[3]
            elif s[2] == 'sa': need_sa = True
            elif s[2] == 'ef5': need_ef5_n += s[3]
        verdict = (ef.get('verdict') or ef.get('overall') or '').upper() if ef else ''
        if verdict and (verdict.startswith('DENY') or verdict.startswith('REJECT')):
            will_block = True
            warnings.append(f'EigenFlux初裁驳回：{ef.get("summary") or verdict}')
        if need_sa and proposer != 'wuchenghao15':
            warnings.append('本流程需要超级管理员wuchenghao15终审+VIKEY实时检测')
        if flow_type in ('RULE_CHANGE', 'RULE_BYPASS'):
            warnings.append('变更将写入SSOT单一数据源，通过后Read-back一致性自动校验')
        # 估算耗时
        est_hours = flow_def['sla_hours'] * (0.7 if verdict and verdict.startswith('APPROVE') else 1.2)
        return jsonify({
            'success': True,
            'flow_type': flow_type,
            'flow_label': flow_def['label'],
            'steps': [{'key': s[0], 'label': s[1], 'actor_type': s[2], 'need_count': s[3]} for s in flow_def['steps']],
            'need_admin_count': need_admin_n,
            'need_super_admin': need_sa,
            'need_ef5_min_pass': need_ef5_n,
            'sla_hours': flow_def['sla_hours'],
            'estimated_hours': round(est_hours, 1),
            'will_block': will_block,
            'warnings': warnings,
            'eigenflux_preview': {
                'verdict': verdict,
                'summary': ef.get('summary') if ef else '',
                'ai_5': (ef.get('ai_5') or ef.get('ai_employees')) if ef else None,
            },
        })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500

