@app.route('/api/approvals/_internal_sla_scan', methods=['POST'])
@system_container('approval_sla_scan', require_auth='admin')
def api_approval_sla_scan():
    try:
        user = _automation_check_session(require_login=True)
        uname = (user or {}).get('username') or (session and session.get('username')) or ''
        if uname != 'wuchenghao15' and ((user or {}).get('role') or '') not in _MT_ADMIN_ROLES:
            return jsonify({'success': False, 'message': '权限不足'}), 403
        with _get_conn(APP_DB) as c:
            _ensure_approval_schema(c)
            _approval_check_sla_and_timeout(c)
            rows = c.execute("""
                SELECT id, request_no, flow_type, status, updated_at, sla_deadline
                FROM approvals
                WHERE status LIKE 'PENDING_%' AND sla_deadline IS NOT NULL
                  AND DATETIME(sla_deadline) <= DATETIME('now')
            """).fetchall()
            urgent_ids = [dict(r) for r in rows]
        ef = _automation_mock_eigenflux_vote('approval_sla_scan', {'urgent_count': len(urgent_ids)})
        return jsonify({'success': True, 'urgent_count': len(urgent_ids),
                        'urgent': urgent_ids, '_eigenflux': ef})
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)}), 500


