def _ensure_skill_schema(c):
    """AI Skill注册表 4张核心表 + 索引（参考 Semantic Kernel + Skillkit + MCP SDK）"""
    c.execute("""
        CREATE TABLE IF NOT EXISTS ai_skills (
            skill_id INTEGER PRIMARY KEY AUTOINCREMENT,
            skill_code TEXT UNIQUE,
            namespace TEXT DEFAULT 'mtscos.core',
            category TEXT NOT NULL,
            skill_name TEXT NOT NULL,
            icon TEXT DEFAULT '🧩',
            version TEXT DEFAULT '1.0.0',
            summary TEXT,
            description TEXT,
            tags_json TEXT DEFAULT '[]',
            input_schema_json TEXT DEFAULT '{}',
            output_schema_json TEXT DEFAULT '{}',
            trigger_patterns_json TEXT DEFAULT '[]',
            entry_point TEXT,
            code_snapshot TEXT,
            install_source TEXT DEFAULT 'BUILTIN',  -- BUILTIN/GITHUB_URL/MARKETPLACE/MCP_REMOTE/CUSTOM_UPLOAD
            install_ref TEXT,
            status TEXT DEFAULT 'PUBLISHED',
            is_builtin INTEGER DEFAULT 0,
            is_verified INTEGER DEFAULT 0,
            is_pinned INTEGER DEFAULT 0,
            starred INTEGER DEFAULT 0,
            use_count INTEGER DEFAULT 0,
            success_rate REAL DEFAULT 0.95,
            avg_latency_ms INTEGER DEFAULT 0,
            ef5_review_status TEXT DEFAULT 'NONE',  -- NONE/REVIEWING/PASSED/REJECTED
            ef5_votes_json TEXT DEFAULT '{}',
            ef5_score REAL DEFAULT 0,
            owner_uid INTEGER DEFAULT 0,
            owner_name TEXT DEFAULT 'system',
            mcp_server_id INTEGER DEFAULT NULL,
            mcp_tool_name TEXT,
            params_dsl_json TEXT DEFAULT '{}',      -- VelvetFlow 参数绑定 DSL
            sla_hours REAL DEFAULT 1.0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            published_at TEXT,
            deprecated_at TEXT,
            attest_hash TEXT,
            ext_json TEXT DEFAULT '{}',
            FOREIGN KEY (mcp_server_id) REFERENCES ai_mcp_servers(mcp_id) ON DELETE SET NULL
        )
    """)
    for col, idx in [('category', 'idx_skill_cat'), ('status', 'idx_skill_status'),
                     ('namespace', 'idx_skill_ns'), ('mcp_server_id', 'idx_skill_mcp')]:
        c.execute(f"CREATE INDEX IF NOT EXISTS {idx} ON ai_skills({col})")

    c.execute("""
        CREATE TABLE IF NOT EXISTS ai_workflows (
            wf_id INTEGER PRIMARY KEY AUTOINCREMENT,
            wf_code TEXT UNIQUE,
            wf_name TEXT NOT NULL,
            category TEXT DEFAULT 'BUSINESS',
            icon TEXT DEFAULT '🎯',
            summary TEXT,
            description TEXT,
            trigger_type TEXT DEFAULT 'MANUAL',
            trigger_cron TEXT,
            trigger_event_json TEXT DEFAULT '{}',
            nodes_json TEXT DEFAULT '[]',        -- [{nid,type,skill_id,params,depends_on,timeout_ms,retries}]
            edges_json TEXT DEFAULT '[]',        -- [{from,to,cond}]
            variables_json TEXT DEFAULT '{}',    -- 全局工作流变量
            env_vars_json TEXT DEFAULT '{}',     -- 注入环境变量名白名单
            status TEXT DEFAULT 'DRAFT',
            is_template INTEGER DEFAULT 0,
            owner_uid INTEGER DEFAULT 0,
            owner_name TEXT DEFAULT 'system',
            ef5_review_status TEXT DEFAULT 'NONE',
            ef5_votes_json TEXT DEFAULT '{}',
            ef5_required INTEGER DEFAULT 0,
            sla_hours REAL DEFAULT 4.0,
            total_runs INTEGER DEFAULT 0,
            success_rate REAL DEFAULT 0.9,
            avg_runtime_ms INTEGER DEFAULT 0,
            last_run_at TEXT,
            next_run_at TEXT,
            auto_approve INTEGER DEFAULT 0,
            allow_parallel INTEGER DEFAULT 1,
            max_concurrency INTEGER DEFAULT 3,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            attest_hash TEXT,
            ext_json TEXT DEFAULT '{}'
        )
    """)
    for col, idx in [('status', 'idx_wf_status'), ('trigger_type', 'idx_wf_trigger'),
                     ('is_template', 'idx_wf_tpl'), ('owner_uid', 'idx_wf_owner')]:
        c.execute(f"CREATE INDEX IF NOT EXISTS {idx} ON ai_workflows({col})")

    c.execute("""
        CREATE TABLE IF NOT EXISTS ai_workflow_runs (
            run_id INTEGER PRIMARY KEY AUTOINCREMENT,
            wf_id INTEGER NOT NULL,
            trigger_type TEXT DEFAULT 'MANUAL',
            trigger_source TEXT,
            started_by_uid INTEGER DEFAULT 0,
            started_by TEXT DEFAULT 'system',
            status TEXT DEFAULT 'RUNNING',
            start_at TEXT NOT NULL,
            end_at TEXT,
            current_node_id TEXT,
            input_payload_json TEXT DEFAULT '{}',
            variables_snapshot_json TEXT DEFAULT '{}',
            nodes_exec_json TEXT DEFAULT '{}',     -- nid -> {status,started,ended,output,error,retries}
            logs_json TEXT DEFAULT '[]',
            error_trace TEXT,
            result_json TEXT DEFAULT '{}',
            ef5_quality_score REAL,
            ef5_review_note TEXT,
            selfheal_tried INTEGER DEFAULT 0,
            rollback_done INTEGER DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            attest_hash TEXT,
            ext_json TEXT DEFAULT '{}',
            FOREIGN KEY (wf_id) REFERENCES ai_workflows(wf_id) ON DELETE CASCADE
        )
    """)
    for col, idx in [('wf_id', 'idx_run_wf'), ('status', 'idx_run_status'), ('start_at', 'idx_run_start')]:
        c.execute(f"CREATE INDEX IF NOT EXISTS {idx_run}_{col[4:] if col.startswith('wf_') else col[4:]} ON ai_workflow_runs({col})" if False else f"CREATE INDEX IF NOT EXISTS {idx} ON ai_workflow_runs({col})")

    c.execute("""
        CREATE TABLE IF NOT EXISTS ai_mcp_servers (
            mcp_id INTEGER PRIMARY KEY AUTOINCREMENT,
            mcp_code TEXT UNIQUE,
            mcp_name TEXT NOT NULL,
            icon TEXT DEFAULT '🔌',
            summary TEXT,
            transport TEXT NOT NULL DEFAULT 'stdio',  -- stdio/http/sse/streamable_http
            command TEXT,                             -- stdio: python/node
            args_json TEXT DEFAULT '[]',              -- stdio: script args
            url TEXT,                                 -- http/sse: endpoint
            auth_token_env TEXT,                      -- 环境变量名取 token
            env_json TEXT DEFAULT '{}',               -- 子进程额外 env
            tools_cache_json TEXT DEFAULT '[]',       -- list_tools 结果缓存
            health_score REAL DEFAULT 1.0,
            health_status TEXT DEFAULT 'UNKNOWN',     -- UNKNOWN/HEALTHY/DEGRADED/DOWN
            last_discovery TEXT,
            total_calls INTEGER DEFAULT 0,
            success_rate REAL DEFAULT 0.95,
            priority INTEGER DEFAULT 100,
            enabled INTEGER DEFAULT 1,
            auto_restart INTEGER DEFAULT 1,
            max_retries INTEGER DEFAULT 3,
            timeout_ms INTEGER DEFAULT 30000,
            created_by TEXT DEFAULT 'system',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            attest_hash TEXT,
            ext_json TEXT DEFAULT '{}'
        )
    """)
    for col, idx in [('transport', 'idx_mcp_tp'), ('health_status', 'idx_mcp_hs'), ('enabled', 'idx_mcp_en')]:
        c.execute(f"CREATE INDEX IF NOT EXISTS {idx} ON ai_mcp_servers({col})")


