@app.route('/api/skills/<int:sid>/ef5_vote', methods=['POST'])
@require_login
def api_skills_ef5_vote(sid):
    try:
        data = request.get_json(force=True, silent=True) or {}
        role = (data.get('role') or 'CEO张晓峰')
        passed = bool(data.get('pass'))
        reason = data.get('reason') or ''
        with _get_conn(APP_DB) as c:
            r = c.execute("SELECT * FROM ai_skills WHERE skill_id=?", (sid,)).fetchone()
            if not r: return jsonify({"success": False, "message": "not found"}), 404
            votes = json.loads(r['ef5_votes_json'] or '{}')
            votes[role] = {"pass": passed, "reason": reason, "at": _timefmt()}
            p_cnt = sum(1 for v in votes.values() if v.get('pass'))
            score = round(p_cnt / 5.0, 3) if 5 else 0
            new_status = "PASSED" if p_cnt >= 4 else ("REJECTED" if len(votes) >= 5 and p_cnt < 3 else "REVIEWING")
            c.execute("UPDATE ai_skills SET ef5_review_status=?,ef5_votes_json=?,ef5_score=?,updated_at=? WHERE skill_id=?",
                      (new_status, json.dumps(votes, ensure_ascii=False), score, _timefmt(), sid))
        ef = eigenflux_5_person_consultation('skill_review', {'skill_id': sid, 'role': role, 'pass': passed, 'reason': reason})
        return jsonify({"success": True, "_eigenflux": ef, "new_status": new_status, "score": score})
    except Exception as e:
        return jsonify({"success": False, "message": str(e)}), 500


