@app.route('/api/workflows/list', methods=['GET'])
@require_login
def api_workflows_list():
    try:
        kw = request.args.get('kw', '').strip()
        tpl_only = request.args.get('tpl', '') == '1'
        status = request.args.get('status', '').strip()
        limit = min(int(request.args.get('limit', 50)), 200)
        offset = int(request.args.get('offset', 0))
        q, args = "1=1", []
        if kw:
            q += " AND (wf_name LIKE ? OR summary LIKE ? OR wf_code LIKE ?)"
            args += [f"%{kw}%"]*3
        if tpl_only: q += " AND is_template=1"
        if status: q += " AND status=?"; args.append(status)
        with _get_conn(APP_DB) as c:
            rows = c.execute(
                f"SELECT wf_id,wf_code,wf_name,category,icon,summary,trigger_type,status,is_template,total_runs,success_rate,last_run_at,sla_hours,owner_name,created_at FROM ai_workflows WHERE {q} ORDER BY is_template DESC,total_runs DESC LIMIT ? OFFSET ?",
                args + [limit, offset]).fetchall()
            total = c.execute(f"SELECT COUNT(*) FROM ai_workflows WHERE {q}", args).fetchone()[0]
        return jsonify({"success": True, "rows": [dict(r) for r in rows], "total": total,
                        "triggers": _MT_WORKFLOW_TRIGGER, "statuses": _MT_WORKFLOW_STATUS})
    except Exception as e:
        return jsonify({"success": False, "message": str(e)}), 500


