@app.route('/api/workflows/create', methods=['POST'])
@require_login
def api_workflows_create():
    try:
        data = request.get_json(force=True, silent=True) or {}
        nodes = data.get('nodes') or []
        edges = data.get('edges') or []
        ok, order = _wf_topo_check_cycle(nodes, edges)
        if not ok:
            ef_log_anomaly('WF_DAG_CYCLE_DETECTED', {"edges": edges, "nodes": [n["nid"] for n in nodes]})
            return jsonify({"success": False, "message": "DAG 存在环路！请检查节点依赖。", "topo_failed": True}), 400
        uc = _get_user_container()
        with _get_conn(APP_DB) as c:
            c.execute(
                """INSERT INTO ai_workflows
                   (wf_code,wf_name,category,icon,summary,description,trigger_type,trigger_cron,nodes_json,edges_json,
                    status,is_template,owner_uid,owner_name,sla_hours,created_at,updated_at,variables_json,env_vars_json)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (data.get('wf_code') or f"WF_{_now_ms()}", data.get('wf_name', '未命名流程'),
                 data.get('category', 'BUSINESS'), data.get('icon', '🎯'),
                 (data.get('summary') or '')[:120], data.get('description', ''),
                 data.get('trigger_type', 'MANUAL'), data.get('trigger_cron'),
                 json.dumps(nodes, ensure_ascii=False), json.dumps(edges, ensure_ascii=False),
                 data.get('status', 'DRAFT'), 0 if not data.get('is_template') else 1,
                 uc.get('uid', 0) or 0, uc.get('username') or uc.get('name') or 'unknown',
                 float(data.get('sla_hours') or 4.0), _timefmt(), _timefmt(),
                 json.dumps(data.get('variables') or {}, ensure_ascii=False),
                 json.dumps(data.get('env_vars') or {}, ensure_ascii=False)))
        return jsonify({"success": True, "topo_order": order})
    except Exception as e:
        return jsonify({"success": False, "message": str(e)}), 500


@app.route('/api/workflows/<int:wid>/run', methods=['POST'])
@require_login
def api_workflows_run(wid):
    try:
        data = request.get_json(force=True, silent=True) or {}
        uc = _get_user_container()
        with _get_conn(APP_DB) as c:
            wf = c.execute("SELECT * FROM ai_workflows WHERE wf_id=?", (wid,)).fetchone()
            if not wf: return jsonify({"success": False, "message": "not found"}), 404
            wf_d = dict(wf)
            nodes = json.loads(wf_d.get('nodes_json') or '[]')
            edges = json.loads(wf_d.get('edges_json') or '[]')
            ok, order = _wf_topo_check_cycle(nodes, edges)
            if not ok:
                ef_log_anomaly('WF_DAG_CYCLE_DETECTED', {"wf_id": wid})
                return jsonify({"success": False, "message": "DAG 含环，拒绝执行"}), 400
            started = _timefmt()
            node_exec = {n["nid"]: {"status": "PENDING", "started": None, "ended": None, "output": None, "error": None, "retries": 0} for n in nodes}
            c.execute(
                "INSERT INTO ai_workflow_runs(wf_id,trigger_type,trigger_source,started_by_uid,started_by,status,start_at,current_node_id,input_payload_json,variables_snapshot_json,nodes_exec_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (wid, data.get('trigger_type', 'MANUAL'), data.get('trigger_source'),
                 uc.get('uid', 0) or 0, uc.get('username') or uc.get('name') or 'user',
                 "RUNNING", started, order[0] if order else None,
                 json.dumps(data.get('input') or {}, ensure_ascii=False),
                 wf_d.get('variables_json') or '{}',
                 json.dumps(node_exec, ensure_ascii=False), started, started))
            run_id = c.execute("SELECT last_insert_rowid()").fetchone()[0]
            # 简化同步模拟执行（LangGraph-like 遍历），真实环境可放后台线程
            current_vars = json.loads(wf_d.get('variables_json') or '{}')
            current_vars.update(data.get('input') or {})
            logs = []
            for nid in order:
                node = next((n for n in nodes if n["nid"] == nid), None)
                if not node: continue
                logs.append({"nid": nid, "step": "started", "t": _timefmt()})
                node_exec[nid]["started"] = _timefmt(); node_exec[nid]["status"] = "RUNNING"
                if node.get("type") == "SKILL":
                    code = node.get("skill_code")
                    if code:
                        r = _skill_execute_sandbox(c, code, {**(node.get("params") or {}), **current_vars}, uc)
                        if r.get("success"):
                            node_exec[nid]["output"] = r.get("output"); node_exec[nid]["status"] = "SUCCESS"
                        else:
                            node_exec[nid]["status"] = "FAILED"; node_exec[nid]["error"] = r.get("error")
                            ef_log_anomaly('SKILL_TIMEOUT_RETRY_EXHAUST', {'wf_id': wid, 'skill': code, 'err': r.get('error')})
                            break
                elif node.get("type") in ("END", "COND", "APPROVAL", "NOTIFY", "SELFHEAL", "EF5"):
                    node_exec[nid]["status"] = "SUCCESS"
                    node_exec[nid]["output"] = {"type": node.get("type"), "t": _timefmt()}
                else:
                    node_exec[nid]["status"] = "SUCCESS"
                node_exec[nid]["ended"] = _timefmt()
            final_status = "FAILED" if any(v["status"] == "FAILED" for v in node_exec.values()) else "COMPLETED"
            quality = round(sum(1 for v in node_exec.values() if v["status"] == "SUCCESS") / max(1, len(node_exec)), 3)
            c.execute(
                "UPDATE ai_workflow_runs SET status=?,end_at=?,current_node_id=NULL,nodes_exec_json=?,logs_json=?,result_json=?,ef5_quality_score=?,updated_at=? WHERE run_id=?",
                (final_status, _timefmt(), json.dumps(node_exec, ensure_ascii=False),
                 json.dumps(logs, ensure_ascii=False),
                 json.dumps({"topo_order": order, "vars": current_vars}, ensure_ascii=False),
                 quality, _timefmt(), run_id))
            c.execute("UPDATE ai_workflows SET total_runs=total_runs+1,success_rate=CASE WHEN ?='COMPLETED' THEN COALESCE(success_rate*0.9+0.1,1) ELSE COALESCE(success_rate*0.9,0.9) END,last_run_at=?,updated_at=? WHERE wf_id=?",
                      (final_status, _timefmt(), _timefmt(), wid))
        return jsonify({"success": True, "run_id": run_id, "status": final_status, "topo_order": order, "quality": quality})
    except Exception as e:
        return jsonify({"success": False, "message": str(e)}), 500


