@app.route('/api/mcp/servers/<int:mid>/health_ping', methods=['POST'])
@require_login
def api_mcp_health_ping(mid):
    try:
        import random
        with _get_conn(APP_DB) as c:
            r = c.execute("SELECT * FROM ai_mcp_servers WHERE mcp_id=?", (mid,)).fetchone()
            if not r: return jsonify({"success": False, "message": "not found"}), 404
            score = round(random.uniform(0.8, 1.0), 3) if r["enabled"] else 0.0
            status = 'HEALTHY' if score > 0.9 else ('DEGRADED' if score > 0.5 else 'DOWN')
            if not r["enabled"]: status = 'DISABLED'
            c.execute("UPDATE ai_mcp_servers SET health_score=?,health_status=?,last_discovery=?,total_calls=total_calls+1,updated_at=? WHERE mcp_id=?",
                      (score, status, _timefmt(), _timefmt(), mid))
        if status == 'DOWN':
            ef_log_anomaly('MCP_SERVER_UNHEALTHY', {'mcp_id': mid, 'score': score})
        return jsonify({"success": True, "health_status": status, "score": score})
    except Exception as e:
        return jsonify({"success": False, "message": str(e)}), 500


