# ============================================================================
# (14) MTSCOS CHANGE GOVERNANCE FRAMEWORK
#      每次修改强制：EigenFlux EF5 磋商 → 领域专家介入 → SSOT 写 DB → 打版本 → 本地 git commit/tag → GitHub push
#      GitHub 参考：conventionalcommits / semver.org / changelog.md 最佳实践
# ============================================================================
_GOV_BASE_DIR = os.path.dirname(os.path.abspath(__file__))
# 向上找最近的 .git 目录（若当前目录不是 git 仓库根）；找不到则保持当前目录
try:
    p = _GOV_BASE_DIR
    for _ in range(6):
        if os.path.isdir(os.path.join(p, '.git')):
            _GOV_BASE_DIR = p
            break
        up = os.path.dirname(p)
        if not up or up == p: break
        p = up
except Exception:
    pass
_GOV_DEFAULT_APPROVAL_FLOW = 'SYSTEM_UPGRADE'  # 每次修改都走 SYSTEM_UPGRADE 审批类
_GOV_VERSION_PREFIX = 'MTSCOS-v'
_GOV_RELEASE_CHANNEL = os.environ.get('MTSCOS_RELEASE_CHANNEL', 'dev')  # dev/stable/beta/hotfix

# ---- 领域专家池（AI 员工 / 外部专家 / 默认 EF5 扩展）----
_GOV_EXPERT_POOL = [
    # uid, name, role, [expertise tags], contribution_weight, description
    ('EX-ARCH-001', '首席架构师·张晓峰', '首席架构师 / SYSTEM', ['架构设计','性能调优','分布式','技术债'], 1.0, '跨模块架构决策、高并发/高可用、重大技术选型'),
    ('EX-DBA-001',  'SQLite/DBA专家·陈守正', 'DBA / DATA',        ['SQLite','MySQL','PostgreSQL','索引优化','迁移DDL'], 1.0, 'schema 评审、ALTER TABLE、查询优化、事务锁'),
    ('EX-SRE-001',  'SRE监控专家·林天翼',   'SRE / OPS',         ['Prometheus','告警降噪','OnCall','日志聚合','SLO'], 1.0, '告警抑制策略、SLA 偏差、故障自愈'),
    ('EX-SEC-001',  '网络安全专家·赵保安',   'CISO / SEC',        ['渗透测试','CVE','ai_firewall','CORS','加密狗'], 1.0, '安全漏洞、合规审查、AI防火墙策略'),
    ('EX-FE-001',   '前端全栈专家·林晓婷',   '前端 / FULLSTACK',  ['React','Canvas粒子','Tailwind','字体CDN','Playwright'], 1.0, '前端错误、性能、浏览器兼容、视觉回归'),
    ('EX-AI-001',   'AI训练专家·王智学',    'AI / ML',          ['RAG','向量嵌入','Prompt','微调','幻觉检测'], 0.9, 'AI技能准确性、Skill 质量审查'),
    ('EX-BACK-001', '后端API专家·沈致远',   '后端 / BACKEND',    ['Flask','WSGI','REST','鉴权','权限装饰器'], 0.9, 'API合约、权限装饰器、中间件、错误码规范'),
    ('EX-GIT-001',  'GitOps发布专家·孙文澜', 'DevOps / GIT',     ['semver','conventionalcommits','release分支','PR模板','GitHub Actions'], 0.9, '版本规范、git 策略、PR review、CI/CD'),
]

# ---- 版本号规范：MTSCOS-vM.m.p[-YYYYMMDD.HHMM+GIT7] ----
def _gov_next_version(release_channel=_GOV_RELEASE_CHANNEL):
    """读取 mtscos_version_history 最大版本号 +1；若表空则从 1.0.0 起"""
    import subprocess  # noqa: F401  （确保 git subprocess 在模块未全局 import 时也可用）
    import re as _re_gv
    major, minor, patch = 1, 0, 0
    try:
        with _get_conn(APP_DB) as c:
            try:
                rows = c.execute("SELECT version FROM mtscos_version_history ORDER BY id DESC LIMIT 50").fetchall()
            except Exception:
                rows = []
            for (v,) in rows:
                m = _re_gv.search(r'v(\d+)\.(\d+)\.(\d+)', str(v))
                if not m: continue
                ma, mi, pa = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if (ma, mi, pa) >= (major, minor, patch):
                    major, minor, patch = ma, mi, pa
    except Exception:
        pass
    # +1 patch
    patch += 1
    # date + short commit
    now_ts = datetime.now().strftime('%Y%m%d.%H%M')
    git7 = ''
    try:
        r = subprocess.run(['git','-C',_GOV_BASE_DIR,'rev-parse','--short=7','HEAD'], capture_output=True, text=True, timeout=5)
        if r.returncode == 0: git7 = r.stdout.strip()
    except Exception:
        pass
    build = f"-{now_ts}" + (f"+{git7}" if git7 else "")
    return (
        f"{_GOV_VERSION_PREFIX}{major}.{minor}.{patch}{build}",
        major, minor, patch, build, release_channel, git7 or None
    )

# ---- Git 封装：查脏 / commit / tag / push（经验1022369：先 --porcelain 查 dirty，再操作；否则维护分支）----
def _gov_git_status():
    """return {'dirty':bool, 'untracked':[...], 'modified':[...], 'staged':[...], 'branch':str, 'head':str}
    """
    import subprocess  # noqa: F401  在函数内部确保可用（避免全局未import）
    base = {'dirty': False, 'untracked': [], 'modified': [], 'staged': [], 'branch': '', 'head': '', 'error': None, 'has_git': True}
    try:
        # 是否有 .git
        if not os.path.exists(os.path.join(_GOV_BASE_DIR, '.git')):
            base['has_git'] = False
            base['error'] = 'project 不是 git 仓库（缺 .git）'
            return base
        r = subprocess.run(['git','-C',_GOV_BASE_DIR,'status','--porcelain=v1','-b','--untracked-files=normal'], capture_output=True, text=True, timeout=10)
        if r.returncode != 0:
            base['error'] = (r.stderr or r.stdout or 'git status failed').strip()[:400]
            return base
        for ln in (r.stdout or '').splitlines():
            if ln.startswith('##'):
                base['branch'] = ln[2:].strip().split('...')[0].strip()
                continue
            x, y = (ln + '  ')[0], (ln + '  ')[1]
            path = ln[3:].strip().split(' -> ')[-1]
            if x == '?' and y == '?': base['untracked'].append(path)
            else:
                if x in 'MADRC': base['staged'].append(path)
                if y in 'MADRC' or (x == ' ' and y in 'MD'): base['modified'].append(path)
        dirty = bool(base['untracked'] or base['modified'] or base['staged'])
        base['dirty'] = dirty
        # head commit
        r2 = subprocess.run(['git','-C',_GOV_BASE_DIR,'rev-parse','HEAD'], capture_output=True, text=True, timeout=5)
        if r2.returncode == 0: base['head'] = r2.stdout.strip()
    except Exception as e:
        base['error'] = f'git status err: {type(e).__name__}: {e}'[:400]
    return base

def _gov_git_commit_and_tag(version_full, summary, changelog_lines,
                            strategy_if_dirty='maintenance_branch',     # skip / maintenance_branch / export_patch_only
                            do_push=False):
    """执行：git add -A → commit (conventionalcommits) → tag version_full → (可选) push origin tag+branch
    strategy_if_dirty：
      - skip: dirty 直接返回 {'skipped':True, reason}（经验：默认不越权）
      - maintenance_branch: 创建 maintenance/YYYYMMDD/vX.Y.Z 分支，把本地修改 commit 上去
      - export_patch_only: 只导出 patch 到 data/databases/patches/，不 commit
    """
    import subprocess  # noqa: F401  内部确保可用
    result = {'ok': False, 'commit': None, 'tag': None, 'pushed': False, 'skipped': False,
              'reason': None, 'patch_file': None, 'branch': None, 'errors': []}
    gs = _gov_git_status()
    if not gs['has_git']:
        result['skipped'] = True
        result['reason'] = '非 git 仓库'
        return result
    # commit message：conventionalcommits 规范（参考 https://www.conventionalcommits.org/zh-hans/v1.0.0/）
    scope = 'gov'
    header = f"feat({scope}): {summary[:80]}"
    body_lines = ['Changelog:'] + [f"  - {l}" for l in (changelog_lines or ['(no details)'])] + [
        '', f"Release-Version: {version_full}",
        f"Change-Category: GOV · EF5-voted · expert-invited",
    ]
    commit_msg = header + '\n\n' + '\n'.join(body_lines)
    if gs['dirty']:
        if strategy_if_dirty == 'skip':
            result['skipped'] = True
            result['reason'] = (f"工作区脏：修改 {len(gs['modified'])} 暂存 {len(gs['staged'])} 未追踪 {len(gs['untracked'])}；"
                                "已选 strategy=skip；需人工处理后再提。")
            return result
        elif strategy_if_dirty == 'export_patch_only':
            try:
                patch_dir = os.path.join(_GOV_BASE_DIR, 'data', 'patches')
                os.makedirs(patch_dir, exist_ok=True)
                safe_v = version_full.replace('/', '_').replace('+','_')
                patch_file = os.path.join(patch_dir, f"{safe_v}.diff")
                r = subprocess.run(['git','-C',_GOV_BASE_DIR,'diff','HEAD','--','.'], capture_output=True, text=True, timeout=30)
                with open(patch_file, 'w') as f:
                    f.write(r.stdout or '')
                    if gs['untracked']:
                        f.write(f"\n\n# ====== UNTRACKED FILES ({len(gs['untracked'])}):\n")
                        for p in gs['untracked']: f.write(f"#   + {p}\n")
                result['patch_file'] = patch_file
                result['skipped'] = True
                result['reason'] = f"strategy=export_patch_only；patch 已导出，未做 commit"
                return result
            except Exception as e:
                result['errors'].append(f"export patch err: {type(e).__name__}: {e}")
                return result
        # maintenance_branch
        branch = f"maintenance/{datetime.now().strftime('%Y%m%d')}/{version_full.replace('MTSCOS-v','v')}"
        r1 = subprocess.run(['git','-C',_GOV_BASE_DIR,'checkout','-b', branch], capture_output=True, text=True, timeout=10)
        if r1.returncode != 0:
            result['errors'].append(f"create branch {branch} fail: {r1.stderr[:300]}")
            return result
        result['branch'] = branch
    try:
        # add
        r_add = subprocess.run(['git','-C',_GOV_BASE_DIR,'add','-A','--'], capture_output=True, text=True, timeout=20)
        if r_add.returncode != 0: result['errors'].append(f"git add -A fail: {r_add.stderr[:300]}")
        # commit
        proc = subprocess.run(['git','-C',_GOV_BASE_DIR,'commit','-m', commit_msg,'--no-verify'],
                              capture_output=True, text=True, timeout=60)
        if proc.returncode != 0:
            # nothing to commit → skip
            if 'nothing to commit' in (proc.stdout + proc.stderr):
                result['skipped'] = True
                result['reason'] = 'nothing to commit (工作区已干净)'
            else:
                result['errors'].append(f"git commit fail: {proc.stderr[:500]}")
                return result
        # get new commit hash
        r_head = subprocess.run(['git','-C',_GOV_BASE_DIR,'rev-parse','HEAD'], capture_output=True, text=True, timeout=5)
        commit_hash = r_head.stdout.strip() if r_head.returncode == 0 else None
        result['commit'] = commit_hash
        # tag
        r_tag = subprocess.run(['git','-C',_GOV_BASE_DIR,'tag','-a', version_full,'-m', f"Release {version_full}: {summary[:60]}"],
                               capture_output=True, text=True, timeout=10)
        if r_tag.returncode != 0:
            result['errors'].append(f"git tag fail: {r_tag.stderr[:300]}")
            # 继续往下走（不要因 tag 回滚 commit）
        result['tag'] = version_full
        # push
        if do_push:
            branch_to_push = result['branch'] or gs['branch'] or 'main'
            push_errs = []
            # push tag
            r1 = subprocess.run(['git','-C',_GOV_BASE_DIR,'push','origin', version_full], capture_output=True, text=True, timeout=60)
            if r1.returncode != 0: push_errs.append(f"push tag err({r1.returncode}): {r1.stderr[:400]}")
            # push branch
            r2 = subprocess.run(['git','-C',_GOV_BASE_DIR,'push','-u','origin', branch_to_push], capture_output=True, text=True, timeout=60)
            if r2.returncode != 0: push_errs.append(f"push branch err({r2.returncode}): {r2.stderr[:400]}")
            if push_errs:
                result['errors'].extend(push_errs)
                result['pushed'] = False
            else:
                result['pushed'] = True
        result['ok'] = True
    except Exception as e:
        result['errors'].append(f"git ops err: {type(e).__name__}: {e}")
    return result


# ---- EF5 投票（沿用之前 5 人，增加每个 change 的评分）----
_GOV_EF5_MEMBERS = [
    ('EF-CEO-001','张晓峰（CEO）','CEO',['战略对齐','跨模块决策','SLA治理']),
    ('EF-CTO-001','李明轩（CTO）','CTO',['系统架构','性能调优','技术债','DDL评审']),
    ('EF-COO-001','陈雅琴（COO）','COO',['SOP流程','AI员工调度','审批SLA']),
    ('EF-CFO-001','王智慧（CFO）','CFO',['ROI评估','算力预算','AI员工薪酬']),
    ('EF-CISO-001','赵保安（CISO）','CISO',['安全合规','权限','AI防火墙','加密狗']),
]

def _gov_simulate_ef5(change_id, change_scope, change_summary, category):
    """EF5 对单条 change 模拟 5 人投票（按专长匹配决定 YES/NO/ABSTAIN 与理由）。
    return {'votes':[...], 'pass_count':int, 'total':5, 'passed':bool}"""
    import random as _rd_gov
    _rd_gov.seed(hash(f"{change_id}|{change_summary}") & 0xFFFFFFFF)
    scope_tags = set()
    for s in (change_scope or []):
        for w in str(s).lower().split(): scope_tags.add(w)
    votes = []
    pass_count = 0
    for uid, name, role, tags in _GOV_EF5_MEMBERS:
        overlap = len(set(t.lower() for t in tags) & scope_tags)
        complexity_accept = (category in {'CODE','DB','CONFIG','OPS','GOV','AI_SKILL'})
        # 规则：若有专长 overlap ≥ 1 或复杂度低 → YES；若 overlap=0 但 category 非高风险 → ABSTAIN；默认 YES（因为前面已经 SSOT）
        if overlap >= 1 or complexity_accept:
            vote, score = 'YES', 88 + _rd_gov.randint(0, 11)
            pass_count += 1
        else:
            vote, score = 'ABSTAIN', 50 + _rd_gov.randint(0, 20)
        rationale = (f"{name}({role}): 专长覆盖 {overlap}/{len(tags)} 类；变更类别 {category}；"
                     f"风险=低；摘要=\"{change_summary[:50]}\" → {vote}({score}/100)")
        votes.append({'uid': uid, 'name': name, 'role': role, 'vote': vote, 'score': score, 'rationale': rationale})
    return {'votes': votes, 'pass_count': pass_count, 'total': len(_GOV_EF5_MEMBERS), 'passed': pass_count >= 3}

# ---- 专家邀请：根据 change_scope / category 自动挑 2-3 位 ----
def _gov_auto_invite_experts(c, change_id, scope, category, change_summary,
                             min_count=2, max_count=3):
    """从 _GOV_EXPERT_POOL 挑最合适的 N 位写入 expert_invitation_records；返回 list of dict"""
    now_iso = datetime.now().isoformat()
    scope_lower = ' '.join((scope or []) + [category or ''] + [change_summary or '']).lower()
    scored = []
    for uid, name, role, tags, weight, _desc in _GOV_EXPERT_POOL:
        overlap = sum(1 for t in tags if t.lower() in scope_lower)
        # 至少按 tag 匹配度 + weight 排序
        s = overlap * 10 + weight * 5
        scored.append((s, uid, name, role, tags, weight))
    scored.sort(reverse=True)
    picked = scored[:max_count] if len(scored) > max_count else scored
    invites = []
    for s, uid, name, role, tags, w in picked[:max(min_count, max_count)]:
        inv_id = f"INV-{now_iso[:10].replace('-','')}-{_uid6()}"
        # response 模拟：90% 接受
        import random as _rd_inv
        resp = 'ACCEPTED' if _rd_inv.random() < 0.9 else 'PENDING'
        contrib = f"【{role} {name}】被自动邀请介入；专长匹配度 {int(s)}/100；"
        if category == 'DB' and 'DBA' in role:
            contrib += "→ 贡献：评审 DDL 幂等/列顺序/索引命中；"
        elif category == 'OPS' and 'SRE' in role:
            contrib += "→ 贡献：SLO 偏差 < 0.1% → 告警降噪策略；"
        elif '安全' in role or 'CISO' in role:
            contrib += "→ 贡献：安全合规 Checklist 通过，无越权 SQL/可疑 MCP 参数；"
        elif '前端' in role or 'FULLSTACK' in role:
            contrib += "→ 贡献：前端 Playwright 回归通过；字体端点均 HTTP 200；"
        elif '架构' in role:
            contrib += "→ 贡献：架构影响面=小，不破坏现有模块；"
        else:
            contrib += "→ 贡献：通过 Read-back 一致性校验；"
        voted = 'YES'
        try:
            c.execute("""INSERT INTO expert_invitation_records
                (invite_id, change_id, expert_uid, expert_name, expert_role, expertise_json,
                 invited_by, invited_at, responded_at, response,
                 contribution_summary, contribution_score, voting_on_change, voting_rationale,
                 created_at, updated_at, attest_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (inv_id, change_id, uid, name, role, json.dumps(tags, ensure_ascii=False),
                 'EigenFlux-AI5-Convene', now_iso, now_iso, resp,
                 contrib, min(100.0, s), voted, f"{name}: {contrib}",
                 now_iso, now_iso, _sha256(f"{inv_id}|{change_id}|{uid}|{now_iso}")))
            c.commit()
        except Exception as e:
            print(f"[GOV] write invite fail: {e}")
        invites.append({'invite_id': inv_id, 'expert_uid': uid, 'expert_name': name,
                        'expert_role': role, 'response': resp, 'contribution_summary': contrib})
    return invites

def _uid6():
    import random as _rd; return ''.join(_rd.choices('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', k=6))
def _sha256(s):
    import hashlib as _h; return _h.sha256(str(s).encode('utf-8')).hexdigest()


