@app.route('/api/governance/meta', methods=['GET'])
def api_gov_meta():
    """返回：治理框架状态（表存在？版本号？git状态？专家池？EF5成员池？）"""
    ok = True
    err = None
    try:
        with _get_conn(APP_DB) as c:
            c.execute("SELECT COUNT(*) FROM mtscos_version_history").fetchone()
            c.execute("SELECT COUNT(*) FROM change_audit_log").fetchone()
            c.execute("SELECT COUNT(*) FROM expert_invitation_records").fetchone()
    except Exception as e:
        ok = False
        err = str(e)
    return jsonify({
        "framework_enabled": ok,
        "framework_error": err,
        "default_approval_flow": _GOV_DEFAULT_APPROVAL_FLOW,
        "version_prefix": _GOV_VERSION_PREFIX,
        "release_channel": _GOV_RELEASE_CHANNEL,
        "ef5_members": [{'uid':u,'name':n,'role':r,'expertise':t} for (u,n,r,t) in _GOV_EF5_MEMBERS],
        "expert_pool": [{'uid':u,'name':n,'role':r,'expertise':t,'weight':w,'desc':d}
                        for (u,n,r,t,w,d) in _GOV_EXPERT_POOL],
        "categories": ['CODE','DB','CONFIG','AI_SKILL','RELEASE','OPS','GOV','SECURITY','FRONTEND'],
        "git": _gov_git_status(),
    })


