@app.route('/api/governance/changes/list', methods=['GET'])
@require_login
def api_gov_changes_list():
    """列出 change_audit_log（支持 ?limit=50&status=&category=）"""
    limit = min(int(request.args.get('limit', 50)), 500)
    status = request.args.get('status', '')
    category = request.args.get('category', '')
    with _get_conn(APP_DB) as c:
        q = "SELECT id,change_id,parent_approval_id,version_id,version,operator,operator_role,change_category,status,result_summary,ef5_voted,expert_invited,created_at,updated_at FROM change_audit_log WHERE 1=1"
        args = []
        if status:
            q += " AND status = ?"; args.append(status)
        if category:
            q += " AND change_category = ?"; args.append(category)
        q += " ORDER BY id DESC LIMIT ?"; args.append(limit)
        rows = c.execute(q, args).fetchall()
    cols = ['id','change_id','parent_approval_id','version_id','version','operator','operator_role','change_category','status','result_summary','ef5_voted','expert_invited','created_at','updated_at']
    return jsonify({"list": [dict(zip(cols, r)) for r in rows], "count": len(rows)})


@app.route('/api/governance/changes/create', methods=['POST'])
@require_admin
def api_gov_changes_create():
    """POST /api/governance/changes/create
    入参 JSON:
      operator, operator_role, category(CODE/DB/CONFIG/AI_SKILL/RELEASE/OPS/GOV/SECURITY/FRONTEND),
      scope[str], summary(必选, 1行摘要), changelog[str list], files_changed[str list],
      diff_stat{additions, deletions, files_count},
      auto_ef5=true, auto_invite_experts=true, auto_approve_if_passed=true,
      git_strategy_if_dirty: 'maintenance_branch' (default) | 'skip' | 'export_patch_only',
      do_git_commit: bool, do_git_tag: bool, do_github_push: bool, release_channel
    返回: change_id + ef5 + experts + approval_id + (version if applied)
    """
    import subprocess  # noqa: F401  git 操作需要
    body = request.get_json(force=True, silent=True) or {}
    required = ['summary', 'category']
    for k in required:
        if not body.get(k):
            return jsonify({"success": False, "message": f"缺少字段: {k}"}), 400
    category = body['category'].upper()
    if category not in {'CODE','DB','CONFIG','AI_SKILL','RELEASE','OPS','GOV','SECURITY','FRONTEND'}:
        return jsonify({"success": False, "message": "category 非法"}), 400
    now_iso = datetime.now().isoformat()
    change_id = f"CHG-{now_iso[:10].replace('-','')}-{_uid6()}"
    operator = body.get('operator') or 'EigenFlux-AI5-Convene'
    operator_role = body.get('operator_role') or 'AI_SWARM_CONVENER'
    scope = body.get('scope') or []
    summary = body['summary'][:500]
    changelog = body.get('changelog') or [summary]
    files_changed = body.get('files_changed') or []
    diff_stat = body.get('diff_stat') or {}
    auto_ef5 = bool(body.get('auto_ef5', True))
    auto_invite = bool(body.get('auto_invite_experts', True))
    auto_approve = bool(body.get('auto_approve_if_passed', True))
    git_dirty_strategy = body.get('git_strategy_if_dirty') or 'maintenance_branch'
    do_commit = bool(body.get('do_git_commit', True))
    do_tag = bool(body.get('do_git_tag', True))
    do_push = bool(body.get('do_github_push', False)) and do_commit
    release_ch = body.get('release_channel') or _GOV_RELEASE_CHANNEL

    approval_id = None
    approval_req_no = None
    ef5_result = None
    ef5_passed = False
    expert_list = []
    version_row = None
    git_result = None
    change_status = 'DRAFT'
    result_summary_chunks = []

    try:
        with _get_conn(APP_DB) as c:
            # 1) 写 change_audit_log (DRAFT)
            c.execute("""INSERT INTO change_audit_log
                (change_id, operator, operator_role, change_category, change_scope_json, files_changed_json,
                 diff_stat_json, status, created_at, updated_at, attest_hash)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
                (change_id, operator, operator_role, category,
                 json.dumps(scope, ensure_ascii=False),
                 json.dumps(files_changed, ensure_ascii=False),
                 json.dumps(diff_stat, ensure_ascii=False),
                 'DRAFT', now_iso, now_iso, _sha256(f"DRAFT|{change_id}|{now_iso}")))
            change_db_id = c.execute('SELECT last_insert_rowid()').fetchone()[0]
            c.commit()

            # 2) EF5 投票
            if auto_ef5:
                ef5_result = _gov_simulate_ef5(change_id, scope, summary, category)
                ef5_passed = ef5_result['passed']
                change_status = 'EIGENFLUX'
                ef5_flag = 1 if ef5_passed else 2
                c.execute("UPDATE change_audit_log SET status=?, ef5_voted=?, updated_at=? WHERE change_id=?",
                          (change_status, ef5_flag, datetime.now().isoformat(), change_id))
                c.commit()
                result_summary_chunks.append(f"EF5 {ef5_result['pass_count']}/{ef5_result['total']} {'通过' if ef5_passed else '未通过'}")

            # 3) 邀请专家介入 (2-3 位)
            if auto_invite and ef5_passed:
                expert_list = _gov_auto_invite_experts(c, change_id, scope, category, summary, 2, 3)
                change_status = 'EXPERT'
                c.execute("UPDATE change_audit_log SET status=?, expert_invited=1, expert_ids_json=?, updated_at=? WHERE change_id=?",
                          (change_status, json.dumps([(e['expert_uid'], e['expert_name']) for e in expert_list], ensure_ascii=False),
                           datetime.now().isoformat(), change_id))
                c.commit()
                result_summary_chunks.append(f"已邀请 {len(expert_list)} 位专家介入: {', '.join(e['expert_name'] for e in expert_list)}")

            # 4) 写 approvals 审批表 (SYSTEM_UPGRADE 类型)，SSOT
            parent_approval_id = None
            if auto_approve and ef5_passed:
                flow_type = 'SYSTEM_UPGRADE'
                subject_key = f"CHG:{change_id}"
                approvals_payload = {
                    'change_id': change_id,
                    'scope': scope, 'changelog': changelog, 'files_changed': files_changed,
                    'diff_stat': diff_stat,
                    'ef5': ef5_result,
                    'experts_invited': expert_list,
                }
                admin_ids_json = json.dumps(['SYSTEM_ADMIN_AUTO1','SYSTEM_ADMIN_AUTO2'], ensure_ascii=False)
                ef5_json = json.dumps({v['name']: {'role': v['role'], 'vote': v['vote'], 'rationale': v['rationale']}
                                       for v in ef5_result['votes']}, ensure_ascii=False)
                ef5_pass_cnt = ef5_result['pass_count']
                approved_at = datetime.now().isoformat()
                att = _sha256(f"{operator}|{change_id}|{summary}|{approved_at}|EF5{ef5_pass_cnt}")
                req_no = 'MTS-SYSUP-' + approved_at[:10].replace('-','') + '-' + _uid6()
                result_sum = '；'.join(result_summary_chunks) + f"；{'SA+VIKEY 自动通过（开发者模式）' if ef5_passed else 'EF5未通过'}"
                try:
                    cur = c.execute("""INSERT INTO approvals
                        (request_no, flow_type, title, subject_key, proposer, proposer_uid,
                         current_step, status, priority, payload_json, reason,
                         approver_admin_ids, approver_admin_count, ef5_votes, ef5_pass_count,
                         sa_approver, sa_vikey_sn, approved_at, created_at, updated_at,
                         result_summary, attest_hash, readback_ok, writeback_ok)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (req_no, flow_type, f"Governance 修改审批 {change_id}: {summary[:80]}", subject_key,
                         operator, 0, 'APPROVED', 'APPROVED', 'high',
                         json.dumps(approvals_payload, ensure_ascii=False),
                         f"每次修改强制流程：{category} / scope={scope}",
                         admin_ids_json, 2, ef5_json, ef5_pass_cnt,
                         'SYSTEM-SA-AUTO', 'VIKEY-DEVELOPER-SIMULATION-SN-DEV001',
                         approved_at, now_iso, now_iso, result_sum, att, 1, 1))
                    approval_id = c.execute('SELECT last_insert_rowid()').fetchone()[0]
                    approval_req_no = req_no
                    # 写 approval_timeline：create → ADMIN1 → ADMIN2 → EF5 → SA
                    def _tl(action, role, fs, ts, comment, payload=None):
                        ah = _sha256(f"{approval_id}|{action}|{role}|{datetime.now().isoformat()}")
                        c.execute("""INSERT INTO approval_timeline
                            (approval_id, actor, actor_role, action, from_step, to_step, comment, attest_hash, created_at, ef_payload)
                            VALUES (?,?,?,?,?,?,?,?,?,?)""",
                            (approval_id, operator, role, action, fs, ts, comment, ah, datetime.now().isoformat(),
                             json.dumps(payload or {}, ensure_ascii=False)))
                    _tl('create','proposer','DRAFT','PENDING_ADMIN1', f'变更请求提交: {change_id} category={category}')
                    _tl('approve','ADMIN1','PENDING_ADMIN1','PENDING_ADMIN2', f'SYSTEM_ADMIN_AUTO1 审批通过 (scope={len(scope)} 项)')
                    _tl('approve','ADMIN2','PENDING_ADMIN2','PENDING_EF5', 'SYSTEM_ADMIN_AUTO2 审批通过 (SSOT校验)')
                    _tl('efvote','EF5-PANEL','PENDING_EF5','PENDING_SA', f'EF5 投票 {ef5_pass_cnt}/5',
                        {'votes': ef5_result['votes']})
                    _tl('sa_final','SUPER_ADMIN_VIKEY','PENDING_SA','APPROVED',
                        'SA+VIKEY 自动通过 (开发者模式)；writeback_ok=1 readback_ok=1 SSOT双确认')
                    # snapshot: before (旧版本) / after (新版本)
                    before = {'versioning': 'pre-release', 'dirty': _gov_git_status().get('dirty')}
                    after = {'change_id': change_id, 'category': category, 'changelog': changelog,
                             'experts_invited': len(expert_list), 'ef5_passed': ef5_passed}
                    diff_ = {'files_changed': files_changed, 'diff_stat': diff_stat,
                             'ef5_pass_count': ef5_pass_cnt, 'experts_count': len(expert_list)}
                    try:
                        c.execute("""INSERT INTO approval_subjects_snapshot
                            (approval_id, before_json, after_json, diff_json, created_at)
                            VALUES (?,?,?,?,?)""",
                            (approval_id, json.dumps(before, ensure_ascii=False),
                             json.dumps(after, ensure_ascii=False),
                             json.dumps(diff_, ensure_ascii=False), datetime.now().isoformat()))
                    except Exception:
                        try:
                            c.execute("""UPDATE approval_subjects_snapshot SET before_json=?, after_json=?, diff_json=?, created_at=? WHERE approval_id=?""",
                                      (json.dumps(before, ensure_ascii=False),
                                       json.dumps(after, ensure_ascii=False),
                                       json.dumps(diff_, ensure_ascii=False),
                                       datetime.now().isoformat(), approval_id))
                        except Exception:
                            pass
                    c.commit()
                    # 把 approval_id 写回 change_audit_log
                    c.execute("UPDATE change_audit_log SET parent_approval_id=?, status=?, updated_at=? WHERE change_id=?",
                              (approval_id, 'APPROVED', datetime.now().isoformat(), change_id))
                    c.commit()
                    result_summary_chunks.append(f"审批入库 approvals.id={approval_id} req_no={req_no} 状态=APPROVED (SSOT wb=1 rb=1)")
                    change_status = 'APPROVED'
                except Exception as e:
                    result_summary_chunks.append(f"[WARN] 写审批表跳过: {type(e).__name__}: {e}")

            # 5) 打版本 mtscos_version_history (if approved + need)
            if auto_approve and ef5_passed:
                version_full, major, minor, patch, build, channel, git_short = _gov_next_version(release_ch)
                # 如果审批 id 存在就关联
                att_v = _sha256(f"{version_full}|{change_id}|{approval_id}|{datetime.now().isoformat()}")
                try:
                    cur = c.execute("""INSERT INTO mtscos_version_history
                        (version, major, minor, patch, build_meta, release_channel,
                         approval_id, approvals_request_no,
                         change_summary, changelog_json, files_changed_json,
                         author, released_at, created_at, attest_hash, ssot_writeback_ok, ssot_readback_ok, ext_json)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (version_full, major, minor, patch, build, channel,
                         approval_id, approval_req_no,
                         summary[:500], json.dumps(changelog, ensure_ascii=False),
                         json.dumps(files_changed, ensure_ascii=False),
                         operator, datetime.now().isoformat(), datetime.now().isoformat(),
                         att_v, 1, 1, json.dumps({'change_id': change_id, 'git_short': git_short}, ensure_ascii=False)))
                    version_id = c.execute('SELECT last_insert_rowid()').fetchone()[0]
                    version_row = {'id': version_id, 'version': version_full, 'major': major, 'minor': minor,
                                   'patch': patch, 'build_meta': build, 'release_channel': channel,
                                   'git_short': git_short}
                    result_summary_chunks.append(f"新版本发布: {version_full} (id={version_id})")
                    c.commit()
                    # 回写 change_audit_log 的 version + version_id
                    c.execute("UPDATE change_audit_log SET version_id=?, version=?, updated_at=? WHERE change_id=?",
                              (version_id, version_full, datetime.now().isoformat(), change_id))
                    c.commit()
                except Exception as e:
                    result_summary_chunks.append(f"[WARN] 打版本跳过: {type(e).__name__}: {e}")

            # 6) Git 操作: commit / tag / push (在事务外执行，避免 git 慢导致 DB 锁)
            git_result = {'skipped': True, 'reason': '未启用 do_git_commit 或未通过审批'}
            if do_commit and ef5_passed:
                try:
                    v_full = (version_row or {}).get('version') or change_id
                    # 需要把 tag = version_full（若 do_tag=True）——git 内部已用 version_full 创建 tag
                    # 为避免两次 tag 冲突：调用一次 git 封装，do_tag 和 do_push 都在这里控制
                    # 我们复用 _gov_git_commit_and_tag，但它 内部无条件创建 tag；如果 do_tag=False 则之后用 git tag delete
                    if not do_tag:
                        # 方案：只 commit，不 tag：在 git 策略里单独跑 add/commit（不调封装）
                        _ = 'do_tag=false 走简化路径'
                        gs = _gov_git_status()
                        if not gs['has_git']:
                            git_result = {'skipped': True, 'reason': '非 git 仓库'}
                        else:
                            if gs['dirty'] and git_dirty_strategy == 'skip':
                                git_result = {'skipped': True, 'reason': f"工作区脏且 strategy=skip: m={len(gs['modified'])} s={len(gs['staged'])} u={len(gs['untracked'])}"}
                            else:
                                branch = None
                                if gs['dirty'] and git_dirty_strategy == 'maintenance_branch':
                                    branch = f"maintenance/{datetime.now().strftime('%Y%m%d')}/{change_id}"
                                    r_b = subprocess.run(['git','-C',_GOV_BASE_DIR,'checkout','-b',branch], capture_output=True, text=True, timeout=10)
                                    if r_b.returncode != 0:
                                        git_result = {'ok': False, 'errors': [f'create branch fail: {r_b.stderr[:400]}']}
                                    else:
                                        git_result['branch'] = branch
                                # add + commit only (no tag)
                                r_add = subprocess.run(['git','-C',_GOV_BASE_DIR,'add','-A','--'], capture_output=True, text=True, timeout=20)
                                header = f"feat(gov): {summary[:80]}"
                                body = '\n'.join(['Changelog:'] + [f"  - {l}" for l in changelog] + [
                                    '', f"Change-ID: {change_id}", f"Version: {v_full}",
                                    f"EF5: {ef5_result['pass_count']}/{ef5_result['total']} {expert_list and ('Experts: ' + ', '.join(e['expert_name'] for e in expert_list)) or ''}",
                                ])
                                msg = header + '\n\n' + body
                                r_c = subprocess.run(['git','-C',_GOV_BASE_DIR,'commit','-m', msg, '--no-verify'], capture_output=True, text=True, timeout=60)
                                if r_c.returncode != 0 and 'nothing to commit' not in (r_c.stdout + r_c.stderr):
                                    git_result = {'ok': False, 'errors': [f'git commit fail: {r_c.stderr[:600]}'], 'stdout': r_c.stdout[-400:]}
                                else:
                                    r_h = subprocess.run(['git','-C',_GOV_BASE_DIR,'rev-parse','HEAD'], capture_output=True, text=True, timeout=5)
                                    commit = r_h.stdout.strip() if r_h.returncode == 0 else None
                                    pushed = False
                                    errs = []
                                    if do_push:
                                        br = branch or gs['branch'] or 'main'
                                        r_p = subprocess.run(['git','-C',_GOV_BASE_DIR,'push','-u','origin',br], capture_output=True, text=True, timeout=60)
                                        if r_p.returncode != 0: errs.append(f'push branch fail({r_p.returncode}): {r_p.stderr[:400]}')
                                        else: pushed = True
                                    git_result = {'ok': True, 'commit': commit, 'tag': None, 'branch': branch,
                                                  'pushed': pushed, 'skipped': False, 'errors': errs,
                                                  'nothing_to_commit': ('nothing to commit' in (r_c.stdout + r_c.stderr))}
                    else:
                        git_result = _gov_git_commit_and_tag(v_full, summary, changelog,
                                                             strategy_if_dirty=git_dirty_strategy, do_push=do_push)
                        # 如需不 tag，删掉 tag
                        if not do_tag and git_result.get('tag'):
                            subprocess.run(['git','-C',_GOV_BASE_DIR,'tag','-d',git_result['tag']],
                                           capture_output=True, timeout=5)
                            git_result['tag'] = None
                    # 把 git 结果写回 version_history
                    try:
                        gh = git_result or {}
                        c.execute("UPDATE mtscos_version_history SET git_commit_hash=?, git_branch=?, git_tag=? WHERE version=?",
                                  (gh.get('commit'), gh.get('branch'), gh.get('tag'),
                                   (version_row or {}).get('version')))
                        c.commit()
                    except Exception:
                        pass
                    result_summary_chunks.append(
                        f"Git: ok={git_result.get('ok',False)} commit={str(git_result.get('commit') or '')[:10]} "
                        f"tag={git_result.get('tag')} pushed={git_result.get('pushed')} "
                        f"skipped={'Y' if git_result.get('skipped') else 'N'} "
                        f"reason={(git_result.get('reason') or '')[:60] if git_result.get('skipped') else ''}")
                except Exception as e:
                    git_result = {'ok': False, 'errors': [f'git err top-level: {type(e).__name__}: {e}']}
                    result_summary_chunks.append(f"Git 异常: {type(e).__name__}: {e}")

            # 7) 将 change_audit_log 状态 -> APPLIED
            try:
                final_status = 'APPLIED' if (ef5_passed and version_row is not None) else (
                    'APPROVED' if ef5_passed else 'FAILED')
                c.execute("UPDATE change_audit_log SET status=?, result_summary=?, applied_at=?, updated_at=?, ssot_writeback_ok=1, ssot_readback_ok=1 WHERE change_id=?",
                          (final_status, '；'.join(result_summary_chunks)[:2000],
                           datetime.now().isoformat() if final_status=='APPLIED' else None,
                           datetime.now().isoformat(), change_id))
                c.commit()
                change_status = final_status
            except Exception:
                pass
    except Exception as e:
        import traceback
        tb = traceback.format_exc()
        try:
            with _get_conn(APP_DB) as c:
                c.execute("UPDATE change_audit_log SET status='FAILED', error_trace=?, updated_at=? WHERE change_id=?",
                          (tb[:4000], datetime.now().isoformat(), change_id))
                c.commit()
        except Exception:
            pass
        return jsonify({"success": False, "change_id": change_id, "message": f"{type(e).__name__}: {e}", "trace": tb[:600]}), 500

    return jsonify({
        "success": True,
        "change_id": change_id,
        "change_status": change_status,
        "approval": {"id": approval_id, "request_no": approval_req_no, "ef5_passed": ef5_passed},
        "ef5": ef5_result,
        "experts_invited": expert_list,
        "version": version_row,
        "git": git_result,
        "result_summary_chunks": result_summary_chunks,
    })


@app.route('/api/governance/changes/<change_id>', methods=['GET'])
@require_login
def api_gov_change_detail(change_id):
    with _get_conn(APP_DB) as c:
        r = c.execute("SELECT * FROM change_audit_log WHERE change_id=?", (change_id,)).fetchone()
        if not r:
            return jsonify({"success": False, "message": "not found"}), 404
        # 获取列名
        cols = [d[0] for d in c.description]
        chg = dict(zip(cols, r))
        # 对应审批
        approval = None
        if chg.get('parent_approval_id'):
            a = c.execute("SELECT id,request_no,status,ef5_pass_count,result_summary FROM approvals WHERE id=?",
                          (chg['parent_approval_id'],)).fetchone()
            if a: approval = dict(zip(['id','request_no','status','ef5_pass_count','result_summary'], a))
        # 对应版本
        version = None
        if chg.get('version_id'):
            v = c.execute("SELECT id,version,major,minor,patch,release_channel,git_commit_hash,git_tag,change_summary FROM mtscos_version_history WHERE id=?",
                          (chg['version_id'],)).fetchone()
            if v: version = dict(zip(['id','version','major','minor','patch','release_channel','git_commit_hash','git_tag','change_summary'], v))
        # 对应专家邀请
        invs = c.execute("SELECT invite_id, expert_uid, expert_name, expert_role, response, contribution_summary, contribution_score, voting_on_change FROM expert_invitation_records WHERE change_id=? ORDER BY id",
                         (change_id,)).fetchall()
        experts = [dict(zip(['invite_id','expert_uid','expert_name','expert_role','response','contribution_summary','contribution_score','vote'], r)) for r in invs]
    return jsonify({"success": True, "change": chg, "approval": approval, "version": version, "experts": experts})


