@app.route('/api/governance/ai_employees/create', methods=['POST'])
@require_admin
def api_gov_ai_emp_create():
    """新建 AI 员工并写入 DB → 建立审批单 → EF5 投票 → 打版本 → git
    入参 JSON:
      employee_name, role_title, department, expertise:[str], skills:[str],
      persona(str 可选), scores{overall/skill/arch/comm} 可选, salary_tokens_per_hour,
      approval_note, link_to_change_id(可选)
    """
    body = request.get_json(force=True, silent=True) or {}
    for k in ['employee_name', 'role_title']:
        if not body.get(k): return jsonify({"success": False, "message": f"缺少 {k}"}), 400
    now_iso = datetime.now().isoformat()
    emp_uid = 'EMP-' + now_iso[:10].replace('-','') + '-' + _uid6()
    expertise = body.get('expertise') or []
    skills = body.get('skills') or []
    persona = (body.get('persona') or f"你是{body['role_title']}「{body['employee_name']}」，专长：{'、'.join(expertise) or '综合'}。")
    scores = body.get('scores') or {}
    overall = float(scores.get('overall', 80.0))
    sk = float(scores.get('skill', 85.0))
    arch = float(scores.get('arch', 75.0))
    comm = float(scores.get('comm', 80.0))
    salary = int(body.get('salary_tokens_per_hour') or 1000)
    dept = body.get('department') or 'Governance-Swarm'
    approval_note = body.get('approval_note') or ''
    onboarded_by = session.get('username') or 'Governance-Swarm'
    scores_dict = {"overall": overall, "skill": sk, "arch": arch, "comm": comm}
    att = _sha256(f"{emp_uid}|{body['employee_name']}|{body['role_title']}|{now_iso}")
    emp_id = None

    # 1) SSOT：先跑迁移确保表存在，再 INSERT（列名完全对齐迁移 DDL）
    try:
        with _get_conn(APP_DB) as c:
            _ensure_core_tables_ensure_on_conn(c)
            cur = c.execute("""INSERT INTO mtscos_ai_employees
                (uid, name, role, dept, expertise_json, skills_json, scores_json,
                 salary_tokens_per_hour, approval_note, onboarded_at, onboarded_by,
                 is_active, status, created_at, updated_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (emp_uid, body['employee_name'], body['role_title'], dept,
                 json.dumps(expertise, ensure_ascii=False),
                 json.dumps(skills, ensure_ascii=False),
                 json.dumps(scores_dict, ensure_ascii=False),
                 salary, approval_note, now_iso, onboarded_by,
                 1, 'active', now_iso, now_iso))
            emp_id = c.execute('SELECT last_insert_rowid()').fetchone()[0]
            c.commit()
    except Exception as e:
        return jsonify({"success": False, "message": f"写入 mtscos_ai_employees 失败: {type(e).__name__}: {e}"}), 500

    # 2) 创建 governance change 审批链（用内部 Flask test_client 复用 /api/governance/changes/create）
    note = body.get('approval_note') or f"新建 AI 员工 {body['employee_name']} 入职 {dept}"
    chg_scope = ['AI员工招聘','Governance-Swarm','专家扩容'] + list(expertise)[:3]
    change_payload = {
        "operator": "Governance-NewHire-API",
        "operator_role": "HR_GOVERNANCE_BOT",
        "category": "GOV",
        "scope": chg_scope,
        "summary": note,
        "changelog": [note,
                      f"姓名: {body['employee_name']}，头衔: {body['role_title']}",
                      f"专长: {expertise}",
                      f"综合评分: {overall}/100 (技能 {sk}，架构 {arch}，沟通 {comm})",
                      f"薪酬: {salary} tokens/hour",
                      f"员工 UID: {emp_uid}"],
        "files_changed": [f"DB:mtscos_ai_employees id={emp_id} uid={emp_uid}"],
        "diff_stat": {"additions": 1, "files_count": 1},
        "auto_ef5": True,
        "auto_invite_experts": True,
        "auto_approve_if_passed": True,
        "git_strategy_if_dirty": body.get('git_strategy_if_dirty') or 'skip',
        "do_git_commit": bool(body.get('do_git_commit', False)),
        "do_git_tag": bool(body.get('do_git_tag', False)),
        "do_github_push": bool(body.get('do_github_push', False)),
        "release_channel": _GOV_RELEASE_CHANNEL,
        "linked_ai_employee_uid": emp_uid,
    }
    gov_resp = {}
    linked_approval_id = None
    try:
        client = app.test_client()
        with client.session_transaction() as s:
            s['user_id'] = 1
            s['uid'] = 1
            s['username'] = session.get('username') or 'Governance-NewHire-API'
            s['role'] = 'super_admin'
            s['logged_in'] = True
            s['_sa_override_from_vikey'] = True
            s['roles'] = json.dumps(['super_admin','admin'])
            s['permissions'] = json.dumps({'admin': True, 'super_admin': True})
        resp = client.post('/api/governance/changes/create', json=change_payload)
        try:
            gov_resp = resp.get_json() or {}
        except Exception:
            gov_resp = {'raw_status': resp.status_code, 'raw_text': (resp.data or b'')[:500].decode('utf-8','ignore')}
    except Exception as e:
        gov_resp = {'error': f"调用治理链失败: {type(e).__name__}: {e}"}
    # 回写 linked_approval_id / linked_change_id
    linked_change_id = None
    try:
        linked_approval_id = (gov_resp.get('approval') or {}).get('id')
        linked_change_id = gov_resp.get('change_id')
        if linked_approval_id or linked_change_id:
            with _get_conn(APP_DB) as c:
                c.execute("UPDATE mtscos_ai_employees SET linked_approval_id=?, linked_change_id=?, updated_at=? WHERE id=?",
                          (linked_approval_id, linked_change_id, datetime.now().isoformat(), emp_id))
                c.commit()
    except Exception:
        pass
    return jsonify({
        "success": True,
        "employee": {"id": emp_id, "uid": emp_uid, "name": body['employee_name'],
                     "role": body['role_title'], "dept": dept,
                     "scores": scores_dict,
                     "salary_tokens_per_hour": salary,
                     "expertise": expertise, "skills": skills, "persona": persona,
                     "onboarded_at": now_iso, "onboarded_by": onboarded_by},
        "linked_approval_id": linked_approval_id,
        "linked_change_id": linked_change_id,
        "governance_chain": gov_resp,
    })


@app.route('/api/governance/ai_employees/list', methods=['GET'])
@require_login
def api_gov_ai_emp_list():
    limit = min(int(request.args.get('limit', 50)), 500)
    active_only = request.args.get('active', '1') == '1'
    with _get_conn(APP_DB) as c:
        _ensure_core_tables_ensure_on_conn(c)
        try:
            cols = ['id','uid','name','role','dept','scores_json','salary','active','onboarded_at','onboarded_by','linked_approval_id','linked_change_id']
            if active_only:
                rows = c.execute("SELECT id,uid,name,role,dept,scores_json,salary_tokens_per_hour,is_active,onboarded_at,onboarded_by,linked_approval_id,linked_change_id FROM mtscos_ai_employees WHERE is_active=1 ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
            else:
                rows = c.execute("SELECT id,uid,name,role,dept,scores_json,salary_tokens_per_hour,is_active,onboarded_at,onboarded_by,linked_approval_id,linked_change_id FROM mtscos_ai_employees ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
            parsed = []
            for r in rows:
                d = dict(zip(cols, r))
                try:
                    sj = json.loads(d.get('scores_json') or '{}')
                    if isinstance(sj, dict):
                        d['score_overall'] = sj.get('overall', 0)
                        d['scores'] = sj
                except Exception:
                    pass
                parsed.append(d)
            return jsonify({"count": len(parsed), "list": parsed, "success": True})
        except Exception as e:
            return jsonify({"success": False, "message": f"查询 mtscos_ai_employees 失败: {type(e).__name__}: {e}"}), 400

# ============================================================================
# v21.1.0 灰度发布系统：3张核心DDL表 + 8API + 自动推进决策器（安全阀优先）
# Experience 1159382：先加审批门控再加执行能力，严禁无审批全量直推
# Experience 118272：所有推进/回滚写入审计表，拿真实DB证据
# ============================================================================
_MT_ADMIN_ROLES_GRAY = {'super_admin','sadmin','admin','teacher_admin','school_admin','ops_admin','release_admin','sa'}

def _gray_ensure_ddl(conn):
    """幂等创建3张灰度发布核心表 + 审计索引"""
    try:
        conn.executescript("""
        CREATE TABLE IF NOT EXISTS release_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            release_id TEXT UNIQUE NOT NULL,                    /* 对外展示用UUID */
            release_name TEXT NOT NULL,                         /* 发版名称 */
            subsystem TEXT DEFAULT 'main',                      /* 子系统ID */
            version_from TEXT, version_to TEXT NOT NULL,
            release_type TEXT DEFAULT 'patch',                  /* patch/minor/major/hotfix */
            status TEXT DEFAULT 'draft',                        /* draft/approved/gray{1..N}/full_rollout/rolled_back/failed */
            gray_stages_json TEXT DEFAULT '[100]',              /* 灰度百分比阶段JSON，例 [5,20,50,100] */
            current_stage INTEGER DEFAULT 0,                    /* 当前阶段索引 */
            current_gray_pct INTEGER DEFAULT 0,                 /* 当前灰度百分比 */
            error_rate_threshold REAL DEFAULT 1.0,              /* 升阶段允许最大错误率% */
            rollback_threshold REAL DEFAULT 5.0,                /* 触发自动回滚错误率% */
            min_stage_seconds INTEGER DEFAULT 1800,             /* 每阶段最短观察时间(s) */
            started_at TEXT, finished_at TEXT,
            approver TEXT, approved_at TEXT,
            operator TEXT NOT NULL DEFAULT 'SYSTEM',
            rollback_reason TEXT, rollback_operator TEXT, rollback_at TEXT,
            detail_json TEXT DEFAULT '{}',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
        CREATE INDEX IF NOT EXISTS idx_rel_status ON release_sessions(status);
        CREATE INDEX IF NOT EXISTS idx_rel_subsystem ON release_sessions(subsystem, created_at);

        CREATE TABLE IF NOT EXISTS release_gray_audit (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            release_id TEXT NOT NULL,
            stage_from INTEGER NOT NULL, pct_from INTEGER NOT NULL,
            stage_to INTEGER NOT NULL, pct_to INTEGER NOT NULL,
            action TEXT NOT NULL,                              /* advance|rollback|full_release|manual_override */
            decision_basis TEXT,                                /* 决策依据 */
            error_rate_pct REAL DEFAULT 0.0, avg_latency_ms REAL, success_rate REAL, login_success_rate REAL,
            total_requests INTEGER DEFAULT 0, total_errors INTEGER DEFAULT 0,
            observed_seconds INTEGER DEFAULT 0,
            operator TEXT NOT NULL DEFAULT 'release_engineer',
            comment TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
        CREATE INDEX IF NOT EXISTS idx_gray_rel ON release_gray_audit(release_id, created_at);

        CREATE TABLE IF NOT EXISTS release_rollback_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            release_id TEXT NOT NULL,
            rollback_from_gray_pct INTEGER, rollback_to_gray_pct INTEGER DEFAULT 0,
            reason TEXT NOT NULL,
            operator TEXT NOT NULL,
            action_taken_json TEXT DEFAULT '{}',                    /* 实际操作记录 */
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
        CREATE INDEX IF NOT EXISTS idx_rb_rel ON release_rollback_logs(release_id);
        """)
        conn.commit()
    except Exception as _ge:
        try: logger.warning(f"[GRAY][DDL] failed: {_ge}")
        except Exception: pass

def _gray_require_admin(f):
    """发布API权限门控：必须登录+管理员/SA白名单"""
    @wraps(f)
    def wrapper(*a, **kw):
        u = _current_user() or {}
        if not u: return _v21_json_resp(ok=False, error='需要登录'), 401
        username = (u.get('username') or '').lower()
        role = (u.get('role') or '').lower()
        is_sa = username == 'wuchenghao15'
        if not is_sa and role not in _MT_ADMIN_ROLES_GRAY:
            return _v21_json_resp(ok=False, error=f'发布操作需要管理员或SA权限,当前role={role}'), 403
        setattr(wrapper, '_operator', username)
        setattr(wrapper, '_is_sa', is_sa)
        return f(*a, **kw)
    return wrapper

def _gray_default_stages_for(release_type):
    """按升级类型返回默认灰度阶段百分比数组（经验1159382：major最保守）"""
    t = (release_type or 'patch').lower()
    if t == 'patch':   return [10, 30, 100]
    if t == 'minor':   return [10, 50, 100]
    if t == 'hotfix':  return [20, 100]
    if t in ('major','release'): return [5, 20, 50, 100]
    return [100]

def _gray_release_engineer_decision(session_row, metrics):
    """发布工程师AI员工：根据阶段+观察时长+错误率决定下一个动作
    返回 {'action':'advance'|'hold'|'rollback', 'reason':'...', 'next_pct':int}
    错误率阈值：error_rate_pct < 1% → advance；1%-5% → hold；>5% → rollback
    """
    import time as _tm
    try:
        stages = json.loads(session_row['gray_stages_json'] or '[]')
    except Exception: stages = [100]
    stage = int(session_row['current_stage'] or 0)
    cur_pct = int(session_row['current_gray_pct'] or 0)
    err = float(metrics.get('error_rate_pct', 0.0) or 0.0)
    obs_sec = int(metrics.get('observed_seconds', 0) or 0)
    min_sec = int(session_row['min_stage_seconds'] or 0)
    rbt = float(session_row['rollback_threshold'] or 5.0)
    ert = float(session_row['error_rate_threshold'] or 1.0)
    # 绝对红线：错误率超回滚阈值 → 立即回滚
    if err >= rbt:
        return {'action':'rollback', 'reason':f'错误率{err:.2f}% ≥ 回滚红线{rbt:.1f}%，触发GRM-001自动回滚','next_pct':0}
    # 未达到最短观察时间 → 等待
    if obs_sec < min_sec and cur_pct > 0 and cur_pct < 100 and stage < len(stages):
        return {'action':'hold', 'reason':f'当前阶段已观察{obs_sec}s < 最短{min_sec}s，需继续观察至{min_sec}s','next_pct':cur_pct}
    # 错误率可接受但还未100% → 推进下阶段
    # Stage语义：stage=当前已完成的阶段下标；cur_pct=0代表尚未开始首阶段
    if err < ert and cur_pct < 100:
        if cur_pct == 0:
            # 首次启动 → 落第一阶（stages[0]，比如5%）
            target_idx = 0
            next_pct = stages[0] if stages else 100
        elif stage < len(stages) - 1:
            target_idx = stage + 1
            next_pct = stages[target_idx]
        else:
            # 最后一阶且100%存在 → 全量
            if 100 in stages or stages[-1] == 100:
                return {'action':'full_release', 'reason':f'最后阶段错误率{err:.2f}% < 阈值{ert:.1f}%，全量发布100%','next_pct':100}
            return {'action':'hold', 'reason':f'已达最后阶段（{cur_pct}%）且未配置100%阶段，保持当前','next_pct':cur_pct}
        return {'action':'advance', 'reason':f'错误率{err:.2f}% < 阈值{ert:.1f}%，观察时长满足，推进到灰度{next_pct}%（stage {stage}→{target_idx}）', 'next_pct':int(next_pct)}
    if cur_pct == 100: return {'action':'hold', 'reason':'已达100%全量，无需继续推进','next_pct':100}
    return {'action':'hold', 'reason':f'错误率{err:.2f}% 位于[{ert:.1f}, {rbt:.1f}]灰区，建议人工介入后再决策；当前保持{cur_pct}%','next_pct':cur_pct}

# ============ 8个灰度发布API ============
# API1 创建发布
@app.route('/api/release/create', methods=['POST'])
@_gray_require_admin
def api_release_create():
    try:
        b = _v21_parse_body()
        name = (b.get('release_name') or '').strip()
        ver_to = (b.get('version_to') or '').strip()
        if not name or not ver_to:
            return _v21_json_resp(ok=False, error='release_name + version_to 必填'), 400
        rtype = (b.get('release_type') or 'patch').lower()
        stages = b.get('gray_stages') or _gray_default_stages_for(rtype)
        import uuid as _uu
        rel_id = 'rel-' + _uu.uuid4().hex[:12]
        operator = getattr(api_release_create, '_operator', 'SYSTEM')
        conn = _get_conn(APP_DB); c = conn.cursor()
        _gray_ensure_ddl(c)
        c.execute("""INSERT INTO release_sessions(release_id,release_name,subsystem,version_from,version_to,release_type,gray_stages_json,current_gray_pct,error_rate_threshold,rollback_threshold,min_stage_seconds,operator,status)
                     VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                  (rel_id, name, (b.get('subsystem') or 'main'), b.get('version_from',''), ver_to, rtype,
                   json.dumps(stages, ensure_ascii=False), 0,
                   float(b.get('error_rate_threshold', 1.0)), float(b.get('rollback_threshold', 5.0)),
                   int(b.get('min_stage_seconds', 1800)), operator, 'approved' if getattr(api_release_create,'_is_sa',False) else 'draft'))
        conn.commit()
        conn.close()
        return _v21_json_resp(ok=True, release_id=rel_id, status='approved' if getattr(api_release_create,'_is_sa',False) else 'draft', gray_stages=stages, next_action='API: /api/release/advance 启动灰度推进')
    except Exception as e:
        logger.warning(f'[RELEASE][CREATE] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

# API2 查询发布状态（含gray%/错误率）
@app.route('/api/release/status/<release_id>', methods=['GET'])
@_gray_require_admin
def api_release_status(release_id):
    try:
        conn = _get_conn(APP_DB); c = conn.cursor()
        _gray_ensure_ddl(c)
        sess = c.execute('SELECT * FROM release_sessions WHERE release_id=?', (release_id,)).fetchone()
        if not sess: return _v21_json_resp(ok=False, error=f'release_id不存在: {release_id}'), 404
        d = dict(sess)
        try: d['gray_stages'] = json.loads(d.get('gray_stages_json') or '[]')
        except Exception: d['gray_stages'] = []
        audits = c.execute('SELECT * FROM release_gray_audit WHERE release_id=? ORDER BY id DESC LIMIT 50', (release_id,)).fetchall()
        rollbacks = c.execute('SELECT * FROM release_rollback_logs WHERE release_id=? ORDER BY id DESC LIMIT 20', (release_id,)).fetchall()
        conn.close()
        return _v21_json_resp(ok=True, session=d, audits=[dict(r) for r in audits], rollbacks=[dict(r) for r in rollbacks])
    except Exception as e:
        logger.warning(f'[RELEASE][STATUS] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

# API3 推进灰度阶段（含AI决策）
@app.route('/api/release/advance/<release_id>', methods=['POST'])
@_gray_require_admin
def api_release_advance(release_id):
    try:
        b = _v21_parse_body()
        metrics = b.get('metrics') or {}
        operator = getattr(api_release_advance, '_operator', 'SYSTEM')
        is_sa = getattr(api_release_advance, '_is_sa', False)
        conn = _get_conn(APP_DB); c = conn.cursor(); _gray_ensure_ddl(c)
        sess = c.execute('SELECT * FROM release_sessions WHERE release_id=?', (release_id,)).fetchone()
        if not sess: return _v21_json_resp(ok=False, error=f'release_id不存在: {release_id}'), 404
        s = dict(sess)
        if s['status'] in ('rolled_back','failed'):
            return _v21_json_resp(ok=False, error=f'当前状态{s["status"]}不可推进，先/api/release/rollback或创建新发布'), 400
        if s['status'] == 'draft' and not is_sa:
            return _v21_json_resp(ok=False, error='草稿状态需先审批（由SA/管理员POST /api/release/approve）'), 403
        # 决策：若显式指定override_pct → 人工推进；否则调用发布工程师决策
        override_pct = b.get('override_pct')
        if override_pct is not None:
            decision = {'action':'advance' if override_pct > s['current_gray_pct'] else 'hold', 'reason':f'MANUAL OVERRIDE by {operator}', 'next_pct': int(override_pct)}
        else:
            decision = _gray_release_engineer_decision(s, metrics)
        action = decision['action']; next_pct = decision['next_pct']; reason = decision['reason']
        stages = json.loads(s.get('gray_stages_json') or '[]')
        # 根据动作更新状态
        if action == 'rollback':
            c.execute("UPDATE release_sessions SET status='rolled_back', current_gray_pct=0, rollback_reason=?, rollback_operator=?, rollback_at=CURRENT_TIMESTAMP, updated_at=CURRENT_TIMESTAMP WHERE release_id=?",
                      (reason, operator, release_id))
            c.execute("INSERT INTO release_rollback_logs(release_id,rollback_from_gray_pct,rollback_to_gray_pct,reason,operator,action_taken_json) VALUES(?,?,?,?,?,?)",
                      (release_id, s['current_gray_pct'], 0, reason, operator, json.dumps({'decision':decision,'metrics':metrics}, ensure_ascii=False)))
            new_status, new_stage, new_pct = 'rolled_back', 0, 0
        elif action == 'full_release' or next_pct == 100:
            new_stage = max(0, max([i for i,p in enumerate(stages) if p <= 100], default=len(stages)-1))
            new_pct = 100; new_status = 'full_rollout'
            c.execute("UPDATE release_sessions SET status='full_rollout', current_stage=?, current_gray_pct=100, finished_at=CURRENT_TIMESTAMP, updated_at=CURRENT_TIMESTAMP WHERE release_id=?",
                      (new_stage, release_id))
        elif action == 'hold':
            new_stage = s['current_stage']; new_pct = s['current_gray_pct']; new_status = s['status'] or 'in_gray'
        else:  # advance
            # 找到next_pct在stages中的索引
            try: new_stage = stages.index(next_pct)
            except Exception: new_stage = min(s['current_stage'] + 1, len(stages) - 1)
            new_pct = next_pct; new_status = f'gray{new_stage+1}'
            c.execute("UPDATE release_sessions SET status=?, current_stage=?, current_gray_pct=?, updated_at=CURRENT_TIMESTAMP, started_at=COALESCE(started_at, CURRENT_TIMESTAMP) WHERE release_id=?",
                      (new_status, new_stage, new_pct, release_id))
        # 审计写入
        c.execute("""INSERT INTO release_gray_audit(release_id,stage_from,pct_from,stage_to,pct_to,action,decision_basis,error_rate_pct,avg_latency_ms,success_rate,login_success_rate,total_requests,total_errors,observed_seconds,operator,comment)
                     VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                  (release_id, s['current_stage'], s['current_gray_pct'], new_stage, new_pct, action, reason,
                   float(metrics.get('error_rate_pct',0) or 0), float(metrics.get('avg_latency_ms',0) or 0),
                   float(metrics.get('success_rate',100) or 100), float(metrics.get('login_success_rate',100) or 100),
                   int(metrics.get('total_requests',0) or 0), int(metrics.get('total_errors',0) or 0),
                   int(metrics.get('observed_seconds',0) or 0), operator, b.get('comment','')))
        conn.commit(); conn.close()
        return _v21_json_resp(ok=True, action=action, next_gray_pct=new_pct, new_status=new_status, reason=reason, decision_engine='release_engineer v1.0')
    except Exception as e:
        logger.warning(f'[RELEASE][ADVANCE] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

