# API5 回滚（安全红线：非管理员+SA）
@app.route('/api/release/rollback/<release_id>', methods=['POST'])
@_gray_require_admin
def api_release_rollback(release_id):
    try:
        b = _v21_parse_body()
        operator = getattr(api_release_rollback, '_operator', 'SYSTEM')
        reason = (b.get('reason') or '手动触发回滚').strip()[:500]
        conn = _get_conn(APP_DB); c = conn.cursor(); _gray_ensure_ddl(c)
        sess = c.execute('SELECT * FROM release_sessions WHERE release_id=?', (release_id,)).fetchone()
        if not sess: return _v21_json_resp(ok=False, error=f'release_id不存在: {release_id}'), 404
        s = dict(sess)
        c.execute("UPDATE release_sessions SET status='rolled_back', current_gray_pct=0, rollback_reason=?, rollback_operator=?, rollback_at=CURRENT_TIMESTAMP, updated_at=CURRENT_TIMESTAMP WHERE release_id=?",
                  (reason, operator, release_id))
        c.execute("INSERT INTO release_rollback_logs(release_id,rollback_from_gray_pct,rollback_to_gray_pct,reason,operator,action_taken_json) VALUES(?,?,?,?,?,?)",
                  (release_id, s['current_gray_pct'], 0, reason, operator, json.dumps({'manual':True,'trigger':'user'}, ensure_ascii=False)))
        c.execute("""INSERT INTO release_gray_audit(release_id,stage_from,pct_from,stage_to,pct_to,action,decision_basis,operator,comment)
                     VALUES(?,?,?,?,?,?,?,?,?)""",
                  (release_id, s['current_stage'], s['current_gray_pct'], 0, 0, 'rollback', f'MANUAL ROLLBACK by {operator}: {reason}', operator, reason))
        conn.commit(); conn.close()
        return _v21_json_resp(ok=True, release_id=release_id, new_status='rolled_back', rollback_pct_to=0, operator=operator)
    except Exception as e:
        logger.warning(f'[RELEASE][ROLLBACK] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

# API6 流量监控指标写入（供前端仪表盘调用，同时可被推进API读取）
@app.route('/api/release/metrics/<release_id>', methods=['POST'])
@_gray_require_admin
def api_release_metrics(release_id):
    try:
        b = _v21_parse_body()
        # 先写入审计，供advance下次决策使用（保留最近一条）
        conn = _get_conn(APP_DB); c = conn.cursor(); _gray_ensure_ddl(c)
        sess = c.execute('SELECT current_stage,current_gray_pct FROM release_sessions WHERE release_id=?', (release_id,)).fetchone()
        if not sess: return _v21_json_resp(ok=False, error=f'release_id不存在: {release_id}'), 404
        c.execute("""INSERT INTO release_gray_audit(release_id,stage_from,pct_from,stage_to,pct_to,action,decision_basis,error_rate_pct,avg_latency_ms,success_rate,login_success_rate,total_requests,total_errors,observed_seconds,operator)
                     VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                  (release_id, sess['current_stage'], sess['current_gray_pct'], sess['current_stage'], sess['current_gray_pct'],
                   'metrics_report', 'metrics snapshot',
                   float(b.get('error_rate_pct',0) or 0), float(b.get('avg_latency_ms',0) or 0),
                   float(b.get('success_rate',100) or 100), float(b.get('login_success_rate',100) or 100),
                   int(b.get('total_requests',0) or 0), int(b.get('total_errors',0) or 0),
                   int(b.get('observed_seconds',0) or 0), getattr(api_release_metrics,'_operator','SYSTEM')))
        decision = _gray_release_engineer_decision(
            {'current_stage': sess['current_stage'], 'current_gray_pct': sess['current_gray_pct'],
             'gray_stages_json': c.execute('SELECT gray_stages_json FROM release_sessions WHERE release_id=?',(release_id,)).fetchone()[0],
             'error_rate_threshold': float(b.get('error_rate_threshold',1.0)),
             'rollback_threshold': float(b.get('rollback_threshold',5.0)),
             'min_stage_seconds': int(b.get('min_stage_seconds',1800))}, b)
        conn.commit(); conn.close()
        return _v21_json_resp(ok=True, metrics_saved=True, recommended_next=decision)
    except Exception as e:
        logger.warning(f'[RELEASE][METRICS] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

# API7 发布历史列表（分页）
@app.route('/api/release/list', methods=['GET'])
@_gray_require_admin
def api_release_list():
    try:
        page = _v21_qs_int('page', 1); size = min(_v21_qs_int('size', 50), 500)
        off = max(0, (page - 1) * size)
        status = request.args.get('status') or ''
        sql, args = "SELECT * FROM release_sessions WHERE 1=1", []
        if status:
            sql += " AND status=?"; args.append(status)
        sql += " ORDER BY id DESC LIMIT ? OFFSET ?"; args += [size, off]
        conn = _get_conn(APP_DB); c = conn.cursor(); _gray_ensure_ddl(c)
        total = c.execute("SELECT COUNT(*) FROM release_sessions").fetchone()[0]
        rows = c.execute(sql, args).fetchall()
        data = []
        for r in rows:
            d = dict(r)
            try: d['gray_stages'] = json.loads(d.get('gray_stages_json') or '[]')
            except Exception: d['gray_stages'] = []
            data.append(d)
        conn.close()
        return _v21_json_resp(ok=True, list=data, total=total, page=page, size=size)
    except Exception as e:
        logger.warning(f'[RELEASE][LIST] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

# API8 审批（管理员/SA批准草稿→可推进）
@app.route('/api/release/approve/<release_id>', methods=['POST'])
@_gray_require_admin
def api_release_approve(release_id):
    try:
        b = _v21_parse_body()
        operator = getattr(api_release_approve, '_operator', 'SYSTEM')
        conn = _get_conn(APP_DB); c = conn.cursor(); _gray_ensure_ddl(c)
        row = c.execute("SELECT status FROM release_sessions WHERE release_id=?", (release_id,)).fetchone()
        if not row: return _v21_json_resp(ok=False, error=f'release_id不存在: {release_id}'), 404
        if row['status'] != 'draft':
            return _v21_json_resp(ok=False, error=f'当前状态={row["status"]}，仅draft可审批'), 400
        comment = (b.get('comment') or '').strip()
        c.execute("UPDATE release_sessions SET status='approved', approver=?, approved_at=CURRENT_TIMESTAMP, detail_json=JSON_SET(COALESCE(detail_json,'{}'), '$.approval_comment', ?), updated_at=CURRENT_TIMESTAMP WHERE release_id=?",
                  (operator, comment, release_id))
        conn.commit(); conn.close()
        return _v21_json_resp(ok=True, release_id=release_id, new_status='approved', approver=operator, next_action='/api/release/advance/{id} 启动灰度推进')
    except Exception as e:
        logger.warning(f'[RELEASE][APPROVE] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500




