def _ssl_get_current_user():
    """从session获取当前登录用户，返回 (user_id, username, role) 或 (None, None, None)"""
    try:
        uid = session.get('user_id') or session.get('uid')
        uname = session.get('username') or session.get('user')
        role = session.get('role') or session.get('user_role')
        if not uid and uname:
            with _get_conn(APP_DB) as c:
                row = c.execute("SELECT id, role FROM users WHERE username=?", (uname,)).fetchone()
                if row:
                    uid, role = row[0], row[1]
        return uid, uname, role
    except Exception:
        return None, None, None


@app.route('/api/ssl_cert/bind', methods=['POST'])
def api_ssl_cert_bind():
    """用户补绑SSL证书（历史用户宽限期内补绑）"""
    uid, uname, role = _ssl_get_current_user()
    if not uid or not uname:
        return jsonify({'success': False, 'error': '未登录'}), 401
    try:
        b = _v21_parse_body() if '_v21_parse_body' in dir() else (request.get_json(force=True, silent=True) or {})
        fp = (b.get('ssl_fingerprint') or '').strip()
        cert_pem = b.get('ssl_cert_pem') or ''
        is_primary = bool(b.get('is_primary', True))
        if not fp:
            return jsonify({'success': False, 'code': 'SSL_FP_REQUIRED', 'message': 'SSL证书指纹必填'}), 400
        _ok_fmt, _reason_fmt = _verify_ssl_fingerprint(fp, request.remote_addr or '', request.headers.get('User-Agent', ''), uname)
        if not _ok_fmt:
            return jsonify({'success': False, 'code': 'SSL_FP_INVALID', 'message': f'指纹格式无效：{_reason_fmt}'}), 400
        bind_id = _bind_user_ssl_cert(uid, uname, fp, cert_pem=cert_pem, ip=request.remote_addr, is_primary=is_primary)
        if not bind_id:
            return jsonify({'success': False, 'code': 'SSL_BIND_LIMIT_EXCEEDED', 'message': '绑定数量超过上限(3个)或绑定失败'}), 400
        return jsonify({'success': True, 'binding_id': bind_id, 'message': 'SSL证书绑定成功'})
    except Exception as e:
        logger.warning(f'[SSL_CERT][bind] err: {e}')
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/ssl_cert/revoke/<binding_id>', methods=['POST'])
def api_ssl_cert_revoke(binding_id):
    """吊销SSL证书（需双审批+EigenFlux磋商，此处先记录吊销动作）"""
    uid, uname, role = _ssl_get_current_user()
    if not uid or not uname:
        return jsonify({'success': False, 'error': '未登录'}), 401
    try:
        b = _v21_parse_body() if '_v21_parse_body' in dir() else (request.get_json(force=True, silent=True) or {})
        reason = (b.get('reason') or '用户主动吊销').strip()
        # 检查权限：用户只能吊销自己的证书，管理员可吊销任何证书
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            row = c.execute("SELECT user_id FROM user_ssl_cert_bindings WHERE binding_id=?", (binding_id,)).fetchone()
            if not row:
                return jsonify({'success': False, 'error': '绑定记录不存在'}), 404
            if row[0] != uid and (role or '') not in ('admin', 'sadmin', 'super_admin'):
                return jsonify({'success': False, 'error': '无权吊销他人证书'}), 403
        ok = _revoke_ssl_cert(binding_id, uname, reason)
        if ok:
            return jsonify({'success': True, 'message': 'SSL证书已吊销', 'binding_id': binding_id})
        return jsonify({'success': False, 'error': '吊销失败'}), 500
    except Exception as e:
        logger.warning(f'[SSL_CERT][revoke] err: {e}')
        return jsonify({'success': False, 'error': str(e)}), 500


