@app.route('/api/ssl_cert/approve/<binding_id>', methods=['POST'])
@system_container('ssl_cert_approve', require_auth='admin')
def api_ssl_cert_approve(binding_id):
    """备案管理员/超级管理员审批SSL证书绑定"""
    uid, uname, role = _ssl_get_current_user()
    if not uid or not uname:
        return jsonify({'success': False, 'error': '未登录'}), 401
    if (role or '') not in ('admin', 'sadmin', 'super_admin'):
        return jsonify({'success': False, 'error': '需要管理员权限'}), 403
    try:
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            row = c.execute("SELECT approved_by_hardware_admin, approved_by_super_admin FROM user_ssl_cert_bindings WHERE binding_id=?", (binding_id,)).fetchone()
            if not row:
                return jsonify({'success': False, 'error': '绑定记录不存在'}), 404
            # 双审批逻辑：硬件管理员先审批，超级管理员终审
            if (role or '') in ('super_admin', 'sadmin'):
                c.execute("UPDATE user_ssl_cert_bindings SET approved_by_super_admin=?, approved_at_super_admin=? WHERE binding_id=?", (uname, now, binding_id))
            else:
                c.execute("UPDATE user_ssl_cert_bindings SET approved_by_hardware_admin=?, approved_at_hardware_admin=? WHERE binding_id=?", (uname, now, binding_id))
            c.commit()
        return jsonify({'success': True, 'message': '审批成功', 'binding_id': binding_id, 'approver': uname, 'role': role})
    except Exception as e:
        logger.warning(f'[SSL_CERT][approve] err: {e}')
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/ssl_cert/grace_status', methods=['GET'])
def api_ssl_cert_grace_status():
    """查询当前用户SSL宽限期状态"""
    uid, uname, role = _ssl_get_current_user()
    if not uid or not uname:
        return jsonify({'success': False, 'error': '未登录'}), 401
    try:
        with _get_conn(APP_DB) as c:
            _ensure_ssl_binding_schema(c)
            row = c.execute("SELECT ssl_binding_status, ssl_binding_count, ssl_grace_period_until FROM users WHERE id=?", (uid,)).fetchone()
        if not row:
            return jsonify({'success': False, 'error': '用户不存在'}), 404
        status, count, grace_until = row[0] or 'unbound', row[1] or 0, row[2]
        in_grace = False
        if status != 'bound' and grace_until:
            in_grace = grace_until > datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        return jsonify({
            'success': True,
            'binding_status': status,
            'binding_count': count,
            'grace_period_until': grace_until,
            'in_grace_period': in_grace,
            'needs_binding': status != 'bound',
        })
    except Exception as e:
        logger.warning(f'[SSL_CERT][grace_status] err: {e}')
        return jsonify({'success': False, 'error': str(e)}), 500


