# [8大功能模块扩展 V3.0]
#   1) 系统自动巡检题库更新  2) 课件更新管理  3) 教辅对齐  4) 科目适配
#   5) 课程完善  6) 教师课程丰富化  7) 题目不过时实施跟进  8) 成人课题开发
# - 所有DDL持久化到 DATABASE_PATH（=APP_DB，可写、真实存在）
# - 查询统一参数化占位符 ?，返回 {ok, data, message}
# - 所有API使用 @system_container 装饰器
# ============================================================================

DATABASE_PATH = APP_DB  # 业务模块统一数据库路径（全局变量）

def _mtscos_now():
    """统一时间戳字符串"""
    return datetime.now().strftime('%Y-%m-%d %H:%M:%S')


# ============================================================
# 模块1: 系统自动巡检题库更新
# ============================================================

def _ensure_qbank_inspection_ddls():
    """确保题库巡检相关表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS question_bank_inspection_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                inspection_type TEXT DEFAULT 'full',
                subject TEXT,
                total_questions INTEGER DEFAULT 0,
                outdated_count INTEGER DEFAULT 0,
                duplicate_count INTEGER DEFAULT 0,
                quality_score REAL DEFAULT 0,
                issues_json TEXT,
                recommendations_json TEXT,
                inspected_by TEXT,
                inspected_at TEXT,
                status TEXT DEFAULT 'completed'
            );
            CREATE TABLE IF NOT EXISTS question_freshness_tracker (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                question_id INTEGER,
                subject TEXT,
                last_updated TEXT,
                freshness_score REAL DEFAULT 100,
                is_outdated INTEGER DEFAULT 0,
                outdated_reason TEXT,
                last_verified TEXT,
                reviewer TEXT,
                status TEXT DEFAULT 'active'
            );
            CREATE INDEX IF NOT EXISTS idx_qbi_subject ON question_bank_inspection_logs(subject);
            CREATE INDEX IF NOT EXISTS idx_qft_qid ON question_freshness_tracker(question_id);
            CREATE INDEX IF NOT EXISTS idx_qft_outdated ON question_freshness_tracker(is_outdated);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[qbank_inspection][ddl] err: {e}')

def _qbank_find_question_tables():
    """跨库扫描题目表，返回 [(db_path, table_name, columns_set), ...]
    优先匹配 k12_questions / questions / question_bank 等真实表"""
    out = []
    candidates = _real_db_candidates('question', 'exam', 'app', 'mtscos', 'ai')
    seen = set()
    for p in candidates:
        if not p or not os.path.exists(p) or p in seen:
            continue
        seen.add(p)
        try:
            with _get_conn(p) as c:
                tnames = c.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
                ).fetchall()
                for (tn,) in tnames:
                    ltn = (tn or '').lower()
                    if ltn in ('k12_questions', 'questions', 'question_bank', 'question') or \
                       (ltn.startswith('question') and 'bank' in ltn):
                        try:
                            cols = {r[1] for r in c.execute(f'PRAGMA table_info("{tn}")').fetchall()}
                            out.append((p, tn, cols))
                        except Exception:
                            out.append((p, tn, set()))
        except Exception:
            pass
    return out

def _qbank_scan_outdated(rows, cols):
    """扫描过期题目（last_updated/updated_at/created_at 超过365天）"""
    outdated = []
    cutoff = (datetime.now() - timedelta(days=365)).strftime('%Y-%m-%d %H:%M:%S')
    date_col = None
    for cand in ('last_updated', 'updated_at', 'update_time', 'modify_time', 'created_at', 'create_time'):
        if cand in cols:
            date_col = cand
            break
    if not date_col:
        return outdated, date_col
    for r in rows:
        v = r.get(date_col)
        if not v:
            continue
        try:
            sv = str(v)[:19]
            if sv < cutoff:
                outdated.append(r)
        except Exception:
            pass
    return outdated, date_col

def _qbank_scan_duplicates(rows, cols):
    """扫描重复题目（相同 subject + question_content/content/stem）"""
    subj_col = next((c for c in ('subject', 'subject_name', 'course') if c in cols), None)
    cont_col = next((c for c in ('question_content', 'content', 'stem', 'question_text', 'title', 'question') if c in cols), None)
    if not cont_col:
        return [], subj_col, cont_col
    groups = {}
    for r in rows:
        s = str(r.get(subj_col) or '').strip().lower() if subj_col else ''
        c = str(r.get(cont_col) or '').strip().lower()
        if not c:
            continue
        key = (s, c)
        groups.setdefault(key, []).append(r)
    dups = []
    for k, items in groups.items():
        if len(items) > 1:
            dups.extend(items[1:])  # 留一份，其余标记为重复
    return dups, subj_col, cont_col

def _qbank_compute_quality(rows, cols):
    """计算题库质量评分（基于answer完整性、解析完整性、去重率）"""
    total = len(rows)
    if total == 0:
        return 0.0, {}
    ans_col = next((c for c in ('answer', 'correct_answer', 'right_answer', 'ans') if c in cols), None)
    ana_col = next((c for c in ('analysis', 'explanation', 'explain', '解析', 'analyze') if c in cols), None)
    ans_ok = sum(1 for r in rows if r.get(ans_col)) if ans_col else 0
    ana_ok = sum(1 for r in rows if r.get(ana_col)) if ana_col else 0
    ans_rate = ans_ok / total if ans_col else 0
    ana_rate = ana_ok / total if ana_col else 0
    dup_count = len(_qbank_scan_duplicates(rows, cols)[0])
    dedup_rate = max(0.0, 1.0 - dup_count / total)
    # 质量评分 = answer完整性(50%) + 解析完整性(30%) + 去重率(20%)
    score = round((ans_rate * 0.5 + ana_rate * 0.3 + dedup_rate * 0.2) * 100, 2)
    return score, {
        'answer_complete_rate': round(ans_rate, 4),
        'analysis_complete_rate': round(ana_rate, 4),
        'dedup_rate': round(dedup_rate, 4),
        'answer_column': ans_col,
        'analysis_column': ana_col,
    }

@app.route('/api/qbank/inspection/run', methods=['GET'])
@system_container('qbank_inspection_run', require_auth='admin')
def api_qbank_inspection_run():
    """执行题库巡检：扫描过期题目、重复题目、质量评分"""
    _ensure_qbank_inspection_ddls()
    user = _current_safe_user()
    try:
        tables = _qbank_find_question_tables()
        if not tables:
            return jsonify({'ok': False, 'data': None, 'message': '未找到题目表(k12_questions/questions)'}), 404
        all_issues = []
        all_recs = []
        per_subject_stats = {}
        total_q = 0
        total_outdated = 0
        total_dup = 0
        all_rows_for_quality = []
        all_cols = set()
        for db_path, tname, cols in tables:
            all_cols |= cols
            try:
                rows = _q(db_path, f'SELECT * FROM "{tname}"', (), None)
            except Exception:
                rows = []
            if not rows:
                continue
            total_q += len(rows)
            all_rows_for_quality.extend(rows)
            # 过期扫描
            outdated, date_col = _qbank_scan_outdated(rows, cols)
            total_outdated += len(outdated)
            if outdated:
                all_issues.append({'db': os.path.basename(db_path), 'table': tname,
                                   'type': 'outdated', 'count': len(outdated),
                                   'date_column': date_col})
                all_recs.append(f'[{tname}] {len(outdated)} 道题目已超过365天未更新，建议刷新内容')
            # 重复扫描
            dups, subj_col, cont_col = _qbank_scan_duplicates(rows, cols)
            total_dup += len(dups)
            if dups:
                all_issues.append({'db': os.path.basename(db_path), 'table': tname,
                                   'type': 'duplicate', 'count': len(dups),
                                   'subject_column': subj_col, 'content_column': cont_col})
                all_recs.append(f'[{tname}] 发现 {len(dups)} 道重复题目，建议合并去重')
            # 按科目统计
            if subj_col:
                for r in rows:
                    s = str(r.get(subj_col) or '未分类')
                    per_subject_stats.setdefault(s, {'total': 0, 'outdated': 0, 'duplicate': 0})
                    per_subject_stats[s]['total'] += 1
                for r in outdated:
                    s = str(r.get(subj_col) or '未分类')
                    if s in per_subject_stats:
                        per_subject_stats[s]['outdated'] += 1
            # 写入新鲜度跟踪表
            try:
                with _get_conn(DATABASE_PATH) as c:
                    now = _mtscos_now()
                    for r in outdated:
                        qid = r.get('id') or r.get('question_id') or 0
                        c.execute(
                            "INSERT INTO question_freshness_tracker "
                            "(question_id, subject, last_updated, freshness_score, is_outdated, "
                            "outdated_reason, last_verified, reviewer, status) VALUES (?,?,?,?,?,?,?,?,?)",
                            (qid, str(r.get(subj_col) or ''), str(r.get(date_col) or ''), 30.0, 1,
                             'last_updated超过365天', now, user.get('username') or '', 'outdated')
                        )
                    c.commit()
            except Exception as e:
                logger.warning(f'[qbank_inspection][freshness] err: {e}')
        # 整体质量评分
        quality_score, quality_detail = _qbank_compute_quality(all_rows_for_quality, all_cols)
        if quality_score < 60:
            all_recs.append(f'整体质量评分 {quality_score} 偏低，建议补充答案与解析')
        # 写入巡检日志
        log_id = None
        try:
            with _get_conn(DATABASE_PATH) as c:
                cur = c.execute(
                    "INSERT INTO question_bank_inspection_logs "
                    "(inspection_type, subject, total_questions, outdated_count, duplicate_count, "
                    "quality_score, issues_json, recommendations_json, inspected_by, "
                    "inspected_at, status) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                    ('full', 'ALL', total_q, total_outdated, total_dup, quality_score,
                     json.dumps(all_issues, ensure_ascii=False),
                     json.dumps(all_recs, ensure_ascii=False),
                     user.get('username') or 'system', _mtscos_now(), 'completed')
                )
                c.commit()
                log_id = cur.lastrowid
        except Exception as e:
            logger.warning(f'[qbank_inspection][log] err: {e}')
        return jsonify({'ok': True, 'data': {
            'log_id': log_id,
            'scanned_tables': [{'db': os.path.basename(p), 'table': t, 'columns': sorted(cs)}
                               for p, t, cs in tables],
            'total_questions': total_q,
            'outdated_count': total_outdated,
            'duplicate_count': total_dup,
            'quality_score': quality_score,
            'quality_detail': quality_detail,
            'per_subject_stats': per_subject_stats,
            'issues': all_issues,
            'recommendations': all_recs,
            'inspected_by': user.get('username') or 'system',
            'inspected_at': _mtscos_now(),
        }, 'message': f'巡检完成：扫描{total_q}题，过期{total_outdated}，重复{total_dup}，质量评分{quality_score}'})
    except Exception as e:
        logger.warning(f'[qbank_inspection][run] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


