@app.route('/api/qbank/freshness/update', methods=['POST'])
@system_container('qbank_freshness_update', require_auth='admin')
def api_qbank_freshness_update():
    """更新题目新鲜度标记"""
    _ensure_qbank_inspection_ddls()
    data = request.get_json(silent=True) or {}
    qid = data.get('question_id')
    if not qid:
        return jsonify({'ok': False, 'data': None, 'message': '缺少 question_id'}), 400
    user = _current_safe_user()
    try:
        with _get_conn(DATABASE_PATH) as c:
            existing = c.execute(
                "SELECT id FROM question_freshness_tracker WHERE question_id=?", (qid,)
            ).fetchone()
            now = _mtscos_now()
            if existing:
                c.execute(
                    "UPDATE question_freshness_tracker SET subject=?, last_updated=?, "
                    "freshness_score=?, is_outdated=?, outdated_reason=?, last_verified=?, "
                    "reviewer=?, status=? WHERE question_id=?",
                    (data.get('subject', ''), data.get('last_updated', ''),
                     float(data.get('freshness_score', 100)), int(data.get('is_outdated', 0)),
                     data.get('outdated_reason', ''), now,
                     user.get('username') or '', data.get('status', 'active'), qid)
                )
            else:
                c.execute(
                    "INSERT INTO question_freshness_tracker "
                    "(question_id, subject, last_updated, freshness_score, is_outdated, "
                    "outdated_reason, last_verified, reviewer, status) VALUES (?,?,?,?,?,?,?,?,?)",
                    (qid, data.get('subject', ''), data.get('last_updated', ''),
                     float(data.get('freshness_score', 100)), int(data.get('is_outdated', 0)),
                     data.get('outdated_reason', ''), now,
                     user.get('username') or '', data.get('status', 'active'))
                )
            c.commit()
        return jsonify({'ok': True, 'data': {'question_id': qid, 'last_verified': now},
                        'message': '题目新鲜度已更新'})
    except Exception as e:
        logger.warning(f'[qbank_freshness][update] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


