def _ensure_courseware_ddls():
    """确保课件更新管理表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS courseware_updates (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                course_id INTEGER,
                title TEXT,
                update_type TEXT,
                version_from TEXT,
                version_to TEXT,
                change_summary TEXT,
                updated_by TEXT,
                updated_at TEXT,
                status TEXT DEFAULT 'active',
                file_path TEXT,
                file_size INTEGER DEFAULT 0
            );
            CREATE INDEX IF NOT EXISTS idx_cwu_course ON courseware_updates(course_id);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[courseware][ddl] err: {e}')


@app.route('/api/courseware/list', methods=['GET'])
@system_container('courseware_list', require_auth='login')
def api_courseware_list():
    """课件列表（支持按课程/科目筛选）"""
    _ensure_courseware_ddls()
    try:
        course_id = request.args.get('course_id')
        subject = request.args.get('subject')
        limit = int(request.args.get('limit', 100))
        sql = ("SELECT id, course_id, title, update_type, version_from, version_to, "
               "change_summary, updated_by, updated_at, status, file_path, file_size "
               "FROM courseware_updates WHERE 1=1")
        params = []
        if course_id:
            sql += " AND course_id=?"
            params.append(int(course_id))
        if subject:
            sql += " AND title LIKE ?"
            params.append(f'%{subject}%')
        sql += " ORDER BY id DESC LIMIT ?"
        params.append(limit)
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(sql, tuple(params)).fetchall()
        return jsonify({'ok': True, 'data': [dict(r) for r in rows],
                        'message': f'共{len(rows)}条课件记录'})
    except Exception as e:
        logger.warning(f'[courseware][list] err: {e}')
        return jsonify({'ok': False, 'data': [], 'message': str(e)}), 500


@app.route('/api/courseware/update', methods=['POST'])
@system_container('courseware_update', require_auth='admin')
def api_courseware_update():
    """上传/更新课件"""
    _ensure_courseware_ddls()
