@app.route('/api/teaching_aid/gaps/<subject>', methods=['GET'])
@system_container('teaching_aid_gaps', require_auth='login')
def api_teaching_aid_gaps(subject):
    """获取教辅缺口分析"""
    _ensure_teaching_aid_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT id, subject, grade_level, aid_title, aid_type, aligned_chapter, "
                "alignment_score, alignment_status, gaps_json, recommendations "
                "FROM teaching_aid_alignment WHERE subject=? ORDER BY alignment_score ASC",
                (subject,)
            ).fetchall()
        gaps_list = []
        for r in rows:
            d = dict(r)
            try:
                d['gaps'] = json.loads(d.get('gaps_json') or '[]')
            except Exception:
                d['gaps'] = []
            d.pop('gaps_json', None)
            gaps_list.append(d)
        return jsonify({'ok': True, 'data': {
            'subject': subject,
            'total_aids': len(gaps_list),
            'low_score_count': sum(1 for g in gaps_list if float(g.get('alignment_score') or 0) < 60),
            'aids': gaps_list,
        }, 'message': f'科目[{subject}]缺口分析：{len(gaps_list)}本教辅'})
    except Exception as e:
        logger.warning(f'[teaching_aid][gaps] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


