@app.route('/api/course/completion/update', methods=['POST'])
@system_container('course_completion_update', require_auth='admin')
def api_course_completion_update():
    """更新课程完善度"""
    _ensure_course_completion_ddls()
    data = request.get_json(silent=True) or {}
    course_id = data.get('course_id')
    if not course_id:
        return jsonify({'ok': False, 'data': None, 'message': '缺少 course_id'}), 400
    user = _current_safe_user()
    now = _mtscos_now()
    total = int(data.get('total_lessons', 0) or 0)
    completed = int(data.get('completed_lessons', 0) or 0)
    rate = round(completed / total * 100, 2) if total > 0 else 0.0
    missing_json = json.dumps(data.get('missing_topics', []), ensure_ascii=False)
    try:
        with _get_conn(DATABASE_PATH) as c:
            existing = c.execute(
                "SELECT id FROM course_completion_tracker WHERE course_id=? LIMIT 1",
                (int(course_id),)
            ).fetchone()
            if existing:
                eid = existing[0]
                c.execute(
                    "UPDATE course_completion_tracker SET course_title=?, subject=?, "
                    "total_lessons=?, completed_lessons=?, completion_rate=?, "
                    "missing_topics_json=?, quality_score=?, last_reviewed=?, reviewer=?, "
                    "status=?, updated_at=? WHERE id=?",
                    (data.get('course_title', ''), data.get('subject', ''),
                     total, completed, rate, missing_json,
                     float(data.get('quality_score', 0)), now,
                     user.get('username') or '', data.get('status', 'active'), now, eid)
                )
                c.commit()
                return jsonify({'ok': True, 'data': {'id': eid, 'completion_rate': rate, 'updated': True},
                                'message': '课程完善度已更新'})
            cur = c.execute(
                "INSERT INTO course_completion_tracker "
                "(course_id, course_title, subject, total_lessons, completed_lessons, "
                "completion_rate, missing_topics_json, quality_score, last_reviewed, "
                "reviewer, status, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (int(course_id), data.get('course_title', ''), data.get('subject', ''),
                 total, completed, rate, missing_json,
                 float(data.get('quality_score', 0)), now,
                 user.get('username') or '', data.get('status', 'active'), now, now)
            )
            c.commit()
            return jsonify({'ok': True, 'data': {'id': cur.lastrowid, 'completion_rate': rate, 'updated': False},
                            'message': '课程完善度已创建'})
    except Exception as e:
        logger.warning(f'[course_completion][update] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


