@app.route('/api/teacher/enrichment/feedback', methods=['POST'])
@system_container('teacher_enrichment_feedback', require_auth='login')
def api_teacher_enrichment_feedback():
    """提交学生反馈"""
    _ensure_teacher_enrichment_ddls()
    data = request.get_json(silent=True) or {}
    eid = data.get('id')
    if not eid:
        return jsonify({'ok': False, 'data': None, 'message': '缺少 id'}), 400
    user = _current_safe_user()
    now = _mtscos_now()
    feedback = {
        'student': user.get('username') or 'anonymous',
        'rating': data.get('rating', 0),
        'comment': data.get('comment', ''),
        'submitted_at': now,
    }
    try:
        with _get_conn(DATABASE_PATH) as c:
            row = c.execute(
                "SELECT student_feedback_json, effectiveness_score FROM teacher_course_enrichment WHERE id=?",
                (int(eid),)
            ).fetchone()
            if not row:
                return jsonify({'ok': False, 'data': None, 'message': '记录不存在'}), 404
            try:
                existing = json.loads(row[0] or '[]')
            except Exception:
                existing = []
            existing.append(feedback)
            # 重新计算效果评分（平均rating）
            ratings = [float(f.get('rating') or 0) for f in existing if f.get('rating')]
            new_score = round(sum(ratings) / len(ratings), 2) if ratings else float(row[1] or 0)
            c.execute(
                "UPDATE teacher_course_enrichment SET student_feedback_json=?, "
                "effectiveness_score=?, updated_at=? WHERE id=?",
                (json.dumps(existing, ensure_ascii=False), new_score, now, int(eid))
            )
            c.commit()
        return jsonify({'ok': True, 'data': {'id': eid, 'feedback_count': len(existing),
                                             'effectiveness_score': new_score},
                        'message': '反馈已提交'})
    except Exception as e:
        logger.warning(f'[teacher_enrichment][feedback] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


@app.route('/api/teacher/enrichment/effectiveness/<int:teacher_id>', methods=['GET'])
@system_container('teacher_enrichment_effectiveness', require_auth='login')
def api_teacher_enrichment_effectiveness(teacher_id):
    """教师课程丰富化效果分析"""
    _ensure_teacher_enrichment_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT id, course_id, course_title, enrichment_type, enrichment_status, "
                "effectiveness_score, student_feedback_json, created_at, updated_at "
                "FROM teacher_course_enrichment WHERE teacher_id=? ORDER BY id DESC",
                (teacher_id,)
            ).fetchall()
        data = []
        total_score = 0.0
        for r in rows:
            d = dict(r)
            try:
                fb = json.loads(d.get('student_feedback_json') or '[]')
            except Exception:
                fb = []
            d['feedback_count'] = len(fb)
            d.pop('student_feedback_json', None)
            total_score += float(d.get('effectiveness_score') or 0)
            data.append(d)
        avg_score = round(total_score / len(data), 2) if data else 0.0
        return jsonify({'ok': True, 'data': {
            'teacher_id': teacher_id,
            'total_enrichments': len(data),
            'avg_effectiveness_score': avg_score,
            'enrichments': data,
        }, 'message': f'教师{teacher_id}共{len(data)}条丰富化记录'})
    except Exception as e:
        logger.warning(f'[teacher_enrichment][effectiveness] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


