@app.route('/api/qbank/outdated/stats', methods=['GET'])
@system_container('qbank_outdated_stats', require_auth='login')
def api_qbank_outdated_stats():
    """过时题目统计"""
    _ensure_qbank_outdated_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            total = c.execute("SELECT COUNT(*) FROM question_outdated_tracking").fetchone()[0]
            pending = c.execute(
                "SELECT COUNT(*) FROM question_outdated_tracking WHERE action_status='pending'"
            ).fetchone()[0]
            in_progress = c.execute(
                "SELECT COUNT(*) FROM question_outdated_tracking WHERE action_status='in_progress'"
            ).fetchone()[0]
            resolved = c.execute(
                "SELECT COUNT(*) FROM question_outdated_tracking WHERE action_status='resolved'"
            ).fetchone()[0]
            by_subject = c.execute(
                "SELECT subject, COUNT(*) as cnt FROM question_outdated_tracking "
                "GROUP BY subject ORDER BY cnt DESC"
            ).fetchall()
            by_type = c.execute(
                "SELECT outdated_type, COUNT(*) as cnt FROM question_outdated_tracking "
                "GROUP BY outdated_type ORDER BY cnt DESC"
            ).fetchall()
        return jsonify({'ok': True, 'data': {
            'total': total,
            'pending': pending,
            'in_progress': in_progress,
            'resolved': resolved,
            'resolution_rate': round(resolved / total * 100, 2) if total > 0 else 0,
            'by_subject': [{'subject': r[0] or '未分类', 'count': r[1]} for r in by_subject],
            'by_type': [{'outdated_type': r[0] or '未分类', 'count': r[1]} for r in by_type],
        }, 'message': f'过时题目统计：共{total}条'})
    except Exception as e:
        logger.warning(f'[qbank_outdated][stats] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


