def _ensure_navigation_ddls():
    """确保页面导航注册表存在并完成种子初始化"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS page_navigation_registry (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                page_path TEXT UNIQUE NOT NULL,
                page_name TEXT NOT NULL,
                page_category TEXT,
                parent_page TEXT,
                icon_class TEXT,
                sort_order INTEGER DEFAULT 0,
                require_auth TEXT DEFAULT 'login',
                allowed_roles_json TEXT DEFAULT '[]',
                is_active INTEGER DEFAULT 1,
                created_at TEXT,
                updated_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_nav_parent ON page_navigation_registry(parent_page);
            CREATE INDEX IF NOT EXISTS idx_nav_category ON page_navigation_registry(page_category);
            """)
            now = _mtscos_now()
            for seed in NAVIGATION_SEED:
                page_path, page_name, page_category, parent_page, icon_class, sort_order, require_auth, allowed_roles_json = seed
                c.execute(
                    "INSERT OR IGNORE INTO page_navigation_registry"
                    "(page_path,page_name,page_category,parent_page,icon_class,sort_order,require_auth,allowed_roles_json,is_active,created_at,updated_at)"
                    " VALUES (?,?,?,?,?,?,?,?,1,?,?)",
                    (page_path, page_name, page_category, parent_page, icon_class, sort_order, require_auth, allowed_roles_json, now, now)
                )
            c.commit()
    except Exception as e:
        logger.warning(f'[navigation][ddl] err: {e}')


def _nav_load_all():
    """加载全部active导航项（按sort_order）"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT page_path,page_name,page_category,parent_page,icon_class,sort_order,require_auth,allowed_roles_json,is_active "
                "FROM page_navigation_registry WHERE is_active=1 ORDER BY sort_order ASC, id ASC"
            ).fetchall()
        return [dict(r) for r in rows]
    except Exception:
        return []


@app.route('/api/navigation/tree', methods=['GET'])
@system_container('navigation_tree', require_auth='guest')
def api_navigation_tree():
    """获取完整导航树（含parent/children关系）"""
    _ensure_navigation_ddls()
    try:
        items = _nav_load_all()
        by_path = {it['page_path']: dict(it, children=[]) for it in items}
        roots = []
        for it in items:
            node = by_path[it['page_path']]
            parent = it.get('parent_page')
            if parent and parent in by_path:
                by_path[parent]['children'].append(node)
            else:
                roots.append(node)
        return jsonify({'ok': True, 'data': {'roots': roots, 'total': len(items)},
                        'message': f'导航树已生成，共{len(items)}个页面'})
    except Exception as e:
        logger.warning(f'[navigation][tree] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


@app.route('/api/navigation/breadcrumb', methods=['GET'])
@system_container('navigation_breadcrumb', require_auth='guest')
def api_navigation_breadcrumb():
    """获取指定页面的面包屑路径（从根到当前页面）"""
    _ensure_navigation_ddls()
    page = (request.args.get('page') or '').strip()
    if not page:
        return jsonify({'ok': False, 'data': None, 'message': '缺少参数 page'}), 400
    try:
        items = _nav_load_all()
        by_path = {it['page_path']: it for it in items}
        chain = []
        cur = page
        seen = set()
        while cur and cur in by_path and cur not in seen:
            seen.add(cur)
            chain.append(by_path[cur])
            cur = by_path[cur].get('parent_page')
        chain.reverse()
        return jsonify({'ok': True, 'data': {'breadcrumb': chain, 'depth': len(chain)},
                        'message': f'面包屑共{len(chain)}层'})
    except Exception as e:
        logger.warning(f'[navigation][breadcrumb] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


@app.route('/api/navigation/quick_links', methods=['GET'])
@system_container('navigation_quick_links', require_auth='login')
def api_navigation_quick_links():
    """获取当前用户角色的快捷链接"""
    _ensure_navigation_ddls()
    try:
        user = _current_safe_user()
        role = str(user.get('role') or 'guest').lower()
        is_sa = bool(user.get('is_super_admin'))
        logged_in = bool(user.get('logged_in'))
        items = _nav_load_all()
        out = []
        for it in items:
            try:
                roles = json.loads(it.get('allowed_roles_json') or '[]')
            except Exception:
                roles = []
            roles = [str(r).lower() for r in roles]
            req_auth = str(it.get('require_auth') or 'login')
            if roles:
                if is_sa or role in roles:
                    out.append(it)
            else:
                if req_auth == 'guest':
                    out.append(it)
                elif logged_in:
                    out.append(it)
        return jsonify({'ok': True, 'data': {'links': out, 'count': len(out)},
                        'message': f'快捷链接{len(out)}个'})
    except Exception as e:
        logger.warning(f'[navigation][quick_links] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


@app.route('/api/navigation/register', methods=['POST'])
@system_container('navigation_register', require_auth='admin')
def api_navigation_register():
    """注册新页面到导航表"""
    _ensure_navigation_ddls()
    try:
        payload = request.get_json(silent=True) or {}
    except Exception:
        payload = {}
    page_path = (payload.get('page_path') or '').strip()
    page_name = (payload.get('page_name') or '').strip()
    if not page_path or not page_name:
        return jsonify({'ok': False, 'data': None, 'message': 'page_path 与 page_name 必填'}), 400
    try:
        page_category = (payload.get('page_category') or 'custom') or 'custom'
        parent_page = payload.get('parent_page')
        icon_class = payload.get('icon_class') or 'fas fa-link'
        sort_order = int(payload.get('sort_order') or 100)
        require_auth = payload.get('require_auth') or 'login'
        roles = payload.get('allowed_roles') or []
        allowed_roles_json = json.dumps(roles, ensure_ascii=False) if isinstance(roles, list) else str(roles)
        now = _mtscos_now()
        with _get_conn(DATABASE_PATH) as c:
            c.execute(
                "INSERT INTO page_navigation_registry"
                "(page_path,page_name,page_category,parent_page,icon_class,sort_order,require_auth,allowed_roles_json,is_active,created_at,updated_at)"
                " VALUES (?,?,?,?,?,?,?,?,1,?,?)"
                " ON CONFLICT(page_path) DO UPDATE SET page_name=excluded.page_name,parent_page=excluded.parent_page,"
                "icon_class=excluded.icon_class,sort_order=excluded.sort_order,require_auth=excluded.require_auth,"
                "allowed_roles_json=excluded.allowed_roles_json,updated_at=excluded.updated_at,is_active=1",
                (page_path, page_name, page_category, parent_page, icon_class, sort_order, require_auth, allowed_roles_json, now, now)
            )
            c.commit()
        return jsonify({'ok': True, 'data': {'page_path': page_path, 'updated_at': now},
                        'message': '页面已注册到导航表'})
    except Exception as e:
        logger.warning(f'[navigation][register] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


