def _ensure_settings_sync_ddls():
    """确保设置同步队列表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS settings_sync_queue (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                setting_key TEXT NOT NULL,
                setting_value TEXT,
                sync_direction TEXT DEFAULT 'backend_to_db',
                sync_status TEXT DEFAULT 'pending',
                target_components_json TEXT DEFAULT '[]',
                synced_at TEXT,
                error_msg TEXT,
                created_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_sync_key ON settings_sync_queue(setting_key);
            CREATE INDEX IF NOT EXISTS idx_sync_status ON settings_sync_queue(sync_status);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[settings_sync][ddl] err: {e}')


def _settings_sync_attempt(job_id, setting_key, setting_value, direction, components):
    """执行一次同步尝试：写DB + 更新内存缓存。返回 (ok, err_msg)"""
    try:
        if direction in ('backend_to_db', 'frontend_to_backend', 'backend_to_frontend'):
            # 真实落库（设置 SSOT：legal_red_lines）
            if direction in ('backend_to_db', 'frontend_to_backend'):
                _mt_set_config_rule(setting_key, setting_value)
            # 更新内存覆盖层
            with _SETTINGS_SYNC_LOCK:
                _SETTINGS_MEM_CACHE[setting_key] = setting_value
        now = _mtscos_now()
        with _get_conn(DATABASE_PATH) as c:
            c.execute(
                "UPDATE settings_sync_queue SET sync_status='success', synced_at=?, error_msg='' WHERE id=?",
                (now, job_id)
            )
            c.commit()
        return True, ''
    except Exception as e:
        return False, str(e)[:500]


def _settings_enqueue_sync(setting_key, setting_value, direction, components):
    """入队一个同步任务并立即尝试3次重试"""
    now = _mtscos_now()
    comps_json = json.dumps(components or [], ensure_ascii=False)
    try:
        with _get_conn(DATABASE_PATH) as c:
            cur = c.execute(
                "INSERT INTO settings_sync_queue(setting_key,setting_value,sync_direction,sync_status,target_components_json,created_at)"
                " VALUES (?,?,?,?,?,?)",
                (setting_key, str(setting_value), direction, 'pending', comps_json, now)
            )
            job_id = cur.lastrowid
            c.commit()
    except Exception as e:
        logger.warning(f'[settings_sync][enqueue] err: {e}')
        return None
    # 立即尝试3次重试
    ok = False
    last_err = ''
    for attempt in range(3):
        ok, last_err = _settings_sync_attempt(job_id, setting_key, str(setting_value), direction, components or [])
        if ok:
            break
        time.sleep(0.2 * (attempt + 1))
    if not ok:
        try:
            with _get_conn(DATABASE_PATH) as c:
                c.execute(
                    "UPDATE settings_sync_queue SET sync_status='failed', error_msg=?, synced_at=? WHERE id=?",
                    (last_err, _mtscos_now(), job_id)
                )
                c.commit()
        except Exception:
            pass
    return job_id


