@app.route('/api/settings/sync/push', methods=['POST'])
@system_container('settings_sync_push', require_auth='admin')
def api_settings_sync_push():
    """推送设置变更到所有组件（重试所有pending/failed）"""
    _ensure_settings_sync_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            jobs = c.execute(
                "SELECT id,setting_key,setting_value,sync_direction,target_components_json FROM settings_sync_queue "
                "WHERE sync_status IN ('pending','failed') ORDER BY id ASC LIMIT 100"
            ).fetchall()
        reprocessed = 0
        succeeded = 0
        for j in jobs:
            reprocessed += 1
            try:
                comps = json.loads(j['target_components_json'] or '[]')
            except Exception:
                comps = []
            ok = False
            last_err = ''
            for attempt in range(3):
                ok, last_err = _settings_sync_attempt(j['id'], j['setting_key'], j['setting_value'], j['sync_direction'], comps)
                if ok:
                    break
                time.sleep(0.2 * (attempt + 1))
            if ok:
                succeeded += 1
            else:
                try:
                    with _get_conn(DATABASE_PATH) as c:
                        c.execute("UPDATE settings_sync_queue SET sync_status='failed', error_msg=?, synced_at=? WHERE id=?",
                                  (last_err, _mtscos_now(), j['id']))
                        c.commit()
                except Exception:
                    pass
        return jsonify({'ok': True, 'data': {'reprocessed': reprocessed, 'succeeded': succeeded},
                        'message': f'重试{reprocessed}个任务，成功{succeeded}个'})
    except Exception as e:
        logger.warning(f'[settings_sync][push] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


