    """更新设置（自动触发同步）"""
    _ensure_settings_sync_ddls()
    try:
        payload = request.get_json(silent=True) or {}
    except Exception:
        payload = {}
    key = (payload.get('setting_key') or payload.get('key') or '').strip()
    value = payload.get('setting_value') if payload.get('setting_value') is not None else payload.get('value')
