# ============================================================================
# [系统AI自动化引擎 V1.0]
#   子系统1: 系统心跳包 (System Heartbeat)
#   子系统2: 自动Hook调度器 (Auto Hook Scheduler)
#   子系统3: AI自动计划 (AI Auto Plan)
#   子系统4: AI自我增强引擎 (AI Self-Enhancement)
#   子系统5: AI能动力仪表盘 (AI Proactivity Dashboard)
# - 所有DDL持久化到 DATABASE_PATH（=APP_DB，可写、真实存在）
# - 查询统一参数化占位符 ?，返回 {ok, data, message}
# - 所有API使用 @system_container 装饰器（读 require_auth='login'，写 require_auth='admin'）
# - 后台线程均为 daemon=True，不阻塞主进程；模块末尾启动5大daemon
# ============================================================================
import threading as _thr_sysai

# ============================================================
# 子系统1: 系统心跳包 (System Heartbeat)
# ============================================================

def _ensure_system_heartbeat_ddls():
    """确保系统心跳相关表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS system_heartbeat (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                component_name TEXT NOT NULL,
                component_type TEXT,
                status TEXT DEFAULT 'ALIVE',
                last_beat_at TEXT,
                beat_interval_sec INTEGER DEFAULT 30,
                metrics_json TEXT,
                health_score REAL DEFAULT 100,
                created_at TEXT,
                updated_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_sh_comp ON system_heartbeat(component_name);
            CREATE INDEX IF NOT EXISTS idx_sh_status ON system_heartbeat(status);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[system_heartbeat][ddl] err: {e}')

# 默认注册组件（内存层，可由 register API 追加；DB 中已登记组件也会被 daemon 拾取）
_SYSTEM_DEFAULT_COMPONENTS = [
    {'name': 'flask_app', 'type': 'web', 'interval': 30},
    {'name': 'ai_engine', 'type': 'ai', 'interval': 30},
    {'name': 'scheduler', 'type': 'scheduler', 'interval': 30},
    {'name': 'database_app', 'type': 'database', 'interval': 30},
    {'name': 'database_auth', 'type': 'database', 'interval': 30},
]

def _get_registered_components():
    """返回需要心跳的组件列表 = 默认组件 ∪ DB中已登记过的组件名"""
    comps = list(_SYSTEM_DEFAULT_COMPONENTS)
    seen = {c['name'] for c in comps}
    try:
        _ensure_system_heartbeat_ddls()
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT component_name, component_type, beat_interval_sec FROM system_heartbeat "
                "GROUP BY component_name, component_type, beat_interval_sec"
            ).fetchall()
        for r in rows:
            r = dict(r)
            nm = r.get('component_name')
            if nm and nm not in seen:
                seen.add(nm)
                comps.append({
                    'name': nm,
                    'type': r.get('component_type') or 'generic',
                    'interval': int(r.get('beat_interval_sec') or 30),
                })
    except Exception:
        pass
    return comps

def _heartbeat_collect_metrics(comp):
    """采集单个组件的真实指标，返回 (metrics_dict, health_score)"""
    metrics = {}
    score = 100.0
    ctype = comp.get('type')
    try:
        if ctype == 'database':
            dbp = APP_DB if comp['name'] == 'database_app' else (AUTH_DB if comp['name'] == 'database_auth' else DATABASE_PATH)
            if not os.path.exists(dbp):
                score -= 60
                metrics['error'] = f'db not found: {dbp}'
            else:
                t0 = time.time()
                with _get_conn(dbp) as c:
                    c.execute('SELECT 1').fetchone()
                rt_ms = (time.time() - t0) * 1000
                metrics['response_time_ms'] = round(rt_ms, 2)
                if rt_ms > 500:
                    score -= 30
                elif rt_ms > 200:
                    score -= 15
                elif rt_ms > 100:
                    score -= 5
                try:
                    with _get_conn(dbp) as c:
                        cnt = c.execute("SELECT COUNT(*) FROM sqlite_master WHERE type='table'").fetchone()[0]
                    metrics['table_count'] = cnt
                except Exception:
                    pass
        elif ctype == 'web':
            t0 = time.time()
            has_app = app is not None
            rt_ms = (time.time() - t0) * 1000
            metrics['response_time_ms'] = round(rt_ms, 2)
            metrics['app_registered'] = bool(has_app)
            if not has_app:
                score -= 50
        elif ctype == 'ai':
            try:
                with _get_conn(DATABASE_PATH) as c:
                    ai_tables = c.execute(
                        "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name LIKE 'ai_%'"
                    ).fetchone()[0]
                metrics['ai_tables'] = ai_tables
                if ai_tables == 0:
                    score -= 20
            except Exception as e:
                score -= 30
                metrics['error'] = str(e)
        elif ctype == 'scheduler':
            try:
                active = sum(1 for t in _thr_sysai.enumerate() if t.is_alive() and t.daemon)
                metrics['active_daemon_threads'] = active
                if active < 1:
                    score -= 40
            except Exception:
                pass
        else:
            metrics['note'] = 'generic component'
    except Exception as e:
        score -= 50
        metrics['error'] = str(e)
    # 内存使用（真实）
    try:
        import resource as _res
        mem_kb = _res.getrusage(_res.RUSAGE_SELF).ru_maxrss
        metrics['memory_kb'] = mem_kb
        if mem_kb > 800000:
            score -= 10
    except Exception:
        pass
    score = max(0.0, min(100.0, score))
    return metrics, score

def _heartbeat_daemon():
    """系统心跳后台daemon：每30秒遍历注册组件，记录心跳并计算健康分"""
    time.sleep(5)
    while True:
        try:
            _ensure_system_heartbeat_ddls()
            now = _mtscos_now()
            for comp in _get_registered_components():
                try:
                    metrics, score = _heartbeat_collect_metrics(comp)
                    status = 'ALIVE' if score >= 60 else 'DEGRADED'
                    interval = int(comp.get('interval') or 30)
                    with _get_conn(DATABASE_PATH) as c:
                        c.execute(
                            "INSERT INTO system_heartbeat (component_name, component_type, status, "
                            "last_beat_at, beat_interval_sec, metrics_json, health_score, "
                            "created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)",
                            (comp['name'], comp['type'], status, now, interval,
                             json.dumps(metrics, ensure_ascii=False), score, now, now)
                        )
                        c.commit()
                except Exception as e:
                    logger.warning(f'[system_heartbeat][daemon][{comp.get("name")}] err: {e}')
            # 历史裁剪：保留最近7天
            try:
                cutoff = (datetime.now() - timedelta(days=7)).strftime('%Y-%m-%d %H:%M:%S')
                with _get_conn(DATABASE_PATH) as c:
                    c.execute("DELETE FROM system_heartbeat WHERE last_beat_at < ?", (cutoff,))
                    c.commit()
            except Exception:
                pass
        except Exception as e:
            logger.warning(f'[system_heartbeat][daemon] err: {e}')
        time.sleep(30)

@app.route('/api/system/heartbeat/status', methods=['GET'])
@system_container('system_heartbeat_status', require_auth='login')
def api_system_heartbeat_status():
    """获取所有组件心跳状态（latest per component，含超时DEAD判定）"""
    _ensure_system_heartbeat_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT h.* FROM system_heartbeat h INNER JOIN "
                "(SELECT component_name, MAX(id) AS mid FROM system_heartbeat GROUP BY component_name) m "
                "ON h.id=m.mid ORDER BY h.health_score ASC, h.component_name"
            ).fetchall()
        data = []
        now_dt = datetime.now()
        for r in rows:
            d = dict(r)
            try:
                d['metrics'] = json.loads(d.pop('metrics_json') or '{}')
            except Exception:
                d['metrics'] = {}
            try:
                last_ts = datetime.strptime((d.get('last_beat_at') or '')[:19], '%Y-%m-%d %H:%M:%S')
                interval = int(d.get('beat_interval_sec') or 30)
                if (now_dt - last_ts).total_seconds() > interval * 3:
                    d['status'] = 'DEAD'
                    d['health_score'] = 0
            except Exception:
                pass
            data.append(d)
        alive = sum(1 for d in data if d.get('status') == 'ALIVE')
        degraded = sum(1 for d in data if d.get('status') == 'DEGRADED')
        dead = sum(1 for d in data if d.get('status') == 'DEAD')
        avg = round(sum(float(d.get('health_score') or 0) for d in data) / max(1, len(data)), 2)
        return jsonify({'ok': True, 'data': {
            'components': data, 'total': len(data),
            'alive': alive, 'degraded': degraded, 'dead': dead,
            'avg_health_score': avg,
        }, 'message': f'共{len(data)}个组件，存活{alive}，降级{degraded}，离线{dead}'})
    except Exception as e:
        logger.warning(f'[system_heartbeat][status] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

