# ============================================================
# 子系统3: AI自动计划 (AI Auto Plan)
# ============================================================

def _ensure_ai_auto_plan_ddls():
    """确保AI自动计划相关表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS ai_auto_plans (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                plan_name TEXT NOT NULL,
                plan_type TEXT,
                description TEXT,
                trigger_condition_json TEXT,
                action_steps_json TEXT,
                status TEXT DEFAULT 'draft',
                priority INTEGER DEFAULT 5,
                created_by TEXT,
                created_at TEXT,
                updated_at TEXT,
                last_executed TEXT,
                execution_count INTEGER DEFAULT 0,
                success_count INTEGER DEFAULT 0,
                fail_count INTEGER DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS ai_auto_plan_executions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                plan_id INTEGER,
                started_at TEXT,
                completed_at TEXT,
                status TEXT,
                steps_completed_json TEXT,
                steps_failed_json TEXT,
                result_summary TEXT,
                error_msg TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_aap_type ON ai_auto_plans(plan_type);
            CREATE INDEX IF NOT EXISTS idx_aap_status ON ai_auto_plans(status);
            CREATE INDEX IF NOT EXISTS idx_aape_plan ON ai_auto_plan_executions(plan_id);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[ai_auto_plan][ddl] err: {e}')

def _autoplane_run(plan_id):
    """执行一个自动计划（按 action_steps_json 逐步执行），返回执行结果dict；计划不存在返回None"""
    with _get_conn(DATABASE_PATH) as c:
        row = c.execute("SELECT * FROM ai_auto_plans WHERE id=?", (plan_id,)).fetchone()
    if not row:
        return None
    plan = dict(row)
    try:
        steps = json.loads(plan.get('action_steps_json') or '[]')
    except Exception:
        steps = []
    if not steps:
        return {'plan_id': plan_id, 'status': 'skipped', 'summary': '无执行步骤',
                'steps_completed': 0, 'steps_failed': 0}
    started = _mtscos_now()
    completed_list, failed_list = [], []
    for idx, step in enumerate(steps):
        action = step.get('action') or step.get('target_action')
        params_json = json.dumps(step.get('params', {}), ensure_ascii=False)
        result, elapsed, err = _execute_hook_action(action, params_json)
        item = {'step_index': idx, 'action': action, 'result': result, 'execution_time_ms': elapsed}
        if err:
            item['error'] = err
            failed_list.append(item)
        else:
            completed_list.append(item)
    status = 'success' if not failed_list else ('partial' if completed_list else 'failed')
    summary = f'完成{len(completed_list)}/{len(steps)}步'
    with _get_conn(DATABASE_PATH) as c:
        cur = c.execute(
            "INSERT INTO ai_auto_plan_executions (plan_id, started_at, completed_at, status, "
            "steps_completed_json, steps_failed_json, result_summary, error_msg) VALUES (?,?,?,?,?,?,?,?)",
            (plan_id, started, _mtscos_now(), status,
             json.dumps(completed_list, ensure_ascii=False),
             json.dumps(failed_list, ensure_ascii=False), summary, '')
        )
        exec_id = cur.lastrowid
        c.execute(
            "UPDATE ai_auto_plans SET last_executed=?, execution_count=execution_count+1, "
            "success_count=success_count+?, fail_count=fail_count+?, status=?, updated_at=? WHERE id=?",
            (_mtscos_now(), 1 if status == 'success' else 0,
             1 if status == 'failed' else 0, status, _mtscos_now(), plan_id)
        )
        c.commit()
    return {'execution_id': exec_id, 'plan_id': plan_id, 'status': status,
            'steps_completed': len(completed_list), 'steps_failed': len(failed_list), 'summary': summary}

def _ai_auto_plan_daemon():
    """AI自动计划后台daemon：扫描配置了 auto+interval_sec 的计划并到点自动执行"""
    time.sleep(30)
    while True:
        try:
            _ensure_ai_auto_plan_ddls()
            now_dt = datetime.now()
            with _get_conn(DATABASE_PATH) as c:
                rows = [dict(r) for r in c.execute(
                    "SELECT * FROM ai_auto_plans WHERE status IN ('active','enabled','draft') "
                    "ORDER BY priority DESC, id DESC"
                ).fetchall()]
            for r in rows:
                try:
                    trig = json.loads(r.get('trigger_condition_json') or '{}')
                except Exception:
                    trig = {}
                if not trig.get('auto'):
                    continue
                try:
                    steps = json.loads(r.get('action_steps_json') or '[]')
                except Exception:
                    steps = []
                if not steps:
                    continue
                try:
                    interval = int(trig.get('interval_sec') or 0)
                except Exception:
                    interval = 0
                if interval <= 0:
                    continue
                last = r.get('last_executed') or ''
                if last:
                    try:
                        lt = datetime.strptime(last[:19], '%Y-%m-%d %H:%M:%S')
                        if (now_dt - lt).total_seconds() < interval:
                            continue
                    except Exception:
                        pass
                _autoplane_run(r['id'])
        except Exception as e:
            logger.warning(f'[autoplane][daemon] err: {e}')
        time.sleep(60)

