@app.route('/api/system/autoplane/stats', methods=['GET'])
@system_container('system_autoplane_stats', require_auth='login')
def api_system_autoplane_stats():
    """自动计划统计"""
    _ensure_ai_auto_plan_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            total = c.execute("SELECT COUNT(*) FROM ai_auto_plans").fetchone()[0]
            by_type = c.execute(
                "SELECT plan_type, COUNT(*) AS cnt FROM ai_auto_plans GROUP BY plan_type ORDER BY cnt DESC"
            ).fetchall()
            by_status = c.execute(
                "SELECT status, COUNT(*) AS cnt FROM ai_auto_plans GROUP BY status ORDER BY cnt DESC"
            ).fetchall()
            exec_total = c.execute("SELECT COUNT(*) FROM ai_auto_plan_executions").fetchone()[0]
            exec_success = c.execute("SELECT COUNT(*) FROM ai_auto_plan_executions WHERE status='success'").fetchone()[0]
            exec_failed = c.execute("SELECT COUNT(*) FROM ai_auto_plan_executions WHERE status='failed'").fetchone()[0]
            sum_exec = c.execute("SELECT COALESCE(SUM(execution_count),0) FROM ai_auto_plans").fetchone()[0]
            sum_success = c.execute("SELECT COALESCE(SUM(success_count),0) FROM ai_auto_plans").fetchone()[0]
        return jsonify({'ok': True, 'data': {
            'total_plans': total,
            'by_type': [{'plan_type': r[0] or '未分类', 'count': r[1]} for r in by_type],
            'by_status': [{'status': r[0] or '未分类', 'count': r[1]} for r in by_status],
            'executions': {'total': exec_total, 'success': exec_success, 'failed': exec_failed},
            'cumulative': {'total_executions': sum_exec, 'total_success': sum_success},
            'success_rate': round(sum_success * 100.0 / sum_exec, 2) if sum_exec else 0.0,
        }, 'message': f'共{total}个自动计划'})
    except Exception as e:
        logger.warning(f'[autoplane][stats] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


