def _ensure_ai_enhancement_ddls():
    """确保AI自我增强相关表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS ai_enhancement_suggestions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                suggestion_type TEXT,
                target_component TEXT,
                description TEXT,
                impact_score REAL DEFAULT 0,
                difficulty TEXT,
                status TEXT DEFAULT 'open',
                proposed_by TEXT,
                proposed_at TEXT,
                reviewed_by TEXT,
                reviewed_at TEXT,
                implementation_notes TEXT,
                created_at TEXT
            );
            CREATE TABLE IF NOT EXISTS ai_enhancement_actions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                suggestion_id INTEGER,
                action_type TEXT,
                action_detail TEXT,
                executed_at TEXT,
                result TEXT,
                status TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_aes_status ON ai_enhancement_suggestions(status);
            CREATE INDEX IF NOT EXISTS idx_aes_target ON ai_enhancement_suggestions(target_component);
            CREATE INDEX IF NOT EXISTS idx_aea_sid ON ai_enhancement_actions(suggestion_id);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[ai_enhancement][ddl] err: {e}')

def _ai_self_enhancement_daemon():
    """AI自我增强后台daemon：每5分钟扫描心跳指标，生成增强建议并自动执行高价值低难度建议"""
    time.sleep(20)
    while True:
        try:
            _ensure_ai_enhancement_ddls()
            _ensure_system_heartbeat_ddls()
            with _get_conn(DATABASE_PATH) as c:
                latest = [dict(r) for r in c.execute(
                    "SELECT h.* FROM system_heartbeat h INNER JOIN "
                    "(SELECT component_name, MAX(id) AS mid FROM system_heartbeat GROUP BY component_name) m "
                    "ON h.id=m.mid"
                ).fetchall()]
            now = _mtscos_now()
            cutoff = (datetime.now() - timedelta(hours=24)).strftime('%Y-%m-%d %H:%M:%S')
            for comp in latest:
                name = comp.get('component_name')
                score = float(comp.get('health_score') or 100)
                status = comp.get('status') or 'ALIVE'
                metrics = {}
                try:
                    metrics = json.loads(comp.get('metrics_json') or '{}')
                except Exception:
                    pass
                rt = float(metrics.get('response_time_ms') or 0)
                mem = float(metrics.get('memory_kb') or 0)
                cands = []
                if status == 'DEAD' or score < 30:
                    cands.append(('self_heal', name, f'组件{name}状态为{status}，健康分{score}，需自动恢复',
                                  90, 'low'))
                if 30 <= score < 60:
                    cands.append(('auto_enhance', name, f'组件{name}健康分{score}偏低，建议增强监控与冗余',
                                  70, 'medium'))
                if rt > 200:
                    cands.append(('auto_optimize', name, f'组件{name}响应时间{rt}ms偏高，建议优化查询/缓存',
                                  75, 'medium'))
                if mem > 800000:
                    cands.append(('auto_optimize', name, f'组件{name}内存{int(mem)}KB偏高，建议清理缓存',
                                  65, 'medium'))
                for stype, target, desc, impact, diff in cands:
                    try:
                        with _get_conn(DATABASE_PATH) as c:
                            dup = c.execute(
                                "SELECT id FROM ai_enhancement_suggestions "
                                "WHERE suggestion_type=? AND target_component=? AND description=? "
                                "AND status NOT IN ('done','rejected','auto_executed') AND proposed_at>=?",
                                (stype, target, desc, cutoff)
                            ).fetchone()
                            if dup:
                                continue
                            cur = c.execute(
                                "INSERT INTO ai_enhancement_suggestions (suggestion_type, target_component, "
                                "description, impact_score, difficulty, status, proposed_by, proposed_at, "
                                "implementation_notes, created_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
                                (stype, target, desc, impact, diff, 'open', 'system', now, '', now)
                            )
                            sid = cur.lastrowid
                            if impact >= 80 and diff == 'low':
                                action_detail = 'auto_executed'
                                result = 'logged'
                                if stype == 'self_heal':
                                    try:
                                        c.execute(
                                            "INSERT INTO system_heartbeat (component_name, component_type, status, "
                                            "last_beat_at, beat_interval_sec, metrics_json, health_score, "
                                            "created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)",
                                            (target, 'auto_recovered', 'ALIVE', now, 30,
                                             json.dumps({'recovered_by': 'self_heal'}, ensure_ascii=False),
                                             80.0, now, now)
                                        )
                                        result = 'component_recovered'
                                        action_detail = f'自动为组件{target}注入恢复心跳'
                                    except Exception as e:
                                        result = f'recover_failed:{e}'
                                c.execute(
                                    "INSERT INTO ai_enhancement_actions (suggestion_id, action_type, action_detail, "
                                    "executed_at, result, status) VALUES (?,?,?,?,?,?)",
                                    (sid, 'auto_fix', action_detail, now, result, 'executed')
                                )
                                c.execute(
                                    "UPDATE ai_enhancement_suggestions SET status='auto_executed', "
                                    "reviewed_by='system', reviewed_at=?, implementation_notes=? WHERE id=?",
                                    (now, action_detail, sid)
                                )
                            c.commit()
                    except Exception as e:
                        logger.warning(f'[enhancement][daemon][sug] err: {e}')
        except Exception as e:
            logger.warning(f'[enhancement][daemon] err: {e}')
        time.sleep(300)

