@app.route('/api/system/enhancement/execute/<int:suggestion_id>', methods=['POST'])
@system_container('system_enhancement_execute', require_auth='admin')
def api_system_enhancement_execute(suggestion_id):
    """执行增强建议（self_heal类型会真实注入恢复心跳）"""
    _ensure_ai_enhancement_ddls()
    try:
        data = request.get_json(silent=True) or request.form.to_dict() or {}
        with _get_conn(DATABASE_PATH) as c:
            row = c.execute("SELECT * FROM ai_enhancement_suggestions WHERE id=?", (suggestion_id,)).fetchone()
            if not row:
                return jsonify({'ok': False, 'data': None, 'message': f'建议{suggestion_id}不存在'}), 404
            sug = dict(row)
            user = _current_safe_user()
            now = _mtscos_now()
            detail = data.get('action_detail') or f'手动执行建议{suggestion_id}'
            result = 'manual_executed'
            if sug.get('suggestion_type') == 'self_heal' and sug.get('target_component'):
                try:
                    _ensure_system_heartbeat_ddls()
                    c.execute(
                        "INSERT INTO system_heartbeat (component_name, component_type, status, last_beat_at, "
                        "beat_interval_sec, metrics_json, health_score, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)",
                        (sug['target_component'], 'manual_recovered', 'ALIVE', now, 30,
                         json.dumps({'recovered_by': 'manual'}, ensure_ascii=False), 80.0, now, now)
                    )
                    result = 'component_recovered'
                except Exception as e:
                    result = f'recover_failed:{e}'
            c.execute(
                "INSERT INTO ai_enhancement_actions (suggestion_id, action_type, action_detail, "
                "executed_at, result, status) VALUES (?,?,?,?,?,?)",
                (suggestion_id, 'manual', detail, now, result, 'executed')
            )
            c.execute(
                "UPDATE ai_enhancement_suggestions SET status='done', reviewed_by=?, reviewed_at=?, "
                "implementation_notes=COALESCE(implementation_notes,'')||? WHERE id=?",
                (user.get('username') or 'admin', now, f'|{detail}', suggestion_id)
            )
            c.commit()
        return jsonify({'ok': True, 'data': {'suggestion_id': suggestion_id, 'result': result},
                        'message': f'建议{suggestion_id}已执行'})
    except Exception as e:
        logger.warning(f'[enhancement][execute] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

