def _ensure_proactivity_ddls():
    """确保AI能动力指标表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS ai_proactivity_metrics (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                metric_name TEXT NOT NULL,
                metric_value REAL,
                metric_unit TEXT,
                target_value REAL,
                status TEXT,
                recorded_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_apm_name ON ai_proactivity_metrics(metric_name);
            CREATE INDEX IF NOT EXISTS idx_apm_time ON ai_proactivity_metrics(recorded_at);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[proactivity][ddl] err: {e}')

def _safe_count(db, sql, params=()):
    """安全计数：表/库不存在或异常返回0（真实计数，绝不伪造）"""
    try:
        if not db or not os.path.exists(db):
            return 0
        with _get_conn(db) as c:
            return int(c.execute(sql, params).fetchone()[0] or 0)
    except Exception:
        return 0

def _collect_proactivity_metrics():
    """采集AI能动力指标并写入DB（所有计数均来自真实表）"""
    _ensure_proactivity_ddls()
    _ensure_auto_hook_ddls()
    _ensure_ai_auto_plan_ddls()
    _ensure_ai_enhancement_ddls()
    now = _mtscos_now()
    # AI员工活跃数：优先 mtscos_ai_employees(APP_DB)，回退 ai_employees(SPLIT_AI_DB)
    ai_emp = _safe_count(APP_DB, "SELECT COUNT(*) FROM mtscos_ai_employees WHERE is_active=1")
    if ai_emp == 0:
        ai_emp = _safe_count(SPLIT_AI_DB, "SELECT COUNT(*) FROM ai_employees WHERE is_enabled=1")
    hook_trig = _safe_count(DATABASE_PATH, "SELECT COUNT(*) FROM auto_hook_logs")
    self_heal_ok = _safe_count(DATABASE_PATH,
        "SELECT COUNT(*) FROM ai_auto_plan_executions e JOIN ai_auto_plans p ON e.plan_id=p.id "
        "WHERE p.plan_type='self_heal' AND e.status='success'")
    plan_exec = _safe_count(DATABASE_PATH, "SELECT COUNT(*) FROM ai_auto_plan_executions")
    sug_count = _safe_count(DATABASE_PATH, "SELECT COUNT(*) FROM ai_enhancement_suggestions")
    manual = _safe_count(DATABASE_PATH,
        "SELECT COUNT(*) FROM ai_enhancement_suggestions WHERE proposed_by IS NOT NULL AND proposed_by!='system'")
    auto_sug = _safe_count(DATABASE_PATH,
        "SELECT COUNT(*) FROM ai_enhancement_suggestions WHERE proposed_by='system'")
    auto_actions = hook_trig + plan_exec + auto_sug
    total_actions = auto_actions + manual
    auto_rate = round(auto_actions * 100.0 / total_actions, 2) if total_actions > 0 else 0.0
    metrics = [
        ('ai_employee_active', ai_emp, 'count', 50, 'info'),
        ('auto_hook_triggers', hook_trig, 'count', None, 'info'),
        ('self_heal_success', self_heal_ok, 'count', None, 'info'),
        ('auto_plan_executions', plan_exec, 'count', None, 'info'),
        ('enhancement_suggestions', sug_count, 'count', None, 'info'),
        ('manual_interventions', manual, 'count', 0, 'warning'),        # 目标：减少→0
        ('system_automation_rate', auto_rate, 'percent', 100, 'info'),  # 目标：提升→100
    ]
    try:
        with _get_conn(DATABASE_PATH) as c:
            for name, val, unit, target, status in metrics:
                c.execute(
                    "INSERT INTO ai_proactivity_metrics (metric_name, metric_value, metric_unit, "
                    "target_value, status, recorded_at) VALUES (?,?,?,?,?,?)",
                    (name, val, unit, target, status, now)
                )
            cutoff = (datetime.now() - timedelta(days=7)).strftime('%Y-%m-%d %H:%M:%S')
            c.execute("DELETE FROM ai_proactivity_metrics WHERE recorded_at < ?", (cutoff,))
            c.commit()
    except Exception as e:
        logger.warning(f'[proactivity][collect] err: {e}')

def _proactivity_collector_daemon():
    """AI能动力采集后台daemon：每60秒采集一次"""
    time.sleep(15)
    while True:
        try:
            _collect_proactivity_metrics()
        except Exception as e:
            logger.warning(f'[proactivity][daemon] err: {e}')
        time.sleep(60)

@app.route('/api/system/proactivity/dashboard', methods=['GET'])
@system_container('system_proactivity_dashboard', require_auth='login')
def api_system_proactivity_dashboard():
    """AI能动力仪表盘数据（每个指标最新值）"""
    _ensure_proactivity_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT m.* FROM ai_proactivity_metrics m INNER JOIN "
                "(SELECT metric_name, MAX(id) AS mid FROM ai_proactivity_metrics GROUP BY metric_name) t "
                "ON m.id=t.mid ORDER BY m.metric_name"
            ).fetchall()
        data = [dict(r) for r in rows]
        return jsonify({'ok': True, 'data': {
            'metrics': data, 'metric_count': len(data), 'collected_at': _mtscos_now(),
        }, 'message': f'共{len(data)}个能动力指标'})
    except Exception as e:
        logger.warning(f'[proactivity][dashboard] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/system/proactivity/trends', methods=['GET'])
@system_container('system_proactivity_trends', require_auth='login')
def api_system_proactivity_trends():
    """趋势数据（默认最近24小时）"""
    _ensure_proactivity_ddls()
    try:
        hours = int(request.args.get('hours', 24))
        cutoff = (datetime.now() - timedelta(hours=hours)).strftime('%Y-%m-%d %H:%M:%S')
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT metric_name, metric_value, recorded_at FROM ai_proactivity_metrics "
                "WHERE recorded_at >= ? ORDER BY recorded_at ASC",
                (cutoff,)
            ).fetchall()
        series = {}
        for r in rows:
            r = dict(r)
            series.setdefault(r['metric_name'], []).append({
                'value': r['metric_value'], 'recorded_at': r['recorded_at']
            })
        return jsonify({'ok': True, 'data': {
            'series': series, 'hours': hours,
            'point_count': sum(len(v) for v in series.values()),
        }, 'message': f'最近{hours}小时趋势数据'})
    except Exception as e:
        logger.warning(f'[proactivity][trends] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


# ============================================================
# 模块: 系统文档统一管理与文案存档
#   子系统1: 系统文档统一管理 (system_documents)
#   子系统2: 文案模板管理 (system_copywriting_templates / system_copywriting_records)
#   子系统3: 系统文档自动生成 (system_doc_auto_gen)
#   约束: 全部使用 @system_container 装饰器；真实 SQLite 表；DATABASE_PATH 全局变量
# ============================================================

# ---------- DDL 确保函数 ----------
def _ensure_system_documents_ddls():
    """确保系统文档表 system_documents 存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS system_documents (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                doc_uid TEXT UNIQUE,
                doc_title TEXT NOT NULL,
                doc_category TEXT,
                doc_type TEXT,
                doc_content TEXT,
                doc_summary TEXT,
                doc_tags_json TEXT DEFAULT '[]',
                doc_version TEXT DEFAULT 'v1.0',
                doc_status TEXT DEFAULT 'draft',
                doc_visibility TEXT DEFAULT 'internal',
                parent_doc_id INTEGER,
                author_id INTEGER,
                author_name TEXT,
                reviewer_id INTEGER,
                reviewer_name TEXT,
                reviewed_at TEXT,
                published_at TEXT,
                view_count INTEGER DEFAULT 0,
                download_count INTEGER DEFAULT 0,
                file_path TEXT,
                file_size INTEGER DEFAULT 0,
                file_type TEXT,
                created_at TEXT,
                updated_at TEXT,
                expired_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_sd_category ON system_documents(doc_category);
            CREATE INDEX IF NOT EXISTS idx_sd_type ON system_documents(doc_type);
            CREATE INDEX IF NOT EXISTS idx_sd_status ON system_documents(doc_status);
            CREATE INDEX IF NOT EXISTS idx_sd_parent ON system_documents(parent_doc_id);
            CREATE INDEX IF NOT EXISTS idx_sd_uid ON system_documents(doc_uid);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[docs][ddl] err: {e}')

def _ensure_copywriting_ddls():
    """确保文案模板/记录表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS system_copywriting_templates (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_name TEXT NOT NULL,
                template_category TEXT,
                template_type TEXT,
                template_content TEXT NOT NULL,
                template_variables_json TEXT DEFAULT '[]',
                description TEXT,
                usage_count INTEGER DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                created_by TEXT,
                created_at TEXT,
                updated_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_cwt_category ON system_copywriting_templates(template_category);
            CREATE INDEX IF NOT EXISTS idx_cwt_active ON system_copywriting_templates(is_active);
            CREATE TABLE IF NOT EXISTS system_copywriting_records (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_id INTEGER,
                record_title TEXT,
                record_content TEXT,
                record_context_json TEXT DEFAULT '{}',
                generated_by TEXT,
                target_audience TEXT,
                status TEXT DEFAULT 'active',
                created_at TEXT,
                updated_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_cwr_template ON system_copywriting_records(template_id);
            CREATE INDEX IF NOT EXISTS idx_cwr_status ON system_copywriting_records(status);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[copywriting][ddl] err: {e}')

def _ensure_doc_auto_gen_ddls():
    """确保文档自动生成记录表存在"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS system_doc_auto_gen (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                gen_type TEXT NOT NULL,
                gen_target TEXT,
                gen_content TEXT,
                gen_status TEXT DEFAULT 'completed',
                gen_by TEXT,
                gen_at TEXT,
                metadata_json TEXT DEFAULT '{}'
            );
            CREATE INDEX IF NOT EXISTS idx_dag_type ON system_doc_auto_gen(gen_type);
            CREATE INDEX IF NOT EXISTS idx_dag_time ON system_doc_auto_gen(gen_at);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[doc-auto-gen][ddl] err: {e}')

def _docs_parse_body():
    """安全解析请求体（JSON 优先，回退 form）"""
    b = request.get_json(silent=True)
    if not b:
        b = dict(request.form.items()) if request.form else {}
    return b

def _docs_qs_int(name, default=0):
    try:
        return int(request.args.get(name, default))
    except (ValueError, TypeError):
        return default

def _docs_safe_int(val, default=None):
    try:
        return int(val) if val not in (None, '', 'None') else default
    except (ValueError, TypeError):
        return default

def _docs_current_author():
    """获取当前登录用户作为文档作者信息"""
    _u = _current_safe_user()
    return _docs_safe_int(_u.get('uid')), (_u.get('username') or 'system')

def _record_doc_auto_gen(gen_type, gen_target, gen_content, gen_by='system', metadata=None):
    """记录一次自动生成到 system_doc_auto_gen 表（尽力而为，不抛异常）"""
    try:
        _ensure_doc_auto_gen_ddls()
        with _get_conn(DATABASE_PATH) as c:
            c.execute(
                "INSERT INTO system_doc_auto_gen (gen_type, gen_target, gen_content, gen_status, gen_by, gen_at, metadata_json) "
                "VALUES (?,?,?,?,?,?,?)",
                (gen_type, gen_target, gen_content, 'completed', gen_by, _mtscos_now(),
                 json.dumps(metadata or {}, ensure_ascii=False))
            )
            c.commit()
    except Exception as e:
        logger.warning(f'[doc-auto-gen][record] err: {e}')

# ============================================================
# 子系统1: 系统文档统一管理
# ============================================================

@app.route('/api/docs/list', methods=['GET'])
@system_container('api_docs_list', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_list():
    """文档列表（支持分类/类型/状态/关键词筛选，分页）"""
    _ensure_system_documents_ddls()
    try:
        category = (request.args.get('category') or '').strip()
        doc_type = (request.args.get('doc_type') or '').strip()
        status = (request.args.get('status') or '').strip()
        keyword = (request.args.get('keyword') or '').strip()
        page = max(1, _docs_qs_int('page', 1))
        page_size = min(100, max(1, _docs_qs_int('page_size', 20)))
        where, params = [], []
        if category:
            where.append("doc_category = ?"); params.append(category)
        if doc_type:
            where.append("doc_type = ?"); params.append(doc_type)
        if status:
            where.append("doc_status = ?"); params.append(status)
        else:
            where.append("doc_status != 'deleted'")
        if keyword:
            where.append("(doc_title LIKE ? OR doc_summary LIKE ? OR doc_content LIKE ? OR doc_tags_json LIKE ?)")
            kw = f'%{keyword}%'
            params.extend([kw, kw, kw, kw])
        where_sql = (' WHERE ' + ' AND '.join(where)) if where else ''
        offset = (page - 1) * page_size
        with _get_conn(DATABASE_PATH) as c:
            total = c.execute(f"SELECT COUNT(*) FROM system_documents{where_sql}", params).fetchone()[0]
            rows = c.execute(
                f"SELECT * FROM system_documents{where_sql} ORDER BY updated_at DESC, id DESC LIMIT ? OFFSET ?",
                params + [page_size, offset]
            ).fetchall()
        data = [dict(r) for r in rows]
        return jsonify({'ok': True, 'data': {
            'list': data, 'total': total, 'page': page, 'page_size': page_size,
            'pages': (total + page_size - 1) // page_size if page_size else 0,
        }, 'message': f'共{total}篇文档'})
    except Exception as e:
        logger.warning(f'[docs][list] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/detail/<int:doc_id>', methods=['GET'])
@system_container('api_docs_detail', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_detail(doc_id):
    """文档详情（自增浏览数）"""
    _ensure_system_documents_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.execute("UPDATE system_documents SET view_count = view_count + 1 WHERE id = ?", (doc_id,))
            row = c.execute("SELECT * FROM system_documents WHERE id = ?", (doc_id,)).fetchone()
            c.commit()
        if not row:
            return jsonify({'ok': False, 'data': None, 'message': '文档不存在'}), 404
        return jsonify({'ok': True, 'data': dict(row), 'message': '文档详情'})
    except Exception as e:
        logger.warning(f'[docs][detail] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/create', methods=['POST'])
@system_container('api_docs_create', require_auth='admin', inject_user_ctx=False, write_heartbeat=False)
def api_docs_create():
    """创建文档"""
    _ensure_system_documents_ddls()
    try:
        b = _docs_parse_body()
        title = (b.get('doc_title') or '').strip()
        if not title:
            return jsonify({'ok': False, 'data': None, 'message': 'doc_title 不能为空'}), 400
        author_id, author_name = _docs_current_author()
        tags = b.get('doc_tags') or b.get('doc_tags_json') or []
        if isinstance(tags, str):
            try:
                tags = json.loads(tags)
            except Exception:
                tags = [t.strip() for t in tags.split(',') if t.strip()]
        now = _mtscos_now()
        doc_uid = 'doc_' + _uuid.uuid4().hex[:12]
        with _get_conn(DATABASE_PATH) as c:
            cur = c.execute(
                "INSERT INTO system_documents (doc_uid, doc_title, doc_category, doc_type, doc_content, doc_summary, "
                "doc_tags_json, doc_version, doc_status, doc_visibility, parent_doc_id, author_id, author_name, "
                "file_path, file_size, file_type, created_at, updated_at, expired_at) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (doc_uid, title, (b.get('doc_category') or 'other'), (b.get('doc_type') or 'other'),
                 b.get('doc_content') or '', b.get('doc_summary') or '',
                 json.dumps(tags, ensure_ascii=False), b.get('doc_version') or 'v1.0',
                 'draft', b.get('doc_visibility') or 'internal',
                 _docs_safe_int(b.get('parent_doc_id')), author_id, author_name,
                 b.get('file_path'), _docs_safe_int(b.get('file_size'), 0) or 0,
                 b.get('file_type'), now, now, b.get('expired_at'))
            )
            new_id = cur.lastrowid
            c.commit()
        return jsonify({'ok': True, 'data': {'id': new_id, 'doc_uid': doc_uid},
                        'message': '文档创建成功'})
    except Exception as e:
        logger.warning(f'[docs][create] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/update/<int:doc_id>', methods=['POST'])
@system_container('api_docs_update', require_auth='admin', inject_user_ctx=False, write_heartbeat=False)
def api_docs_update(doc_id):
    """更新文档（仅更新传入字段）"""
    _ensure_system_documents_ddls()
    try:
        b = _docs_parse_body()
        allowed = ['doc_title', 'doc_category', 'doc_type', 'doc_content', 'doc_summary',
                   'doc_version', 'doc_status', 'doc_visibility', 'file_path', 'file_size',
                   'file_type', 'expired_at', 'parent_doc_id']
        sets, params = [], []
        for k in allowed:
            if k in b:
                sets.append(f"{k} = ?"); params.append(b.get(k))
        if 'doc_tags' in b or 'doc_tags_json' in b:
            tags = b.get('doc_tags') if 'doc_tags' in b else b.get('doc_tags_json')
            if isinstance(tags, str):
                try:
                    tags = json.loads(tags)
                except Exception:
                    tags = [t.strip() for t in tags.split(',') if t.strip()]
            sets.append("doc_tags_json = ?"); params.append(json.dumps(tags, ensure_ascii=False))
        if not sets:
            return jsonify({'ok': False, 'data': None, 'message': '无可更新字段'}), 400
        sets.append("updated_at = ?"); params.append(_mtscos_now())
        params.append(doc_id)
        with _get_conn(DATABASE_PATH) as c:
            cur = c.execute(f"UPDATE system_documents SET {', '.join(sets)} WHERE id = ?", params)
            c.commit()
            if cur.rowcount == 0:
                return jsonify({'ok': False, 'data': None, 'message': '文档不存在'}), 404
        return jsonify({'ok': True, 'data': {'id': doc_id}, 'message': '文档更新成功'})
    except Exception as e:
        logger.warning(f'[docs][update] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

