@app.route('/api/docs/stats', methods=['GET'])
@system_container('api_docs_stats', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_stats():
    """文档统计（按分类/类型/状态分组统计）"""
    _ensure_system_documents_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            total = c.execute("SELECT COUNT(*) FROM system_documents").fetchone()[0]
            by_category = [dict(r) for r in c.execute(
                "SELECT doc_category AS category, COUNT(*) AS count FROM system_documents "
                "GROUP BY doc_category ORDER BY count DESC"
            ).fetchall()]
            by_type = [dict(r) for r in c.execute(
                "SELECT doc_type AS type, COUNT(*) AS count FROM system_documents "
                "GROUP BY doc_type ORDER BY count DESC"
            ).fetchall()]
            by_status = [dict(r) for r in c.execute(
                "SELECT doc_status AS status, COUNT(*) AS count FROM system_documents "
                "GROUP BY doc_status ORDER BY count DESC"
            ).fetchall()]
            views = c.execute("SELECT COALESCE(SUM(view_count),0) FROM system_documents").fetchone()[0]
            downloads = c.execute("SELECT COALESCE(SUM(download_count),0) FROM system_documents").fetchone()[0]
        return jsonify({'ok': True, 'data': {
            'total': total, 'by_category': by_category, 'by_type': by_type,
            'by_status': by_status, 'total_views': int(views or 0),
            'total_downloads': int(downloads or 0),
        }, 'message': '文档统计'})
    except Exception as e:
        logger.warning(f'[docs][stats] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

