@app.route('/api/copywriting/templates/list', methods=['GET'])
@system_container('api_copywriting_templates_list', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_copywriting_templates_list():
    """模板列表（支持分类/关键词筛选）"""
    _ensure_copywriting_ddls()
    try:
        category = (request.args.get('category') or '').strip()
        keyword = (request.args.get('keyword') or '').strip()
        is_active = request.args.get('is_active')
        where, params = [], []
        if category:
            where.append("template_category = ?"); params.append(category)
        if keyword:
            where.append("(template_name LIKE ? OR description LIKE ? OR template_content LIKE ?)")
            kw = f'%{keyword}%'; params.extend([kw, kw, kw])
        if is_active in ('0', '1'):
            where.append("is_active = ?"); params.append(int(is_active))
        where_sql = (' WHERE ' + ' AND '.join(where)) if where else ''
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                f"SELECT * FROM system_copywriting_templates{where_sql} ORDER BY updated_at DESC, id DESC"
            ).fetchall()
        return jsonify({'ok': True, 'data': [dict(r) for r in rows],
                        'message': f'共{len(rows)}个模板'})
    except Exception as e:
        logger.warning(f'[copywriting][templates-list] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/copywriting/templates/create', methods=['POST'])
@system_container('api_copywriting_templates_create', require_auth='admin', inject_user_ctx=False, write_heartbeat=False)
def api_copywriting_templates_create():
    """创建模板"""
    _ensure_copywriting_ddls()
    try:
        b = _docs_parse_body()
        name = (b.get('template_name') or '').strip()
        content = b.get('template_content') or ''
        if not name or not content:
            return jsonify({'ok': False, 'data': None, 'message': 'template_name 和 template_content 不能为空'}), 400
        _u = _current_safe_user()
        created_by = _u.get('username') or 'system'
        variables = b.get('template_variables') or b.get('template_variables_json') or []
        if isinstance(variables, str):
            try:
                variables = json.loads(variables)
            except Exception:
                variables = [v.strip() for v in variables.split(',') if v.strip()]
        now = _mtscos_now()
        with _get_conn(DATABASE_PATH) as c:
            cur = c.execute(
                "INSERT INTO system_copywriting_templates (template_name, template_category, template_type, "
                "template_content, template_variables_json, description, is_active, created_by, created_at, updated_at) "
                "VALUES (?,?,?,?,?,?,?,?,?,?)",
                (name, b.get('template_category') or 'notification', b.get('template_type') or '',
                 content, json.dumps(variables, ensure_ascii=False), b.get('description') or '',
                 1 if b.get('is_active', 1) else 0, created_by, now, now)
            )
            new_id = cur.lastrowid
            c.commit()
        return jsonify({'ok': True, 'data': {'id': new_id}, 'message': '模板创建成功'})
    except Exception as e:
        logger.warning(f'[copywriting][templates-create] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/copywriting/templates/render/<int:template_id>', methods=['POST'])
@system_container('api_copywriting_templates_render', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_copywriting_templates_render(template_id):
    """渲染模板（传入变量，返回渲染后内容，支持 {{variable_name}} 替换）"""
    _ensure_copywriting_ddls()
    try:
        b = _docs_parse_body()
        variables = b.get('variables') or b.get('vars') or {}
        if isinstance(variables, str):
            try:
                variables = json.loads(variables)
            except Exception:
                variables = {}
        with _get_conn(DATABASE_PATH) as c:
            row = c.execute(
                "SELECT * FROM system_copywriting_templates WHERE id = ?", (template_id,)
            ).fetchone()
            if not row:
                return jsonify({'ok': False, 'data': None, 'message': '模板不存在'}), 404
            c.execute(
                "UPDATE system_copywriting_templates SET usage_count = usage_count + 1, updated_at = ? WHERE id = ?",
                (_mtscos_now(), template_id)
            )
            c.commit()
        tpl = dict(row)
        content = tpl.get('template_content') or ''
        # 变量替换 {{name}} / {{ name }}
        rendered = content
        for k, v in (variables or {}).items():
            rendered = rendered.replace('{{' + k + '}}', str(v))
            rendered = rendered.replace('{{ ' + k + ' }}', str(v))
            rendered = rendered.replace('{{ ' + k + '}}', str(v))
            rendered = rendered.replace('{{' + k + ' }}', str(v))
        # 记录文案记录
        try:
            _u = _current_safe_user()
            with _get_conn(DATABASE_PATH) as c:
                c.execute(
                    "INSERT INTO system_copywriting_records (template_id, record_title, record_content, "
                    "record_context_json, generated_by, target_audience, status, created_at, updated_at) "
                    "VALUES (?,?,?,?,?,?,?,?,?)",
                    (template_id, tpl.get('template_name'), rendered,
                     json.dumps(variables, ensure_ascii=False), _u.get('username') or 'system',
                     b.get('target_audience') or '', 'active', _mtscos_now(), _mtscos_now())
                )
                c.commit()
        except Exception as _ce:
            logger.warning(f'[copywriting][render-record] err: {_ce}')
        return jsonify({'ok': True, 'data': {
            'template_id': template_id, 'template_name': tpl.get('template_name'),
            'rendered_content': rendered, 'variables': variables,
        }, 'message': '模板渲染成功'})
    except Exception as e:
        logger.warning(f'[copywriting][render] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

