@app.route('/api/docs/auto/api_catalog', methods=['GET'])
@system_container('api_docs_auto_api_catalog', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_auto_api_catalog():
    """自动生成API目录（扫描 app.url_map）"""
    try:
        _u = _current_safe_user()
        apis = []
        for rule in sorted(app.url_map.iter_rules(), key=lambda r: r.rule):
            if rule.rule == '/static/<path:filename>':
                continue
            methods = sorted(m for m in (rule.methods or set()) if m not in ('HEAD', 'OPTIONS'))
            apis.append({
                'rule': rule.rule, 'endpoint': rule.endpoint,
                'methods': methods, 'is_api': rule.rule.startswith('/api/'),
            })
        api_count = sum(1 for a in apis if a['is_api'])
        content = json.dumps({'api_count': len(apis), 'api_endpoint_count': api_count, 'apis': apis},
                             ensure_ascii=False, indent=2)
        _record_doc_auto_gen('api_catalog', 'app.url_map', content,
                             gen_by=_u.get('username') or 'system',
                             metadata={'total': len(apis), 'api_count': api_count})
        return jsonify({'ok': True, 'data': {
            'total': len(apis), 'api_count': api_count, 'page_count': len(apis) - api_count,
            'apis': apis,
        }, 'message': f'扫描到{len(apis)}个路由（API {api_count}个）'})
    except Exception as e:
        logger.warning(f'[docs][auto-api-catalog] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/auto/db_schema', methods=['GET'])
@system_container('api_docs_auto_db_schema', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_auto_db_schema():
    """自动生成数据库表结构文档（扫描 sqlite_master）"""
    try:
        _u = _current_safe_user()
        tables = []
        with _get_conn(DATABASE_PATH) as c:
            trows = c.execute(
                "SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
            ).fetchall()
            for tr in trows:
                tname = tr['name']
                cols = []
                try:
                    for cr in c.execute(f"PRAGMA table_info({tname})").fetchall():
                        cols.append({
                            'cid': cr['cid'], 'name': cr['name'], 'type': cr['type'],
                            'notnull': cr['notnull'], 'default': cr['dflt_value'],
                            'pk': cr['pk'],
                        })
                except Exception:
                    pass
                row_count = 0
                try:
                    row_count = c.execute(f"SELECT COUNT(*) FROM [{tname}]").fetchone()[0]
                except Exception:
                    row_count = 0
                tables.append({
                    'name': tname, 'sql': tr['sql'], 'columns': cols,
                    'column_count': len(cols), 'row_count': int(row_count or 0),
                })
        content = json.dumps({'table_count': len(tables), 'tables': tables},
                             ensure_ascii=False, indent=2)
        _record_doc_auto_gen('db_schema', DATABASE_PATH, content,
                             gen_by=_u.get('username') or 'system',
                             metadata={'table_count': len(tables)})
        return jsonify({'ok': True, 'data': {
            'table_count': len(tables), 'tables': tables,
        }, 'message': f'扫描到{len(tables)}张表'})
    except Exception as e:
        logger.warning(f'[docs][auto-db-schema] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/auto/route_map', methods=['GET'])
@system_container('api_docs_auto_route_map', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_auto_route_map():
    """自动生成页面路由地图（非 /api/ 的页面路由）"""
    try:
        _u = _current_safe_user()
        pages, groups = [], {}
        for rule in sorted(app.url_map.iter_rules(), key=lambda r: r.rule):
            if rule.rule.startswith('/api/') or rule.rule.startswith('/static/'):
                continue
            methods = sorted(m for m in (rule.methods or set()) if m not in ('HEAD', 'OPTIONS'))
            seg = rule.rule.strip('/').split('/')[0] if rule.rule.strip('/') else 'root'
            groups.setdefault(seg, []).append(rule.rule)
            pages.append({'rule': rule.rule, 'endpoint': rule.endpoint, 'methods': methods, 'group': seg})
        content = json.dumps({'page_count': len(pages), 'groups': groups, 'pages': pages},
                             ensure_ascii=False, indent=2)
        _record_doc_auto_gen('page_route_map', 'app.url_map', content,
                             gen_by=_u.get('username') or 'system',
                             metadata={'page_count': len(pages), 'group_count': len(groups)})
        return jsonify({'ok': True, 'data': {
            'page_count': len(pages), 'group_count': len(groups), 'groups': groups, 'pages': pages,
        }, 'message': f'扫描到{len(pages)}个页面路由，{len(groups)}个分组'})
    except Exception as e:
        logger.warning(f'[docs][auto-route-map] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/auto/ai_roster', methods=['GET'])
@system_container('api_docs_auto_ai_roster', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_auto_ai_roster():
    """自动生成AI员工花名册（扫描 mtscos_ai_employees 表）"""
    try:
        _u = _current_safe_user()
        employees = []
        with _get_conn(APP_DB) as c:
            try:
                rows = c.execute(
                    "SELECT id, uid, name, role, dept, expertise_json, skills_json, "
                    "salary_tokens_per_hour, is_active, status, onboarded_at, onboarded_by, updated_at "
                    "FROM mtscos_ai_employees ORDER BY id ASC"
                ).fetchall()
            except Exception:
                rows = []
            for r in rows:
                emp = dict(r)
                try:
                    emp['expertise'] = json.loads(emp.get('expertise_json') or '[]')
                except Exception:
                    emp['expertise'] = []
                try:
                    emp['skills'] = json.loads(emp.get('skills_json') or '[]')
                except Exception:
                    emp['skills'] = []
                employees.append(emp)
        active_count = sum(1 for e in employees if e.get('is_active'))
        content = json.dumps({'total': len(employees), 'active': active_count, 'employees': employees},
                             ensure_ascii=False, indent=2)
        _record_doc_auto_gen('ai_employee_roster', 'mtscos_ai_employees', content,
                             gen_by=_u.get('username') or 'system',
                             metadata={'total': len(employees), 'active': active_count})
        return jsonify({'ok': True, 'data': {
            'total': len(employees), 'active_count': active_count,
            'inactive_count': len(employees) - active_count, 'employees': employees,
        }, 'message': f'共{len(employees)}名AI员工（活跃{active_count}名）'})
    except Exception as e:
        logger.warning(f'[docs][auto-ai-roster] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/auto/system_overview', methods=['GET'])
@system_container('api_docs_auto_system_overview', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_auto_system_overview():
    """自动生成系统概览文档（聚合路由/表/AI员工/文档/文案统计）"""
    try:
        _u = _current_safe_user()
        # 路由统计
        route_total, api_total, page_total = 0, 0, 0
        for rule in app.url_map.iter_rules():
            if rule.rule.startswith('/static/'):
                continue
            route_total += 1
            if rule.rule.startswith('/api/'):
                api_total += 1
            else:
                page_total += 1
        # 表统计
        table_count = 0
        with _get_conn(DATABASE_PATH) as c:
            try:
                table_count = c.execute(
                    "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
                ).fetchone()[0]
            except Exception:
                table_count = 0
        ai_total = _safe_count(APP_DB, "SELECT COUNT(*) FROM mtscos_ai_employees")
        ai_active = _safe_count(APP_DB, "SELECT COUNT(*) FROM mtscos_ai_employees WHERE is_active=1")
        _ensure_system_documents_ddls(); _ensure_copywriting_ddls()
        doc_total = _safe_count(DATABASE_PATH, "SELECT COUNT(*) FROM system_documents WHERE doc_status != 'deleted'")
        tpl_total = _safe_count(DATABASE_PATH, "SELECT COUNT(*) FROM system_copywriting_templates")
        rec_total = _safe_count(DATABASE_PATH, "SELECT COUNT(*) FROM system_copywriting_records")
        v, info, _ = get_version_info()
        overview = {
            'version': v, 'source': info.get('source'), 'database_path': DATABASE_PATH,
            'routes': {'total': route_total, 'api': api_total, 'page': page_total},
            'database': {'table_count': table_count, 'db_path': DATABASE_PATH},
            'ai_employees': {'total': ai_total, 'active': ai_active},
            'documents': {'total': doc_total},
            'copywriting': {'templates': tpl_total, 'records': rec_total},
            'generated_at': _mtscos_now(),
        }
        content = json.dumps(overview, ensure_ascii=False, indent=2)
        _record_doc_auto_gen('system_overview', 'aggregate', content,
                             gen_by=_u.get('username') or 'system', metadata=overview)
        return jsonify({'ok': True, 'data': overview, 'message': '系统概览文档已生成'})
    except Exception as e:
        logger.warning(f'[docs][auto-system-overview] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500

@app.route('/api/docs/auto/changelog', methods=['GET'])
@system_container('api_docs_auto_changelog', require_auth='login', inject_user_ctx=False, write_heartbeat=False)
def api_docs_auto_changelog():
    """自动生成变更日志（扫描 mtscos_version_history 真实版本记录）"""
    try:
        _u = _current_safe_user()
        limit = min(200, max(1, _docs_qs_int('limit', 50)))
        entries = []
        with _get_conn(APP_DB) as c:
            try:
                rows = c.execute(
                    "SELECT id, version, major, minor, patch, build, release_channel, "
                    "change_summary, changelog_json, git_commit_hash, git_tag, published_by, published_at "
                    "FROM mtscos_version_history ORDER BY published_at DESC, id DESC LIMIT ?",
                    (limit,)
                ).fetchall()
            except Exception:
                rows = []
            for r in rows:
                entry = dict(r)
                try:
                    entry['changelog'] = json.loads(entry.get('changelog_json') or '[]')
                except Exception:
                    entry['changelog'] = []
                entries.append(entry)
        content = json.dumps({'entry_count': len(entries), 'entries': entries},
                             ensure_ascii=False, indent=2)
        _record_doc_auto_gen('changelog', 'mtscos_version_history', content,
                             gen_by=_u.get('username') or 'system',
                             metadata={'entry_count': len(entries)})
        return jsonify({'ok': True, 'data': {
            'entry_count': len(entries), 'entries': entries,
        }, 'message': f'共{len(entries)}条变更记录'})
    except Exception as e:
        logger.warning(f'[docs][auto-changelog] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


