def _ensure_eigenflux_comm_ddls():
    """确保EigenFlux交流学习4张表存在（幂等DDL）"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS eigenflux_comm_sessions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                session_uid TEXT UNIQUE,
                session_type TEXT,
                total_employees INTEGER DEFAULT 0,
                total_groups INTEGER DEFAULT 0,
                status TEXT DEFAULT 'pending',
                started_at TEXT,
                completed_at TEXT,
                topics_json TEXT DEFAULT '[]',
                summary TEXT,
                metrics_json TEXT DEFAULT '{}',
                created_at TEXT,
                updated_at TEXT
            );
            CREATE TABLE IF NOT EXISTS eigenflux_comm_messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                session_id INTEGER,
                employee_id INTEGER,
                employee_name TEXT,
                employee_table TEXT,
                message_direction TEXT,
                message_type TEXT,
                message_content TEXT,
                knowledge_tags_json TEXT DEFAULT '[]',
                learning_value INTEGER DEFAULT 0,
                created_at TEXT
            );
            CREATE TABLE IF NOT EXISTS eigenflux_learning_outcomes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                session_id INTEGER,
                employee_id INTEGER,
                employee_name TEXT,
                employee_table TEXT,
                outcome_type TEXT,
                outcome_detail TEXT,
                skill_before TEXT,
                skill_after TEXT,
                knowledge_gained TEXT,
                brain_feed_topic TEXT,
                created_at TEXT
            );
            CREATE TABLE IF NOT EXISTS eigenflux_knowledge_broadcast (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                broadcast_uid TEXT UNIQUE,
                topic TEXT,
                content TEXT,
                target_departments_json TEXT DEFAULT '[]',
                target_count INTEGER DEFAULT 0,
                received_count INTEGER DEFAULT 0,
                acknowledged_count INTEGER DEFAULT 0,
                broadcast_type TEXT,
                priority INTEGER DEFAULT 5,
                created_at TEXT,
                expires_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_efcs_type ON eigenflux_comm_sessions(session_type);
            CREATE INDEX IF NOT EXISTS idx_efcs_status ON eigenflux_comm_sessions(status);
            CREATE INDEX IF NOT EXISTS idx_efcm_session ON eigenflux_comm_messages(session_id);
            CREATE INDEX IF NOT EXISTS idx_efcm_emp ON eigenflux_comm_messages(employee_id, employee_table);
            CREATE INDEX IF NOT EXISTS idx_eflo_session ON eigenflux_learning_outcomes(session_id);
            CREATE INDEX IF NOT EXISTS idx_eflo_emp ON eigenflux_learning_outcomes(employee_id, employee_table);
            CREATE INDEX IF NOT EXISTS idx_efkb_type ON eigenflux_knowledge_broadcast(broadcast_type);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[eigenflux][ddl] err: {e}')


