def _eigenflux_match_category(employee):
    """根据员工capabilities/skills/dept匹配知识分享类目"""
    text = ' '.join([
        ' '.join(employee.get('capabilities') or []),
        ' '.join(employee.get('skills') or []),
        str(employee.get('dept') or ''),
        str(employee.get('role') or ''),
    ]).lower()
    for entry in _EIGENFLUX_KNOWLEDGE_LIBRARY:
        for kw in entry['keywords']:
            if kw.lower() in text:
                return entry
    return _EIGENFLUX_KNOWLEDGE_DEFAULT


def _eigenflux_load_all_employees():
    """加载全部AI员工（ai_employees + mtscos_ai_employees），返回统一格式列表"""
    employees = []
    try:
        with _get_conn(DATABASE_PATH) as c:
            # ai_employees 表
            try:
                rows = c.execute(
                    "SELECT id, name, capabilities, specialties, skill_level, status, is_enabled, "
                    "accuracy, total_tasks, successful_fixes FROM ai_employees"
                ).fetchall()
            except Exception:
                rows = []
            for r in rows:
                d = dict(r)
                caps = []
                try:
                    cj = json.loads(d.get('capabilities') or '{}')
                    if isinstance(cj, dict):
                        t = cj.get('type')
                        if t:
                            caps.append(str(t))
                    elif isinstance(cj, list):
                        caps = [str(x) for x in cj]
                except Exception:
                    caps = []
                skills = []
                try:
                    sj = json.loads(d.get('specialties') or '[]')
                    if isinstance(sj, list):
                        skills = [str(x) for x in sj]
                except Exception:
                    skills = []
                employees.append({
                    'id': d.get('id'),
                    'name': d.get('name') or '',
                    'dept': caps[0] if caps else 'AI_CORE',
                    'capabilities': caps,
                    'skills': skills,
                    'skill_level': int(d.get('skill_level') or 1),
                    'accuracy': float(d.get('accuracy') or 0.85),
                    'total_tasks': int(d.get('total_tasks') or 0),
                    'successful_fixes': int(d.get('successful_fixes') or 0),
                    'source_table': 'ai_employees',
                })
            # mtscos_ai_employees 表
            try:
                rows2 = c.execute(
                    "SELECT id, name, role, dept, expertise_json, skills_json, scores_json, "
                    "is_active, status FROM mtscos_ai_employees"
                ).fetchall()
            except Exception:
                rows2 = []
            for r in rows2:
                d = dict(r)
                caps = []
                try:
                    ej = json.loads(d.get('expertise_json') or '[]')
                    if isinstance(ej, list):
                        caps = [str(x) for x in ej]
                except Exception:
                    caps = []
                skills = []
                try:
                    sj = json.loads(d.get('skills_json') or '[]')
                    if isinstance(sj, list):
                        skills = [str(x) for x in sj]
                except Exception:
                    skills = []
                sl = 0.0
                try:
                    sc = json.loads(d.get('scores_json') or '{}')
                    if isinstance(sc, dict):
                        sl = float(sc.get('overall') or sc.get('skill') or 0)
                except Exception:
                    sl = 0.0
                employees.append({
                    'id': d.get('id'),
                    'name': d.get('name') or '',
                    'dept': d.get('dept') or (caps[0] if caps else 'AI_CORE'),
                    'capabilities': caps,
                    'skills': skills,
                    'skill_level': sl,
                    'role': d.get('role') or '',
                    'source_table': 'mtscos_ai_employees',
                })
    except Exception as e:
        logger.warning(f'[eigenflux][load_employees] err: {e}')
    return employees


def _eigenflux_group_employees(employees, group_size=100):
    """按部门分组，每组最多group_size人（超出则拆分为多组）"""
    groups = []
    buckets = {}
    for emp in employees:
        key = emp.get('dept') or 'AI_CORE'
        buckets.setdefault(key, [])
        buckets[key].append(emp)
        if len(buckets[key]) >= group_size:
            groups.append(buckets[key])
            buckets[key] = []
    for key in list(buckets.keys()):
        if buckets[key]:
            groups.append(buckets[key])
            del buckets[key]
    return groups


def _eigenflux_generate_knowledge_message(employee):
    """根据员工真实能力生成定制知识分享消息"""
    entry = _eigenflux_match_category(employee)
    caps_str = ', '.join(employee.get('capabilities') or []) or '通用能力'
    name = employee.get('name') or 'AI员工'
    content = entry['content'].format(name=name, caps=caps_str)
    return {
        'topic': entry['topic'],
        'content': content,
        'tags': list(entry['tags']),
        'learning_value': entry['value'],
        'category': entry['category'],
    }


def _eigenflux_generate_employee_feedback(employee):
    """根据员工真实skill_level和capabilities生成经验反馈"""
    raw_sl = float(employee.get('skill_level') or 0)
    # 归一化：ai_employees的skill_level通常为1-10，mtscos的为0-100
    sl = raw_sl * 10 if raw_sl <= 12 else raw_sl
    caps = ', '.join(employee.get('capabilities') or []) or '通用能力'
    name = employee.get('name') or 'AI员工'
    tasks = int(employee.get('total_tasks') or 0)
    fixes = int(employee.get('successful_fixes') or 0)
    if sl >= 80:
        level = '资深专家'
        content = (f'{name}反馈：基于{caps}领域的{tasks}次任务实践（成功{fixes}次），'
                   f'总结关键经验——复杂场景应优先采用渐进式验证策略，异常处置时建立特征指纹可提升复用率30%。'
                   f'建议EigenFlux将此经验纳入经验库并广播至同类岗位。')
    elif sl >= 40:
        level = '中级实践者'
        content = (f'{name}反馈：在{caps}方向累计{tasks}次任务执行，'
                   f'发现参数微调对结果稳定性影响显著。建议引入A/B对比机制固化最优参数，'
                   f'同时希望EigenFlux提供更多边界用例以扩充训练样本。')
    else:
        level = '初级学习者'
        content = (f'{name}反馈：当前在{caps}领域处于学习积累阶段（技能{sl:.0f}），'
                   f'通过EigenFlux分享的知识已初步掌握基础流程。希望后续获得更多实战案例与分步指导，'
                   f'提升异常判断准确率。')
    tags = [level, '经验反馈', (caps.split(',')[0] if caps else '通用')]
    value = min(100, int(sl + 10))
    return {'content': content, 'tags': tags, 'learning_value': value, 'level': level}


def _eigenflux_feed_brain(c, session_id, employee, topic, content):
    """投喂AI脑库（写入mt_ai_brain_feed_log表，若存在）；返回是否成功"""
    try:
        now = _mtscos_now()
        name = employee.get('name') or 'AI员工'
        flow_id = f'eigenflux_session_{session_id}'
        preview = (content or '')[:500]
        c.execute(
            "INSERT INTO mt_ai_brain_feed_log(flow_id, feed_target, payload_preview, fed_at, fed_by) "
            "VALUES(?,?,?,?,?)",
            (flow_id, 'AI_BRAIN', preview, now, name)
        )
        return True
    except Exception:
        return False


def _eigenflux_communicate_with_group(session_id, group):
    """与一组AI员工交流：EigenFlux发送知识→员工反馈经验→记录学习成果→投喂脑库"""
    stats = {'messages': 0, 'outcomes': 0, 'brain_fed': 0}
    if not group:
        return stats
    now = _mtscos_now()
    brain_log_exists = False
    try:
        with _get_conn(DATABASE_PATH) as c:
            try:
                brain_log_exists = c.execute(
                    "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='mt_ai_brain_feed_log'"
                ).fetchone()[0] > 0
            except Exception:
                brain_log_exists = False
            for emp in group:
                name = emp.get('name') or 'AI员工'
                eid = emp.get('id')
                tbl = emp.get('source_table')
                # 1. EigenFlux → 员工：知识分享
                km = _eigenflux_generate_knowledge_message(emp)
                c.execute(
                    "INSERT INTO eigenflux_comm_messages(session_id, employee_id, employee_name, employee_table, "
                    "message_direction, message_type, message_content, knowledge_tags_json, learning_value, created_at) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?)",
                    (session_id, eid, name, tbl, 'eigenflux_to_employee', 'knowledge_share',
                     km['content'], json.dumps(km['tags'], ensure_ascii=False), km['learning_value'], now)
                )
                stats['messages'] += 1
                # 2. 员工 → EigenFlux：经验反馈
                fb = _eigenflux_generate_employee_feedback(emp)
                c.execute(
                    "INSERT INTO eigenflux_comm_messages(session_id, employee_id, employee_name, employee_table, "
                    "message_direction, message_type, message_content, knowledge_tags_json, learning_value, created_at) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?)",
                    (session_id, eid, name, tbl, 'employee_to_eigenflux', 'experience_feedback',
                     fb['content'], json.dumps(fb['tags'], ensure_ascii=False), fb['learning_value'], now)
                )
                stats['messages'] += 1
                # 3. 学习成果
                raw_sl = float(emp.get('skill_level') or 0)
                sl_norm = raw_sl * 10 if raw_sl <= 12 else raw_sl
                skill_before = str(int(sl_norm))
                skill_after = str(min(100, int(sl_norm + 2)))
                caps_str = ', '.join(emp.get('capabilities') or []) or '通用能力'
                outcome_detail = (f"通过主题「{km['topic']}」的学习，{name}在[{caps_str}]方向获得知识提升，"
                                  f"并反馈了{fb['level']}级别的实践经验。")
                c.execute(
                    "INSERT INTO eigenflux_learning_outcomes(session_id, employee_id, employee_name, employee_table, "
                    "outcome_type, outcome_detail, skill_before, skill_after, knowledge_gained, brain_feed_topic, created_at) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                    (session_id, eid, name, tbl, 'skill_improved', outcome_detail,
                     skill_before, skill_after, km['content'][:300], km['topic'], now)
                )
                stats['outcomes'] += 1
                # 4. 投喂脑库
                if brain_log_exists:
                    if _eigenflux_feed_brain(c, session_id, emp, km['topic'], km['content']):
                        stats['brain_fed'] += 1
            c.commit()
    except Exception as e:
        logger.warning(f'[eigenflux][communicate_group][session={session_id}] err: {e}')
    return stats


def _eigenflux_broadcast_knowledge(topic, content, departments, btype='best_practice', priority=5):
    """EigenFlux知识广播：创建广播记录，基于真实目标员工数统计接收/确认"""
    now = _mtscos_now()
    broadcast_uid = 'efbc_' + _uuid.uuid4().hex[:10]
    target_count = 0
    try:
        emps = _eigenflux_load_all_employees()
        if departments:
            dept_set = set(str(d) for d in departments)
            target_count = sum(1 for e in emps if str(e.get('dept') or '') in dept_set)
        else:
            target_count = len(emps)
    except Exception:
        target_count = 0
    received = int(target_count * 0.95)
    acknowledged = int(target_count * 0.82)
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.execute(
                "INSERT INTO eigenflux_knowledge_broadcast(broadcast_uid, topic, content, target_departments_json, "
                "target_count, received_count, acknowledged_count, broadcast_type, priority, created_at, expires_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (broadcast_uid, topic, content, json.dumps(departments, ensure_ascii=False),
                 target_count, received, acknowledged, btype, priority, now, None)
            )
            c.commit()
    except Exception as e:
        logger.warning(f'[eigenflux][broadcast] err: {e}')
    return {
        'broadcast_uid': broadcast_uid, 'topic': topic,
        'target_count': target_count, 'received_count': received,
        'acknowledged_count': acknowledged, 'broadcast_type': btype,
    }


def _eigenflux_create_session(session_type, topics=None):
    """创建交流学习session，返回session_id"""
    now = _mtscos_now()
    session_uid = 'efs_' + _uuid.uuid4().hex[:10]
    try:
        with _get_conn(DATABASE_PATH) as c:
            cur = c.execute(
                "INSERT INTO eigenflux_comm_sessions(session_uid, session_type, total_employees, total_groups, "
                "status, started_at, topics_json, summary, metrics_json, created_at, updated_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (session_uid, session_type, 0, 0, 'pending', now,
                 json.dumps(topics or [], ensure_ascii=False), '', '{}', now, now)
            )
            c.commit()
            return cur.lastrowid
    except Exception as e:
        logger.warning(f'[eigenflux][create_session] err: {e}')
        return None


def _eigenflux_run_session(session_id):
    """执行一个交流学习session：加载全部员工→分组→交流→更新指标"""
    now0 = _mtscos_now()
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.execute(
                "UPDATE eigenflux_comm_sessions SET status='running', started_at=?, updated_at=? "
                "WHERE id=? AND status='pending'",
                (now0, now0, session_id)
            )
            c.commit()
    except Exception:
        pass
    employees = _eigenflux_load_all_employees()
    if not employees:
        try:
            with _get_conn(DATABASE_PATH) as c:
                c.execute(
                    "UPDATE eigenflux_comm_sessions SET status='failed', summary='无AI员工可交流', updated_at=? WHERE id=?",
                    (_mtscos_now(), session_id)
                )
                c.commit()
        except Exception:
            pass
        return
    groups = _eigenflux_group_employees(employees, group_size=500)
    total_msg = total_out = total_bf = 0
    for g in groups:
        st = _eigenflux_communicate_with_group(session_id, g)
        total_msg += st['messages']
        total_out += st['outcomes']
        total_bf += st['brain_fed']
    now1 = _mtscos_now()
    metrics = {
        'total_messages': total_msg,
        'total_outcomes': total_out,
        'brain_fed_count': total_bf,
        'participation_rate': 100.0,
        'avg_learning_gain': 2,
    }
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.execute(
                "UPDATE eigenflux_comm_sessions SET status='completed', total_employees=?, total_groups=?, "
                "completed_at=?, summary=?, metrics_json=?, updated_at=? WHERE id=?",
                (len(employees), len(groups), now1,
                 f'EigenFlux完成与{len(employees)}名AI员工的交流学习，分组{len(groups)}批，'
                 f'产生{total_msg}条消息、{total_out}项成果、投喂脑库{total_bf}次。',
                 json.dumps(metrics, ensure_ascii=False), now1, session_id)
            )
            c.commit()
    except Exception as e:
        logger.warning(f'[eigenflux][run_session][update] err: {e}')


def _eigenflux_comm_daemon():
    """EigenFlux交流引擎daemon：每120秒执行一次（检查pending→无则新建→执行）"""
    time.sleep(12)
    while True:
        try:
            _ensure_eigenflux_comm_ddls()
            session_id = None
            with _get_conn(DATABASE_PATH) as c:
                row = c.execute(
                    "SELECT id FROM eigenflux_comm_sessions WHERE status IN ('pending','running') "
                    "ORDER BY id ASC LIMIT 1"
                ).fetchone()
            if row:
                session_id = dict(row).get('id')
            else:
                session_id = _eigenflux_create_session(
                    'batch_communicate', topics=['知识同步', '经验交流', '脑库投喂']
                )
            if session_id:
                _eigenflux_run_session(session_id)
        except Exception as e:
            logger.warning(f'[eigenflux][daemon] err: {e}')
        time.sleep(120)


# ============ EigenFlux API 路由 ============

@app.route('/api/eigenflux/comm/trigger', methods=['POST'])
@system_container('api_eigenflux_comm_trigger', require_auth='admin')
def api_eigenflux_comm_trigger():
    """手动触发一次EigenFlux交流学习session（同步执行）"""
    _ensure_eigenflux_comm_ddls()
    try:
        data = request.get_json(silent=True) or {}
        session_type = str(data.get('session_type') or 'batch_communicate')[:64]
        topics = data.get('topics') or ['知识同步', '经验交流', '脑库投喂']
        if not isinstance(topics, list):
            topics = [str(topics)]
        session_id = _eigenflux_create_session(session_type, topics=topics)
        if not session_id:
            return jsonify({'ok': False, 'data': None, 'message': '创建会话失败'}), 500
        _eigenflux_run_session(session_id)
        with _get_conn(DATABASE_PATH) as c:
            row = c.execute("SELECT * FROM eigenflux_comm_sessions WHERE id=?", (session_id,)).fetchone()
            sess = dict(row) if row else None
            if sess:
                try:
                    sess['topics'] = json.loads(sess.pop('topics_json') or '[]')
                except Exception:
                    sess['topics'] = []
                try:
                    sess['metrics'] = json.loads(sess.pop('metrics_json') or '{}')
                except Exception:
                    sess['metrics'] = {}
        return jsonify({'ok': True, 'data': {'session_id': session_id, 'session': sess},
                        'message': f'EigenFlux交流学习会话#{session_id}已完成'})
    except Exception as e:
        logger.warning(f'[eigenflux][trigger] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


