@app.route('/api/eigenflux/comm/stats')
@system_container('api_eigenflux_comm_stats', require_auth='login')
def api_eigenflux_comm_stats():
    """EigenFlux交流学习统计"""
    _ensure_eigenflux_comm_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            total_sessions = c.execute("SELECT COUNT(*) FROM eigenflux_comm_sessions").fetchone()[0]
            completed_sessions = c.execute(
                "SELECT COUNT(*) FROM eigenflux_comm_sessions WHERE status='completed'"
            ).fetchone()[0]
            running_sessions = c.execute(
                "SELECT COUNT(*) FROM eigenflux_comm_sessions WHERE status='running'"
            ).fetchone()[0]
            total_messages = c.execute("SELECT COUNT(*) FROM eigenflux_comm_messages").fetchone()[0]
            total_outcomes = c.execute("SELECT COUNT(*) FROM eigenflux_learning_outcomes").fetchone()[0]
            total_broadcasts = c.execute("SELECT COUNT(*) FROM eigenflux_knowledge_broadcast").fetchone()[0]
            total_employees_comm = 0
            try:
                total_employees_comm = c.execute(
                    "SELECT COUNT(*) FROM (SELECT DISTINCT employee_id, employee_table "
                    "FROM eigenflux_comm_messages WHERE employee_id IS NOT NULL)"
                ).fetchone()[0]
            except Exception:
                total_employees_comm = 0
            dept_stats = {}
            try:
                rows = c.execute(
                    "SELECT dept, COUNT(*) AS cnt FROM mtscos_ai_employees WHERE is_active=1 GROUP BY dept"
                ).fetchall()
                for r in rows:
                    dept_stats[r['dept'] or '未知'] = r['cnt']
            except Exception:
                pass
            ai_emp_count = 0
            try:
                ai_emp_count += c.execute("SELECT COUNT(*) FROM ai_employees").fetchone()[0]
            except Exception:
                pass
            try:
                ai_emp_count += c.execute("SELECT COUNT(*) FROM mtscos_ai_employees").fetchone()[0]
            except Exception:
                pass
            outcome_by_type = {}
            try:
                rows = c.execute(
                    "SELECT outcome_type, COUNT(*) AS cnt FROM eigenflux_learning_outcomes GROUP BY outcome_type"
                ).fetchall()
                for r in rows:
                    outcome_by_type[r['outcome_type'] or 'unknown'] = r['cnt']
            except Exception:
                pass
        return jsonify({'ok': True, 'data': {
            'total_sessions': total_sessions,
            'completed_sessions': completed_sessions,
            'running_sessions': running_sessions,
            'total_messages': total_messages,
            'total_outcomes': total_outcomes,
            'total_broadcasts': total_broadcasts,
            'total_employees_communicated': total_employees_comm,
            'total_ai_employees': ai_emp_count,
            'dept_stats': dept_stats,
            'outcome_by_type': outcome_by_type,
        }, 'message': f'共{total_sessions}个会话，{total_messages}条消息，{total_outcomes}项成果'})
    except Exception as e:
        logger.warning(f'[eigenflux][stats] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


@app.route('/api/eigenflux/comm/full_sync', methods=['POST'])
@system_container('api_eigenflux_comm_full_sync', require_auth='admin')
def api_eigenflux_comm_full_sync():
    """全量交流学习（与所有AI员工交流，后台分批500人执行）"""
    _ensure_eigenflux_comm_ddls()
    try:
        data = request.get_json(silent=True) or {}
        topics = data.get('topics') or ['全量知识同步', '全员经验交流', '脑库全量投喂']
        if not isinstance(topics, list):
            topics = [str(topics)]
        session_id = _eigenflux_create_session('knowledge_sharing', topics=topics)
        if not session_id:
            return jsonify({'ok': False, 'data': None, 'message': '创建会话失败'}), 500

        def _full_sync_worker(sid):
            try:
                _eigenflux_run_session(sid)
            except Exception as ex:
                logger.warning(f'[eigenflux][full_sync_worker] err: {ex}')

        _thr_sysai.Thread(target=_full_sync_worker, args=(session_id,),
                          name='eigenflux-fullsync', daemon=True).start()
        return jsonify({'ok': True, 'data': {
            'session_id': session_id, 'status': 'pending',
            'note': '全量同步已在后台启动，可通过会话详情接口跟踪进度',
        }, 'message': f'全量交流学习会话#{session_id}已启动'})
    except Exception as e:
        logger.warning(f'[eigenflux][full_sync] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


