@app.route('/api/auto_upgrade/stats')
@system_container('api_auto_upgrade_stats', require_auth='login')
def api_auto_upgrade_stats():
    """统计：总升级次数/成功/失败/平均耗时/版本分布"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            total = c.execute("SELECT COUNT(*) FROM system_auto_upgrade_logs").fetchone()[0]
            completed = c.execute("SELECT COUNT(*) FROM system_auto_upgrade_logs WHERE status='completed'").fetchone()[0]
            failed = c.execute("SELECT COUNT(*) FROM system_auto_upgrade_logs WHERE status='failed'").fetchone()[0]
            running = c.execute("SELECT COUNT(*) FROM system_auto_upgrade_logs WHERE status='running'").fetchone()[0]
            pending = c.execute("SELECT COUNT(*) FROM system_auto_upgrade_logs WHERE status='pending'").fetchone()[0]
            try:
                vrows = c.execute("SELECT upgrade_type, COUNT(*) AS cnt FROM system_auto_upgrade_logs GROUP BY upgrade_type").fetchall()
                version_dist = {r[0] or 'unknown': r[1] for r in vrows}
            except Exception:
                version_dist = {}
            avg_duration_s = 0
            try:
                rows = c.execute("SELECT started_at, completed_at FROM system_auto_upgrade_logs WHERE status='completed' AND started_at IS NOT NULL AND completed_at IS NOT NULL LIMIT 100").fetchall()
                durations = []
                for r in rows:
                    try:
                        s = datetime.strptime(r[0], '%Y-%m-%d %H:%M:%S')
                        e = datetime.strptime(r[1], '%Y-%m-%d %H:%M:%S')
                        durations.append((e - s).total_seconds())
                    except Exception:
                        pass
                if durations:
                    avg_duration_s = sum(durations) / len(durations)
            except Exception:
                pass
            recent = c.execute("SELECT upgrade_uid, current_version, target_version, upgrade_type, status, created_at FROM system_auto_upgrade_logs ORDER BY id DESC LIMIT 5").fetchall()
            recent_list = [dict(r) for r in recent]
        return jsonify({'ok': True, 'data': {
            'total': total, 'completed': completed, 'failed': failed,
            'running': running, 'pending': pending,
            'success_rate': round(completed / total * 100, 1) if total else 0,
            'avg_duration_s': round(avg_duration_s, 1),
            'version_distribution': version_dist,
            'recent': recent_list,
        }, 'message': '升级统计'})
    except Exception as e:
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


