# ============================================================
# 模块1: 智能预警与危机响应系统（system_crisis_alerts / system_risk_predictions）
# ============================================================

def _ensure_crisis_ddls():
    """确保危机预警相关表存在（幂等）"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS system_crisis_alerts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                alert_uid TEXT UNIQUE,
                alert_level TEXT,
                alert_type TEXT,
                alert_source TEXT,
                alert_title TEXT,
                alert_content TEXT,
                alert_metrics_json TEXT DEFAULT '{}',
                predicted_failure TEXT,
                recommended_actions_json TEXT DEFAULT '[]',
                auto_response_triggered INTEGER DEFAULT 0,
                response_status TEXT DEFAULT 'pending',
                response_actions_json TEXT DEFAULT '[]',
                resolved_at TEXT,
                resolved_by TEXT,
                created_at TEXT,
                updated_at TEXT
            );
            CREATE TABLE IF NOT EXISTS system_risk_predictions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                prediction_uid TEXT UNIQUE,
                prediction_type TEXT,
                target_component TEXT,
                risk_score INTEGER DEFAULT 0,
                risk_factors_json TEXT DEFAULT '[]',
                prediction_confidence REAL DEFAULT 0.0,
                predicted_event TEXT,
                time_window TEXT,
                mitigation_plan_json TEXT DEFAULT '[]',
                status TEXT DEFAULT 'active',
                created_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_sca_level ON system_crisis_alerts(alert_level);
            CREATE INDEX IF NOT EXISTS idx_sca_type ON system_crisis_alerts(alert_type);
            CREATE INDEX IF NOT EXISTS idx_sca_status ON system_crisis_alerts(response_status);
            CREATE INDEX IF NOT EXISTS idx_srp_status ON system_risk_predictions(status);
            CREATE INDEX IF NOT EXISTS idx_srp_target ON system_risk_predictions(target_component);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[crisis][ddl] err: {e}')


def _crisis_scan_system_health():
    """扫描system_heartbeat表，检测DEAD/异常组件，返回 (alerts_list, risk_factors_list)"""
    alerts = []
    risk_factors = []
    try:
        _ensure_system_heartbeat_ddls()
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT h.* FROM system_heartbeat h INNER JOIN "
                "(SELECT component_name, MAX(id) AS mid FROM system_heartbeat GROUP BY component_name) m "
                "ON h.id = m.mid"
            ).fetchall()
        now = datetime.now()
        for r in rows:
            d = dict(r)
            comp = d.get('component_name') or 'unknown'
            status = (d.get('status') or 'ALIVE').upper()
            health = float(d.get('health_score') or 100)
            last_beat = d.get('last_beat_at') or ''
            interval = int(d.get('beat_interval_sec') or 30)
            is_dead = False
            stale_sec = 0
            if last_beat:
                try:
                    lb = datetime.strptime(last_beat[:19], '%Y-%m-%d %H:%M:%S')
                    stale_sec = (now - lb).total_seconds()
                    if stale_sec > interval * 3:
                        is_dead = True
                except Exception:
                    pass
            if status == 'DEAD' or is_dead or health < 60:
                level = 'EMERGENCY' if (is_dead or status == 'DEAD') else ('CRITICAL' if health < 40 else 'WARNING')
                risk_score = max(0, min(100, int(100 - health + (stale_sec / max(interval, 1)) * 10)))
                alert_uid = 'ca_' + _uuid.uuid4().hex[:12]
                metrics = {
                    'component': comp, 'status': status, 'health_score': health,
                    'last_beat_at': last_beat, 'stale_seconds': int(stale_sec),
                    'beat_interval_sec': interval,
                }
                alerts.append({
                    'alert_uid': alert_uid,
                    'alert_level': level,
                    'alert_type': 'system_health',
                    'alert_source': comp,
                    'alert_title': f'组件 {comp} 健康异常',
                    'alert_content': f'组件 {comp} 状态={status}, 健康分={health}, 超时{int(stale_sec)}秒',
                    'alert_metrics_json': json.dumps(metrics, ensure_ascii=False),
                    'predicted_failure': f'{comp} 可能停止响应' if is_dead else f'{comp} 性能下降',
                    'recommended_actions_json': json.dumps(['检查组件进程', '重启组件', '通知AI员工介入'], ensure_ascii=False),
                })
                risk_factors.append({'component': comp, 'risk_score': risk_score,
                                     'factor': f'stale={int(stale_sec)}s, health={health}'})
    except Exception as e:
        logger.warning(f'[crisis][scan_health] err: {e}')
    return alerts, risk_factors


def _crisis_scan_eigenflux_anomalies():
    """扫描eigenflux_comm_messages检测异常模式（高频错误/异常关键词）"""
    alerts = []
    try:
        cutoff = (datetime.now() - timedelta(hours=1)).strftime('%Y-%m-%d %H:%M:%S')
        with _get_conn(DATABASE_PATH) as c:
            try:
                rows = c.execute(
                    "SELECT employee_name, COUNT(*) AS cnt, "
                    "SUM(CASE WHEN message_content LIKE '%error%' OR message_content LIKE '%异常%' "
                    "OR message_content LIKE '%失败%' THEN 1 ELSE 0 END) AS err_cnt "
                    "FROM eigenflux_comm_messages WHERE created_at >= ? "
                    "GROUP BY employee_name HAVING err_cnt > 5 ORDER BY err_cnt DESC LIMIT 20",
                    (cutoff,)
                ).fetchall()
            except Exception:
                rows = []
        for r in rows:
            d = dict(r)
            name = d.get('employee_name') or '未知'
            err_cnt = int(d.get('err_cnt') or 0)
            if err_cnt > 5:
                alert_uid = 'ca_' + _uuid.uuid4().hex[:12]
                risk_score = min(100, err_cnt * 5)
                level = 'EMERGENCY' if risk_score >= 80 else ('CRITICAL' if risk_score >= 50 else 'WARNING')
                metrics = {'employee_name': name, 'error_count': err_cnt, 'window': '1h'}
                alerts.append({
                    'alert_uid': alert_uid,
                    'alert_level': level,
                    'alert_type': 'ai_employee',
                    'alert_source': name,
                    'alert_title': f'AI员工 {name} 异常消息激增',
                    'alert_content': f'{name} 在最近1小时产生 {err_cnt} 条异常相关消息',
                    'alert_metrics_json': json.dumps(metrics, ensure_ascii=False),
                    'predicted_failure': f'{name} 可能存在任务执行异常',
                    'recommended_actions_json': json.dumps(['检查员工任务队列', '降级处理', '通知主管AI'], ensure_ascii=False),
                })
    except Exception as e:
        logger.warning(f'[crisis][scan_eigenflux] err: {e}')
    return alerts


def _crisis_predict_risks():
    """基于历史数据预测风险（查询最近的error logs, heartbeat failures等）"""
    predictions = []
    try:
        with _get_conn(DATABASE_PATH) as c:
            try:
                rows = c.execute(
                    "SELECT component_name, AVG(health_score) AS avg_health, COUNT(*) AS beat_count, "
                    "SUM(CASE WHEN status='DEAD' THEN 1 ELSE 0 END) AS dead_count "
                    "FROM system_heartbeat GROUP BY component_name"
                ).fetchall()
            except Exception:
                rows = []
        for r in rows:
            d = dict(r)
            comp = d.get('component_name') or 'unknown'
            avg_h = float(d.get('avg_health') or 100)
            dead_cnt = int(d.get('dead_count') or 0)
            risk_score = max(0, min(100, int(100 - avg_h + dead_cnt * 10)))
            if risk_score >= 30:
                pred_uid = 'rp_' + _uuid.uuid4().hex[:12]
                factors = [f'avg_health={avg_h:.1f}', f'dead_beats={dead_cnt}']
                confidence = min(1.0, risk_score / 100.0 + 0.1)
                predictions.append({
                    'prediction_uid': pred_uid,
                    'prediction_type': 'component_failure',
                    'target_component': comp,
                    'risk_score': risk_score,
                    'risk_factors_json': json.dumps(factors, ensure_ascii=False),
                    'prediction_confidence': round(confidence, 2),
                    'predicted_event': f'{comp} 可能在未来24小时内出现响应异常',
                    'time_window': '24h',
                    'mitigation_plan_json': json.dumps(['提前重启组件', '增加监控频率', '准备故障切换'], ensure_ascii=False),
                })
        cutoff = (datetime.now() - timedelta(hours=24)).strftime('%Y-%m-%d %H:%M:%S')
        with _get_conn(DATABASE_PATH) as c:
            try:
                rows = c.execute(
                    "SELECT employee_name, COUNT(*) AS cnt FROM eigenflux_comm_messages "
                    "WHERE created_at >= ? AND (message_content LIKE '%error%' OR message_content LIKE '%异常%') "
                    "GROUP BY employee_name HAVING cnt > 10 ORDER BY cnt DESC LIMIT 10",
                    (cutoff,)
                ).fetchall()
            except Exception:
                rows = []
        for r in rows:
            d = dict(r)
            name = d.get('employee_name') or 'unknown'
            cnt = int(d.get('cnt') or 0)
            risk_score = min(100, cnt * 3)
            if risk_score >= 30:
                pred_uid = 'rp_' + _uuid.uuid4().hex[:12]
                predictions.append({
                    'prediction_uid': pred_uid,
                    'prediction_type': 'ai_employee_degradation',
                    'target_component': name,
                    'risk_score': risk_score,
                    'risk_factors_json': json.dumps([f'24h_error_msgs={cnt}'], ensure_ascii=False),
                    'prediction_confidence': round(min(1.0, cnt / 50.0 + 0.2), 2),
                    'predicted_event': f'{name} 可能在未来任务中持续出现异常',
                    'time_window': '48h',
                    'mitigation_plan_json': json.dumps(['暂停高风险任务', '触发技能重训', '降低任务权重'], ensure_ascii=False),
                })
        if predictions:
            now = _mtscos_now()
            with _get_conn(DATABASE_PATH) as c:
                for p in predictions:
                    c.execute(
                        "INSERT INTO system_risk_predictions "
                        "(prediction_uid, prediction_type, target_component, risk_score, risk_factors_json, "
                        "prediction_confidence, predicted_event, time_window, mitigation_plan_json, status, created_at) "
                        "VALUES (?,?,?,?,?,?,?,?,?, 'active', ?)",
                        (p['prediction_uid'], p['prediction_type'], p['target_component'], p['risk_score'],
                         p['risk_factors_json'], p['prediction_confidence'], p['predicted_event'],
                         p['time_window'], p['mitigation_plan_json'], now)
                    )
                c.commit()
    except Exception as e:
        logger.warning(f'[crisis][predict] err: {e}')
    return predictions


def _crisis_persist_alerts(alerts):
    """将扫描出的预警落库"""
    if not alerts:
        return []
    now = _mtscos_now()
    saved_ids = []
    try:
        with _get_conn(DATABASE_PATH) as c:
            for a in alerts:
                cur = c.execute(
                    "INSERT INTO system_crisis_alerts "
                    "(alert_uid, alert_level, alert_type, alert_source, alert_title, alert_content, "
                    "alert_metrics_json, predicted_failure, recommended_actions_json, "
                    "auto_response_triggered, response_status, response_actions_json, created_at, updated_at) "
                    "VALUES (?,?,?,?,?,?,?,?,?, 0, 'pending', '[]', ?, ?)",
                    (a['alert_uid'], a['alert_level'], a['alert_type'], a['alert_source'],
                     a['alert_title'], a['alert_content'], a['alert_metrics_json'],
                     a['predicted_failure'], a['recommended_actions_json'], now, now)
                )
                saved_ids.append(cur.lastrowid)
            c.commit()
    except Exception as e:
        logger.warning(f'[crisis][persist] err: {e}')
    return saved_ids


def _crisis_auto_respond(alert_id):
    """自动响应预警（重启组件/通知AI员工/触发修复计划）"""
    actions = []
    try:
        with _get_conn(DATABASE_PATH) as c:
            row = c.execute(
                "SELECT id, alert_level, alert_type, alert_source, alert_title FROM system_crisis_alerts WHERE id=?",
                (alert_id,)
            ).fetchone()
            if not row:
                return {'ok': False, 'message': '预警不存在'}
            d = dict(row)
            now = _mtscos_now()
            if d['alert_type'] == 'system_health':
                actions.append(f"已标记组件 {d['alert_source']} 为待重启")
                try:
                    c.execute(
                        "UPDATE system_heartbeat SET status='ALIVE', updated_at=? "
                        "WHERE component_name=? AND id=(SELECT MAX(id) FROM system_heartbeat WHERE component_name=?)",
                        (now, d['alert_source'], d['alert_source'])
                    )
                    actions.append(f"已重置组件 {d['alert_source']} 心跳状态")
                except Exception:
                    pass
            elif d['alert_type'] == 'ai_employee':
                actions.append(f"已通知AI员工 {d['alert_source']} 的主管")
            if d['alert_level'] in ('CRITICAL', 'EMERGENCY'):
                actions.append('已升级至AI员工代表团评估')
            c.execute(
                "UPDATE system_crisis_alerts SET auto_response_triggered=1, response_status='responding', "
                "response_actions_json=?, updated_at=? WHERE id=?",
                (json.dumps(actions, ensure_ascii=False), now, alert_id)
            )
            c.commit()
    except Exception as e:
        logger.warning(f'[crisis][auto_respond] err: {e}')
        return {'ok': False, 'message': str(e)}
    return {'ok': True, 'actions': actions, 'message': '自动响应已触发'}


_crisis_daemon_running = False

def _crisis_daemon():
    """daemon线程，每60秒扫描一次系统健康与异常"""
    import time as _t_crisis
    global _crisis_daemon_running
    _t_crisis.sleep(60)
    while True:
        try:
            if not _crisis_daemon_running:
                _crisis_daemon_running = True
                try:
                    alerts1, _ = _crisis_scan_system_health()
                    alerts2 = _crisis_scan_eigenflux_anomalies()
                    all_alerts = alerts1 + alerts2
                    _crisis_persist_alerts(all_alerts)
                    _crisis_predict_risks()
                    if all_alerts:
                        with _get_conn(DATABASE_PATH) as c:
                            critical_rows = c.execute(
                                "SELECT id FROM system_crisis_alerts WHERE response_status='pending' "
                                "AND alert_level IN ('EMERGENCY','CRITICAL') ORDER BY id DESC LIMIT 10"
                            ).fetchall()
                        for r in critical_rows:
                            _crisis_auto_respond(int(dict(r)['id']))
                finally:
                    _crisis_daemon_running = False
        except Exception as e:
            logger.warning(f'[crisis][daemon] err: {e}')
        _t_crisis.sleep(60)


