@app.route('/api/crisis/dashboard')
@system_container('api_crisis_dashboard', require_auth='login')
def api_crisis_dashboard():
    """危机响应仪表盘（总预警数/活跃预警/已解决/自动响应率/风险趋势）"""
    _ensure_crisis_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            total = c.execute("SELECT COUNT(*) FROM system_crisis_alerts").fetchone()[0]
            active = c.execute("SELECT COUNT(*) FROM system_crisis_alerts WHERE response_status IN ('pending','responding','escalated')").fetchone()[0]
            resolved = c.execute("SELECT COUNT(*) FROM system_crisis_alerts WHERE response_status='resolved'").fetchone()[0]
            auto_resp = c.execute("SELECT COUNT(*) FROM system_crisis_alerts WHERE auto_response_triggered=1").fetchone()[0]
            emergency = c.execute("SELECT COUNT(*) FROM system_crisis_alerts WHERE alert_level='EMERGENCY' AND response_status!='resolved'").fetchone()[0]
            critical = c.execute("SELECT COUNT(*) FROM system_crisis_alerts WHERE alert_level='CRITICAL' AND response_status!='resolved'").fetchone()[0]
            level_rows = c.execute("SELECT alert_level, COUNT(*) AS cnt FROM system_crisis_alerts GROUP BY alert_level").fetchall()
            type_rows = c.execute("SELECT alert_type, COUNT(*) AS cnt FROM system_crisis_alerts GROUP BY alert_type").fetchall()
            cutoff_7d = (datetime.now() - timedelta(days=7)).strftime('%Y-%m-%d %H:%M:%S')
            trend_rows = c.execute(
                "SELECT substr(created_at,1,10) AS day, COUNT(*) AS cnt FROM system_crisis_alerts "
                "WHERE created_at >= ? GROUP BY day ORDER BY day",
                (cutoff_7d,)
            ).fetchall()
            active_preds = c.execute("SELECT COUNT(*) FROM system_risk_predictions WHERE status='active'").fetchone()[0]
            high_risk_preds = c.execute("SELECT COUNT(*) FROM system_risk_predictions WHERE status='active' AND risk_score>=70").fetchone()[0]
        auto_rate = round((auto_resp / total * 100), 1) if total else 0.0
        return jsonify({'ok': True, 'data': {
            'total_alerts': total, 'active_alerts': active, 'resolved_alerts': resolved,
            'emergency_alerts': emergency, 'critical_alerts': critical,
            'auto_response_count': auto_resp, 'auto_response_rate': auto_rate,
            'active_predictions': active_preds, 'high_risk_predictions': high_risk_preds,
            'by_level': {dict(r)['alert_level']: dict(r)['cnt'] for r in level_rows},
            'by_type': {dict(r)['alert_type']: dict(r)['cnt'] for r in type_rows},
            'trend_7d': [{'day': dict(r)['day'], 'count': dict(r)['cnt']} for r in trend_rows],
        }, 'message': '危机响应仪表盘'})
    except Exception as e:
        logger.warning(f'[crisis][dashboard] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


