# ============================================================
# 模块2: AI员工成长树系统（ai_employee_growth_tree / ai_employee_achievements / ai_employee_skill_nodes）
# ============================================================

def _ensure_growth_ddls():
    """确保AI员工成长树相关表存在（幂等）"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS ai_employee_growth_tree (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                employee_id INTEGER,
                employee_name TEXT,
                employee_table TEXT,
                skill_tree_json TEXT DEFAULT '{}',
                growth_level INTEGER DEFAULT 1,
                growth_exp INTEGER DEFAULT 0,
                growth_path_json TEXT DEFAULT '[]',
                mentor_id INTEGER,
                mentor_name TEXT,
                mentee_ids_json TEXT DEFAULT '[]',
                last_evaluation TEXT,
                evaluation_score REAL DEFAULT 0.0,
                created_at TEXT,
                updated_at TEXT
            );
            CREATE TABLE IF NOT EXISTS ai_employee_achievements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                employee_id INTEGER,
                employee_name TEXT,
                achievement_code TEXT,
                achievement_name TEXT,
                achievement_type TEXT,
                achievement_desc TEXT,
                achievement_icon TEXT,
                achievement_value INTEGER DEFAULT 0,
                earned_at TEXT,
                created_at TEXT
            );
            CREATE TABLE IF NOT EXISTS ai_employee_skill_nodes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                employee_id INTEGER,
                employee_name TEXT,
                skill_category TEXT,
                skill_name TEXT,
                skill_level INTEGER DEFAULT 1,
                skill_exp INTEGER DEFAULT 0,
                skill_max_level INTEGER DEFAULT 10,
                skill_status TEXT DEFAULT 'learning',
                unlocked_at TEXT,
                created_at TEXT,
                updated_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_aegt_emp ON ai_employee_growth_tree(employee_id, employee_table);
            CREATE INDEX IF NOT EXISTS idx_aea_emp ON ai_employee_achievements(employee_id);
            CREATE INDEX IF NOT EXISTS idx_aesn_emp ON ai_employee_skill_nodes(employee_id);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[growth][ddl] err: {e}')


def _growth_load_employee_info(employee_id, table):
    """加载AI员工基本信息（真实查询 ai_employees / mtscos_ai_employees）"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            if table == 'mtscos_ai_employees':
                row = c.execute(
                    "SELECT id, name, role, dept, expertise_json, skills_json, scores_json, is_active, status "
                    "FROM mtscos_ai_employees WHERE id=?",
                    (employee_id,)
                ).fetchone()
                if not row:
                    return None
                d = dict(row)
                caps = []
                try:
                    ej = json.loads(d.get('expertise_json') or '[]')
                    if isinstance(ej, list):
                        caps = [str(x) for x in ej]
                except Exception:
                    pass
                skills = []
                try:
                    sj = json.loads(d.get('skills_json') or '[]')
                    if isinstance(sj, list):
                        skills = [str(x) for x in sj]
                except Exception:
                    pass
                sl = 0.0
                try:
                    sc = json.loads(d.get('scores_json') or '{}')
                    if isinstance(sc, dict):
                        sl = float(sc.get('overall') or sc.get('skill') or 0)
                except Exception:
                    pass
                if sl > 12:
                    sl = sl / 10.0
                return {
                    'id': d.get('id'), 'name': d.get('name') or '',
                    'role': d.get('role') or '', 'dept': d.get('dept') or '',
                    'capabilities': caps, 'skills': skills,
                    'skill_level': max(1, min(10, int(round(sl)))),
                    'source_table': 'mtscos_ai_employees',
                }
            else:
                row = c.execute(
                    "SELECT id, name, capabilities, specialties, skill_level, status, is_enabled "
                    "FROM ai_employees WHERE id=?",
                    (employee_id,)
                ).fetchone()
                if not row:
                    return None
                d = dict(row)
                caps = []
                try:
                    cj = json.loads(d.get('capabilities') or '{}')
                    if isinstance(cj, dict):
                        t = cj.get('type')
                        if t:
                            caps.append(str(t))
                    elif isinstance(cj, list):
                        caps = [str(x) for x in cj]
                except Exception:
                    pass
                skills = []
                try:
                    sj = json.loads(d.get('specialties') or '[]')
                    if isinstance(sj, list):
                        skills = [str(x) for x in sj]
                except Exception:
                    pass
                sl = max(1, min(10, int(d.get('skill_level') or 1)))
                return {
                    'id': d.get('id'), 'name': d.get('name') or '',
                    'role': '', 'dept': caps[0] if caps else 'AI_CORE',
                    'capabilities': caps, 'skills': skills,
                    'skill_level': sl, 'source_table': 'ai_employees',
                }
    except Exception as e:
        logger.warning(f'[growth][load_emp] err: {e}')
    return None


def _growth_generate_skill_tree(employee_id, table):
    """生成技能树JSON结构（基于员工capabilities+skills）"""
    info = _growth_load_employee_info(employee_id, table)
    if not info:
        return {'nodes': [], 'edges': []}
    caps = info.get('capabilities') or []
    skills = info.get('skills') or []
    base_sl = info.get('skill_level') or 1
    nodes = [{'id': 'root', 'label': info['name'], 'type': 'root', 'level': base_sl}]
    edges = []
    for i, cap in enumerate(caps[:8]):
        cap_id = f'cap_{i}'
        nodes.append({'id': cap_id, 'label': cap, 'type': 'capability', 'level': max(1, base_sl - 1)})
        edges.append({'source': 'root', 'target': cap_id})
        for j, sk in enumerate(skills[:5]):
            sk_id = f'cap_{i}_skill_{j}'
            nodes.append({'id': sk_id, 'label': sk, 'type': 'skill', 'level': max(1, base_sl - 2)})
            edges.append({'source': cap_id, 'target': sk_id})
    return {'nodes': nodes, 'edges': edges}


def _growth_init_employee(employee_id, table):
    """为AI员工初始化成长树（基于其capabilities生成技能节点）"""
    _ensure_growth_ddls()
    info = _growth_load_employee_info(employee_id, table)
    if not info:
        return {'ok': False, 'message': 'AI员工不存在'}
    now = _mtscos_now()
    skill_tree = _growth_generate_skill_tree(employee_id, table)
    caps = info.get('capabilities') or []
    skills = info.get('skills') or []
    base_sl = info.get('skill_level') or 1
    try:
        with _get_conn(DATABASE_PATH) as c:
            existing = c.execute(
                "SELECT id FROM ai_employee_growth_tree WHERE employee_id=? AND employee_table=?",
                (employee_id, table)
            ).fetchone()
            if existing:
                c.execute(
                    "UPDATE ai_employee_growth_tree SET skill_tree_json=?, growth_level=?, updated_at=? "
                    "WHERE employee_id=? AND employee_table=?",
                    (json.dumps(skill_tree, ensure_ascii=False), base_sl, now, employee_id, table)
                )
            else:
                c.execute(
                    "INSERT INTO ai_employee_growth_tree "
                    "(employee_id, employee_name, employee_table, skill_tree_json, growth_level, growth_exp, "
                    "growth_path_json, mentee_ids_json, evaluation_score, created_at, updated_at) "
                    "VALUES (?,?,?,?,?, 0, '[]', '[]', ?, ?, ?)",
                    (employee_id, info['name'], table, json.dumps(skill_tree, ensure_ascii=False),
                     base_sl, float(base_sl) * 10.0, now, now)
                )
            c.execute("DELETE FROM ai_employee_skill_nodes WHERE employee_id=? AND employee_name=?",
                      (employee_id, info['name']))
            for cap in caps[:10]:
                sl = base_sl
                c.execute(
                    "INSERT INTO ai_employee_skill_nodes "
                    "(employee_id, employee_name, skill_category, skill_name, skill_level, skill_exp, "
                    "skill_max_level, skill_status, unlocked_at, created_at, updated_at) "
                    "VALUES (?,?,?,?,?,?, 10, ?, ?, ?, ?)",
                    (employee_id, info['name'], cap, cap, sl, sl * 100,
                     'mastered' if sl >= 7 else ('expert' if sl >= 9 else 'learning'),
                     now, now, now)
                )
            for sk in skills[:15]:
                c.execute(
                    "INSERT INTO ai_employee_skill_nodes "
                    "(employee_id, employee_name, skill_category, skill_name, skill_level, skill_exp, "
                    "skill_max_level, skill_status, unlocked_at, created_at, updated_at) "
                    "VALUES (?,?,?,?,?,?, 10, ?, ?, ?, ?)",
                    (employee_id, info['name'], 'specialty', sk, max(1, base_sl - 1), max(0, (base_sl - 1) * 80),
                     'learning', now, now, now)
                )
            c.commit()
        return {'ok': True, 'skill_tree': skill_tree, 'message': f'已初始化 {info["name"]} 的成长树'}
    except Exception as e:
        logger.warning(f'[growth][init] err: {e}')
        return {'ok': False, 'message': str(e)}


def _growth_add_exp(employee_id, table, exp, reason):
    """增加经验值并检查升级"""
    _ensure_growth_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            row = c.execute(
                "SELECT id, growth_level, growth_exp, growth_path_json, employee_name FROM ai_employee_growth_tree "
                "WHERE employee_id=? AND employee_table=?",
                (employee_id, table)
            ).fetchone()
            if not row:
                return {'ok': False, 'message': '成长树未初始化，请先调用 init'}
            d = dict(row)
            now = _mtscos_now()
            new_exp = int(d.get('growth_exp') or 0) + int(exp)
            old_level = int(d.get('growth_level') or 1)
            new_level = old_level
            while new_exp >= new_level * 1000 and new_level < 100:
                new_exp -= new_level * 1000
                new_level += 1
            try:
                path = json.loads(d.get('growth_path_json') or '[]')
            except Exception:
                path = []
            path.append({'time': now, 'exp_delta': int(exp), 'reason': reason,
                         'level_before': old_level, 'level_after': new_level})
            leveled_up = new_level > old_level
            c.execute(
                "UPDATE ai_employee_growth_tree SET growth_exp=?, growth_level=?, growth_path_json=?, updated_at=? WHERE id=?",
                (new_exp, new_level, json.dumps(path, ensure_ascii=False), now, d['id'])
            )
            c.commit()
            return {'ok': True, 'data': {
                'employee_id': employee_id, 'employee_name': d.get('employee_name'),
                'growth_exp': new_exp, 'growth_level': new_level,
                'leveled_up': leveled_up, 'reason': reason,
            }, 'message': f'+{exp}经验{"，升级到Lv." + str(new_level) if leveled_up else ""}'}
    except Exception as e:
        logger.warning(f'[growth][add_exp] err: {e}')
        return {'ok': False, 'message': str(e)}


def _growth_check_achievements(employee_id, table):
    """检查并授予成就"""
    _ensure_growth_ddls()
    earned = []
    try:
        with _get_conn(DATABASE_PATH) as c:
            tree = c.execute(
                "SELECT growth_level, growth_exp, employee_name FROM ai_employee_growth_tree "
                "WHERE employee_id=? AND employee_table=?",
                (employee_id, table)
            ).fetchone()
            if not tree:
                return {'ok': False, 'message': '成长树未初始化'}
            d = dict(tree)
            level = int(d.get('growth_level') or 1)
            exp = int(d.get('growth_exp') or 0)
            name = d.get('employee_name') or ''
            achievement_defs = [
                ('first_steps', '初出茅庐', 'milestone', '完成成长树初始化', '🌱', 10, True),
                ('level_5', '小有所成', 'milestone', '成长等级达到5级', '⭐', 50, level >= 5),
                ('level_10', '独当一面', 'milestone', '成长等级达到10级', '🏆', 100, level >= 10),
                ('exp_1000', '勤奋者', 'experience', '累计经验值超过1000', '💪', 30, exp >= 1000),
                ('exp_5000', '经验丰富', 'experience', '累计经验值超过5000', '🎯', 80, exp >= 5000),
            ]
            now = _mtscos_now()
            for code, aname, atype, desc, icon, value, condition in achievement_defs:
                if not condition:
                    continue
                existing = c.execute(
                    "SELECT id FROM ai_employee_achievements WHERE employee_id=? AND achievement_code=?",
                    (employee_id, code)
                ).fetchone()
                if existing:
                    continue
                c.execute(
                    "INSERT INTO ai_employee_achievements "
                    "(employee_id, employee_name, achievement_code, achievement_name, achievement_type, "
                    "achievement_desc, achievement_icon, achievement_value, earned_at, created_at) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?)",
                    (employee_id, name, code, aname, atype, desc, icon, value, now, now)
                )
                earned.append({'code': code, 'name': aname, 'icon': icon, 'value': value})
            c.commit()
        return {'ok': True, 'data': {'earned': earned, 'count': len(earned)}, 'message': f'新获得{len(earned)}个成就'}
    except Exception as e:
        logger.warning(f'[growth][check_ach] err: {e}')
        return {'ok': False, 'message': str(e)}


def _growth_build_mentor_chain():
    """建立师徒关系（高skill_level→低skill_level）"""
    _ensure_growth_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            rows = c.execute(
                "SELECT id, employee_id, employee_name, employee_table, growth_level "
                "FROM ai_employee_growth_tree ORDER BY growth_level DESC"
            ).fetchall()
            trees = [dict(r) for r in rows]
            now = _mtscos_now()
            updated = 0
            mentor_count = max(1, len(trees) // 3)
            mentors = trees[:mentor_count]
            mentees = trees[mentor_count:]
            for i, mentee in enumerate(mentees):
                mentor = mentors[i % len(mentors)] if mentors else None
                if not mentor or mentor['id'] == mentee['id']:
                    continue
                c.execute(
                    "UPDATE ai_employee_growth_tree SET mentor_id=?, mentor_name=?, updated_at=? WHERE id=?",
                    (mentor['employee_id'], mentor['employee_name'], now, mentee['id'])
                )
                mentor_row = c.execute(
                    "SELECT mentee_ids_json FROM ai_employee_growth_tree WHERE id=?",
                    (mentor['id'],)
                ).fetchone()
                try:
                    mentee_ids = json.loads(dict(mentor_row).get('mentee_ids_json') or '[]')
                except Exception:
                    mentee_ids = []
                if mentee['employee_id'] not in mentee_ids:
                    mentee_ids.append(mentee['employee_id'])
                    c.execute(
                        "UPDATE ai_employee_growth_tree SET mentee_ids_json=?, updated_at=? WHERE id=?",
                        (json.dumps(mentee_ids, ensure_ascii=False), now, mentor['id'])
                    )
                updated += 1
            c.commit()
        return {'ok': True, 'data': {'mentor_count': len(mentors), 'mentee_count': len(mentees), 'links': updated},
                'message': f'师徒关系建立完成：{len(mentors)}名导师，{len(mentees)}名学徒'}
    except Exception as e:
        logger.warning(f'[growth][mentor] err: {e}')
        return {'ok': False, 'message': str(e)}


@app.route('/api/growth/tree/<int:employee_id>')
@system_container('api_growth_tree', require_auth='login')
def api_growth_tree(employee_id):
    """员工成长树（含技能节点+成就+师徒）"""
    _ensure_growth_ddls()
    try:
        table = request.args.get('table', 'ai_employees').strip()
        with _get_conn(DATABASE_PATH) as c:
            tree_row = c.execute(
                "SELECT * FROM ai_employee_growth_tree WHERE employee_id=? AND employee_table=?",
                (employee_id, table)
            ).fetchone()
            if not tree_row:
                return jsonify({'ok': False, 'data': None, 'message': '成长树未初始化'}), 404
            d = dict(tree_row)
            try: d['skill_tree'] = json.loads(d.pop('skill_tree_json') or '{}')
            except Exception: d['skill_tree'] = {}
            try: d['growth_path'] = json.loads(d.pop('growth_path_json') or '[]')
            except Exception: d['growth_path'] = []
            try: d['mentee_ids'] = json.loads(d.pop('mentee_ids_json') or '[]')
            except Exception: d['mentee_ids'] = []
            skill_rows = c.execute(
                "SELECT * FROM ai_employee_skill_nodes WHERE employee_id=? ORDER BY id",
                (employee_id,)
            ).fetchall()
            d['skill_nodes'] = [dict(r) for r in skill_rows]
            ach_rows = c.execute(
                "SELECT * FROM ai_employee_achievements WHERE employee_id=? ORDER BY id DESC",
                (employee_id,)
            ).fetchall()
            d['achievements'] = [dict(r) for r in ach_rows]
            if d.get('mentor_id'):
                mentor_row = c.execute(
                    "SELECT employee_id, employee_name, growth_level FROM ai_employee_growth_tree WHERE employee_id=? AND employee_table=?",
                    (d['mentor_id'], table)
                ).fetchone()
                d['mentor_info'] = dict(mentor_row) if mentor_row else None
            else:
                d['mentor_info'] = None
        return jsonify({'ok': True, 'data': d, 'message': f'{d.get("employee_name","")}的成长树'})
    except Exception as e:
        logger.warning(f'[growth][tree] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


