@app.route('/api/growth/add_exp', methods=['POST'])
@system_container('api_growth_add_exp', require_auth='admin')
def api_growth_add_exp():
    """增加经验值"""
    data = request.get_json(silent=True) or {}
    employee_id = data.get('employee_id')
    table = data.get('table', 'ai_employees').strip()
    exp = int(data.get('exp') or 0)
    reason = (data.get('reason') or '手动奖励').strip()
    if not employee_id or exp <= 0:
        return jsonify({'ok': False, 'data': None, 'message': 'employee_id和exp(>0)必填'}), 400
    result = _growth_add_exp(int(employee_id), table, exp, reason)
    if result.get('ok'):
        _growth_check_achievements(int(employee_id), table)
        return jsonify(result)
    return jsonify(result), 400


