@app.route('/api/growth/batch_init', methods=['POST'])
@system_container('api_growth_batch_init', require_auth='admin')
def api_growth_batch_init():
    """批量初始化全部AI员工成长树"""
    _ensure_growth_ddls()
    try:
        success, failed = 0, 0
        try:
            with _get_conn(DATABASE_PATH) as c:
                rows = c.execute("SELECT id FROM ai_employees WHERE is_enabled=1").fetchall()
            for r in rows:
                eid = int(dict(r)['id'])
                res = _growth_init_employee(eid, 'ai_employees')
                if res.get('ok'):
                    success += 1
                else:
                    failed += 1
        except Exception as e:
            logger.warning(f'[growth][batch_init] ai_employees err: {e}')
        try:
            with _get_conn(DATABASE_PATH) as c:
                rows = c.execute("SELECT id FROM mtscos_ai_employees WHERE is_active=1").fetchall()
            for r in rows:
                eid = int(dict(r)['id'])
                res = _growth_init_employee(eid, 'mtscos_ai_employees')
                if res.get('ok'):
                    success += 1
                else:
                    failed += 1
        except Exception as e:
            logger.warning(f'[growth][batch_init] mtscos err: {e}')
        _growth_build_mentor_chain()
        return jsonify({'ok': True, 'data': {'success': success, 'failed': failed},
                        'message': f'批量初始化完成：成功{success}，失败{failed}'})
    except Exception as e:
        logger.warning(f'[growth][batch_init] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


# ============================================================
# 模块3: AI员工议会系统（ai_parliament_proposals / ai_parliament_votes / ai_parliament_sessions）
# ============================================================

def _ensure_parliament_ddls():
    """确保AI员工议会相关表存在（幂等）"""
    try:
        with _get_conn(DATABASE_PATH) as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS ai_parliament_proposals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                proposal_uid TEXT UNIQUE,
                proposal_title TEXT,
                proposal_content TEXT,
                proposal_category TEXT,
                proposed_by TEXT,
                proposed_by_id INTEGER,
                proposed_by_table TEXT,
                status TEXT DEFAULT 'voting',
                vote_for INTEGER DEFAULT 0,
                vote_against INTEGER DEFAULT 0,
                vote_abstain INTEGER DEFAULT 0,
                total_votes INTEGER DEFAULT 0,
                quorum_required INTEGER DEFAULT 100,
                voting_deadline TEXT,
                result_json TEXT DEFAULT '{}',
                implementation_status TEXT DEFAULT 'pending',
                created_at TEXT,
                updated_at TEXT
            );
            CREATE TABLE IF NOT EXISTS ai_parliament_votes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                proposal_id INTEGER,
                voter_id INTEGER,
                voter_name TEXT,
                voter_table TEXT,
                vote_choice TEXT,
                vote_reason TEXT,
                vote_weight INTEGER DEFAULT 1,
                created_at TEXT
            );
            CREATE TABLE IF NOT EXISTS ai_parliament_sessions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                session_uid TEXT UNIQUE,
                session_type TEXT,
                total_proposals INTEGER DEFAULT 0,
                passed_count INTEGER DEFAULT 0,
                rejected_count INTEGER DEFAULT 0,
                total_voters INTEGER DEFAULT 0,
                status TEXT DEFAULT 'open',
                started_at TEXT,
                closed_at TEXT,
                summary TEXT,
                created_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_app_status ON ai_parliament_proposals(status);
            CREATE INDEX IF NOT EXISTS idx_app_category ON ai_parliament_proposals(proposal_category);
            CREATE INDEX IF NOT EXISTS idx_apv_proposal ON ai_parliament_votes(proposal_id);
            CREATE INDEX IF NOT EXISTS idx_apv_voter ON ai_parliament_votes(voter_id, voter_table);
            CREATE INDEX IF NOT EXISTS idx_aps_status ON ai_parliament_sessions(status);
            """)
            c.commit()
    except Exception as e:
        logger.warning(f'[parliament][ddl] err: {e}')


def _parliament_load_active_employees():
    """加载活跃AI员工列表（用于投票）"""
    employees = []
    try:
        with _get_conn(DATABASE_PATH) as c:
            try:
                rows = c.execute(
                    "SELECT id, name, capabilities, specialties, skill_level FROM ai_employees WHERE is_enabled=1"
                ).fetchall()
                for r in rows:
                    d = dict(r)
                    employees.append({
                        'id': d.get('id'),
                        'name': d.get('name') or '',
                        'capabilities': str(d.get('capabilities') or '')[:200],
                        'skill_level': max(1, min(10, int(d.get('skill_level') or 1))),
                        'table': 'ai_employees',
                    })
            except Exception:
                pass
            try:
                rows = c.execute(
                    "SELECT id, name, role, expertise_json, scores_json FROM mtscos_ai_employees WHERE is_active=1"
                ).fetchall()
                for r in rows:
                    d = dict(r)
                    sl = 0.0
                    try:
                        sc = json.loads(d.get('scores_json') or '{}')
                        if isinstance(sc, dict):
                            sl = float(sc.get('overall') or sc.get('skill') or 0)
                    except Exception:
                        pass
                    if sl > 12:
                        sl = sl / 10.0
                    employees.append({
                        'id': d.get('id'),
                        'name': d.get('name') or '',
                        'capabilities': str(d.get('expertise_json') or '')[:200],
                        'skill_level': max(1, min(10, int(round(sl)))),
                        'table': 'mtscos_ai_employees',
                    })
            except Exception:
                pass
    except Exception as e:
        logger.warning(f'[parliament][load_emps] err: {e}')
    return employees


def _parliament_auto_generate_proposals():
    """AI自动生成提案（基于系统状态分析）"""
    _ensure_parliament_ddls()
    proposals = []
    try:
        dead_comps = []
        try:
            with _get_conn(DATABASE_PATH) as c:
                rows = c.execute(
                    "SELECT component_name FROM system_heartbeat WHERE status='DEAD' GROUP BY component_name"
                ).fetchall()
            dead_comps = [dict(r)['component_name'] for r in rows]
        except Exception:
            pass
        crisis_count = 0
        try:
            with _get_conn(DATABASE_PATH) as c:
                crisis_count = c.execute(
                    "SELECT COUNT(*) FROM system_crisis_alerts WHERE response_status='pending'"
                ).fetchone()[0]
        except Exception:
            pass
        ai_count = 0
        try:
            with _get_conn(DATABASE_PATH) as c:
                ai_count = c.execute("SELECT COUNT(*) FROM ai_employees WHERE is_enabled=1").fetchone()[0]
                ai_count += c.execute("SELECT COUNT(*) FROM mtscos_ai_employees WHERE is_active=1").fetchone()[0]
        except Exception:
            pass
        proposal_templates = []
        if dead_comps:
            proposal_templates.append({
                'title': f'紧急修复失效组件: {", ".join(dead_comps[:3])}',
                'content': f'系统检测到以下组件失效: {", ".join(dead_comps)}。建议立即启动修复流程，分配AI员工代表团跟进。',
                'category': 'system_improvement',
            })
        if crisis_count > 5:
            proposal_templates.append({
                'title': '加强危机响应机制',
                'content': f'当前有 {crisis_count} 条待处理危机预警，建议增加自动响应规则并扩充AI员工代表团规模。',
                'category': 'system_improvement',
            })
        if ai_count > 0:
            proposal_templates.append({
                'title': '优化AI员工任务调度策略',
                'content': f'当前AI员工总数 {ai_count} 人，建议引入基于skill_level的动态任务分配机制，提升整体效率。',
                'category': 'feature_request',
            })
        proposal_templates.append({
            'title': '设立AI员工成长激励计划',
            'content': '建议建立月度成长排行榜奖励机制，对成长等级提升最快的AI员工给予tokens奖励。',
            'category': 'ai_welfare',
        })
        employees = _parliament_load_active_employees()
        now = _mtscos_now()
        deadline = (datetime.now() + timedelta(days=3)).strftime('%Y-%m-%d %H:%M:%S')
        try:
            with _get_conn(DATABASE_PATH) as c:
                for i, tmpl in enumerate(proposal_templates):
                    existing = c.execute(
                        "SELECT id FROM ai_parliament_proposals WHERE proposal_title=? AND status='voting'",
                        (tmpl['title'],)
                    ).fetchone()
                    if existing:
                        continue
                    proposer = employees[i % len(employees)] if employees else None
                    puid = 'pp_' + _uuid.uuid4().hex[:12]
                    c.execute(
                        "INSERT INTO ai_parliament_proposals "
                        "(proposal_uid, proposal_title, proposal_content, proposal_category, "
                        "proposed_by, proposed_by_id, proposed_by_table, status, voting_deadline, created_at, updated_at) "
                        "VALUES (?,?,?,?,?,?,?, 'voting', ?, ?, ?)",
                        (puid, tmpl['title'], tmpl['content'], tmpl['category'],
                         proposer['name'] if proposer else 'AI议会',
                         proposer['id'] if proposer else None,
                         proposer['table'] if proposer else None,
                         deadline, now, now)
                    )
                    proposals.append({'proposal_uid': puid, 'title': tmpl['title'], 'category': tmpl['category']})
                c.commit()
        except Exception as e:
            logger.warning(f'[parliament][gen_persist] err: {e}')
    except Exception as e:
        logger.warning(f'[parliament][auto_gen] err: {e}')
    return proposals


def _parliament_auto_vote(proposal_id):
    """AI员工自动投票（基于capabilities和提案category匹配）"""
    _ensure_parliament_ddls()
    voted = 0
    vote_for_cnt, vote_against_cnt, vote_abstain_cnt = 0, 0, 0
    try:
        with _get_conn(DATABASE_PATH) as c:
            proposal = c.execute(
                "SELECT id, proposal_title, proposal_content, proposal_category FROM ai_parliament_proposals WHERE id=?",
                (proposal_id,)
            ).fetchone()
            if not proposal:
                return {'ok': False, 'message': '提案不存在'}
            p = dict(proposal)
            title = (p.get('proposal_title') or '').lower()
            content = (p.get('proposal_content') or '').lower()
            category = p.get('proposal_category') or ''
            voted_rows = c.execute(
                "SELECT voter_id, voter_table FROM ai_parliament_votes WHERE proposal_id=?",
                (proposal_id,)
            ).fetchall()
            voted_set = {(dict(r)['voter_id'], dict(r)['voter_table']) for r in voted_rows}
        employees = _parliament_load_active_employees()
        import random as _rand_pv
        _rand_pv.shuffle(employees)
        voters = employees[:100]
        now = _mtscos_now()
        with _get_conn(DATABASE_PATH) as c:
            for v in voters:
                key = (v['id'], v['table'])
                if key in voted_set:
                    continue
                caps = (v.get('capabilities') or '').lower()
                sl = v.get('skill_level') or 1
                support_score = 0
                if category in ('system_improvement', 'feature_request'):
                    support_score += sl
                if category == 'ai_welfare':
                    support_score += 5
                if category == 'rule_change':
                    support_score -= 2
                if caps and any(kw in content for kw in caps.split(',')):
                    support_score += 3
                support_score += _rand_pv.randint(-3, 3)
                if support_score > 3:
                    choice = 'for'
                    vote_for_cnt += 1
                elif support_score < -1:
                    choice = 'against'
                    vote_against_cnt += 1
                else:
                    choice = 'abstain'
                    vote_abstain_cnt += 1
                reason_map = {
                    'for': f'基于skill_level={sl}与能力匹配度，支持该提案',
                    'against': f'基于风险评估（skill_level={sl}），持保留意见',
                    'abstain': f'能力领域不完全匹配，选择弃权',
                }
                c.execute(
                    "INSERT INTO ai_parliament_votes "
                    "(proposal_id, voter_id, voter_name, voter_table, vote_choice, vote_reason, vote_weight, created_at) "
                    "VALUES (?,?,?,?,?,?,?,?)",
                    (proposal_id, v['id'], v['name'], v['table'], choice, reason_map[choice], sl, now)
                )
                voted += 1
            c.execute(
                "UPDATE ai_parliament_proposals SET vote_for=vote_for+?, vote_against=vote_against+?, "
                "vote_abstain=vote_abstain+?, total_votes=total_votes+?, updated_at=? WHERE id=?",
                (vote_for_cnt, vote_against_cnt, vote_abstain_cnt, voted, now, proposal_id)
            )
            c.commit()
        return {'ok': True, 'data': {
            'voted': voted, 'for': vote_for_cnt, 'against': vote_against_cnt, 'abstain': vote_abstain_cnt
        }, 'message': f'{voted}名AI员工完成投票'}
    except Exception as e:
        logger.warning(f'[parliament][auto_vote] err: {e}')
        return {'ok': False, 'message': str(e)}


def _parliament_tally_votes(proposal_id):
    """统计投票结果"""
    _ensure_parliament_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            row = c.execute(
                "SELECT id, proposal_title, vote_for, vote_against, vote_abstain, total_votes, quorum_required, status "
                "FROM ai_parliament_proposals WHERE id=?",
                (proposal_id,)
            ).fetchone()
            if not row:
                return {'ok': False, 'message': '提案不存在'}
            d = dict(row)
            now = _mtscos_now()
            vfor = int(d.get('vote_for') or 0)
            vagainst = int(d.get('vote_against') or 0)
            vabstain = int(d.get('vote_abstain') or 0)
            total = int(d.get('total_votes') or 0)
            quorum = int(d.get('quorum_required') or 100)
            passed = False
            result_status = d.get('status')
            if total >= quorum:
                if vfor > vagainst:
                    result_status = 'passed'
                    passed = True
                else:
                    result_status = 'rejected'
            else:
                result_status = 'voting'
            result = {
                'for': vfor, 'against': vagainst, 'abstain': vabstain,
                'total': total, 'quorum_required': quorum,
                'quorum_met': total >= quorum, 'passed': passed, 'status': result_status,
            }
            c.execute(
                "UPDATE ai_parliament_proposals SET status=?, result_json=?, updated_at=? WHERE id=?",
                (result_status, json.dumps(result, ensure_ascii=False), now, proposal_id)
            )
            c.commit()
        return {'ok': True, 'data': result, 'message': f'统计完成：{"通过" if passed else "未通过"}'}
    except Exception as e:
        logger.warning(f'[parliament][tally] err: {e}')
        return {'ok': False, 'message': str(e)}


_parliament_daemon_running = False

def _parliament_daemon():
    """daemon线程，每5分钟检查待表决提案并自动投票"""
    import time as _t_parl
    global _parliament_daemon_running
    _t_parl.sleep(180)
    while True:
        try:
            if not _parliament_daemon_running:
                _parliament_daemon_running = True
                try:
                    _ensure_parliament_ddls()
                    try:
                        with _get_conn(DATABASE_PATH) as c:
                            recent = c.execute(
                                "SELECT COUNT(*) FROM ai_parliament_proposals WHERE created_at >= ?",
                                ((datetime.now() - timedelta(hours=24)).strftime('%Y-%m-%d %H:%M:%S'),)
                            ).fetchone()[0]
                        if recent < 3:
                            _parliament_auto_generate_proposals()
                    except Exception as e:
                        logger.warning(f'[parliament][daemon][gen] err: {e}')
                    with _get_conn(DATABASE_PATH) as c:
                        rows = c.execute(
                            "SELECT id FROM ai_parliament_proposals WHERE status='voting' ORDER BY id DESC LIMIT 5"
                        ).fetchall()
                    for r in rows:
                        pid = int(dict(r)['id'])
                        _parliament_auto_vote(pid)
                    now_str = _mtscos_now()
                    with _get_conn(DATABASE_PATH) as c:
                        expired = c.execute(
                            "SELECT id FROM ai_parliament_proposals WHERE status='voting' AND voting_deadline < ?",
                            (now_str,)
                        ).fetchall()
                    for r in expired:
                        _parliament_tally_votes(int(dict(r)['id']))
                finally:
                    _parliament_daemon_running = False
        except Exception as e:
            logger.warning(f'[parliament][daemon] err: {e}')
        _t_parl.sleep(300)


@app.route('/api/parliament/proposals/list')
@system_container('api_parliament_proposals_list', require_auth='login')
def api_parliament_proposals_list():
    """提案列表"""
    _ensure_parliament_ddls()
    try:
        page = max(1, int(request.args.get('page', 1)))
        page_size = min(200, max(1, int(request.args.get('page_size', 50))))
        offset = (page - 1) * page_size
        status = request.args.get('status', '').strip()
        category = request.args.get('category', '').strip()
        where, params = [], []
        if status:
            where.append("status=?"); params.append(status)
        if category:
            where.append("proposal_category=?"); params.append(category)
        where_sql = (" WHERE " + " AND ".join(where)) if where else ""
        with _get_conn(DATABASE_PATH) as c:
            total = c.execute("SELECT COUNT(*) FROM ai_parliament_proposals" + where_sql, params).fetchone()[0]
            rows = c.execute(
                "SELECT * FROM ai_parliament_proposals" + where_sql + " ORDER BY id DESC LIMIT ? OFFSET ?",
                params + [page_size, offset]
            ).fetchall()
        items = []
        for r in rows:
            d = dict(r)
            try: d['result'] = json.loads(d.pop('result_json') or '{}')
            except Exception: d['result'] = {}
            items.append(d)
        return jsonify({'ok': True, 'data': {'items': items, 'total': total, 'page': page, 'page_size': page_size},
                        'message': f'共{total}条提案'})
    except Exception as e:
        logger.warning(f'[parliament][proposals_list] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


