@app.route('/api/parliament/vote/<int:proposal_id>', methods=['POST'])
@system_container('api_parliament_vote', require_auth='admin')
def api_parliament_vote(proposal_id):
    """投票"""
    _ensure_parliament_ddls()
    try:
        data = request.get_json(silent=True) or {}
        voter_id = data.get('voter_id')
        voter_name = (data.get('voter_name') or '').strip()
        voter_table = (data.get('voter_table') or 'ai_employees').strip()
        choice = (data.get('choice') or '').strip().lower()
        reason = (data.get('reason') or '').strip()
        weight = int(data.get('weight') or 1)
        if choice not in ('for', 'against', 'abstain'):
            return jsonify({'ok': False, 'data': None, 'message': 'choice必须是for/against/abstain'}), 400
        if not voter_id or not voter_name:
            return jsonify({'ok': False, 'data': None, 'message': 'voter_id和voter_name必填'}), 400
        now = _mtscos_now()
        with _get_conn(DATABASE_PATH) as c:
            proposal = c.execute("SELECT status FROM ai_parliament_proposals WHERE id=?", (proposal_id,)).fetchone()
            if not proposal:
                return jsonify({'ok': False, 'data': None, 'message': '提案不存在'}), 404
            if dict(proposal)['status'] != 'voting':
                return jsonify({'ok': False, 'data': None, 'message': '提案已结束表决'}), 400
            existing = c.execute(
                "SELECT id FROM ai_parliament_votes WHERE proposal_id=? AND voter_id=? AND voter_table=?",
                (proposal_id, voter_id, voter_table)
            ).fetchone()
            if existing:
                return jsonify({'ok': False, 'data': None, 'message': '该员工已投票'}), 400
            c.execute(
                "INSERT INTO ai_parliament_votes "
                "(proposal_id, voter_id, voter_name, voter_table, vote_choice, vote_reason, vote_weight, created_at) "
                "VALUES (?,?,?,?,?,?,?,?)",
                (proposal_id, voter_id, voter_name, voter_table, choice, reason, weight, now)
            )
            if choice == 'for':
                c.execute("UPDATE ai_parliament_proposals SET vote_for=vote_for+1, total_votes=total_votes+1, updated_at=? WHERE id=?", (now, proposal_id))
            elif choice == 'against':
                c.execute("UPDATE ai_parliament_proposals SET vote_against=vote_against+1, total_votes=total_votes+1, updated_at=? WHERE id=?", (now, proposal_id))
            else:
                c.execute("UPDATE ai_parliament_proposals SET vote_abstain=vote_abstain+1, total_votes=total_votes+1, updated_at=? WHERE id=?", (now, proposal_id))
            c.commit()
        return jsonify({'ok': True, 'data': {'proposal_id': proposal_id, 'choice': choice, 'weight': weight},
                        'message': f'{voter_name}投票成功({choice})'})
    except Exception as e:
        logger.warning(f'[parliament][vote] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


