@system_container('api_parliament_stats', require_auth='login')
def api_parliament_stats():
    """议会统计"""
    _ensure_parliament_ddls()
    try:
        with _get_conn(DATABASE_PATH) as c:
            total_proposals = c.execute("SELECT COUNT(*) FROM ai_parliament_proposals").fetchone()[0]
            voting = c.execute("SELECT COUNT(*) FROM ai_parliament_proposals WHERE status='voting'").fetchone()[0]
            passed = c.execute("SELECT COUNT(*) FROM ai_parliament_proposals WHERE status='passed'").fetchone()[0]
            rejected = c.execute("SELECT COUNT(*) FROM ai_parliament_proposals WHERE status='rejected'").fetchone()[0]
            implemented = c.execute("SELECT COUNT(*) FROM ai_parliament_proposals WHERE implementation_status='implemented'").fetchone()[0]
            total_votes = c.execute("SELECT COUNT(*) FROM ai_parliament_votes").fetchone()[0]
            total_sessions = c.execute("SELECT COUNT(*) FROM ai_parliament_sessions").fetchone()[0]
            open_sessions = c.execute("SELECT COUNT(*) FROM ai_parliament_sessions WHERE status='open'").fetchone()[0]
            cat_rows = c.execute(
                "SELECT proposal_category, COUNT(*) AS cnt FROM ai_parliament_proposals GROUP BY proposal_category"
            ).fetchall()
        pass_rate = round((passed / total_proposals * 100), 1) if total_proposals else 0.0
        return jsonify({'ok': True, 'data': {
            'total_proposals': total_proposals, 'voting_proposals': voting,
            'passed_proposals': passed, 'rejected_proposals': rejected,
            'implemented_proposals': implemented, 'total_votes': total_votes,
            'total_sessions': total_sessions, 'open_sessions': open_sessions,
            'pass_rate': pass_rate,
            'by_category': {dict(r)['proposal_category']: dict(r)['cnt'] for r in cat_rows},
        }, 'message': '议会统计'})
    except Exception as e:
        logger.warning(f'[parliament][stats] err: {e}')
        return jsonify({'ok': False, 'data': None, 'message': str(e)}), 500


