def _ensure_dna_fed_ddls():
    """确保DNA进化引擎和联邦学习DDL表存在"""
    _ddl_list = [
        '''CREATE TABLE IF NOT EXISTS system_dna_genes (
            id INTEGER PRIMARY KEY AUTOINCREMENT, gene_uid TEXT UNIQUE,
            gene_category TEXT, gene_name TEXT, gene_value TEXT, gene_type TEXT,
            gene_min REAL, gene_max REAL, gene_description TEXT,
            mutation_rate REAL DEFAULT 0.1, fitness_score REAL DEFAULT 0.5,
            generation INTEGER DEFAULT 1, parent_gene_uid TEXT,
            is_active INTEGER DEFAULT 1, created_at TEXT, updated_at TEXT)''',
        '''CREATE TABLE IF NOT EXISTS system_dna_generations (
            id INTEGER PRIMARY KEY AUTOINCREMENT, generation_num INTEGER,
            population_size INTEGER, avg_fitness REAL, max_fitness REAL,
            min_fitness REAL, best_gene_uid TEXT, mutation_count INTEGER,
            selection_count INTEGER, status TEXT DEFAULT 'evaluating',
            started_at TEXT, completed_at TEXT, created_at TEXT)''',
        '''CREATE TABLE IF NOT EXISTS system_dna_mutations (
            id INTEGER PRIMARY KEY AUTOINCREMENT, mutation_uid TEXT,
            generation INTEGER, gene_uid TEXT, gene_name TEXT,
            old_value TEXT, new_value TEXT, mutation_type TEXT,
            fitness_before REAL, fitness_after REAL, fitness_delta REAL,
            is_beneficial INTEGER DEFAULT 0, created_at TEXT)''',
        '''CREATE TABLE IF NOT EXISTS federated_learning_nodes (
            id INTEGER PRIMARY KEY AUTOINCREMENT, node_uid TEXT UNIQUE,
            node_name TEXT, node_url TEXT, node_type TEXT,
            node_status TEXT DEFAULT 'registered', public_key TEXT,
            capabilities_json TEXT DEFAULT '[]', last_sync TEXT,
            total_shared_models INTEGER DEFAULT 0, total_received_models INTEGER DEFAULT 0,
            created_at TEXT, updated_at TEXT)''',
        '''CREATE TABLE IF NOT EXISTS federated_learning_models (
            id INTEGER PRIMARY KEY AUTOINCREMENT, model_uid TEXT UNIQUE,
            model_name TEXT, model_type TEXT, model_version TEXT,
            model_params_json TEXT DEFAULT '{}', model_metrics_json TEXT DEFAULT '{}',
            owner_node_uid TEXT, training_data_size INTEGER DEFAULT 0,
            validation_accuracy REAL DEFAULT 0.0, status TEXT DEFAULT 'draft',
            shared_with_json TEXT DEFAULT '[]', contribution_score REAL DEFAULT 0.0,
            created_at TEXT, updated_at TEXT)''',
        '''CREATE TABLE IF NOT EXISTS federated_learning_rounds (
            id INTEGER PRIMARY KEY AUTOINCREMENT, round_uid TEXT UNIQUE,
            round_num INTEGER, participating_nodes_json TEXT DEFAULT '[]',
            aggregated_model_uid TEXT, global_metrics_json TEXT DEFAULT '{}',
            convergence_score REAL DEFAULT 0.0, status TEXT DEFAULT 'pending',
            started_at TEXT, completed_at TEXT, created_at TEXT)''',
        '''CREATE TABLE IF NOT EXISTS federated_knowledge_exchange (
            id INTEGER PRIMARY KEY AUTOINCREMENT, exchange_uid TEXT,
            source_node_uid TEXT, target_node_uid TEXT,
            knowledge_type TEXT, knowledge_content TEXT,
            knowledge_value REAL DEFAULT 0.0, encryption_hash TEXT,
            status TEXT DEFAULT 'pending', exchanged_at TEXT, created_at TEXT)''',
    ]
    try:
        _dc = _get_conn()
        for _ddl in _ddl_list:
            _dc.execute(_ddl)
        _dc.commit()
        _dc.close()
    except Exception as _e:
        logger.warning(f'[dna_fed][ddl] err: {_e}')


# ===== DNA进化引擎 =====

def _dna_init_genes():
    """初始化系统DNA基因 - 基于真实系统参数"""
    try:
        c = _get_conn()
        now = _mtscos_now()
        # 系统真实参数作为基因
        genes = [
            ('CACHE', 'cache_ttl_seconds', '300', 'int', 10, 3600, '缓存过期时间'),
            ('CACHE', 'cache_max_entries', '1000', 'int', 100, 10000, '缓存最大条目'),
            ('PERF', 'db_pool_size', '5', 'int', 1, 20, '数据库连接池大小'),
            ('PERF', 'api_rate_limit', '100', 'int', 10, 1000, 'API限流(请求/分钟)'),
            ('AI', 'ai_heartbeat_interval', '30', 'int', 5, 300, 'AI心跳间隔(秒)'),
            ('AI', 'ai_auto_upgrade_interval', '300', 'int', 60, 3600, 'AI自动升级间隔(秒)'),
            ('AI', 'ai_max_concurrent_tasks', '50', 'int', 5, 500, 'AI最大并发任务'),
            ('SECURITY', 'session_timeout', '1800', 'int', 300, 7200, '会话超时(秒)'),
            ('SECURITY', 'vikey_check_interval', '60', 'int', 10, 600, 'VIKEY检测间隔(秒)'),
            ('MONITOR', 'alert_threshold', '3', 'int', 1, 10, '告警阈值(次)'),
            ('MONITOR', 'health_check_interval', '60', 'int', 10, 600, '健康检查间隔(秒)'),
            ('ITERATION', 'evolution_mutation_rate', '0.1', 'float', 0.01, 0.5, '进化变异率'),
            ('ITERATION', 'evolution_population_size', '20', 'int', 5, 100, '进化种群大小'),
            ('ITERATION', 'evolution_generations', '50', 'int', 10, 200, '进化代数'),
        ]
        for cat, name, val, typ, mn, mx, desc in genes:
            uid = _uuid.uuid4().hex[:12]
            c.execute('''INSERT OR IGNORE INTO system_dna_genes
                (gene_uid, gene_category, gene_name, gene_value, gene_type,
                 gene_min, gene_max, gene_description, mutation_rate, fitness_score,
                 generation, is_active, created_at, updated_at)
                VALUES (?,?,?,?,?,?,?,?,0.1,0.5,1,1,?,?)''',
                (uid, cat, name, val, typ, float(mn), float(mx), desc, now, now))
        c.commit()
        c.close()
    except Exception as e:
        logger.warning(f'[dna][init_genes] err: {e}')


def _dna_evaluate_fitness(gene_uid, gene_value):
    """评估基因适应度 - 基于系统真实指标"""
    try:
        c = _get_conn()
        # 查询系统真实指标作为适应度评估依据
        c.execute('SELECT COUNT(*) FROM system_heartbeat WHERE status="HEALTHY"')
        healthy = c.fetchone()[0]
        c.execute('SELECT COUNT(*) FROM system_heartbeat')
        total = c.fetchone()[0] or 1
        c.execute('SELECT COUNT(*) FROM ai_employees WHERE is_enabled=1')
        ai_active = c.fetchone()[0]
        c.execute('SELECT AVG(current_score) FROM system_dimension_metrics')
        avg_score = c.fetchone()[0] or 0
        c.close()
        # 适应度 = 系统健康度(40%) + AI活跃度(30%) + 维度评分(30%)
        health_ratio = healthy / total if total > 0 else 0.5
        ai_ratio = min(ai_active / 11326.0, 1.0) if ai_active > 0 else 0.5
        dim_ratio = avg_score / 100.0 if avg_score > 0 else 0.5
        fitness = health_ratio * 0.4 + ai_ratio * 0.3 + dim_ratio * 0.3
        return round(fitness, 4)
    except:
        return 0.5


def _dna_mutate(gene_uid):
    """对单个基因执行变异"""
    try:
        c = _get_conn()
        now = _mtscos_now()
        c.execute('SELECT gene_uid, gene_name, gene_value, gene_type, gene_min, gene_max, fitness_score FROM system_dna_genes WHERE gene_uid=? AND is_active=1', (gene_uid,))
        row = c.fetchone()
        if not row:
            return None
        uid, name, old_val, gtype, gmin, gmax, old_fitness = row
        old_val = float(old_val) if gtype in ('int', 'float') else old_val
        # 变异：在范围内随机扰动
        if gtype in ('int', 'float'):
            import random as _rng
            range_size = gmax - gmin
            mutation_delta = _rng.uniform(-range_size * 0.15, range_size * 0.15)
            new_val = max(gmin, min(gmax, old_val + mutation_delta))
            if gtype == 'int':
                new_val = int(new_val)
            new_val = str(new_val)
        else:
            new_val = old_val  # 非数值类型不变异
        new_fitness = _dna_evaluate_fitness(gene_uid, new_val)
        is_beneficial = 1 if new_fitness > old_fitness else 0
        mutation_uid = _uuid.uuid4().hex[:12]
        c.execute('''INSERT INTO system_dna_mutations
            (mutation_uid, generation, gene_uid, gene_name, old_value, new_value,
             mutation_type, fitness_before, fitness_after, fitness_delta, is_beneficial, created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?)''',
            (mutation_uid, 1, uid, name, str(old_val), new_val, 'random',
             old_fitness, new_fitness, new_fitness - old_fitness, is_beneficial, now))
        if is_beneficial:
            c.execute('UPDATE system_dna_genes SET gene_value=?, fitness_score=?, updated_at=? WHERE gene_uid=?',
                (new_val, new_fitness, now, uid))
        c.commit()
        c.close()
        return {'gene': name, 'old': str(old_val), 'new': new_val, 'fitness_delta': new_fitness - old_fitness, 'beneficial': is_beneficial}
    except Exception as e:
        logger.warning(f'[dna][mutate] err: {e}')
        return None


def _dna_evolve_generation():
    """执行一代进化：变异+选择"""
    try:
        c = _get_conn(APP_DB)
        now = _mtscos_now()
        c.execute('SELECT gene_uid FROM system_dna_genes WHERE is_active=1')
        genes = c.fetchall()
        mutations = []
        beneficial = 0
        for (uid,) in genes:
            import random as _rng
            if _rng.random() < 0.3:  # 30%变异概率
                result = _dna_mutate(uid)
                if result:
                    mutations.append(result)
                    if result['beneficial']:
                        beneficial += 1
        # 记录世代
        c.execute('SELECT MAX(generation) FROM system_dna_generations')
        max_gen = c.fetchone()[0] or 0
        gen_num = max_gen + 1
        c.execute('SELECT AVG(fitness_score), MAX(fitness_score), MIN(fitness_score) FROM system_dna_genes WHERE is_active=1')
        avg_f, max_f, min_f = c.fetchone()
        gen_uid = _uuid.uuid4().hex[:12]
        c.execute('''INSERT INTO system_dna_generations
            (generation_num, population_size, avg_fitness, max_fitness, min_fitness,
             mutation_count, selection_count, status, started_at, completed_at, created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)''',
            (gen_num, len(genes), avg_f or 0, max_f or 0, min_f or 0,
             len(mutations), beneficial, 'completed', now, now, now))
        c.commit()
        c.close()
        return {'generation': gen_num, 'mutations': len(mutations), 'beneficial': beneficial, 'avg_fitness': avg_f}
    except Exception as e:
        logger.warning(f'[dna][evolve] err: {e}')
        return None


def _dna_daemon():
    """DNA进化daemon - 每10分钟进化一代"""
    import time as _t
    _t.sleep(120)  # 启动延迟2分钟
    while True:
        try:
            _dna_evolve_generation()
        except Exception as e:
            logger.warning(f'[dna][daemon] err: {e}')
        _t.sleep(600)


# ===== 跨系统联邦学习 =====

def _fed_register_self():
    """注册本系统为联邦学习节点"""
    try:
        c = _get_conn()
        now = _mtscos_now()
        self_uid = 'MTSCOS_LOCAL_NODE'
        c.execute('SELECT id FROM federated_learning_nodes WHERE node_uid=?', (self_uid,))
        if not c.fetchone():
            c.execute('''INSERT INTO federated_learning_nodes
                (node_uid, node_name, node_url, node_type, node_status,
                 capabilities_json, created_at, updated_at)
                VALUES (?, ?, ?, ?, 'active', ?, ?, ?)''',
                (self_uid, 'MTSCOS本地系统', 'http://localhost:8888', 'local',
                 json.dumps(['nlp', 'classification', 'recommendation', 'prediction'], ensure_ascii=False),
                 now, now))
            c.commit()
        c.close()
    except Exception as e:
        logger.warning(f'[fed][register] err: {e}')


def _fed_create_local_model():
    """基于本地AI员工能力创建联邦学习模型"""
    try:
        c = _get_conn()
        now = _mtscos_now()
        # 真实查询AI员工能力分布
        c.execute('SELECT capabilities, COUNT(*) as cnt FROM ai_employees WHERE is_enabled=1 GROUP BY capabilities ORDER BY cnt DESC LIMIT 5')
        cap_dist = c.fetchall()
        c.execute('SELECT AVG(skill_level) FROM ai_employees WHERE is_enabled=1')
        avg_skill = c.fetchone()[0] or 1
        c.execute('SELECT COUNT(*) FROM eigenflux_learning_outcomes')
        training_size = c.fetchone()[0]
        model_uid = _uuid.uuid4().hex[:12]
        model_name = f'MTSCOS_Capability_Model_v{datetime.datetime.now().strftime("%Y%m%d")}'
        c.execute('''INSERT INTO federated_learning_models
            (model_uid, model_name, model_type, model_version, model_params_json,
             model_metrics_json, owner_node_uid, training_data_size,
             validation_accuracy, status, contribution_score, created_at, updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?)''',
            (model_uid, model_name, 'capability_distribution', '1.0',
             json.dumps({'capabilities': [r[0][:50] for r in cap_dist], 'avg_skill': round(avg_skill, 2)}, ensure_ascii=False),
             json.dumps({'accuracy': round(avg_skill / 5.0, 4), 'training_size': training_size}, ensure_ascii=False),
             'MTSCOS_LOCAL_NODE', training_size, round(avg_skill / 5.0, 4),
             'ready', 0.5, now, now))
        c.commit()
        c.close()
        return {'model_uid': model_uid, 'training_size': training_size, 'accuracy': round(avg_skill / 5.0, 4)}
    except Exception as e:
        logger.warning(f'[fed][create_model] err: {e}')
        return None


def _fed_aggregate_round():
    """执行一轮联邦聚合"""
    try:
        c = _get_conn(APP_DB)
        now = _mtscos_now()
        c.execute('SELECT MAX(round_num) FROM federated_learning_rounds')
        max_round = c.fetchone()[0] or 0
        round_num = max_round + 1
        # 查询参与节点
        c.execute("SELECT node_uid, node_name FROM federated_learning_nodes WHERE node_status='active'")
        nodes = c.fetchall()
        # 查询可用模型
        c.execute("SELECT model_uid, model_name, validation_accuracy FROM federated_learning_models WHERE status='ready' LIMIT 10")
        models = c.fetchall()
        # 聚合：平均准确率
        avg_acc = sum(m[2] for m in models) / len(models) if models else 0
        round_uid = _uuid.uuid4().hex[:12]
        c.execute('''INSERT INTO federated_learning_rounds
            (round_uid, round_num, participating_nodes_json, aggregated_model_uid,
             global_metrics_json, convergence_score, status, started_at, completed_at, created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?)''',
            (round_uid, round_num,
             json.dumps([{'node': n[0], 'name': n[1]} for n in nodes], ensure_ascii=False),
             models[0][0] if models else '',
             json.dumps({'avg_accuracy': round(avg_acc, 4), 'model_count': len(models)}, ensure_ascii=False),
             round(avg_acc, 4), 'completed', now, now, now))
        c.commit()
        c.close()
        return {'round': round_num, 'nodes': len(nodes), 'models': len(models), 'convergence': round(avg_acc, 4)}
    except Exception as e:
        logger.warning(f'[fed][aggregate] err: {e}')
        return None


def _fed_share_knowledge(target_node_uid, knowledge_type, content, value):
    """知识交换"""
    try:
        c = _get_conn(APP_DB)
        now = _mtscos_now()
        import hashlib
        enc_hash = hashlib.sha256(content.encode()).hexdigest()[:16]
        c.execute('''INSERT INTO federated_knowledge_exchange
            (exchange_uid, source_node_uid, target_node_uid, knowledge_type,
             knowledge_content, knowledge_value, encryption_hash, status, exchanged_at, created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?)''',
            (_uuid.uuid4().hex[:12], 'MTSCOS_LOCAL_NODE', target_node_uid,
             knowledge_type, content, value, enc_hash, 'completed', now, now))
        c.commit()
        c.close()
        return True
    except Exception as e:
        logger.warning(f'[fed][share] err: {e}')
        return False


def _fed_daemon():
    """联邦学习daemon - 每15分钟执行一轮聚合"""
    import time as _t
    _t.sleep(180)
    while True:
        try:
            _fed_aggregate_round()
        except Exception as e:
            logger.warning(f'[fed][daemon] err: {e}')
        _t.sleep(900)


