@app.route('/api/fed/share', methods=['POST'])
@system_container('api_fed_share', require_auth='admin')
def api_fed_share():
    data = request.get_json() or {}
    target = data.get('target_node_uid', '')
    ktype = data.get('knowledge_type', 'experience')
    content = data.get('knowledge_content', '')
    value = float(data.get('knowledge_value', 0.5))
    if not target or not content:
        return jsonify({'ok': False, 'message': '缺少必要参数'})
    if _fed_share_knowledge(target, ktype, content, value):
        return jsonify({'ok': True, 'message': '知识共享成功'})
    return jsonify({'ok': False, 'message': '知识共享失败'})


@app.route('/api/fed/dashboard')
@system_container('api_fed_dashboard', require_auth='login')
def api_fed_dashboard():
    try:
        c = _get_conn()
        c.execute('SELECT COUNT(*) FROM federated_learning_nodes WHERE node_status="active"')
        active_nodes = c.fetchone()[0]
        c.execute('SELECT COUNT(*) FROM federated_learning_models')
        total_models = c.fetchone()[0]
        c.execute('SELECT MAX(round_num) FROM federated_learning_rounds')
        max_round = c.fetchone()[0] or 0
        c.execute('SELECT AVG(validation_accuracy) FROM federated_learning_models WHERE status="ready"')
        avg_acc = c.fetchone()[0] or 0
        c.execute('SELECT COUNT(*) FROM federated_knowledge_exchange WHERE status="completed"')
        exchanges = c.fetchone()[0]
        c.close()
        return jsonify({'ok': True, 'data': {
            'active_nodes': active_nodes, 'total_models': total_models,
            'current_round': max_round, 'avg_accuracy': round(avg_acc, 4),
            'knowledge_exchanges': exchanges
        }})
    except Exception as e:
        return jsonify({'ok': False, 'message': str(e)})


# ===== daemon启动 =====
try:
    _ensure_dna_fed_ddls()
    _dna_init_genes()
    _fed_register_self()
    _thr_sysai.Thread(target=_dna_daemon, name='dna-evolution-daemon', daemon=True).start()
    _thr_sysai.Thread(target=_fed_daemon, name='federated-learning-daemon', daemon=True).start()
except Exception as _df_start_err:
    logger.warning(f'[dna_fed][daemon-start] err: {_df_start_err}')




