        offset = (page - 1) * per_page
        c.execute(f'SELECT COUNT(*) FROM {table_name}')
        total = c.fetchone()[0]
        c.execute(f'SELECT * FROM {table_name} ORDER BY id DESC LIMIT ? OFFSET ?', (per_page, offset))
        rows = c.fetchall()
        c.execute(f'PRAGMA table_info({table_name})')
        col_names = [r[1] for r in c.fetchall()]
        data = [dict(zip(col_names, row)) for row in rows]
        c.close()
        return jsonify({'ok': True, 'data': data, 'total': total, 'page': page, 'per_page': per_page})
