@app.route('/api/ff/dashboard')
@system_container('api_ff_dashboard', require_auth='login')
def api_ff_dashboard():
    """功能工厂仪表盘"""
    try:
        c = _get_conn()
        c.execute('SELECT COUNT(*) FROM system_feature_factory_logs')
        total_features = c.fetchone()[0]
        c.execute('SELECT feature_cat, COUNT(*) FROM system_feature_factory_logs GROUP BY feature_cat ORDER BY COUNT(*) DESC')
        cat_stats = [{'category': r[0], 'count': r[1]} for r in c.fetchall()]
        c.execute("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name LIKE 'ff_%'")
        real_tables = c.fetchone()[0]
        total_records = 0
        c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'ff_%'")
        for (tbl,) in c.fetchall():
            try:
                c.execute(f'SELECT COUNT(*) FROM {tbl}')
                total_records += c.fetchone()[0]
            except:
                pass
        c.close()
        return jsonify({'ok': True, 'data': {
            'total_features': total_features, 'real_tables': real_tables,
            'total_records': total_records, 'categories': cat_stats,
            'api_per_table': 6, 'total_apis': real_tables * 6
        }})
    except Exception as e:
        return jsonify({'ok': False, 'message': str(e)})




