@app.route('/api/ff4/<table_name>/create', methods=['POST'])
@system_container('api_ff4_create', require_auth='admin')
def api_ff4_create(table_name):
    try:
        if not table_name.startswith('ff4_'):
            return jsonify({'ok': False, 'message': 'Invalid table name'})
        data = request.get_json() or {}
        c = _get_conn()
        c.execute(f'PRAGMA table_info({table_name})')
        all_cols = [r[1] for r in c.fetchall() if r[1] != 'id']
        valid_cols = [col for col in all_cols if col in data]
        if not valid_cols:
            return jsonify({'ok': False, 'message': 'No valid fields'})
        placeholders = ', '.join(['?'] * len(valid_cols))
        values = [data[col] for col in valid_cols]
        c.execute(f'INSERT INTO {table_name} ({", ".join(valid_cols)}) VALUES ({placeholders})', values)
        c.execute('SELECT last_insert_rowid()')
        new_id = c.fetchone()[0]
        c.commit()
        c.close()
        return jsonify({'ok': True, 'data': {'id': new_id}, 'message': 'Created'})
    except Exception as e:
        return jsonify({'ok': False, 'message': str(e)})


