@app.route('/api/ledgame/score/<int:gid>', methods=['POST'])
@system_container('api_ledgame_score', require_auth='login')
def api_ledgame_score(gid):
    data = request.get_json() or {}
    c = _get_conn(APP_DB)
    score = data.get('score', 0)
    level = data.get('level', 1)
    c.execute('UPDATE ard_led_games SET current_score=?, level=? WHERE id=?', (score, level, gid))
    c.execute('UPDATE ard_led_games SET high_score=CASE WHEN ? > high_score THEN ? ELSE high_score END WHERE id=?', (score, score, gid))
    c.commit(); c.close()
    return jsonify({'ok': True, 'message': 'Score updated'})

