    c.execute('''CREATE TABLE IF NOT EXISTS ard_doorlock_codes (
        id INTEGER PRIMARY KEY AUTOINCREMENT, lock_id TEXT, code_hash TEXT,
        user_id INTEGER, valid_from TEXT, valid_until TEXT, uses_count INTEGER,
        max_uses INTEGER, active INTEGER)''')
    c.execute('''CREATE TABLE IF NOT EXISTS ard_doorlock_fingerprints (
        id INTEGER PRIMARY KEY AUTOINCREMENT, lock_id TEXT, finger_id INTEGER,
        user_id INTEGER, template_hash TEXT, enrolled_at TEXT)''')
    c.commit(); c.close()

