@app.route('/api/datalogger/sessions/start', methods=['POST'])
@system_container('api_dl_start', require_auth='login')
def api_dl_start():
    _ensure_datalogger_ddls()
    data = request.get_json() or {}
    c = _get_conn(APP_DB)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    c.execute('''INSERT INTO ard_datalogger_sessions (session_name, channel_count, sample_rate_hz, duration_s, sd_card_used_mb, started_at, stopped_at, status)
        VALUES (?, ?, ?, 0, 0, ?, '', 'recording')''',
        (data.get('session_name','Session'), data.get('channel_count',4), data.get('sample_rate_hz',1.0), now))
    c.commit()
    sid = c.execute('SELECT last_insert_rowid()').fetchone()[0]
    # 创建通道
    for ch in range(data.get('channel_count',4)):
        c.execute('INSERT INTO ard_datalogger_channels (session_id, channel_num, sensor_type, unit, min_value, max_value, avg_value, sample_count) VALUES (?,?,?,?,0,0,0,0)',
            (sid, ch+1, data.get(f'ch{ch+1}_type','voltage'), data.get(f'ch{ch+1}_unit','V')))
    c.commit(); c.close()
    return jsonify({'ok': True, 'data': {'session_id': sid}, 'message': 'Data logging started'})

@app.route('/api/datalogger/readings/add', methods=['POST'])
@system_container('api_dl_add', require_auth='login')
def api_dl_add():
    _ensure_datalogger_ddls()
    data = request.get_json() or {}
    c = _get_conn(APP_DB)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    sid = data.get('session_id',0)
    ch = data.get('channel_num',1)
    val = data.get('value',0)
    c.execute('INSERT INTO ard_datalogger_readings (session_id, channel_num, value, timestamp) VALUES (?,?,?,?)', (sid, ch, val, now))
    c.execute('UPDATE ard_datalogger_channels SET sample_count=sample_count+1, min_value=CASE WHEN min_value=0 THEN ? ELSE MIN(min_value,?) END, max_value=MAX(max_value,?), avg_value=(avg_value*(sample_count-1)+?)/sample_count WHERE session_id=? AND channel_num=?',
        (val, val, val, val, sid, ch))
    c.commit(); c.close()
    return jsonify({'ok': True, 'message': 'Reading recorded'})

