    c = _get_conn(APP_DB)
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_ap (
        id INTEGER PRIMARY KEY AUTOINCREMENT, ssid TEXT, password_hash TEXT,
        channel INTEGER, hidden INTEGER, max_clients INTEGER, connected_clients INTEGER,
        encryption TEXT, ip_gateway TEXT, ip_subnet TEXT, dhcp_enabled INTEGER,
        uptime_s REAL, tx_bytes INTEGER, rx_bytes INTEGER, active INTEGER, created_at TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_ap_clients (
        id INTEGER PRIMARY KEY AUTOINCREMENT, ap_id INTEGER, client_mac TEXT,
        client_ip TEXT, connected_at TEXT, idle_time_s REAL, rx_bytes INTEGER,
        tx_bytes INTEGER, signal_dbm REAL, hostname TEXT, blocked INTEGER)''')
    c.commit(); c.close()

