@app.route('/api/wifi/sta/connect', methods=['POST'])
@system_container('api_wifi_sta_connect', require_auth='admin')
def api_wifi_sta_connect():
    _ensure_wifi_sta_ddls()
    data = request.get_json() or {}
    ssid = data.get('ssid','')
    pwd = data.get('password','')
    pwd_hash = hashlib.md5(pwd.encode()).hexdigest() if pwd else ''
    c = _get_conn(APP_DB)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    rssi = data.get('rssi', -60)
    if rssi < -80:
        return jsonify({'ok': False, 'message': 'Signal too weak (RSSI < -80dBm)'})
    c.execute('''INSERT INTO ard_wifi_sta_connections (ssid, bssid, password_hash, ip_address, gateway, dns, rssi, channel, auto_reconnect, connected_at, disconnected_at, disconnect_reason, status)
        VALUES (?,?,?,?,?,?,?,?,?,?,'','', 'connected')''',
        (ssid, data.get('bssid',''), pwd_hash, data.get('ip_address',''),
         data.get('gateway',''), data.get('dns',''), rssi, data.get('channel',0),
         data.get('auto_reconnect',1), now))
    c.execute('UPDATE ard_wifi_known_networks SET last_connected=?, connect_count=connect_count+1 WHERE ssid=?', (now, ssid))
    if c.execute('SELECT changes()').fetchone()[0] == 0:
        c.execute('INSERT INTO ard_wifi_known_networks (ssid, password_hash, bssid, encryption, priority, auto_connect, last_connected, connect_count) VALUES (?,?,?,?,0,1,?,1)',
            (ssid, pwd_hash, data.get('bssid',''), data.get('encryption','WPA2'), now))
    c.commit()
    conn_id = c.execute('SELECT last_insert_rowid()').fetchone()[0]
    c.close()
    return jsonify({'ok': True, 'data': {'conn_id': conn_id, 'rssi': rssi}, 'message': 'WiFi connected'})

