# --- WiFi SmartConfig/AP配网 ---
def _ensure_wifi_prov_ddls():
    c = _get_conn(APP_DB)
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_provisioning (
        id INTEGER PRIMARY KEY AUTOINCREMENT, device_id TEXT, method TEXT,
        ssid TEXT, password_hash TEXT, token TEXT, status TEXT,
        phone_ip TEXT, config_time TEXT, expires_at TEXT, attempt_count INTEGER)''')
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_prov_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, provision_id INTEGER, event TEXT,
        detail TEXT, timestamp TEXT)''')
    c.commit(); c.close()

@app.route('/api/wifi/provision/start', methods=['POST'])
@system_container('api_wifi_prov_start', require_auth='admin')
def api_wifi_prov_start():
    _ensure_wifi_prov_ddls()
    data = request.get_json() or {}
    method = data.get('method', 'smartconfig')
    if method not in ('smartconfig', 'apmode', 'bleserial', 'qrcode'):
        return jsonify({'ok': False, 'message': 'Invalid method. Use: smartconfig/apmode/bleserial/qrcode'})
    token = uuid.uuid4().hex[:16]
    c = _get_conn(APP_DB)
    now = datetime.now()
    expires = (now + timedelta(minutes=5)).strftime('%Y-%m-%d %H:%M:%S')
    now_str = now.strftime('%Y-%m-%d %H:%M:%S')
    c.execute('''INSERT INTO ard_wifi_provisioning (device_id, method, ssid, password_hash, token, status, phone_ip, config_time, expires_at, attempt_count)
        VALUES (?, ?, '', '', ?, 'waiting', '', ?, ?, 0)''',
        (data.get('device_id','ESP32_001'), method, token, now_str, expires))
    c.execute('INSERT INTO ard_wifi_prov_log (provision_id, event, detail, timestamp) VALUES (?, ?, ?, ?)',
        (c.execute('SELECT last_insert_rowid()').fetchone()[0], 'started', f'Method: {method}', now_str))
    c.commit()
    c.close()
    return jsonify({'ok': True, 'data': {'token': token, 'method': method, 'expires_at': expires}, 'message': 'Provisioning started'})

@app.route('/api/wifi/provision/complete', methods=['POST'])
@system_container('api_wifi_prov_complete', require_auth='admin')
def api_wifi_prov_complete():
    _ensure_wifi_prov_ddls()
    data = request.get_json() or {}
    token = data.get('token','')
    c = _get_conn(APP_DB)
    row = c.execute('SELECT id, expires_at, status FROM ard_wifi_provisioning WHERE token=?', (token,)).fetchone()
    if not row:
        return jsonify({'ok': False, 'message': 'Invalid token'})
    if row[2] != 'waiting':
        return jsonify({'ok': False, 'message': f'Provisioning already {row[2]}'})
    now_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    ssid = data.get('ssid','')
    pwd = data.get('password','')
    pwd_hash = hashlib.md5(pwd.encode()).hexdigest() if pwd else ''
    c.execute('UPDATE ard_wifi_provisioning SET ssid=?, password_hash=?, status=?, phone_ip=?, attempt_count=attempt_count+1 WHERE token=?',
        (ssid, pwd_hash, 'completed', data.get('phone_ip',''), token))
    c.execute('INSERT INTO ard_wifi_prov_log (provision_id, event, detail, timestamp) VALUES (?, ?, ?, ?)',
        (row[0], 'completed', f'SSID: {ssid}', now_str))
    c.commit(); c.close()
    return jsonify({'ok': True, 'message': 'Provisioning completed', 'ssid': ssid})

@app.route('/api/wifi/provision/status/<token>')
@system_container('api_wifi_prov_status', require_auth='login')
def api_wifi_prov_status(token):
    _ensure_wifi_prov_ddls()
    c = _get_conn(APP_DB)
    row = c.execute('SELECT * FROM ard_wifi_provisioning WHERE token=?', (token,)).fetchone()
    if not row:
        return jsonify({'ok': False, 'message': 'Not found'})
    c.close()
    cols = ['id','device_id','method','ssid','password_hash','token','status','phone_ip','config_time','expires_at','attempt_count']
    return jsonify({'ok': True, 'data': dict(zip(cols, row))})


# --- WiFi OTA固件更新 ---
def _ensure_wifi_ota_ddls():
    c = _get_conn(APP_DB)
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_ota (
        id INTEGER PRIMARY KEY AUTOINCREMENT, device_id TEXT, firmware_version TEXT,
        firmware_url TEXT, firmware_size INTEGER, firmware_md5 TEXT,
        target_board TEXT, status TEXT, progress REAL, error_msg TEXT,
        started_at TEXT, completed_at TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_ota_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT, device_id TEXT, version_from TEXT,
        version_to TEXT, success INTEGER, rollback_available INTEGER,
        duration_s REAL, timestamp TEXT)''')
    c.commit(); c.close()

@app.route('/api/wifi/ota/start', methods=['POST'])
@system_container('api_wifi_ota_start', require_auth='admin')
def api_wifi_ota_start():
    _ensure_wifi_ota_ddls()
    data = request.get_json() or {}
    c = _get_conn(APP_DB)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    c.execute('''INSERT INTO ard_wifi_ota (device_id, firmware_version, firmware_url, firmware_size, firmware_md5, target_board, status, progress, error_msg, started_at, completed_at)
        VALUES (?,?,?,?,?,?, 'downloading', 0, '', ?, '')''',
        (data.get('device_id','ESP32_001'), data.get('firmware_version','1.0.0'),
         data.get('firmware_url',''), data.get('firmware_size',0),
         data.get('firmware_md5',''), data.get('target_board','esp32'), now))
    c.commit()
    ota_id = c.execute('SELECT last_insert_rowid()').fetchone()[0]
    c.close()
    return jsonify({'ok': True, 'data': {'ota_id': ota_id}, 'message': 'OTA update started'})

@app.route('/api/wifi/ota/progress/<int:ota_id>', methods=['POST'])
@system_container('api_wifi_ota_progress', require_auth='login')
def api_wifi_ota_progress(ota_id):
    data = request.get_json() or {}
    c = _get_conn(APP_DB)
    progress = min(max(float(data.get('progress', 0)), 0), 100)
    status = data.get('status', '')
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    if status == 'completed':
        c.execute('UPDATE ard_wifi_ota SET status=?, progress=100, completed_at=? WHERE id=?', ('completed', now, ota_id))
        row = c.execute('SELECT device_id, firmware_version FROM ard_wifi_ota WHERE id=?', (ota_id,)).fetchone()
        if row:
            c.execute('INSERT INTO ard_wifi_ota_history (device_id, version_from, version_to, success, rollback_available, duration_s, timestamp) VALUES (?, ?, ?, 1, 1, 0, ?)',
                (row[0], data.get('old_version',''), row[1], now))
    elif status == 'failed':
        c.execute('UPDATE ard_wifi_ota SET status=?, error_msg=?, completed_at=? WHERE id=?', ('failed', data.get('error',''), now, ota_id))
    else:
        c.execute('UPDATE ard_wifi_ota SET progress=?, status=? WHERE id=?', (progress, data.get('status','downloading'), ota_id))
    c.commit(); c.close()
    return jsonify({'ok': True, 'progress': progress})

@app.route('/api/wifi/ota/history/<device_id>')
@system_container('api_wifi_ota_history', require_auth='login')
def api_wifi_ota_history(device_id):
    _ensure_wifi_ota_ddls()
    c = _get_conn(APP_DB)
    rows = c.execute('SELECT * FROM ard_wifi_ota_history WHERE device_id=? ORDER BY id DESC LIMIT 50', (device_id,)).fetchall()
    c.close()
    cols = ['id','device_id','version_from','version_to','success','rollback_available','duration_s','timestamp']
    return jsonify({'ok': True, 'data': [dict(zip(cols, r)) for r in rows]})

@app.route('/api/wifi/ota/rollback/<int:ota_id>', methods=['POST'])
@system_container('api_wifi_ota_rollback', require_auth='admin')
def api_wifi_ota_rollback(ota_id):
    c = _get_conn(APP_DB)
    row = c.execute('SELECT device_id, version_to FROM ard_wifi_ota_history WHERE id=?', (ota_id,)).fetchone()
    if not row:
        return jsonify({'ok': False, 'message': 'No rollback available'})
    c.execute('UPDATE ard_wifi_ota_history SET rollback_available=0 WHERE id=?', (ota_id,))
    c.commit(); c.close()
    return jsonify({'ok': True, 'message': f'Rollback initiated for {row[0]} from v{row[1]}'})


# --- WiFi嗅探与网络监控 ---
def _ensure_wifi_sniff_ddls():
    c = _get_conn(APP_DB)
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_sniff_packets (
        id INTEGER PRIMARY KEY AUTOINCREMENT, channel INTEGER, rssi REAL,
        packet_type TEXT, src_mac TEXT, dst_mac TEXT, ssid TEXT,
        length INTEGER, timestamp TEXT, encrypted INTEGER)''')
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_sniff_stats (
        id INTEGER PRIMARY KEY AUTOINCREMENT, channel INTEGER, total_packets INTEGER,
        probe_req INTEGER, beacon INTEGER, data_pkt INTEGER, deauth INTEGER,
        eapol INTEGER, unknown INTEGER, scan_duration_s REAL, timestamp TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_deauth_detect (
        id INTEGER PRIMARY KEY AUTOINCREMENT, src_mac TEXT, dst_mac TEXT,
        channel INTEGER, reason_code INTEGER, count INTEGER,
        suspected_attack INTEGER, timestamp TEXT)''')
    c.commit(); c.close()

@app.route('/api/wifi/sniff/packets')
@system_container('api_wifi_sniff_pkts', require_auth='admin')
def api_wifi_sniff_pkts():
    _ensure_wifi_sniff_ddls()
    c = _get_conn(APP_DB)
    pkt_type = request.args.get('type', '')
    if pkt_type:
        rows = c.execute('SELECT * FROM ard_wifi_sniff_packets WHERE packet_type=? ORDER BY id DESC LIMIT 500', (pkt_type,)).fetchall()
    else:
        rows = c.execute('SELECT * FROM ard_wifi_sniff_packets ORDER BY id DESC LIMIT 500').fetchall()
    c.close()
    cols = ['id','channel','rssi','packet_type','src_mac','dst_mac','ssid','length','timestamp','encrypted']
    return jsonify({'ok': True, 'data': [dict(zip(cols, r)) for r in rows]})

@app.route('/api/wifi/sniff/add', methods=['POST'])
@system_container('api_wifi_sniff_add', require_auth='login')
def api_wifi_sniff_add():
    _ensure_wifi_sniff_ddls()
    data = request.get_json() or {}
    pkt_type = data.get('packet_type', 'data')
    c = _get_conn(APP_DB)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    c.execute('''INSERT INTO ard_wifi_sniff_packets (channel, rssi, packet_type, src_mac, dst_mac, ssid, length, timestamp, encrypted)
        VALUES (?,?,?,?,?,?,?,?,?)''',
        (data.get('channel',6), data.get('rssi',-60), pkt_type,
         data.get('src_mac',''), data.get('dst_mac',''), data.get('ssid',''),
         data.get('length',0), now, data.get('encrypted',0)))
    # deauth检测
    if pkt_type == 'deauth':
        src = data.get('src_mac','')
        dst = data.get('dst_mac','')
        existing = c.execute('SELECT id, count FROM ard_wifi_deauth_detect WHERE src_mac=? AND dst_mac=? AND channel=? ORDER BY id DESC LIMIT 1',
            (src, dst, data.get('channel',6))).fetchone()
        if existing:
            new_count = existing[1] + 1
            c.execute('UPDATE ard_wifi_deauth_detect SET count=?, suspected_attack=? WHERE id=?',
                (new_count, 1 if new_count >= 5 else 0, existing[0]))
        else:
            c.execute('INSERT INTO ard_wifi_deauth_detect (src_mac, dst_mac, channel, reason_code, count, suspected_attack, timestamp) VALUES (?,?,?,?,1,0,?)',
                (src, dst, data.get('channel',6), data.get('reason_code',0), now))
    c.commit(); c.close()
    return jsonify({'ok': True, 'message': 'Packet captured'})

@app.route('/api/wifi/sniff/stats')
@system_container('api_wifi_sniff_stats', require_auth='admin')
def api_wifi_sniff_stats():
    _ensure_wifi_sniff_ddls()
    c = _get_conn(APP_DB)
    rows = c.execute('SELECT * FROM ard_wifi_sniff_stats ORDER BY id DESC LIMIT 50').fetchall()
    c.close()
    cols = ['id','channel','total_packets','probe_req','beacon','data_pkt','deauth','eapol','unknown','scan_duration_s','timestamp']
    return jsonify({'ok': True, 'data': [dict(zip(cols, r)) for r in rows]})

