def api_wifi_deauth():
    _ensure_wifi_sniff_ddls()
    c = _get_conn(APP_DB)
    rows = c.execute('SELECT * FROM ard_wifi_deauth_detect WHERE suspected_attack=1 ORDER BY count DESC').fetchall()
