@app.route('/api/wifi/relay/create', methods=['POST'])
@system_container('api_wifi_relay_create', require_auth='admin')
def api_wifi_relay_create():
    _ensure_wifi_relay_ddls()
    data = request.get_json() or {}
    upstream_rssi = data.get('upstream_rssi', -70)
    if upstream_rssi < -85:
        return jsonify({'ok': False, 'message': 'Upstream signal too weak for relay (RSSI < -85dBm)'})
    c = _get_conn(APP_DB)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    c.execute('''INSERT INTO ard_wifi_relay (relay_name, upstream_ssid, upstream_bssid, upstream_rssi, downstream_ssid, downstream_channel, downstream_encryption, nat_enabled, mac_clone, repeater_mode, throughput_mbps, connected_clients, uptime_s, status, created_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,0,0,0,'running',?)''',
        (data.get('relay_name','Relay1'), data.get('upstream_ssid',''),
         data.get('upstream_bssid',''), upstream_rssi,
         data.get('downstream_ssid','MTSCOS_Relay'),
         data.get('downstream_channel',6), data.get('downstream_encryption','WPA2'),
         data.get('nat_enabled',1), data.get('mac_clone',0),
         data.get('repeater_mode','wds'), now))
    c.commit()
    rid = c.execute('SELECT last_insert_rowid()').fetchone()[0]
    c.close()
    return jsonify({'ok': True, 'data': {'relay_id': rid}, 'message': 'WiFi relay created'})

