def _ensure_wifi_heatmap_ddls():
    c = _get_conn(APP_DB)
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_heatmap (
        id INTEGER PRIMARY KEY AUTOINCREMENT, gps_lat REAL, gps_lon REAL,
        ssid TEXT, bssid TEXT, rssi REAL, channel INTEGER, encryption TEXT,
        scan_count INTEGER, avg_rssi REAL, min_rssi REAL, max_rssi REAL,
        last_scanned TEXT, location_name TEXT)''')
    c.commit(); c.close()

@app.route('/api/wifi/heatmap/list')
@system_container('api_wifi_heatmap', require_auth='login')
def api_wifi_heatmap():
    _ensure_wifi_heatmap_ddls()
    c = _get_conn(APP_DB)
    rows = c.execute('SELECT * FROM ard_wifi_heatmap ORDER BY avg_rssi DESC LIMIT 500').fetchall()
    c.close()
    cols = ['id','gps_lat','gps_lon','ssid','bssid','rssi','channel','encryption','scan_count','avg_rssi','min_rssi','max_rssi','last_scanned','location_name']
    return jsonify({'ok': True, 'data': [dict(zip(cols, r)) for r in rows]})

@app.route('/api/wifi/heatmap/add', methods=['POST'])
@system_container('api_wifi_heatmap_add', require_auth='login')
def api_wifi_heatmap_add():
    _ensure_wifi_heatmap_ddls()
    data = request.get_json() or {}
    c = _get_conn(APP_DB)
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    lat = data.get('gps_lat', 0)
    lon = data.get('gps_lon', 0)
    bssid = data.get('bssid', '')
    existing = c.execute('SELECT id, scan_count, avg_rssi, min_rssi, max_rssi FROM ard_wifi_heatmap WHERE bssid=? AND gps_lat BETWEEN ?-0.001 AND ?+0.001 AND gps_lon BETWEEN ?-0.001 AND ?+0.001',
        (bssid, lat, lat, lon, lon)).fetchone()
    rssi = data.get('rssi', -60)
    if existing:
        new_count = existing[1] + 1
        new_avg = (existing[2] * existing[1] + rssi) / new_count
        new_min = min(existing[3], rssi)
        new_max = max(existing[4], rssi)
        c.execute('UPDATE ard_wifi_heatmap SET scan_count=?, avg_rssi=?, min_rssi=?, max_rssi=?, rssi=?, last_scanned=? WHERE id=?',
            (new_count, new_avg, new_min, new_max, rssi, now, existing[0]))
    else:
        c.execute('''INSERT INTO ard_wifi_heatmap (gps_lat, gps_lon, ssid, bssid, rssi, channel, encryption, scan_count, avg_rssi, min_rssi, max_rssi, last_scanned, location_name)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)''',
            (lat, lon, data.get('ssid',''), bssid, rssi, data.get('channel',0),
             data.get('encryption','WPA2'), 1, rssi, rssi, rssi, now, data.get('location_name','')))
    c.commit(); c.close()
    return jsonify({'ok': True, 'message': 'Heatmap point added'})

