    c = _get_conn(APP_DB)
    rows = c.execute('SELECT * FROM ard_wifi_heatmap WHERE gps_lat BETWEEN ? AND ? AND gps_lon BETWEEN ? AND ? ORDER BY avg_rssi DESC',
        (lat_min, lat_max, lon_min, lon_max)).fetchall()
    c.close()
    cols = ['id','gps_lat','gps_lon','ssid','bssid','rssi','channel','encryption','scan_count','avg_rssi','min_rssi','max_rssi','last_scanned','location_name']
