@app.route('/api/wifi/web/routes/register', methods=['POST'])
@system_container('api_wifi_web_register', require_auth='admin')
def api_wifi_web_register():
    _ensure_wifi_web_ddls()
    data = request.get_json() or {}
    method = data.get('method','GET').upper()
    if method not in ('GET','POST','PUT','DELETE','PATCH'):
        return jsonify({'ok': False, 'message': 'Invalid HTTP method'})
    c = _get_conn(APP_DB)
    c.execute('''INSERT INTO ard_wifi_web_routes (device_id, method, path, handler_name, auth_required, params, description, active)
        VALUES (?,?,?,?,?,?,?,1)''',
        (data.get('device_id','ESP32_001'), method, data.get('path','/'),
         data.get('handler_name','handle_root'), data.get('auth_required',0),
         data.get('params',''), data.get('description','')))
    c.commit()
    rid = c.execute('SELECT last_insert_rowid()').fetchone()[0]
    c.close()
    return jsonify({'ok': True, 'data': {'route_id': rid}, 'message': f'Route {method} {data.get("path","/")} registered'})

