# --- WiFi能耗优化 ---
def _ensure_wifi_power_ddls():
    c = _get_conn(APP_DB)
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_power (
        id INTEGER PRIMARY KEY AUTOINCREMENT, device_id TEXT, mode TEXT,
        sleep_interval_ms INTEGER, wake_duration_ms INTEGER, avg_current_ma REAL,
        peak_current_ma REAL, battery_level REAL, battery_voltage REAL,
        estimated_lifetime_h REAL, wifi_on_ratio REAL, timestamp TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS ard_wifi_power_modes (
        id INTEGER PRIMARY KEY AUTOINCREMENT, mode_name TEXT, description TEXT,
        wifi_on_ms INTEGER, wifi_off_ms INTEGER, expected_current_ua REAL,
        use_case TEXT, recommended INTEGER)''')
    c.commit(); c.close()

