    c.execute('SELECT COUNT(*) FROM ard_wifi_power_modes')
    if c.fetchone()[0] == 0:
        modes = [
            ('modem_sleep', 'WiFi modem sleep', 0, 0, 20000, 'Connected, idle between beacons', 1),
            ('light_sleep', 'Light sleep with WiFi wake', 5000, 200, 800, 'Periodic sensor reading', 1),
            ('deep_sleep', 'Deep sleep, WiFi off', 60000, 500, 100, 'Long interval IoT sensor', 1),
            ('always_on', 'WiFi always on', 0, 0, 80000, 'Real-time application', 0),
        ]
        for m in modes:
            c.execute('INSERT INTO ard_wifi_power_modes (mode_name, description, wifi_on_ms, wifi_off_ms, expected_current_ua, use_case, recommended) VALUES (?,?,?,?,?,?,?)', m)
