def _ensure_omega_schema(conn):
    """幂等创建Omega AI所需的4张表"""
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS mt_omega_ai_knowledge (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            knowledge_id TEXT UNIQUE NOT NULL,
            domain TEXT NOT NULL,
            category TEXT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            source TEXT,
            source_id TEXT,
            tags_json TEXT,
            confidence REAL DEFAULT 0.5,
            learning_count INTEGER DEFAULT 0,
            related_employees_json TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            is_active INTEGER DEFAULT 1
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS mt_omega_ai_relationships (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            omega_uid TEXT NOT NULL,
            employee_id TEXT NOT NULL,
            employee_table TEXT NOT NULL,
            relationship_type TEXT,
            strength REAL DEFAULT 0.5,
            interactions INTEGER DEFAULT 0,
            last_interaction_at TEXT,
            shared_knowledge_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(omega_uid, employee_id, employee_table)
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS mt_omega_ai_learning_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id TEXT,
            source_type TEXT,
            source_detail TEXT,
            knowledge_gained TEXT,
            brain_feed_topic TEXT,
            eigenflux_verdict TEXT,
            learning_value REAL DEFAULT 0.5,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS mt_omega_ai_proposals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            proposal_id TEXT UNIQUE NOT NULL,
            proposer_id TEXT NOT NULL,
            proposer_name TEXT NOT NULL,
            proposer_role TEXT,
            title TEXT NOT NULL,
            description TEXT NOT NULL,
            category TEXT,
            priority INTEGER DEFAULT 5,
            status TEXT DEFAULT 'pending',
            admin_votes_json TEXT,
            zhang_xiaofeng_decision TEXT,
            zhang_xiaofeng_comment TEXT,
            wuchenghao15_final_decision TEXT,
            wuchenghao15_final_comment TEXT,
            group_discussion_json TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            decided_at TEXT,
            executed_at TEXT
        )""")
        # 索引
        for idx_sql in [
            "CREATE INDEX IF NOT EXISTS idx_omega_knowledge_domain ON mt_omega_ai_knowledge(domain, is_active)",
            "CREATE INDEX IF NOT EXISTS idx_omega_knowledge_source ON mt_omega_ai_knowledge(source)",
            "CREATE INDEX IF NOT EXISTS idx_omega_relationships_emp ON mt_omega_ai_relationships(employee_id, employee_table)",
            "CREATE INDEX IF NOT EXISTS idx_omega_learning_log_session ON mt_omega_ai_learning_log(session_id)",
            "CREATE INDEX IF NOT EXISTS idx_omega_proposals_status ON mt_omega_ai_proposals(status, priority)",
            "CREATE INDEX IF NOT EXISTS idx_omega_proposals_proposer ON mt_omega_ai_proposals(proposer_id)",
        ]:
            try:
                conn.execute(idx_sql)
            except Exception:
                pass
        conn.commit()
    except Exception as _e:
        logger.warning(f'[Omega][schema] init warn: {_e}')


def _omega_get_status():
    """获取Omega AI当前状态"""
    try:
        with _get_conn(APP_DB) as c:
            _ensure_omega_schema(c)
            knowledge_count = c.execute("SELECT COUNT(*) FROM mt_omega_ai_knowledge WHERE is_active=1").fetchone()[0]
            relationship_count = c.execute("SELECT COUNT(*) FROM mt_omega_ai_relationships").fetchone()[0]
            learning_count = c.execute("SELECT COUNT(*) FROM mt_omega_ai_learning_log").fetchone()[0]
            pending_proposals = c.execute("SELECT COUNT(*) FROM mt_omega_ai_proposals WHERE status='pending'").fetchone()[0]
            # 按域统计知识量
            domain_stats = {}
            for row in c.execute("SELECT domain, COUNT(*) FROM mt_omega_ai_knowledge WHERE is_active=1 GROUP BY domain").fetchall():
                domain_stats[row[0]] = row[1]
        return {
            'uid': _OMEGA_AI_UID,
            'name': _OMEGA_AI_NAME,
            'role': _OMEGA_AI_ROLE,
            'version': _OMEGA_AI_VERSION,
            'domains': _OMEGA_DOMAINS,
            'knowledge_count': knowledge_count,
            'relationship_count': relationship_count,
            'learning_count': learning_count,
            'pending_proposals': pending_proposals,
            'domain_stats': domain_stats,
            'status': 'active',
        }
    except Exception as e:
        return {'uid': _OMEGA_AI_UID, 'name': _OMEGA_AI_NAME, 'status': 'error', 'error': str(e)}


def _omega_scan_system_knowledge():
    """全系统功能扫描：扫描所有表/路由/页面，生成知识条目存入知识库"""
    import re as _re
    scanned = {'tables': 0, 'routes': 0, 'pages': 0, 'knowledge_added': 0}
    now = _mtscos_now()
    try:
        with _get_conn(APP_DB) as c:
            _ensure_omega_schema(c)
            # 1. 扫描数据库表
            tables = c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").fetchall()
            for (tbl,) in tables:
                kid = f'sys_table_{tbl}'
                exists = c.execute("SELECT 1 FROM mt_omega_ai_knowledge WHERE knowledge_id=?", (kid,)).fetchone()
                if not exists:
                    # 获取列数
                    try:
                        cols = c.execute(f"PRAGMA table_info({tbl})").fetchall()
                        col_count = len(cols)
                        col_names = [col[1] for col in cols]
                    except Exception:
                        col_count = 0
                        col_names = []
                    c.execute(
                        "INSERT OR IGNORE INTO mt_omega_ai_knowledge(knowledge_id, domain, category, title, content, source, tags_json, confidence, created_at, updated_at) "
                        "VALUES(?,?,?,?,?,?,?,?,?,?)",
                        (kid, 'system', 'table', f'数据库表: {tbl}',
                         _rj.dumps({'table_name': tbl, 'column_count': col_count, 'columns': col_names}, ensure_ascii=False),
                         'auto_scan', '["database","table","schema"]', 0.9, now, now))
                    scanned['tables'] += 1
                    scanned['knowledge_added'] += 1
            # 2. 扫描路由（从server_real_db.py源码）
            try:
                with open(__file__, 'r') as f:
                    src_lines = f.readlines()
                route_pattern = _re.compile(r"@app\.route\(['\"]([^'\"]+)['\"]")
                for i, line in enumerate(src_lines):
                    m = route_pattern.search(line)
                    if m:
                        path = m.group(1)
                        is_api = path.startswith('/api/') or path.startswith('/auth/')
                        domain = 'system'
                        if '/exam' in path or '/paper' in path: domain = 'exam'
                        elif '/ai' in path or '/cluster' in path: domain = 'ai_engine'
                        elif '/security' in path or '/vikey' in path or '/ssl' in path: domain = 'security'
                        elif '/knowledge' in path or '/brain' in path: domain = 'knowledge'
                        elif '/question' in path or '/qa' in path: domain = 'question'
                        kid = f'sys_route_{path}'
                        exists = c.execute("SELECT 1 FROM mt_omega_ai_knowledge WHERE knowledge_id=?", (kid,)).fetchone()
                        if not exists:
                            c.execute(
                                "INSERT OR IGNORE INTO mt_omega_ai_knowledge(knowledge_id, domain, category, title, content, source, tags_json, confidence, created_at, updated_at) "
                                "VALUES(?,?,?,?,?,?,?,?,?,?)",
                                (kid, domain, 'api' if is_api else 'page',
                                 f'{"API" if is_api else "页面"}路由: {path}',
                                 _rj.dumps({'path': path, 'type': 'api' if is_api else 'page', 'source_line': i + 1}, ensure_ascii=False),
                                 'auto_scan', f'["route","{domain}"]', 0.85, now, now))
                            scanned['routes'] += 1
                            scanned['knowledge_added'] += 1
                        if not is_api:
                            scanned['pages'] += 1
            except Exception:
                pass
            c.commit()
    except Exception as e:
        logger.warning(f'[Omega][scan] err: {e}')
    return scanned


def _omega_learn_from_eigenflux(session_id=None, limit=50):
    """从EigenFlux交流消息中学习知识"""
    learned = {'messages_scanned': 0, 'knowledge_extracted': 0, 'brain_fed': 0}
    now = _mtscos_now()
    try:
        with _get_conn(DATABASE_PATH) as c:
            # 查询EigenFlux交流消息
            if session_id:
                rows = c.execute(
                    "SELECT id, session_id, employee_name, message_direction, message_type, message_content, knowledge_tags_json, learning_value, created_at "
                    "FROM eigenflux_comm_messages WHERE session_id=? ORDER BY created_at DESC LIMIT ?",
                    (session_id, limit)
                ).fetchall()
            else:
                rows = c.execute(
                    "SELECT id, session_id, employee_name, message_direction, message_type, message_content, knowledge_tags_json, learning_value, created_at "
                    "FROM eigenflux_comm_messages ORDER BY created_at DESC LIMIT ?",
                    (limit,)
                ).fetchall()
            learned['messages_scanned'] = len(rows)
        if rows:
            with _get_conn(APP_DB) as c:
                _ensure_omega_schema(c)
                for row in rows:
                    msg_id, sid, emp_name, direction, msg_type, content, tags_json, learn_val, created = row
                    # 提取知识
                    kid = f'ef_learn_{msg_id}'
                    exists = c.execute("SELECT 1 FROM mt_omega_ai_knowledge WHERE knowledge_id=?", (kid,)).fetchone()
                    if not exists:
                        tags = []
                        try:
                            tags = _rj.loads(tags_json) if tags_json else []
                        except Exception:
                            tags = []
                        domain = 'knowledge'
                        # 根据消息类型推断领域
                        content_lower = (content or '').lower()
                        if any(k in content_lower for k in ['考试', '题目', 'exam', 'paper']): domain = 'exam'
                        elif any(k in content_lower for k in ['安全', '加密', 'vikey', 'security']): domain = 'security'
                        elif any(k in content_lower for k in ['AI', '引擎', '集群', 'engine', 'cluster']): domain = 'ai_engine'
                        elif any(k in content_lower for k in ['知识', '学习', 'brain', 'knowledge']): domain = 'knowledge'
                        elif any(k in content_lower for k in ['前端', 'UI', '页面', 'frontend']): domain = 'frontend'
                        c.execute(
                            "INSERT OR IGNORE INTO mt_omega_ai_knowledge(knowledge_id, domain, category, title, content, source, source_id, tags_json, confidence, related_employees_json, created_at, updated_at) "
                            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                            (kid, domain, 'eigenflux_message',
                             f'EigenFlux交流: {emp_name} - {msg_type}',
                             (content or '')[:2000],
                             'eigenflux', str(msg_id),
                             _rj.dumps(tags, ensure_ascii=False) if tags else '[]',
                             min(0.95, float(learn_val or 0.5)),
                             _rj.dumps([{'name': emp_name, 'direction': direction}], ensure_ascii=False),
                             now, now))
                        learned['knowledge_extracted'] += 1
                    # 记录学习日志
                    c.execute(
                        "INSERT INTO mt_omega_ai_learning_log(session_id, source_type, source_detail, knowledge_gained, brain_feed_topic, eigenflux_verdict, learning_value, created_at) "
                        "VALUES(?,?,?,?,?,?,?,?)",
                        (str(sid), 'eigenflux', f'{emp_name}/{msg_type}',
                         (content or '')[:300], msg_type, direction, float(learn_val or 0.5), now))
                # 投喂脑库
                try:
                    c.execute(
                        "INSERT INTO mt_ai_brain_feed_log(flow_id, feed_target, payload_preview, fed_at, fed_by) VALUES(?,?,?,?,?)",
                        (f'omega_learn_{now}', 'AI_BRAIN',
                         f'Omega AI从{len(rows)}条EigenFlux消息中学习{learned["knowledge_extracted"]}条知识',
                         now, _OMEGA_AI_NAME))
                    learned['brain_fed'] = 1
                except Exception:
                    pass
                c.commit()
    except Exception as e:
        logger.warning(f'[Omega][learn_eigenflux] err: {e}')
    return learned


def _omega_connect_employee(employee_id, employee_table='ai_employees', relationship_type='partner'):
    """与AI员工建立知识连接（交友）"""
    now = _mtscos_now()
    try:
        with _get_conn(APP_DB) as c:
            _ensure_omega_schema(c)
            # 查找员工信息
            emp_name = employee_id
            emp_role = ''
            try:
                with _get_conn(DATABASE_PATH) as dc:
                    if employee_table == 'mtscos_ai_employees':
                        row = dc.execute("SELECT name, role FROM mtscos_ai_employees WHERE uid=?", (employee_id,)).fetchone()
                    else:
                        row = dc.execute("SELECT name, role FROM ai_employees WHERE id=? OR uid=?", (employee_id, employee_id)).fetchone()
                    if row:
                        emp_name = row[0] or employee_id
                        emp_role = row[1] or ''
            except Exception:
                pass
            # 插入或更新关系
            c.execute(
                "INSERT INTO mt_omega_ai_relationships(omega_uid, employee_id, employee_table, relationship_type, strength, interactions, last_interaction_at, shared_knowledge_count, created_at) "
                "VALUES(?,?,?,?,1,1,?,0,?) "
                "ON CONFLICT(omega_uid, employee_id, employee_table) DO UPDATE SET "
                "interactions=mt_omega_ai_relationships.interactions+1, "
                "last_interaction_at=excluded.last_interaction_at, "
                "strength=MIN(1.0, mt_omega_ai_relationships.strength+0.05)",
                (_OMEGA_AI_UID, employee_id, employee_table, relationship_type, now, now))
            c.commit()
            # 同时创建一条知识条目
            kid = f'rel_{employee_id}'
            c.execute(
                "INSERT OR IGNORE INTO mt_omega_ai_knowledge(knowledge_id, domain, category, title, content, source, source_id, tags_json, confidence, related_employees_json, created_at, updated_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
                (kid, 'system', 'employee_relation',
                 f'AI员工档案: {emp_name}',
                 _rj.dumps({'employee_id': employee_id, 'name': emp_name, 'role': emp_role,
                            'table': employee_table, 'relationship': relationship_type}, ensure_ascii=False),
                 'employee', employee_id, f'["employee","{employee_table}"]', 0.7,
                 _rj.dumps([{'id': employee_id, 'name': emp_name}], ensure_ascii=False), now, now))
            c.commit()
        return {'success': True, 'employee_id': employee_id, 'name': emp_name, 'relationship': relationship_type}
    except Exception as e:
        return {'success': False, 'error': str(e)}


def _omega_search_knowledge(query, domain=None, limit=20):
    """搜索Omega AI知识库"""
    try:
        with _get_conn(APP_DB) as c:
            _ensure_omega_schema(c)
            sql = "SELECT knowledge_id, domain, category, title, content, source, confidence, learning_count, created_at FROM mt_omega_ai_knowledge WHERE is_active=1"
            params = []
            if domain and domain != 'all':
                sql += " AND domain=?"
                params.append(domain)
            if query:
                sql += " AND (title LIKE ? OR content LIKE ?)"
                params.extend([f'%{query}%', f'%{query}%'])
            sql += " ORDER BY confidence DESC, learning_count DESC LIMIT ?"
            params.append(limit)
            rows = c.execute(sql, params).fetchall()
            results = []
            for row in rows:
                results.append({
                    'knowledge_id': row[0], 'domain': row[1], 'category': row[2],
                    'title': row[3], 'content': row[4][:500], 'source': row[5],
                    'confidence': row[6], 'learning_count': row[7], 'created_at': row[8],
                })
            # 增加学习计数
            for r in results:
                c.execute("UPDATE mt_omega_ai_knowledge SET learning_count=learning_count+1 WHERE knowledge_id=?", (r['knowledge_id'],))
            c.commit()
        return {'success': True, 'results': results, 'count': len(results)}
    except Exception as e:
        return {'success': False, 'error': str(e)}


