def _omega_admin_vote_proposal(proposal_id, voter_id, voter_name, vote, comment=''):
    """admin权限AI对提案投票（需2+admin AI通过才进入张晓峰决策）"""
    now = _mtscos_now()
    try:
        with _get_conn(APP_DB) as c:
            _ensure_omega_schema(c)
            row = c.execute("SELECT status, admin_votes_json FROM mt_omega_ai_proposals WHERE proposal_id=?", (proposal_id,)).fetchone()
            if not row:
                return {'success': False, 'error': '提案不存在'}
            status, votes_json = row
            if status != 'pending':
                return {'success': False, 'error': f'提案状态为{status}，不可投票'}
            votes = []
            try:
                votes = _rj.loads(votes_json) if votes_json else []
            except Exception:
                votes = []
            # 验证投票者是否已投过
            for v in votes:
                if v.get('voter_id') == voter_id:
                    return {'success': False, 'error': '已投过票'}
            votes.append({
                'voter_id': voter_id, 'voter_name': voter_name,
                'vote': vote, 'comment': comment, 'voted_at': now,
            })
            approve_count = sum(1 for v in votes if v.get('vote') == 'approve')
            # 更新投票记录
            new_status = status
            zhang_decision = None
            if approve_count >= 2:
                # 2+admin通过 → 进入张晓峰决策
                new_status = 'zhang_xiaofeng_review'
                zhang_decision = 'pending'
                # 模拟张晓峰AI决策（如果有本地LLM就用真实LLM）
                try:
                    has = _ai_list_active_providers()
                    if has and len(has) > 0:
                        # 用真实LLM模拟张晓峰决策
                        proposal_row = c.execute("SELECT title, description, category FROM mt_omega_ai_proposals WHERE proposal_id=?", (proposal_id,)).fetchone()
                        if proposal_row:
                            ctx = f'提案标题: {proposal_row[0]}\n提案内容: {proposal_row[1]}\n分类: {proposal_row[2]}\n已获{approve_count}位admin AI批准'
                            ok, ans, prov, lat = _ai_engine_chat(
                                messages=[{'role': 'user', 'content': f'你是张晓峰（CEO·业务战略），请对以下AI提案做出决策。只返回JSON: {{"decision":"approve|reject|escalate","reason":"理由"}}\n\n{ctx}'}],
                                system_prompt='你是张晓峰，公司CEO，负责业务战略决策。请从业务价值、战略方向、可行性角度评估此提案。',
                                temperature=0.2, timeout_s=20
                            )
                            if ok and ans:
                                import re as _re2
                                s = ans.find('{')
                                e = ans.rfind('}')
                                if s >= 0 and e > s:
                                    jj = _rj.loads(ans[s:e+1])
                                    zhang_decision = jj.get('decision', 'pending')
                                    c.execute(
                                        "UPDATE mt_omega_ai_proposals SET admin_votes_json=?, status=?, zhang_xiaofeng_decision=?, zhang_xiaofeng_comment=?, decided_at=? WHERE proposal_id=?",
                                        (_rj.dumps(votes, ensure_ascii=False),
                                         'approved' if zhang_decision == 'approve' else ('escalated' if zhang_decision == 'escalate' else 'rejected'),
                                         zhang_decision,
                                         jj.get('reason', ''), now, proposal_id))
                                    if zhang_decision == 'approve':
                                        # 张晓峰通过 → 自动报备wuchenghao15 → 自动执行
                                        c.execute(
                                            "UPDATE mt_omega_ai_proposals SET wuchenghao15_final_decision='auto_notified', wuchenghao15_final_comment='张晓峰批准，自动报备wuchenghao15', executed_at=? WHERE proposal_id=?",
                                            (now, proposal_id))
                                        new_status = 'approved_and_executed'
                                    elif zhang_decision == 'escalate':
                                        # 张晓峰不通过 → 上报wuchenghao15终审
                                        new_status = 'escalated_to_wuchenghao15'
                                    c.commit()
                                    return {'success': True, 'proposal_id': proposal_id, 'approve_count': approve_count,
                                            'zhang_xiaofeng_decision': zhang_decision, 'new_status': new_status,
                                            'message': f'张晓峰决策: {zhang_decision}'}
                    # 无LLM → 张晓峰默认escalate到wuchenghao15
                    zhang_decision = 'escalate'
                    c.execute(
                        "UPDATE mt_omega_ai_proposals SET admin_votes_json=?, status='escalated_to_wuchenghao15', zhang_xiaofeng_decision='escalate', zhang_xiaofeng_comment='无LLM，默认上报wuchenghao15终审', decided_at=? WHERE proposal_id=?",
                        (_rj.dumps(votes, ensure_ascii=False), now, proposal_id))
                    c.commit()
                    return {'success': True, 'proposal_id': proposal_id, 'approve_count': approve_count,
                            'zhang_xiaofeng_decision': 'escalate', 'new_status': 'escalated_to_wuchenghao15',
                            'message': '张晓峰上报wuchenghao15终审'}
                except Exception as _e:
                    logger.warning(f'[Omega][zhang_decision] err: {_e}')
                    c.execute(
                        "UPDATE mt_omega_ai_proposals SET admin_votes_json=?, status='escalated_to_wuchenghao15', zhang_xiaofeng_decision='escalate', zhang_xiaofeng_comment=?, decided_at=? WHERE proposal_id=?",
                        (_rj.dumps(votes, ensure_ascii=False), f'决策异常: {_e}', now, proposal_id))
                    c.commit()
                    return {'success': True, 'proposal_id': proposal_id, 'approve_count': approve_count,
                            'zhang_xiaofeng_decision': 'escalate', 'new_status': 'escalated_to_wuchenghao15'}
            else:
                # 不足2票，继续等待
                c.execute("UPDATE mt_omega_ai_proposals SET admin_votes_json=? WHERE proposal_id=?",
                          (_rj.dumps(votes, ensure_ascii=False), proposal_id))
                c.commit()
            return {'success': True, 'proposal_id': proposal_id, 'approve_count': approve_count,
                    'needed': 2, 'new_status': new_status,
                    'message': f'已获{approve_count}/2票，等待更多admin AI投票'}
    except Exception as e:
        return {'success': False, 'error': str(e)}


def _omega_wuchenghao15_final_decision(proposal_id, decision, comment=''):
    """wuchenghao15终审决策（仅超级管理员可操作）"""
    now = _mtscos_now()
    try:
        with _get_conn(APP_DB) as c:
            _ensure_omega_schema(c)
            row = c.execute("SELECT status FROM mt_omega_ai_proposals WHERE proposal_id=?", (proposal_id,)).fetchone()
            if not row:
                return {'success': False, 'error': '提案不存在'}
            if row[0] != 'escalated_to_wuchenghao15':
                return {'success': False, 'error': f'提案状态为{row[0]}，不可终审'}
            final_status = 'approved_and_executed' if decision == 'approve' else 'rejected_by_wuchenghao15'
            c.execute(
                "UPDATE mt_omega_ai_proposals SET wuchenghao15_final_decision=?, wuchenghao15_final_comment=?, status=?, executed_at=? WHERE proposal_id=?",
                (decision, comment, final_status, now if decision == 'approve' else None, proposal_id))
            c.commit()
        return {'success': True, 'proposal_id': proposal_id, 'final_decision': decision,
                'message': f'wuchenghao15终审: {decision}'}
    except Exception as e:
        return {'success': False, 'error': str(e)}


