def api_omega_proposals_vote(proposal_id):
    """admin权限AI对提案投票"""
    data = request.get_json(silent=True) or {}
    user = _current_safe_user()
    voter_id = str(data.get('voter_id') or user.get('uid') or user.get('username') or '')
    voter_name = str(data.get('voter_name') or user.get('username') or '')
    vote = str(data.get('vote') or '').strip()
    comment = str(data.get('comment') or '').strip()
    if vote not in ('approve', 'reject'):
        return jsonify({'success': False, 'message': 'vote必须是approve或reject'}), 400
    return jsonify(_omega_admin_vote_proposal(proposal_id, voter_id, voter_name, vote, comment))


