# ===== 客户端/服务器逻辑优化（装饰器已添加到原始心跳和状态API） =====


if __name__ == '__main__':
    v, info, _ = get_version_info()
    import os, threading
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1' or os.environ.get('DEBUG', '0') == '1'
    _enforce_super_admin_rule()
    # 启动时统一确保装饰/粒子/自动化/安全/记住我/审批/技能/工作流/MCP/Omega schema 存在
    try:
        with _get_conn(APP_DB) as _c:
            _ensure_site_decoration_schema(_c)
            _ensure_particle_perf_schema(_c)
            _ensure_automation_schema(_c)
            _ensure_security_schema(_c)
            _ensure_ssl_binding_schema(_c)  # 【STEP_7 SSL绑定】启动时建表+迁移
            _ensure_approval_schema(_c)
            _approval_check_sla_and_timeout(_c)
            _ensure_skill_schema(_c)
            _seed_default_skills(_c)
            _ensure_omega_schema(_c)  # 2026-08-12 Omega全知AI建表
    except Exception as _se:
        print(f'[SkillSchema] init warn: {_se}')
    try:
        with _get_conn(APP_DB) as _c:
            _seed_github_skills(_c)
    except Exception as _se:
        print(f'[GitHubSkillSeed] init warn: {_se}')
    try:
        with _get_conn(AUTH_DB) as _c:
            _ensure_remember_me_schema(_c)
    except Exception:
        pass
    print(f'[MTSCOS Real DB] schema+seed ready  version=v{v}  source={info.get("source")}  auth={AUTH_DB} debug={debug_mode}')
    print(f'[MTSCOS Real DB] bind=127.0.0.1:8888 —— 先启动 HTTP，后台线程再跑 EF5 健康扫描/AutoPlans/Monitor')

    def _bg_heavy_init():
        """后台线程：EigenFlux 20 类健康扫描 + AutoPlans 调度器 + EF 监控守护引擎 + 自动维护Agent"""
        # 1) EigenFlux 启动静态健康扫描（20类），允许环境变量跳过或超时 60s
        _skip = os.environ.get('MTSCOS_SKIP_EF_STARTUP_SCAN', '0') == '1'
        if not _skip:
            try:
                import signal
                class _EfScanTimeout(Exception): pass
                def _alarm_handler(signum, frame): raise _EfScanTimeout('EF 健康扫描超过 60s，后台继续但不阻塞 HTTP')
                _old = signal.signal(signal.SIGALRM, _alarm_handler)
                signal.alarm(60)
                try:
                    print('[EigenFlux-Heal] 启动时执行20类静态健康扫描...')
                    _scan = _ef_startup_health_scan()
                    _passed = sum(1 for _v in _scan.values() if _v is True)
                    _total = len(_scan)
                    print(f'[EigenFlux-Heal] 扫描完成: {_passed}/{_total} 项通过')
                    for _k, _v in _scan.items():
                        if _v is not True:
                            print(f'  ⚠️ {_k}: {_v}')
                except _EfScanTimeout as _te:
                    print(f'[EigenFlux-Heal] 超时（>60s），已跳过: {_te}')
                finally:
                    signal.alarm(0)
                    try: signal.signal(signal.SIGALRM, _old)
                    except Exception: pass
            except Exception as _se:
                print(f'[EigenFlux-Heal] 健康扫描跳过: {_se}')
        else:
            print('[EigenFlux-Heal] 已通过 MTSCOS_SKIP_EF_STARTUP_SCAN=1 显式跳过')
        # 2) 启动自动计划调度器
        try:
            from core.services.auto_plans import create_all_plans_and_register, get_plan_scheduler, get_dynamic_generator
            print('[AutoPlans] 正在初始化自动计划调度器...')
            scheduler = create_all_plans_and_register()
            try:
                generator = get_dynamic_generator()
                auto_generated = generator.scan_and_generate()
                print(f'[AutoPlans] AI 自动延展生成 {len(auto_generated)} 个新计划')
            except Exception as _ae:
                print(f'[AutoPlans] AI 延展跳过: {_ae}')
            scheduler.start_all()
            status = scheduler.get_overall_status()
            print(f'[AutoPlans] 已启动 {status["total_plans"]} 个计划（{status["active_plans"]} 活跃）')
        except Exception as _e:
            print(f'[AutoPlans] 调度器启动失败: {_e}')
        # 3) EigenFlux 实时监控守护引擎
        try:
            from services.eigenflux.eigenflux_monitor_daemon import start_monitor_daemon
            _monitor = start_monitor_daemon(interval=15)
            _status = _monitor.get_status()
            print('[EigenFlux-Monitor] 实时监控守护引擎已启动')
            print(f'  PID={_status["pid"]} 间隔={_status["interval"]}s 健康={_status["health"].get("overall", 0):.4f}')
        except Exception as _e:
            print(f'[EigenFlux-Monitor] 监控守护引擎启动失败: {_e}')
        # 4) 自动维护Agent（系统健康/数据库/路由/日志/文件系统 监控+自动修复）
        try:
            from ai_engines.auto_maintenance_agent import init_maintenance_agent
            _mt_agent = init_maintenance_agent(base_url='http://127.0.0.1:8888')
            _mt_agent.start(check_interval=300)
            _mt_st = _mt_agent.get_status()
            print(f'[Maintenance-Agent] 自动维护Agent已启动 (id={_mt_st.get("agent_id","?")})')
            print(f'  状态={_mt_st.get("state","?")} 间隔={_mt_st.get("check_interval","?")}s 自动修复={_mt_st.get("auto_repair","?")}')
        except Exception as _e:
            print(f'[Maintenance-Agent] 自动维护Agent启动失败: {_e}')

    _bg = threading.Thread(target=_bg_heavy_init, name='bg-heavy-init', daemon=True)
    _bg.start()

    # host='::' 同时监听 IPv6 (::1) 和 IPv4 (127.0.0.1)
    # 修复 localhost 解析优先使用 IPv6 导致浏览器 502/ERR_ABORTED 的问题
    try:
        app.run(host='::', port=8888, debug=debug_mode, threaded=True)
    except (OSError, socket.error) as _e:
        if 'Address already in use' in str(_e) or "Can't assign requested address" in str(_e):
            app.run(host='0.0.0.0', port=8888, debug=debug_mode, threaded=True)
        else:
            raise

