def _v21_json_resp(ok=True, **kw):
    d = {'success': ok}
    d.update(kw)
    return jsonify(d)

def _v21_parse_body():
    return request.get_json(silent=True) or {}

def _v21_qs_int(name, default=0):
    try: return int(request.args.get(name, default))
    except (ValueError, TypeError): return default

