def api_k12_game_points_add():
    try:
        b = _v21_parse_body()
        uid = int(b.get('user_id', 0)); delta = int(b.get('points', 0))
        if uid <= 0: return _v21_json_resp(ok=False, error='user_id必填'), 400
        conn = _get_conn(APP_DB); c = conn.cursor()
        exists = c.execute('SELECT id FROM k12_game_points WHERE user_id=?', (uid,)).fetchone()
        if exists:
            c.execute('UPDATE k12_game_points SET total_points=total_points+?, coins=coins+?, last_play_at=CURRENT_TIMESTAMP, updated_at=CURRENT_TIMESTAMP WHERE user_id=?',
                      (delta, int(b.get('coins',0)), uid))
        else:
            c.execute('INSERT INTO k12_game_points(user_id,total_points,coins) VALUES(?,?,?)',
                      (uid, max(0,delta), int(b.get('coins',0))))
        conn.commit(); conn.close()
        return _v21_json_resp(ok=True, added_points=delta)
    except Exception as e:
        logger.warning(f'[K12][game_points_add] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

