# ============ 管理员模块 12个 CRUD/功能 API (require_admin 权限) ============
_V21_ADMIN_ENTITIES = {
    'classes': {'table': 'admin_classes', 'cols': ['name','grade','teacher_id','student_count','schedule_json','semester','status']},
    'courses': {'table': 'admin_courses', 'cols': ['name','code','subject','credit','hours','description','teacher_id','status']},
    'questions': {'table': 'admin_questions', 'cols': ['subject','type','difficulty','stem_text','options_json','answer','analysis','creator_id','status']},
    'exams': {'table': 'admin_exams', 'cols': ['name','subject','class_id','total_score','duration_min','start_time','end_time','questions_json','status','creator_id']},
    'users': {'table': 'users', 'cols': ['username','email','role','is_active','avatar','phone']},
    'notifications': {'table': 'admin_notifications', 'cols': ['title','body','priority','target_roles_json','published_by','published_at','is_draft']},
}

def _v21_ensure_admin_tables(conn):
    for e, cfg in _V21_ADMIN_ENTITIES.items():
        t = cfg['table']
        if t == 'users': continue
        col_sql = ', '.join(f'{c} TEXT' for c in cfg['cols'])
        try:
            conn.execute(f"""CREATE TABLE IF NOT EXISTS {t} (
                id INTEGER PRIMARY KEY AUTOINCREMENT, {col_sql},
                created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            )""")
            conn.commit()
        except Exception:
            pass
        try:
            conn.execute(f'CREATE INDEX IF NOT EXISTS idx_{t}_status ON {t}(status)')
            conn.commit()
        except Exception:
            pass

def _v21_admin_require_role(f):
    @_ft.wraps(f)
    def wrapper(*a, **kw):
        u = _current_user()
        if not u:
            return _v21_json_resp(ok=False, error='需要登录'), 401
        role = (u.get('role') or '').lower()
        sa = (u.get('username') or '').lower() == 'wuchenghao15'
        if not sa and role not in _MT_ADMIN_ROLES:
            return _v21_json_resp(ok=False, error='需要管理员权限'), 403
        return f(*a, **kw)
    return wrapper

def _v21_admin_entity_crud(entity):
    cfg = _V21_ADMIN_ENTITIES[entity]
    table = cfg['table']; cols = cfg['cols']

    @_v21_admin_require_role
    def list_fn():
        try:
            page = _v21_qs_int('page', 1); size = _v21_qs_int('size', 50)
            if size > 500: size = 500
            off = max(0, (page - 1) * size)
            conn = _get_conn(APP_DB); c = conn.cursor()
            _v21_ensure_admin_tables(conn)
            total = c.execute(f'SELECT COUNT(*) FROM {table}').fetchone()[0] if table != 'users' else c.execute(f'SELECT COUNT(*) FROM users').fetchone()[0]
            rows = c.execute(f'SELECT * FROM {table} ORDER BY id DESC LIMIT ? OFFSET ?', (size, off)).fetchall()
            conn.close()
            return _v21_json_resp(data=[dict(r) for r in rows], total=total, page=page, size=size)
        except Exception as e:
            logger.warning(f'[ADMIN][{entity}][list] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    @_v21_admin_require_role
    def get_fn(id):
        try:
            conn = _get_conn(APP_DB); c = conn.cursor()
            _v21_ensure_admin_tables(conn)
            r = c.execute(f'SELECT * FROM {table} WHERE id=?', (id,)).fetchone()
            conn.close()
            if not r: return _v21_json_resp(ok=False, error='记录不存在'), 404
            return _v21_json_resp(data=dict(r))
        except Exception as e:
            logger.warning(f'[ADMIN][{entity}][get] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    @_v21_admin_require_role
    def create_fn():
        try:
            b = _v21_parse_body()
            vals = [b.get(c) for c in cols]
            placeholders = ','.join(['?'] * len(cols))
            col_sql = ','.join(cols)
            conn = _get_conn(APP_DB); c = conn.cursor()
            _v21_ensure_admin_tables(conn)
            c.execute(f'INSERT INTO {table}({col_sql}) VALUES({placeholders})', vals)
            conn.commit(); new_id = c.lastrowid; conn.close()
            return _v21_json_resp(id=new_id)
        except Exception as e:
            logger.warning(f'[ADMIN][{entity}][create] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    @_v21_admin_require_role
    def update_fn(id):
        try:
            b = _v21_parse_body()
            sets, vals = [], []
            for c in cols:
                if c in b:
                    sets.append(f'{c}=?')
                    vals.append(b[c])
            if not sets: return _v21_json_resp(ok=False, error='无更新字段'), 400
            vals.append(id)
            conn = _get_conn(APP_DB); c = conn.cursor()
            _v21_ensure_admin_tables(conn)
            c.execute(f'UPDATE {table} SET {",".join(sets)}, updated_at=CURRENT_TIMESTAMP WHERE id=?', vals)
            conn.commit(); aff = c.rowcount; conn.close()
            return _v21_json_resp(updated=aff)
        except Exception as e:
            logger.warning(f'[ADMIN][{entity}][update] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    @_v21_admin_require_role
    def delete_fn(id):
        try:
            conn = _get_conn(APP_DB); c = conn.cursor()
            _v21_ensure_admin_tables(conn)
            c.execute(f'DELETE FROM {table} WHERE id=?', (id,))
            conn.commit(); aff = c.rowcount; conn.close()
            return _v21_json_resp(deleted=aff)
        except Exception as e:
            logger.warning(f'[ADMIN][{entity}][delete] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    return list_fn, get_fn, create_fn, update_fn, delete_fn

for ent in _V21_ADMIN_ENTITIES:
    list_fn, get_fn, create_fn, update_fn, delete_fn = _v21_admin_entity_crud(ent)
    app.add_url_rule(f'/api/admin/{ent}', view_func=list_fn, methods=['GET'], endpoint=f'admin_{ent}_list_v21')
    app.add_url_rule(f'/api/admin/{ent}/<int:id>', view_func=get_fn, methods=['GET'], endpoint=f'admin_{ent}_get_v21')
    app.add_url_rule(f'/api/admin/{ent}', view_func=create_fn, methods=['POST'], endpoint=f'admin_{ent}_create_v21')
    app.add_url_rule(f'/api/admin/{ent}/<int:id>', view_func=update_fn, methods=['PUT'], endpoint=f'admin_{ent}_update_v21')
    app.add_url_rule(f'/api/admin/{ent}/<int:id>', view_func=delete_fn, methods=['DELETE'], endpoint=f'admin_{ent}_delete_v21')

