@app.route('/api/admin/stats', methods=['GET'])
@_v21_admin_require_role
def api_admin_stats():
    try:
        conn = _get_conn(APP_DB); c = conn.cursor()
        stats = {}
        for tbl in ['users','admin_classes','admin_courses','admin_questions','admin_exams','admin_notifications']:
            try:
                stats[tbl] = c.execute(f'SELECT COUNT(*) FROM {tbl}').fetchone()[0]
            except Exception:
                try:
                    conn.execute(f'CREATE TABLE IF NOT EXISTS {tbl}(id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT)')
                    conn.commit()
                    stats[tbl] = 0
                except Exception:
                    stats[tbl] = 0
        try:
            stats['approval_pending'] = c.execute('SELECT COUNT(*) FROM approval_requests WHERE status=?', ('pending',)).fetchone()[0]
        except Exception:
            stats['approval_pending'] = 0
        conn.close()
        return _v21_json_resp(data=stats)
    except Exception as e:
        logger.warning(f'[ADMIN][stats] err: {e}')
        return _v21_json_resp(ok=False, error=str(e)), 500

# ============ 教师模块 11个 API (require_teacher 权限) ============
def _v21_teacher_require(f):
    @_ft.wraps(f)
    def wrapper(*a, **kw):
        u = _current_user()
        if not u:
            return _v21_json_resp(ok=False, error='需要登录'), 401
        role = (u.get('role') or '').lower()
        sa = (u.get('username') or '').lower() == 'wuchenghao15'
        if not sa and role not in _MT_TEACHER_ROLES:
            return _v21_json_resp(ok=False, error='需要教师权限'), 403
        return f(*a, **kw)
    return wrapper

_V21_TEACHER_ENTITIES = {
    'classes': {'table': 'teacher_classes'},
    'questions': {'table': 'teacher_questions', 'ensure_ddl': """CREATE TABLE IF NOT EXISTS teacher_questions (
        id INTEGER PRIMARY KEY AUTOINCREMENT, teacher_id INTEGER, subject TEXT, type TEXT,
        difficulty TEXT, stem_text TEXT, options_json TEXT, answer TEXT, analysis TEXT,
        status TEXT DEFAULT 'draft', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )"""},
    'homework': {'table': 'teacher_homework', 'ensure_ddl': """CREATE TABLE IF NOT EXISTS teacher_homework (
        id INTEGER PRIMARY KEY AUTOINCREMENT, teacher_id INTEGER, class_id INTEGER, title TEXT,
        subject TEXT, questions_json TEXT, due_date TEXT, status TEXT DEFAULT 'draft',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )"""},
    'exams': {'table': 'teacher_exams'},
}

def _v21_teacher_entity_crud(entity):
    cfg = _V21_TEACHER_ENTITIES.get(entity, {}); table = cfg.get('table', f'teacher_{entity}')
    @_v21_teacher_require
    def list_fn():
        try:
            conn = _get_conn(APP_DB); c = conn.cursor()
            ddl = cfg.get('ensure_ddl')
            if ddl:
                try: conn.execute(ddl); conn.commit()
                except Exception: pass
            u = _current_user(); tid = u and u.get('id')
            if tid:
                rows = c.execute(f'SELECT * FROM {table} WHERE teacher_id=? ORDER BY id DESC LIMIT 500', (tid,)).fetchall()
            else:
                rows = c.execute(f'SELECT * FROM {table} ORDER BY id DESC LIMIT 500').fetchall()
            conn.close()
            return _v21_json_resp(data=[dict(r) for r in rows])
        except Exception as e:
            logger.warning(f'[TEACHER][{entity}][list] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    @_v21_teacher_require
    def create_fn():
        try:
            b = _v21_parse_body()
            u = _current_user(); tid = b.get('teacher_id') or (u and u.get('id'))
            conn = _get_conn(APP_DB); c = conn.cursor()
            ddl = cfg.get('ensure_ddl')
            if ddl:
                try: conn.execute(ddl); conn.commit()
                except Exception: pass
            # 简易通用插入
            cols = ['teacher_id'] + [k for k in b.keys() if k != 'teacher_id']
            vals = [tid] + [b[k] for k in cols if k != 'teacher_id']
            cols_actual = ['teacher_id'] + [k for k in b.keys() if k != 'teacher_id']
            vals_actual = [tid] + [b[k] for k in cols_actual if k != 'teacher_id']
            placeholders = ','.join(['?'] * len(cols_actual))
            c.execute(f'INSERT INTO {table}({",".join(cols_actual)}) VALUES({placeholders})', vals_actual)
            conn.commit(); new_id = c.lastrowid; conn.close()
            return _v21_json_resp(id=new_id)
        except Exception as e:
            logger.warning(f'[TEACHER][{entity}][create] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    @_v21_teacher_require
    def update_fn(id):
        try:
            b = _v21_parse_body()
            sets, vals = [], []
            for k, v in b.items():
                sets.append(f'{k}=?'); vals.append(v)
            if not sets: return _v21_json_resp(ok=False, error='无更新字段'), 400
            vals.append(id)
            conn = _get_conn(APP_DB); c = conn.cursor()
            c.execute(f'UPDATE {table} SET {",".join(sets)}, updated_at=CURRENT_TIMESTAMP WHERE id=?', vals)
            conn.commit(); aff = c.rowcount; conn.close()
            return _v21_json_resp(updated=aff)
        except Exception as e:
            logger.warning(f'[TEACHER][{entity}][update] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500

    @_v21_teacher_require
    def delete_fn(id):
        try:
            conn = _get_conn(APP_DB); c = conn.cursor()
            c.execute(f'DELETE FROM {table} WHERE id=?', (id,))
            conn.commit(); aff = c.rowcount; conn.close()
            return _v21_json_resp(deleted=aff)
        except Exception as e:
            logger.warning(f'[TEACHER][{entity}][delete] err: {e}')
            return _v21_json_resp(ok=False, error=str(e)), 500
    return list_fn, create_fn, update_fn, delete_fn

for ent in ['classes','questions','homework','exams']:
    list_fn, create_fn, update_fn, delete_fn = _v21_teacher_entity_crud(ent)
    app.add_url_rule(f'/api/teacher/{ent}', view_func=list_fn, methods=['GET'], endpoint=f'teacher_{ent}_list_v21')
    app.add_url_rule(f'/api/teacher/{ent}', view_func=create_fn, methods=['POST'], endpoint=f'teacher_{ent}_create_v21')
    app.add_url_rule(f'/api/teacher/{ent}/<int:id>', view_func=update_fn, methods=['PUT'], endpoint=f'teacher_{ent}_update_v21')
    app.add_url_rule(f'/api/teacher/{ent}/<int:id>', view_func=delete_fn, methods=['DELETE'], endpoint=f'teacher_{ent}_delete_v21')

